  str_dispatch_book_bookdes_4000 = "มันคือความฝัน เสียงโหยหวน ความสิ้นหวัง ที่อัดอั้นไปด้วยความคับข้องใจที่ยังไม่ได้แก้ไขในสมัยโบราณ เช่นเดียวกับความวิตกกังวลที่แปลกประหลาดเกี่ยวกับอนาคต... แต่สิ่งที่ทำให้ทุกอย่างดูน่าเบื่อและไร้ความหมายอย่างแท้จริงก็คือหนังสือเล่มนี้เป็นเพียงการลอกเลียนแบบแย่ ๆ แม้ว่าเราจะพยายามทำความเข้าใจอย่างจริงจังที่สุดแล้ว แต่ก็ไม่มีอะไรสามารถอธิบายความจริงที่ยิ่งใหญ่ เก่าแก่ และซ่อนเร้นได้อย่างแท้จริง \n...อย่างนั้นเหรอ?",
  str_dispatch_book_bookdes_5000 = "นักเดินทางพาร์ทไทม์และนักกินมืออาชีพ เชฟกระทะเหล็กแห่งทะเลทรายเรดีเซล และผู้เชี่ยวชาญเนื้ออิคลิพไซท์ ที่พูดมาทั้งหมดคือตัวฉันเอง! หากคุณหลงทางอยู่ในทะเลทราย แสดงว่าคุณกล้าหาญมากหรือไม่ก็โง่เกินเยียวยา แต่อย่ากังวลไป ตราบใดที่มีตำราอาหารของลุงจอห์นเล่มนี้ มื้อสุดท้ายของคุณจะไม่ต้องกินทรายแน่ ๆ ถ้ากินทรายเข้าไป กว่าจะเบ่งออกมายากนะ รู้มั้ย? ฮ่าฮ่าฮ่า เจ้านกโง่!",
  str_dispatch_book_bookdes_6000 = "มีแค่ไม่กี่คนที่รู้ว่านอกจากการเป็นผู้นำทางลูโมโพลิสแล้ว มิสบลังค์ยังเป็นนักเดินทางตัวยงและไกด์นำทางท่องเที่ยวที่มีความสามารถ (โปรแกรมไกด์นำเที่ยวสุดพิเศษของเธอจะให้บริการเฉพาะแขกที่ใกล้ชิดที่สุดและเคารพนับถือมากที่สุดเท่านั้น) เรามีความยินดีที่ได้สัมภาษณ์มิสบลังค์ และหนังสือเล่มนี้เป็นการรวบรวมหัวข้อที่พูดคุยกัน\nลูกค้าที่สั่งซื้อหนังสือเล่มนี้ล่วงหน้าที่ร้านหนังสือในเครือของเราจะได้รับโปสต์การ์ดมิสบลังค์สุดพิเศษ และผู้ซื้อที่โชคดี 10 ท่านจะได้รับโปสต์การ์ดพร้อมลายเซ็นเป็นของขวัญ",
  str_dispatch_book_bookdes_7000 = "พงศาวดารแห่งจุดจบได้รวบรวมบันทึกที่เป็นลายลักษณ์อักษร ซึ่งกล่าวว่ามาจากอารยธรรมโบราณที่อาศัยอยู่รอบนอกของนอร์ธแลนด์ หลังจากที่ถูกค้นพบเป็นครั้งแรก นักวิจัยสรุปว่าความเสียหายมหาศาลที่เกิดขึ้นต่อบันทึกเป็นไปอย่างจงใจ ไม่น่าจะใช่การเสื่อมสภาพจากกาลเวลา โชคดีที่ข้อความหลายตอนในเล่มยังอยู่ในสภาพที่ค่อนข้างสมบูรณ์ ข้อความที่กระจายเป็นส่วน ๆ ดูเหมือนจะพยากรณ์ถึงหายนะวันสิ้นโลก...",
  str_dispatch_book_bookdes_8000 = "ว่ากันว่าตำราโบราณปริศนานี้ถูกเขียนขึ้นโดยหัวหน้าฝ่ายวิทยาศาสตร์และเทคโนโลยีคนแรกของอิลลูมินา ซึ่งเป็นการรวบรวมการวิจัยทางวิทยาศาสตร์และเทคโนโลยีเกี่ยวกับอารยธรรมโบราณนานนับหลายปีและบันทึกการทดลองนับไม่ถ้วนที่สูญหายไปตามกาลเวลา เมื่อหัวหน้าคนนี้จากไปก็ไม่เจอตำราโบราณปริศนานี้อีกเลย ปัจจุบันมีเพียงเศษเสี้ยวของความรู้ที่พบในตำราเท่านั้นที่ถูกเผยแพร่ออกมา แม้ว่าความถูกต้องของความรู้ยังคงเป็นที่กังขาอยู่ก็ตาม",
  str_dispatch_book_bookdes_9000 = "\"การเดินทางของนักผจญภัย\" เป็นการผจญภัยสมมติที่เขียนขึ้นโดยนักประพันธ์ที่เกิดในอัมบราตัน บอกเล่าเรื่องราวของชายหนุ่มที่ออกทะเลพร้อมกองทัพเรือของอาณาจักรของเขา เผชิญหน้ากับสัตว์ประหลาดและความลึกลับทุกรูปแบบ ในที่สุดก็พบสมบัติในตำนานและปกป้องอาณาจักรจากสัตว์ประหลาดไว้ได้ เรื่องนี้มีหลายบท ทว่ามีเพียงตอนต่อไปนี้เท่านั้นที่เหลืออยู่ในเล่มแรก",
  str_dispatch_book_bookdes_10000 = "สหพันธรัฐอิลลูมินาแห่งแอสตรา หรือที่เรียกขานกันว่าอิลลูมินา คือเมืองหลวงที่ตั้งอยู่ในเมืองแกนน่อน เขียนโดยสำนักบริหารสหพันธรัฐอิลลูมินาด้วยความร่วมมือกับที่ปรึกษาจากสภารัฐบาลกลางอิลลูมินา กองทัพสหพันธรัฐอิลลูมินา และศูนย์วิจัยอิลลูมินา หนังสือเล่มนี้มีจุดมุ่งหมายเพื่อเป็นแนวทางที่เหมาะสมสำหรับพลเมืองใหม่ทั้งหมดของอิลลูมินา",
  str_dispatch_book_bookdes_11000 = "เอด้าและโคลอสซัส ซึ่งเขียนโดยเฮย์เดน คือเทพนิยายยอดนิยมในอีราเวล และเป็นแรงบันดาลใจให้กับชาวเคเลสไทต์ หนังสือเล่มนี้บอกเล่าเรื่องราวของหญิงสาวชาวเคเลสไทต์ชื่อเอด้าที่เชื่อมโยงกระแสจิตกับแคซ ผู้เป็นโคลอสซัสที่อ่อนแอที่สุด และเดินทางออกจากอีราเวลไปเพื่อสำรวจโลก ในการผจญภัยของพวกเขา ผู้เขียนได้อธิบายแนวความคิดต่าง ๆ เช่น อีโอเรีย วันที่ไม่มีที่สิ้นสุดและคืนที่ไม่รู้จบ ออโรเรียน อิคลิพไซท์ และอื่น ๆ",
  str_dispatch_book_bookdes_12000 = "มินะเป็นนักเดินทางที่มีชื่อเสียง ซึ่งมีชาวออโรเรียนของแอสตราได้อ่านบันทึกของเธอกันอย่างกว้างขวาง ในบันทึกการเดินทางเล่มหนึ่งของเธอ บรรยายถึงความเสียใจที่เธอเก็บไว้ตั้งแต่ยังเป็นเด็กสาว เมื่อเธอเติบโตขึ้นมาในหมู่บ้านริมฝั่งแม่น้ำทองคำ เธอได้สร้างมิตรภาพอันลึกซึ้งกับอัศวินจากเมืองลูโมโพลิสที่ชื่อเชริโอซา แต่ท้ายที่สุด พวกเขาก็ต้องแยกจากกัน ในเรื่องนี้ที่ชื่อ \"รุ่งอรุณแห่งการเดินทาง\" ม่านที่ปกคลุมทั้งอัศวินลูโมและลูมินาติกส์จะค่อย ๆ ถูกเปิดเผย",
  str_dispatch_book_bookdes_13000 = "นี่เป็นเรื่องราวที่เล่าขานกันในนอร์ธแลนด์ แม้ว่าจะไม่มีใครรู้ว่าเป็นเรื่องจริงหรือไม่ แต่นักร้องหญิงที่ท่องทั่วไปในนอร์ธแลนด์ได้รวบรวมไว้ในบทกวี... เด็กกำพร้าชาวออโรเรียนผมบลอนด์สองคนไม่ทราบที่มาได้พบกันในหมู่บ้านนอร์ธแลนด์สร้างความผูกพันอันแน่นแฟ้นจากการช่วยเหลือและการยอมรับ\nซึ่งกันและกัน\nนอกจากนี้เรายังจะได้เห็นถึงชีวิตประจำวันของออโรเรียนนอร์ธแลนด์ในเรื่องนี้อีกด้วย",
  str_dispatch_book_bookdes_14000 = "นี่คือกองจดหมายโต้ตอบระหว่างช่างเทคนิคโรซ่าแห่งทะเลทรายเรดีเซลกับร้านอะไหล่มือสอง M&M ในอัมบราตัน โดยมีจดหมายหลายฉบับขาดหายไป โรซ่าต้องการซื้ออะไหล่ราคาถูกเพื่อทำโครงการดัดแปลงปรับแต่งเครื่องจักร จึงเขียนจดหมายถึงร้านอะไหล่ M&M ในอัมบราตันซึ่งมีของที่เธอต้องการ ความร่วมมือของทั้งสองฝ่ายดำเนินไปนานกว่าทศวรรษจนกระทั่งโรซ่าเสียชีวิต การอ่านจดหมายเหล่านี้น่าจะทำให้เราสัมผัสได้ถึงของการใช้ชีวิตประจำวันในทะเลทรายเรดีเซลและอัมบราตัน",
  str_dispatch_book_bookdes_15000 = "อีวอนน์เป็นนักประพันธ์ที่มีชื่อเสียงซึ่งเป็นที่รู้จักจากการผสมผสานเหตุการณ์ในชีวิตจริงและผู้คนเข้ากับเรื่องแต่ง Mrs. Red Mercury เป็นหนึ่งในเรื่องสั้นที่โด่งดังของเธอ บอกเล่าเรื่องราวในตำนานของ Mrs. Red Mercury หัวหน้ากิลด์ใน Umbraton หนังสือเล่มนี้พิมพ์ซ้ำหลายครั้ง บรรณาธิการที่รับผิดชอบฉบับที่สองสามารถตรวจสอบการมีอยู่ของบุคคลและเหตุการณ์ที่กล่าวถึงในเรื่องนี้ และผลการวิจัยของเขารวมอยู่ในคำหลัง หนังสือเล่มนี้ช่วยให้ผู้อ่านได้เห็นภาพรวมของชีวิตใน Umbraton เมื่อหลายสิบปีก่อน",
