  str_dispatch_book_chaptername_15000_11 = "บทส่งท้ายของบรรณาธิการ (ตอนที่ 1)",
  str_dispatch_book_chaptername_15000_12 = "บทส่งท้ายของบรรณาธิการ (ตอนที่ 2)",
  str_dispatch_book_chapterdes_1000_1 = "ผู้ศรัทธาจะได้พบการรู้แจ้ง จงกราบและสดับฟังด้วยความเกรงกลัวและความกรุณาในหัวใจ\nผู้ไร้ศรัทธาจะไม่มีทางได้พบการรู้แจ้ง จำต้องอยู่อย่างหลงผิดด้วยความเขลาและใช้ชีวิตแบบไร้ขื่อแป\nผู้ที่พบการรู้แจ้งจะรู้จักสงคราม แต่รอดพ้นจากความวิบัติได้\nผู้ที่ไม่รู้จักการรู้แจ้งจะรอดพ้นจากสงคราม แต่มีชีวิตอยู่อย่างคนที่แหลกสลาย",
  str_dispatch_book_chapterdes_1000_2 = "\"เทพเจ้าแห่งแสงจะสู้เพื่อทุกคน ดังนั้นทุกคนต้องหนักแน่นและนิ่งเงียบ\nเทพเจ้าแห่งแสงแยกสมุทรและทำลายภูผา ดังนั้นทุกคนต้องหนักแน่นและนิ่งเงียบ\"",
  str_dispatch_book_chapterdes_1000_3 = "\"ระหว่างสิ่งมีชีวิตทั้งสอง จะต้องมีการพิพากษา แล้วทุกคนจะได้รู้วิถีของเทพเจ้าแห่งแสง \nทั้งผู้ที่สักการะเทพเจ้าแห่งแสง และผู้ที่ไม่เชื่อมั่น จะต้องน้อมรับด้วยชีวิตโดยไม่มีการอภัยโทษ\"",
  str_dispatch_book_chapterdes_1000_4 = "\"คำขอของเจ้าทั้งหมดจะเป็นจริง \nและคำสาบานทั้งหมดของเจ้าจะได้รับการตอบแทน \nจำคำของข้าไว้ชั่วนิรันดร์ และทุกอย่างจะเป็นไปตามคำสัญญาที่ให้ไว้ \nการรู้แจ้งจะอยู่ชั่วกาลนาน\"",
  str_dispatch_book_chapterdes_2000_1 = "กลอุบายแห่งโชคชะตา ทำให้พวกครึ่งมนุษย์ค้นพบถ้ำที่มนุษย์สร้างขึ้นที่ใหญ่ที่สุดในประวัติศาสตร์ พวกเขามีความทะเยอทะยานแต่ไร้เดียงสาตามธรรมชาติ มุ่งมั่นที่จะสร้าง \"ดินแดนแห่งคำมั่นสัญญา\" ของตนเองด้วยความปรารถนาอันแรงกล้าที่จะเคลื่อนย้ายภูเขาและแยกมหาสมุทร",
  str_dispatch_book_chapterdes_2000_2 = "นานกว่าพันปีแล้วที่พวกครึ่งมนุษย์ได้ค้นพบดินแดนลับ หลังจากนั้นหลายร้อยปีพวกครึ่งมนุษย์นับไม่ถ้วนก็ได้ถือกำเนิดขึ้น เติบโต และอาศัยอยู่ที่นี่ พวกครึ่งมนุษย์เชื่อว่าดินแดนลับเป็นมรดกอันล้ำค่าที่บรรพบุรุษได้ทิ้งเอาไว้ และถือเป็นบ้านเกิดอันศักดิ์สิทธิ์สูงสุดของเผ่าพันธุ์ ทว่าหลังจากการรุกรานของฝูงอิคลิพไซท์ ในที่สุดพวกครึ่งมนุษย์ก็สูญเสียการปกครองดินแดนลับไป...",
  str_dispatch_book_chapterdes_2000_3 = "ดินแดนลับเป็นทั้งบ้านเกิดทางรูปธรรมและจิตวิญญาณของพวกครึ่งมนุษย์ทั้งหลาย ในช่วงที่อิคลิพไซท์บุกรุก พวกครึ่งมนุษย์ที่อาศัยอยู่ในถ้ำไม่ใช่กลุ่มเดียวที่ต่อสู้เพื่อลมหายใจของตัวเอง แต่ยังมีพวกครึ่งมนุษย์จากทุกมุมโลกที่กลับมาต่อสู้เคียงข้างญาติพี่น้อง ความยึดติดในบ้านเกิดเมืองนอนอย่างแน่วแน่เช่นนี้ ส่งผลให้พวกเขาต้องเผชิญกับความพินาศในที่สุด",
  str_dispatch_book_chapterdes_2000_4 = "การทำลายล้างพวกครึ่งมนุษย์อย่างราบคาบทำให้ออโรเรียนตกตะลึง สหพันธรัฐอิลลูมินาต้องการตรวจสอบสาเหตุของการทำลายล้าง จึงส่งทีมสำรวจที่กล้าหาญไปยังดินแดนลับที่เต็มไปด้วยพวกอิคลิพไซต์ ตอนนั้นดินแดนลับได้กลายเป็นสถานที่แห่งความอันตรายและความตายที่ไม่มีสิ่งใดเทียบไปแล้ว แม้แต่ทหารที่แน่วแน่ที่สุดของอิลลูมินาก็ยังต้องสั่นสะท้านด้วยความหวาดกลัว",
  str_dispatch_book_chapterdes_3000_1 = "กลุ่มทหารรับจ้างนิรนามที่เกี่ยวข้องกับเหตุการณ์หลังเสร็จสิ้นภารกิจ ทหารรับจ้างเหล่านั้นต้องการรักษาความลับ จึงลบชื่อหรือบดบังชื่อสถานที่ต่าง ๆ ที่กล่าวถึงในบันทึก และปล่อยให้คาดเดากันไปเอง",
  str_dispatch_book_chapterdes_3000_2 = "อีกบันทึกของทหารรับจ้างนิรนาม ดูเหมือนว่าค่าตอบแทนสำหรับงานก่อนหน้าไม่ได้เป็นไปตามที่พวกเขาคิด ยิ่งไปกว่านั้นภารกิจต่อไปก็ประสบปัญหาเช่นกัน",
  str_dispatch_book_chapterdes_3000_3 = "หลังจากความล้มเหลวทางการเงินครั้งใหญ่ และการไม่สามารถทำภารกิจที่ยากลำบากให้สำเร็จลุล่วงได้ ทหารรับจ้างนิรนามก็ได้หางานที่อยู่นอกเหนือความเชี่ยวชาญตามปกติของพวกเขา เมื่ออ่านบันทึกนี้จะสามารถสัมผัสได้ถึงความสุขและความพึงพอใจที่คลุมเครือของผู้เขียนได้",
  str_dispatch_book_chapterdes_3000_4 = "บทความสุดท้ายในบันทึกของทหารรับจ้างนิรนาม พวกเขาระลึกถึงงานที่ทำในฐานะทหารรับจ้าง และอธิบายแผนการที่วางไว้สำหรับชีวิตใหม่ ทำให้ผู้อ่านมีความหวังอย่างแรงกล้า",
  str_dispatch_book_chapterdes_4000_1 = "ความจริงเป็นสิ่งที่ไม่อาจมองเห็นได้\nสานุศิษย์ เจ้าถูกมองเห็นแล้ว\nจงเพรียกหา และรู้ที่อยู่ของมัน\nจงปฏิเสธหากเจ้ามิอาจทำได้",
  str_dispatch_book_chapterdes_4000_2 = "ดูเหมือนมันจะอยู่ในทุกที่\nความเจ็บปวดเกิดขึ้นทันที\nและมันควรอยู่ในทุกหนแห่ง\nหมู่มวลดอกไม้เบ่งบานอยู่ในท้องทะเลสีเลือด",
  str_dispatch_book_chapterdes_4000_3 = "โคลนคือโฉมหน้าของความจริง\nโคลนคือรสชาติของความจริง\nต้องกลืนกินมัน เพื่อรับรู้ความจริง\nลิ้มรสเพื่อที่จะรู้ความจริง",
  str_dispatch_book_chapterdes_4000_4 = "วันนั้นจะไม่มีทางมาถึง\nเชื่อข้าเถิด มันเป็นเพียงแค่คำลวง\nความตายมาเยือนแล้วก็จากไป\nแต่ความสุขจะไม่มีวันเลือนหาย",
  str_dispatch_book_chapterdes_5000_1 = "ถ้าคุณมาเยือนทะเลทรายเรดีเซล คุณต้องลองกินเมนูเด็ดที่มีเฉพาะที่นี่ แต่ถ้าคุณอยากกินอาหารชั้นสูงแบบผู้ดีก็เชิญกลับไปทางที่มาได้เลย เพราะสถานที่แห่งนี้คือทะเลทรายเรดีเซล คุณจะได้ลิ้มลองรสชาติเนื้อหนอนทรายตากแห้ง จิ้งหรีดทอด อูฐตุ๋น และกระบองเพชรเรดีเซล!",
  str_dispatch_book_chapterdes_5000_2 = "ตอนนี้คุณคงคิดว่า \"พวกทะเลทรายต้องดื่มเรดีเซลเข้าไปจนบ้าพอถึงขั้นกินของพรรค์นี้ได้!\" ไม่ใช่เลย คุณคิดผิดแล้ว เวลาหิวน้ำพวกเราจะไปที่หนองน้ำของลุงจอห์น บาร์หนอนทรายดิ้น เพื่อดื่มเครื่องดื่มดี ๆ และนั่งชิลล์ อะไรนะ ยังกินเหล้าไม่ได้เพราะอายุไม่ถึงเหรอ ฮ่าฮ่าฮ่า ที่นี่พอมีเมนูนมอูฐสำหรับเสิร์ฟให้เด็กน้อยอยู่นะ!",
  str_dispatch_book_chapterdes_5000_3 = "ว่าไงนะ เป็นมังสวิรัติเหรอ?! นั่นไม่ใช่ข้ออ้างที่จะปฏิเสธเนื้ออูฐเลยนะ! แค่คิดว่ามันเป็นผลไม้หรืออะไรก็ได้ ฉันจะไม่บอกใครถ้าคุณไม่พูด ตกลงมั้ย ลองชิมดูสิ รับประกันว่าลองชิมแค่คำเดียวคุณจะต้องหลงใหลแน่นอน!",
  str_dispatch_book_chapterdes_5000_4 = "เผ็ด! ร้อน! นี่คือจุดเด่นของทะเลทรายเรดีเซล เผ็ดจนทำให้คุณพ่นควันและไฟออกทางหูและปากของคุณได้! ความร้อนที่จะทะลุหัวออกมา! หากคุณกินเผ็ดไม่ได้ ก็ไม่มีทางเลยที่คุณจะอยู่ในทะเลทรายเรดีเซลได้ แค่นั้นเอง มีคำพูดโบราณที่ว่า \"มีเฉพาะนักสู้ที่ดีเท่านั้นที่สามารถกินอาหารเผ็ดของพวกเขาได้!\"",
  str_dispatch_book_chapterdes_5000_5 = "ฉันมักได้ยินพวกคนหนุ่มสาวชอบพูดถึงการท่องโลกและลองกินอาหารใหม่ ๆ แล้วทำไมพวกเขาถึงลังเลสำหรับทะเลทรายเรดีเซลล่ะ โธ่ ไม่ใช่จะบังคับให้กินทรายสักหน่อย เจ้าบ้า! แต่ฉันรู้ว่าข้าวหินทรายคือเมนูของเกาะเขี้ยวฉลาม...",
  str_dispatch_book_chapterdes_6000_1 = "ว่ากันว่าทะเลสาบทุกแห่งคือบ่อน้ำตาของเทพเจ้า และทะเลสาบกระจกเงาก็ไม่มีข้อยกเว้น มันเป็นทะเลสาบที่เก่าแก่และสวยงามที่สุดในทวีปนี้ ต้องมีโศกนาฏกรรมครั้งใหญ่เกิดขึ้นเป็นแน่ เหล่าทวยเทพถึงได้สร้างทะเลสาบนี้ขึ้นมา",
  str_dispatch_book_chapterdes_6000_2 = "แม้จะอยู่ในเขตทางใต้ของนอร์ธแลนด์ แต่ป่าลู่ลมก็ไม่ได้มีสภาพอากาศหนาวเย็นและโหดร้ายเหมือนกับดินแดนที่ปกคลุมไปด้วยหิมะ ที่นี่มีสภาพอากาศที่อบอุ่นและเย็นสบายเกือบตลอดทั้งปี และว่ากันว่าพืชพรรณและสัตว์ในป่าเหล่านี้ต่างก็มีชีวิตที่สุขสบายภายใต้ที่พักพิงแห่งลม",
  str_dispatch_book_chapterdes_6000_3 = "เมื่อมองแวบแรก อาจดูเหมือนเป็นเนินกว้าง แต่ตามตำนานท้องถิ่น ลักษณะที่แท้จริงของป่าสนนอร์ธแลนด์เรียกว่า \"คริสตัลที่แตกสลาย\"",
  str_dispatch_book_chapterdes_6000_4 = "พระราชวังเหมันต์ ตั้งอยู่ใจกลางสุดขอบโลก คือวังที่สร้างมาจากน้ำแข็งทั้งหมด มันคือบ้านของราชินีเบธเลเฮมและเป็นที่ตั้งของรัฐบาลนอร์ธแลนด์",
  str_dispatch_book_chapterdes_7000_1 = "ชิ้นส่วนของหนังสือที่ชื่อว่า \"ก่อนรัตติกาลมาเยือน\" ข้อความส่วนที่ขาดหายไปแสดงให้เห็นว่ามีคนตั้งใจลบมันออกไป",
  str_dispatch_book_chapterdes_7000_2 = "นักวิจัยเห็นพ้องกันว่าข้อความส่วนนี้ไม่ได้เขียนโดยผู้เขียนในสมัยโบราณคนเดียวกันกับข้อความที่เหลือ แต่เขียนขึ้นโดยผู้เขียนในยุคหลัง จนถึงทุกวันนี้ แม้จะเป็นส่วนหนึ่งของพงศาวดารแห่งจุดจบ แต่ผู้คนก็ยังไม่สามารถเชื่อมโยงความสัมพันธ์ใด ๆ ของข้อความนี้กับวันสิ้นโลกได้เลย",
  str_dispatch_book_chapterdes_7000_3 = "ชิ้นส่วนนี้ขาดหายไปในครึ่งแรก นักวิจัยคาดการณ์ว่า \"พวกเขา\" ที่กล่าวถึงในข้อความหมายถึงผู้ที่มีชีวิตอยู่ก่อนสงคราม และ \"เรา\" หมายถึงผู้ที่ทิ้งบันทึกเหล่านี้ไว้",
  str_dispatch_book_chapterdes_8000_1 = "ไฟล์ทดลองในชื่อรหัส \"วาลคีรี่\" ที่ถูกค้นพบท่ามกลางซากโบราณของอารยธรรมโบราณที่อยู่ลึกเข้าไปในภูเขาของนอร์ธแลนด์ นอกจากนี้ยังพบแคชไฟล์ขนาดใหญ่และข้อมูลการทดลองในพื้นที่ด้วย แต่ไฟล์ส่วนใหญ่ถูกทำลายไปโดยไม่ทราบสาเหตุ และไม่สามารถระบุใจความได้แล้ว",
  str_dispatch_book_chapterdes_8000_2 = "ส่วนหนึ่งของเอกสารของนักวิทยาศาสตร์ ถูกค้นพบในซากโบราณใกล้เมืองบาส เมื่ออ่านมันแล้วจะพบว่าเขาใช้ลูกสาวของตัวเองเป็นวัตถุในการทดลองพิลึกพิลั่น",
  str_dispatch_book_chapterdes_8000_3 = "เศษหน้าหนังสือที่ฉีกขาดจากต้นฉบับตำราโบราณ ซึ่งพบได้ทั่วไปตามเขตถิ่นฐานที่ติดกับทะเลทรายเรดีเซล ดูเหมือนว่าจะเป็นบันทึกการต่อสู้ แม้ว่าจะไม่ทราบเวลา สถานที่ และตัวตนของนักสู้ก็ตาม สิ่งที่ทราบจากการอ่านหน้าหนังสือคือความรู้ขั้นสูงเกี่ยวกับเทคโนโลยีของอารยธรรมโบราณ",
  str_dispatch_book_chapterdes_8000_4 = "ข้อความที่ฉีกขาดนี้ถูกพบในซากโบราณใกล้กับโอลด์ทาวน์ ดูเหมือนว่าจะเป็นบทจากนวนิยายหรือบันทึกบางอย่างเกี่ยวกับบุคคลในตำนานที่เรียกว่า \"แดรกคูลา\"",
  str_dispatch_book_chapterdes_9000_1 = "ราชอาณาจักรเรียกเหล่าแชมเปี้ยนมาเพื่อสำรวจเกาะใหม่ในทะเล บทที่สามชื่อ \"พายุ\" บอกเล่าเรื่องราวการเผชิญหน้าของกองทัพเรือกับพายุอันโหดร้าย และวิธีที่โคลินได้รับความเคารพจากเพื่อนร่วมงานของเขาเพราะความกล้าหาญที่เขามี",
  str_dispatch_book_chapterdes_9000_2 = "วีรบุรุษของอาณาจักรเริ่มสำรวจเกาะเพื่อค้นหาสมบัติ \"เกาะทั้งเจ็ด\" เรื่องราวบทที่ 2 บอกเล่าประสบการณ์บาดใจของทีมกับมังกรบนเกาะที่สอง อย่างไรก็ตาม เมื่อถอยกลับไปที่เกาะแรก พวกเขาพบว่ามันหายไปหมดแล้ว...",
  str_dispatch_book_chapterdes_9000_3 = "นกแก้วยักษ์และลูกทีมของเธอถูกสัตว์ทะเลมีหนวดขนาดมหึมาซุ่มโจมตี และถูกลากลงสู่ห้วงน้ำลึกกันทั้งหมด \"อาณาจักรใต้ทะเล\" บทที่ 4 ของเรื่องราว บอกเล่าเรื่องราวของโคลินและคนอื่น ๆ ที่ตื่นขึ้นมาหลังจากการโจมตีและพบว่าตัวเองอยู่ในอาณาจักรใต้น้ำลึกลับ",
  str_dispatch_book_chapterdes_9000_4 = "วีรบุรุษของอาณาจักรต่างมองหาวิธีที่จะโจมตีสัตว์ร้ายขนาดมหึมาที่ถือกำเนิดขึ้นจากส่วนลึกของท้องทะเล “สัตว์ร้ายแห่งทะเลลึก” บทที่ 6 ของเรื่องราว บอกเล่าความเป็นไปของโคลินผู้กล้าและสหายของเขาเมื่อมาถึงเกาะที่สมบัติชิ้นสุดท้ายถูกซ่อนอยู่ ที่นี่ สัตว์ประหลาดแห่งห้วงน้ำลึกได้เปิดเผยรูปร่างที่แท้จริงของมันต่อเหล่านักรบ...",
  str_dispatch_book_chapterdes_10000_1 = "ตอนหนึ่งของคู่มือปฏิสัมพันธ์ทางสังคมและชีวิตของชาวอิลลูมินา ส่วนใหญ่ครอบคลุมความเชื่อหลักของผู้คนในอิลลูมินา",
  str_dispatch_book_chapterdes_10000_2 = "ตอนหนึ่งของคู่มือปฏิสัมพันธ์ทางสังคมและชีวิตของชาวอิลลูมินา ส่วนใหญ่ครอบคลุมวินัยหลักของผู้คนในอิลลูมินา",
  str_dispatch_book_chapterdes_10000_3 = "ตอนหนึ่งของคู่มือปฏิสัมพันธ์ทางสังคมและชีวิตของชาวอิลลูมินา ส่วนใหญ่ครอบคลุมความรู้ทางวัฒนธรรมที่ประชาชนอิลลูมินาทุกคนควรรู้",
  str_dispatch_book_chapterdes_10000_4 = "ส่วนหนึ่งของคู่มือปฏิสัมพันธ์ทางสังคมและชีวิตของชาวอิลลูมินา ส่วนนี้ครอบคลุมจรรยาบรรณที่ชาวอิลลูมินาทุกคนควรรู้",
  str_dispatch_book_chapterdes_10000_5 = "ส่วนหนึ่งของคู่มือปฏิสัมพันธ์ทางสังคมและชีวิตของชาวอิลลูมินา ส่วนนี้ครอบคลุมบรรทัดฐานที่อิลลูมินาทุกคนควรปฏิบัติตาม",
  str_dispatch_book_chapterdes_11000_1 = "ในวันนั้น เอด้าและแคซ โคลอสซัสที่อ่อนแอที่สุด ได้ออกโบยบินไปในท้องฟ้าที่เต็มไปด้วยดวงดาว ออกไปจากอีราเวล อันเป็นสถานที่แห่งเดียวที่พวกเขาเคยใช้ชีวิตอยู่ โลกภายนอกค่อย ๆ เปิดกว้างเหมือนภาพวาด ออโรราทำให้ท้องฟ้าในบทแรกของการผจญภัยอันยิ่งใหญ่ของพวกเขาสว่างขึ้น",
  str_dispatch_book_chapterdes_11000_2 = "สัตว์ตัวเล็กแปลกประหลาดที่เรียกตัวเองว่า \"ครึ่งมนุษย์\" มีขนเต็มตัวและนุ่มนิ่มน่าจับ แม้แต่โคลอสซัสก็ไม่อาจต้านทานมันได้! ซุกตัวใต้ขนนุ่มภายใต้แสงแดดอุ่น ๆ ในวันสบาย ๆ",
  str_dispatch_book_chapterdes_11000_3 = "โคลอสซัสที่ถูกปกคลุมด้วยดอกไม้ได้ถึงช่วงสุดท้ายของชีวิตแล้ว มันจากอีราเวลมานานเกินไป มันและผู้นำทางของมันก็เหมือนกับเอด้าและแคซ ที่เคยฝันถึงโลกภายนอก แต่โลกภายนอกเป็นหนทางที่ใช่จริงหรือ? บางครั้งเมื่อคุณไปไกลเกินไป คุณก็อาจจะไม่สามารถหาทางกลับบ้านได้อีกเลย",
  str_dispatch_book_chapterdes_11000_4 = "เรือที่แล่นในทะเลทรายหยุดลงตรงหน้าเอด้าและแคซ มันบรรทุกนักเดินทางออโรเรียนมากลุ่มหนึ่ง ลมพัดทรายจากพื้น แท้จริงแล้วเรือไม่ได้ล่องไปตามทราย แต่มันแล่นไปตามเส้นทางของดวงดาว",
  str_dispatch_book_chapterdes_11000_5 = "เอด้าและแคซทิ้งรอยเท้าไว้ทั่วโลก แต่ยกเว้นที่หนึ่ง นั่นคืออีราเวล บางทีนี่อาจถึงเวลาแล้วที่จะต้องกลับไปยังจุดเริ่มต้น",
  str_dispatch_book_chapterdes_12000_1 = "สำหรับมินะ วันเวลาที่อยู่ริมฝั่งแม่น้ำทองคำเป็นช่วงที่ยากจะลืมเลือน ในตอนนั้น ชีวิตของเธอขาดทั้งความตื่นเต้นและไร้ความหมาย เธอต้องอดทนต่อชีวิตขั้นพื้นฐานที่แร้นแค้น แต่ทั้งหมดนี้ก็เปลี่ยนไปเมื่อกองคาราวานปรากฏตัว",
  str_dispatch_book_chapterdes_12000_2 = "สำหรับมินะ วันเวลาที่อยู่ริมฝั่งแม่น้ำทองคำเป็นช่วงที่ยากจะลืมเลือน ในตอนนั้น ชีวิตของเธอขาดทั้งความตื่นเต้นและไร้ความหมาย เธอต้องอดทนต่อชีวิตขั้นพื้นฐานที่แร้นแค้น แต่ทั้งหมดนี้ก็เปลี่ยนไปเมื่อกองคาราวานปรากฏตัว",
  str_dispatch_book_chapterdes_12000_3 = "หลังจากที่กองคาราวานปฏิเสธคำขอของมินะที่จะแลกเปลี่ยนสินค้ากับพวกเขา เธอยืนอายในเงามืดอย่างหดหู่ ตอนนั้นเองที่ชายชุดเกราะสีขาวช่วยชีวิตเธอจากสภาพที่เลวร้าย มินะมารู้ชื่อของเขาในภายหลัง—เขามีชื่อว่าเชริโอซา",
  str_dispatch_book_chapterdes_12000_4 = "หลังจากที่กองคาราวานปฏิเสธคำขอของมินะที่จะแลกเปลี่ยนสินค้ากับพวกเขา เธอยืนอายในเงามืดอย่างหดหู่ ตอนนั้นเองที่ชายชุดเกราะสีขาวช่วยชีวิตเธอจากสภาพที่เลวร้าย มินะมารู้ชื่อของเขาในภายหลัง—เขามีชื่อว่าเชริโอซา",
  str_dispatch_book_chapterdes_12000_5 = "หลังจากที่เชริโอซาออกจากหมู่บ้าน เขาส่งจดหมายถึงมินะเป็นประจำ มินะจินตนาการถึงโลกภายนอกอย่างไม่สิ้นสุด และด้วยเหตุนี้ ในที่สุดเธอก็หนีออกจากหมู่บ้านเพื่อออกสำรวจความลึกลับมากมายบนโลกใบนี้",
  str_dispatch_book_chapterdes_12000_6 = "หลังจากที่เชริโอซาออกจากหมู่บ้าน เขาส่งจดหมายถึงมินะเป็นประจำ มินะจินตนาการถึงโลกภายนอกอย่างไม่สิ้นสุด และด้วยเหตุนี้ ในที่สุดเธอก็หนีออกจากหมู่บ้านเพื่อออกสำรวจความลึกลับมากมายบนโลกใบนี้",
  str_dispatch_book_chapterdes_12000_7 = "มินะสมัครเข้าร่วมสหภาพผู้ส่งสาร แต่ใบสมัครของเธอถูกปฏิเสธ ขณะที่เธอรอจดหมายฉบับต่อไปของเชริโอซา เธอก็เริ่มหมดหวัง และในที่สุดก็ตัดสินใจออกจากดินแดนที่ชุบเลี้ยงเธอเพื่อออกไปดูโลกภายนอกด้วยตาของตัวเอง จุดหมายแรกของเธอคือลูโมโพลิส",
  str_dispatch_book_chapterdes_12000_8 = "มินะสมัครเข้าร่วมสหภาพผู้ส่งสาร แต่ใบสมัครของเธอถูกปฏิเสธ ขณะที่เธอรอจดหมายฉบับต่อไปของเชริโอซา เธอก็เริ่มหมดหวัง และในที่สุดก็ตัดสินใจออกจากดินแดนที่ชุบเลี้ยงเธอเพื่อออกไปดูโลกภายนอกด้วยตาของตัวเอง จุดหมายแรกของเธอคือลูโมโพลิส",
  str_dispatch_book_chapterdes_12000_9 = "แม้ว่าเธอจะถูกปฏิเสธเมื่อพยายามจะเข้าไปในเมืองลูโมโพลิส แต่มินะก็โชคดีพอที่จะได้รับโอกาสเข้าไปอีกครั้ง และเป็นโอกาสฟรีอีกด้วย หลังจากเข้าเมืองได้สำเร็จ มินะได้สอบถามเกี่ยวกับที่พักของเชริโอซาแต่ก็ได้รับเพียงข้อมูลที่ไม่น่าเชื่อถือ",
  str_dispatch_book_chapterdes_12000_10 = "แม้ว่าเธอจะถูกปฏิเสธเมื่อพยายามจะเข้าไปในเมืองลูโมโพลิส แต่มินะก็โชคดีพอที่จะได้รับโอกาสเข้าไปอีกครั้ง และเป็นโอกาสฟรีอีกด้วย หลังจากเข้าเมืองได้สำเร็จ มินะได้สอบถามเกี่ยวกับที่พักของเชริโอซาแต่ก็ได้รับเพียงข้อมูลที่ไม่น่าเชื่อถือ",
  str_dispatch_book_chapterdes_12000_11 = "ขณะที่มินะพยายามสืบหาที่อยู่ของเชริโอซา เธอได้รับข้อมูลที่เหลือเชื่อมากมาย ในท้ายที่สุด เธอก็สามารถตามหาเชริโอซาคนในดวงของเธอจนพบ แต่ทุกอย่างกลับไม่เป็นไปตามที่เธอคิด",
  str_dispatch_book_chapterdes_12000_12 = "ขณะที่มินะพยายามสืบหาที่อยู่ของเชริโอซา เธอได้รับข้อมูลที่เหลือเชื่อมากมาย ในท้ายที่สุด เธอก็สามารถตามหาเชริโอซาคนในดวงของเธอจนพบ แต่ทุกอย่างกลับไม่เป็นไปตามที่เธอคิด",
  str_dispatch_book_chapterdes_13000_1 = "พี่น้องโดโรธีอาศัยอยู่ในหมู่บ้านนอร์ธแลนด์ พ่อแม่เสียชีวิตตั้งแต่พวกเขายังเล็ก ดังนั้นจึงต้องทำงานสารพัดอย่างเพื่อเลี้ยงตัวเอง ผู้อาวุโสหวังว่าพวกเขาจะมีผู้อุปการะและมีครอบครัวใหม่ที่อบอุ่น แต่เด็กสาวปฏิเสธความหวังดีนั้น",
  str_dispatch_book_chapterdes_13000_2 = "ระหว่างทางกลับบ้าน พี่น้องได้ช่วยเหลือออโรเรียนที่ล้มลงท่ามกลางหิมะ ออโรเรียนพักอยู่ในหมู่บ้าน แต่แล้วในช่วงดึกสงัดก็เกิดพายุหิมะถล่มบ้านของออโรเรียน ทำให้ออโรเรียนต้องขอความช่วยเหลือจากพี่น้องอีกครั้ง",
  str_dispatch_book_chapterdes_13000_3 = "ด้วยความช่วยเหลือจากผู้อาวุโส มาร์ธาสาวผมบลอนด์ผู้มาใหม่จึงย้ายเข้ามาอยู่กับโดโรธีและน้องชายของเธอ เมื่อเวลาผ่านไป ทั้งสามคนได้สร้างความสัมพันธ์ที่ใกล้ชิดระหว่างกัน",
  str_dispatch_book_chapterdes_13000_4 = "มาร์ธาชอบทำอาหารและถึงกับรู้วิธีในการทำเกลือเองได้ หลังจากฟังคำอธิบายของมาร์ธาแล้ว โดโรธีก็มีความคิดที่จะลองทำด้วยตัวเอง",
  str_dispatch_book_chapterdes_13000_5 = "มาร์ธาทำอาหารเย็นให้พี่น้อง และจากการพูดคุยกับครูซ น้องชายของเธอ เธอได้รู้เรื่องที่โดโรธีออกจากบ้านไป แต่นั่นไม่ใช่ประเด็น ประเด็นคือตอนนี้ก็ค่ำมืดแล้ว แต่โดโรธียังไม่กลับบ้านทั้ง ๆ ที่ควรจะกลับมาได้แล้ว",
  str_dispatch_book_chapterdes_13000_6 = "โดโรธีไปที่ทะเลสาบน้ำเค็มตามเส้นทางที่มาร์ธาไป แต่พายุหิมะทำให้เธอกลับบ้านไม่ได้ ขณะหาที่หลบ โชคไม่ดีที่เธอไปเจอหมาป่าที่หิวโหย",
  str_dispatch_book_chapterdes_13000_7 = "โดโรธีใช้ลูมินาติกส์เพื่อขับไล่การโจมตีของพวกมัน แต่ฝูงสัตว์มีมากกว่าที่เธอจะรับมือได้ ในช่วงจังหวะที่สิ้นหวังนั้น ใครบางคนก็แช่แข็งหมาป่าที่บ้าคลั่งและช่วยเธอให้พ้นจากอันตราย",
  str_dispatch_book_chapterdes_13000_8 = "ปีใหม่มาเยือนนอร์ธแลนด์ มาร์ธาและพี่น้องโดโรธีใช้เวลาร่วมกัน ความผูกพันแน่นแฟ้นยิ่งขึ้นในงานเลี้ยงสังสรรค์ของหมู่บ้าน",
  str_dispatch_book_chapterdes_13000_9 = "มีผู้มาเยือนคนใหม่อีกคนเข้ามาในหมู่บ้าน และพฤติกรรมที่ผิดปกติของมาร์ธาทำให้โดโรธีเห็นชัดเจนว่าผู้มาเยือนนั้นมาหามาร์ธาโดยเฉพาะ แต่มาร์ธาปฏิเสธที่จะบอกความจริงกับโดโรธี",
  str_dispatch_book_chapterdes_13000_10 = "ผู้อาวุโสก่อตั้งกลุ่มค้นหา และเมื่อโดโรธีพยายามเข้าร่วมอย่างลับ ๆ มาร์ธาก็หยุดเธอ ระหว่างการเผชิญหน้า โดโรธีพูดอะไรบางอย่างที่ทำร้ายจิตใจ",
  str_dispatch_book_chapterdes_13000_11 = "มาร์ธารู้สาเหตุการตายของพ่อแม่ของพี่น้อง ซึ่งทำให้เธอต้องตัดสินใจไปจากนอร์ธแลนด์ เธอไม่อาจทนต่อความรู้สึกผิดได้",
  str_dispatch_book_chapterdes_13000_12 = "มาร์ธาออกเดินทางแต่แล้วโดโรธีก็หยุดยั้งเธอไว้ โดโรธีบอกว่าเธอไม่สนใจอดีตของมาร์ธา แต่ก็ไม่ได้จะเหนี่ยวรั้งเธอไว้แต่อย่างใด เธอได้แต่หวังว่ามาร์ธาจะกลับมาที่นอร์ธแลนด์ในสักวันหนึ่ง",
  str_dispatch_book_chapterdes_14000_1 = "ช่างเทคนิคโรซ่าค่อนข้างหัวเสียที่อะไหล่ในทะเลทรายเรดีเซลขาดตลาด แต่เธอก็เจอร้านอะไหล่มือสอง M&M ในใบปลิว ซึ่งโฆษณาว่ามีอะไหล่ต่าง ๆ มากมายขายในราคาจับต้องได้ เธอสั่งซื้อครั้งแรกผ่านจดหมายและพึงพอใจกับคำตอบจากทางร้านเป็นอย่างมาก",
  str_dispatch_book_chapterdes_14000_2 = "แม้จะเกิดเรื่องพลิกผันขึ้นบ้าง แต่อะไหล่ที่สั่งก็มาถึงโรซ่าในที่สุด เธอจึงตัดสินใจส่งจดหมายสั่งซื้อผ่านสหภาพผู้ส่งสารตั้งแต่นั้นมา จดหมายตอบกลับจาก M&M นั้นเขียนโดยมินนี่ซึ่งเป็นลูกสาวเจ้าของร้าน",
  str_dispatch_book_chapterdes_14000_3 = "โรซ่าต้องดัดแปลงรถเป่าลมของเธอให้เข้ากับสภาพแวดล้อมทางภูมิศาสตร์และสภาพอากาศที่ค่อนข้างพิเศษของทะเลทรายเรดีเซล เธอเปิดเผยตัวตนที่แท้จริงของตนในจดหมายฉบับนี้ว่าเธอคือสมาชิกของทีมสำรวจที่หลบหนีออกมาจากอิลลูมินา",
  str_dispatch_book_chapterdes_14000_4 = "แม็กซ์ซึ่งเป็นเจ้าของร้านตอบรับการสั่งซื้อโดยไม่ชำระเงินทันทีของโรซ่า มินนี่เองก็แสดงความสนใจในแบบร่างการดัดแปลงรถเป่าลมเป็นอย่างมาก ถึงขั้นประกอบเครื่องยนต์ตามภาพที่โรซ่าร่างไว้",
  str_dispatch_book_chapterdes_14000_5 = "ขบวนรถของโรซ่าได้ต่อสู้อย่างดุเดือดกับกลุ่มหัวขโมย เธอได้เงินมาก้อนใหญ่และชำระหนี้ก่อนหน้านี้ได้ ในช่วงเวลาเดียวกันนั้น เธอก็ได้รับเด็กสาวชื่อว่าซัมเมอร์เข้ามาอยู่ด้วย เด็กคนนี้ได้ทำให้เธอพบกับวัตถุมากมายซึ่งสร้างด้วยเทคโนโลยีโบราณ",
  str_dispatch_book_chapterdes_14000_6 = "โรซ่าหวังว่าร้านอะไหล่แห่งนี้จะหาเครื่องมือบางอย่างมาแยกชิ้นส่วนเทคโนโลยีโบราณให้เธอได้ ซึ่งเป็นเรื่องที่ไม่ง่ายเลยสำหรับร้านที่เป็นธุรกิจครอบครัว มินนี่ก็ดูจะไม่ได้สนใจปัญหาของพ่อเลย เธอไปฉลองงานวันก่อตั้งลูโมโพลิสและส่งของขวัญมากมายให้โรซ่า",
  str_dispatch_book_chapterdes_14000_7 = "โรซ่าวางแผนที่จะแปลงกีตาร์ให้กับเพื่อนคนหนึ่งที่หลงใหลในเสียงเพลง เธอขอบคุณที่มินนี่ส่งขนมมากมายไปให้ เนื่องจากเธอเองก็กล้ำกลืนฝืนทนกับอาหารในทะเลทรายเรดีเซล",
  str_dispatch_book_chapterdes_14000_8 = "ขบวนรถของเธอได้ปล้นสะดมกองขนส่งของเหล่าอิลลูมินา ซึ่งหลายชีวิตจากทั้งสองฝ่ายต้องจบลงเพราะสถานการณ์เกินที่จะควบคุมได้ โรซ่าสูญเสียขาทั้งสองข้าง แต่สิ่งที่ทำให้เธอเจ็บปวดมากที่สุดคือการต้องลั่นไกใส่สหายเก่าของตัวเอง",
  str_dispatch_book_chapterdes_14000_9 = "มินนี่เชิญโรซ่ามางานแต่งงานของเธอที่กำลังจะจัดขึ้น เธอไม่ได้วาดฝันเกี่ยวกับชีวิตคู่ในจดหมาย แต่ได้ระบายถึงความเหนื่อยหน่ายในเส้นทางการเติบโตอันแสนยาวนานและจืดชืด",
  str_dispatch_book_chapterdes_14000_10 = "โรซ่าไม่ได้ไปงานแต่งงานของมินนี่เนื่องด้วยปัญหาสุขภาพ แต่เธอก็ทำช่อกุหลาบโลหะมอบให้เจ้าสาวพร้อมกับคำอวยพรแสนวิเศษ",
  str_dispatch_book_chapterdes_14000_11 = "จดหมายฉบับนี้เขียนขึ้นโดยซัมเมอร์ เด็กสาวซึ่งเคยพาโรซ่าไปค้นหาวัตถุที่สร้างขึ้นด้วยเทคโนโลยีโบราณ ซึ่งเธอก็ได้กลายเป็นผู้ช่วยส่วนตัวของโรซ่าตั้งแต่นั้นมา ซัมเมอร์ได้แจ้งข่าวอันน่าสะเทือนใจให้แม็กซ์และลูกสาวทราบ",
  str_dispatch_book_chapterdes_14000_12 = "มินนี่ย้อนกลับไปอ่านจดหมายโต้ตอบระหว่างโรซ่ากับครอบครัวของเธอ เธอมองว่าโรซ่าเป็นคนที่น่าทึ่งและมหัศจรรย์ที่สุดเท่าที่เคยรู้จักมา และได้ติดต่อไปยังขบวนรถเพื่อขออนุญาตออกเดินทางไปยังทะเลทรายเรดีเซลเพื่อกล่าวอำลาแก่เพื่อนของเธอเป็นครั้งสุดท้าย",
  str_dispatch_book_chapterdes_15000_1 = "เพื่อนของฉันและฉันกำลังดูการต่อสู้ที่ Pit ใน Umbraton นักสู้ทั้งสองดูเหมือนจะไม่ตรงกัน และคนที่อ่อนแอกว่ากลับกลายเป็นสมาชิกของกิลด์ สิ่งนี้ทำให้ฉันสับสน เพราะไม่มีทางที่หัวหน้ากิลด์จะไม่เข้าไปยุ่งเมื่อสมาชิกในกิลด์กำลังต่อสู้เพื่อเอาชีวิตรอด",
  str_dispatch_book_chapterdes_15000_2 = "ไม่น่าแปลกใจเลยที่นักสู้ตัวเล็กกว่าเสียเปรียบอย่างรวดเร็ว แต่เมื่อผู้ชมเริ่มกังวลเกี่ยวกับตัวเขา เสียงนกหวีดก็ดังขึ้นเพื่อหยุดการแข่งขัน ทำให้เขารอดพ้นจากความตาย ระหว่างที่การต่อสู้หยุดชั่วคราว โบรฮาฮาก็ปรากฏตัวขึ้นในมุมมืดของอัฒจันทร์ที่นางเรด เมอร์คิวรีนั่งอยู่",
  str_dispatch_book_chapterdes_15000_3 = "สายตาของเชลยที่ออกมาจากอัฒจันทร์ดูเหมือนจะกระตุ้นให้นักสู้ตัวเล็กกว่า และเขาก็ชนะการต่อสู้ต่อไป อย่างไรก็ตาม ก็ยังไม่แน่ใจว่า Mrs. Red Mercury จะทำอะไรกับเขา",
  str_dispatch_book_chapterdes_15000_4 = "หลังจากไปเที่ยวที่ Pit ฉันอยากเรียนรู้เพิ่มเติมเกี่ยวกับ Mrs. Red Mercury ดังนั้นฉันจึงถามเพื่อนๆ ว่าพวกเขารู้อะไรเกี่ยวกับเธอบ้าง มีข่าวลือมากมายเกี่ยวกับเธอ และมีเพียงไม่กี่เรื่องที่เป็นจริง แต่ถึงอย่างนั้น ต้นกำเนิดและการตัดสินใจอย่างแน่วแน่ที่จะแต่งงานของเธอก็เพียงพอแล้วที่จะทำให้เธอกลายเป็นตำนาน",
  str_dispatch_book_chapterdes_15000_5 = "ต่อมาได้มีโอกาสไปที่ลูโมโปลิส ขณะที่ฉันกำลังรอบัตรเข้าเมืองได้รับการอนุมัติที่โรงเตี๊ยมแห่งหนึ่งในเขตเปลี่ยนเครื่อง ฉันเห็นใครบางคนที่ฉันไม่คาดคิดว่าจะได้พบในสถานที่ดังกล่าว",
  str_dispatch_book_chapterdes_15000_6 = "ฉันกลัวที่จะเข้าหา Mrs. Red Mercury แต่ความอยากรู้อยากเห็นของฉันบังคับให้ฉันลอง ในที่สุดโอกาสอันยอดเยี่ยมก็ปรากฏขึ้น แสร้งทำเป็นไม่รู้ว่าเธอเป็นใคร ฉันเดินไปหาเธอและเริ่มบทสนทนา",
  str_dispatch_book_chapterdes_15000_7 = "ในที่สุดฉันก็ได้คุยกับ Mrs. Red Mercury ในระหว่างการสนทนาของเรา เธอพูดถึงว่าเธอมาอยู่ในโซนเปลี่ยนเครื่องได้อย่างไร มันเกี่ยวข้องกับความฝันของเธอและการที่เธอคิดถึงเพื่อนเก่า",
  str_dispatch_book_chapterdes_15000_8 = "วันรุ่งขึ้นฉันตื่นขึ้นมาพบว่านางปรอทแดงได้จากไปแล้ว ตามคำบอกเล่าของเจ้าของโรงแรม เรือเหาะจากลูโมโปลิสมารับเธอไป ฉันกลับไปที่ห้องด้วยความรู้สึกโหยหา แต่ข้างใน ความประหลาดใจกำลังรอฉันอยู่",
  str_dispatch_book_chapterdes_15000_9 = "เจ้าหน้าที่ถือโอกาสออกคำสั่งให้ฉันเข้าเมือง ฉันรู้สึกกระวนกระวายที่จะเข้าไปข้างใน ฉันเลยถามไปทั่วว่าเกิดอะไรขึ้นในลูโมโพลิส มีคนบอกว่ามีการฆาตกรรมที่น่าสยดสยองเกิดขึ้นที่นั่น ในที่สุดเมื่อฉันเข้าไป ฉันแทบรอไม่ไหวที่จะเรียนรู้รายละเอียดของงาน",
  str_dispatch_book_chapterdes_15000_10 = "เมื่อฉันพบอดีตผู้ใต้บังคับบัญชาของ Mrs. Red Mercury คนหนึ่งใน Umbraton ฉันอดไม่ได้ที่จะถามข่าวเกี่ยวกับเธอจากพวกเขา ฉันกลัวสิ่งที่เลวร้ายที่สุด แต่ปรากฏว่าความจริงนั้นแตกต่างจากที่ฉันจินตนาการไว้มาก",
  str_dispatch_book_chapterdes_15000_11 = "บรรณาธิการของ Mrs. Red Mercury ฉบับที่ 2 ได้ค้นคว้าเรื่องสมาคมลักลอบค้าอาวุธใน Umbraton และคดีฆาตกรรมใน Lumopolis รายละเอียดถูกแบ่งปันกับผู้อ่านในคำหลัง",
  str_dispatch_book_chapterdes_15000_12 = "บรรณาธิการยังได้แชร์ความคิดส่วนตัวเกี่ยวกับตัวละครของ Mrs. Red Mercury ในคำต่อท้ายด้วย เขาเชื่อว่าผู้อ่านไม่จำเป็นต้องพยายามหาบุคคลที่ Mrs. Red Mercury อิงตาม เพราะนั่นไม่ใช่จุดประสงค์ของงานเขียนของอีวอนน์",
  str_dispatch_book_chaptercont_1000_1 = "การรู้แจ้งของเทพเจ้าแห่งแสง ได้มอบชีวิตและความหวังให้กับออโรเรียนทั้งหมด เพื่อสั่งสอนพวกเขาในสิ่งที่จำเป็น และเพื่อส่งผู้ส่งสารไปเผยแพร่ความศรัทธาให้กับออโรเรียนทั้งหมด วิถีของเทพเจ้าแห่งแสงตลอดจนคัมภีร์ของรัตติกาลสีขาว ต่างพิสูจน์ให้ออโรเรียนได้รู้จากสิ่งที่ประจักษ์แก่สายตา บรรดาผู้สดับฟังคำพยากรณ์และพระคัมภีร์ภายในตำรานี้ ล้วนเป็นผู้ศรัทธา และจะได้รับพรจากเทพแห่งแสงสว่าง\n วิหารทั้ง 7 ในรัตติกาลสีขาวเบื้องบน นักบุญในอดีต ปัจจุบัน และอนาคต และทุกคนที่เป็นพยานอย่างซื่อสัตย์ต่อพระสิริของเทพเจ้าแห่งแสงจะยืนหยัด พวกเขาจะอยู่รอดในวัฏจักรนิรันดร์ของกลางวันและกลางคืน และเอาชนะภัยพิบัติทางธรรมชาติ ปรปักษ์ปีศาจ และบาปทั้งปวงของบรรพบุรุษของพวกเขา\n แผ่นดินจะจับตามองปีศาจในรัตติกาลสีขาวเบื้องบน เมื่อมันลงมายังโลก แผ่นดินจะหลั่งน้ำตาที่ขมขื่น น้ำตาที่แผดเผา และทุกคนจะได้รู้ความจริง\n เทพเจ้าแห่งแสงจะประกาศก้องว่า \"ข้าคือรากเหง้า ความลึกลับ และโลกีย์ ข้าเป็นผู้สร้างและผู้ทำลายอารยธรรมในอดีต ข้าเป็นพระเจ้าของออโรเรียนทั้งปวง และเป็นพี่น้องกับพวกเขา ข้ายืนอยู่เคียงข้างออโรเรียนทั้งมวลในอาณาจักรแห่งความทุกข์ทรมานนี้ ร่วมทนทุกข์และอดทนเป็นน้ำหนึ่งใจเดียวกัน เพื่อพวกเขาจะได้ประจักษ์ถึงวิถีของเราและเป็นสักขีพยานแห่งวิสุทธิชนของเรา”\n ในวันแห่งโชคชะตานั้น มวลชนต่างพากันหวั่นไหวตามคำของนักบุญ และพวกเขาได้ยินผู้ส่งสารของเทพเจ้าแห่งแสงมาแต่ไกล กล่าวว่า \"สิ่งที่เจ้าได้เห็นและได้ยินในวันนี้ จงจดบันทึกไว้ในหนังสือ เพื่อส่งไปยังวิหารทั้ง 7 ของลัคบิน แซลลัส แดโมคลีส แกรนดี้ ซาร์ดิเนีย แกนน่อน และทรอย\"\n เทพเจ้าแห่งแสงปรากฏบนท้องฟ้าเบื้องบน พูดกับนักบุญ เมื่อพวกออโรเรียนหันกลับมามอง พวกเขาก็เห็นเชิงเทียนสีทอง 7 อัน ตรงกลางมีร่างที่คล้ายกับชาวออโรเรียน สวมเสื้อคลุมยาวคาดเข็มขัดสีทอง คาดหน้าอก ผมและเคราของเขาขาวราวกับหิมะที่แสนบริสุทธิ์ ดวงตาของเขาแผดเผาเหมือนไฟ และเท้าของเขาส่องแสงราวกับทองแดงที่เจิดจ้าในเตาหลอมที่ร้อนแรงที่สุด ใบหน้าของเขาเปล่งประกายราวกับดวงอาทิตย์ และเสียงของเขาก้องกังวานราวกับคลื่นซัดในมหาสมุทร ในมือขวาของเขา ถือลำแสงบริสุทธิ์ มือซ้ายกำดาบสองคมขนาดใหญ่และน่าสยดสยอง\n ชาวออโรเรียนมากมายทรุดลงกับพื้นราวกับอยู่ในอาการระทมตายต่อหน้าสายตาที่สุกสกาวนี้ ชายผู้เปล่งประกายวางมือขวาบนศีรษะของชาวออโรเรียนและพูดเบา ๆ กับพวกเขาทั้งหมดว่า \"อย่ากลัวเลย เพราะเราเป็นคนแรกและคนสุดท้าย เราคือผู้ที่มีชีวิตอยู่และตายไป และตอนนี้ก็จะมีชีวิตอยู่ตลอดไปเป็นนิรันดร์ เราจะมอบกุญแจแห่งนรกและความตายให้เจ้า เพื่อเจ้าจะได้เขียนสิ่งที่เจ้าเห็นในวันนี้ สิ่งที่เกิดขึ้นในขณะนี้ และสิ่งที่จะเกิดขึ้นในอนาคต\"\n สงครามจะมาสู่พวกเจ้าทั้งปวง",
  str_dispatch_book_chaptercont_1000_2 = "เมื่อการรู้แจ้งมาถึง ผู้ส่งสารเปิดผนึกแรกออก เขามองเห็นออโรเรียนบนอาชาสีขาวบนท้องฟ้า สวมมงกุฎสีแดงเลือดและกระหน่ำยิงธนูลงมา \nเมื่อผนึกที่ 2 ถูกทำลาย ออโรเรียนบนหลังอาชาสีแดงก็ปรากฏออกมา ปีศาจมอบดาบให้กับออโรเรียน และด้วยเหตุนี้มันจึงแย่งชิงความสงบสุขจากแผ่นดินไป ทำให้ผู้คนเข่นฆ่ากันเอง\nเมื่อผนึกที่ 3 ถูกทำลาย อาชาสีดำปรากฏ ผู้ขี่ถือตราชูแห่งความยุติธรรมและพูดว่า \"หนึ่งบาป หนึ่งกรรม หนึ่งชีวิต และหนึ่งคำตัดสิน\"\nเมื่อผนึกที่ 4 ถูกทำลาย ออโรเรียนที่ตายแล้วบนอาชาสีเทาก็ปรากฏตัว นำชาวนรกออกมาทำลายดินแดน และออโรเรียนผู้ตายแล้วก็แผ่ขยายสงคราม ความอดอยาก โรคระบาด และอิคลิพไซท์มาสู่โลก\nเมื่อผนึกที่ 5 ถูกทำลาย ผู้คนนับไม่ถ้วนที่สวมชุดขาวเป็นพยานถึงความพินาศ และบันทึกชื่อของผู้ที่ต้องตายจากไป\nเมื่อผนึกที่ 6 ถูกทำลาย แผ่นดินก็สั่นสะเทือน ดวงอาทิตย์เปลี่ยนเป็นสีดำไม่ต่างจากหลุมดำ และพระจันทร์เต็มดวงก็ลอยอยู่บนท้องฟ้าสีแดงราวกับโลหิต ดวงดาวบนท้องฟ้าเริ่มร่วงหล่นราวกับผลอันยังไม่สุกงอมจากต้นไม้ที่ถูกพายุพัด ท้องฟ้าม้วนตัวไปมาดั่งม้วนหนังสือ ผู้คนทั้งหลาย ไม่ว่าจะเป็นกษัตริย์หรือเจ้าเมือง พ่อค้าหรือผู้รับใช้ ทาสหรือนาย ต่างพากันหลบภัยในถ้ำและใต้โขดหิน บนหน้าผาแห่งการต่อสู้ขั้นสุดท้ายระหว่างเทพเจ้าแห่งแสงและปีศาจ ไม่มีใครสามารถยืนต่อหน้าพวกเขาได้\nไม่นานหลังจากนั้น ออโรเรียนจากดินแดนดวงอาทิตย์ขึ้นก็ลุกขึ้นยืน ถือตราประทับของเทพเจ้าแห่งแสงไว้เหนือหัว ประกาศก้องว่า: \"ท้องฟ้า ดิน ทะเล และต้นไม้ จะไม่มีใครทำร้ายผู้รับใช้ของเทพเจ้าแห่งแสงได้ จนกว่าพวกเขาจะประทับตราบนหน้าผาก\" \nเมื่อผู้ส่งสารทำลายผนึกอันที่ 7 โลกก็เงียบสงัด ผู้ส่งสารเรียกออโรเรียนออกมาและมอบแตร 7 อัน ให้กับมัน ออโรเรียนเป่าแตร ทีละอัน ทีละอัน \nเป่าแตรครั้งแรก ไฟและลูกเห็บสีแดงปนเลือดตกลงมาจากท้องฟ้า และหญ้าเขียวขจีบนพื้นโลกก็เริ่มเหี่ยวเฉาและลุกไหม้ \nเป่าแตรครั้งที่ 2 ภูเขาแห่งเปลวเพลิงก็ตกลงสู่ทะเล สังหารสิ่งมีชีวิตทั้งหมดที่อยู่ใต้น้ำ และทำให้มันกลายเป็นดินโคลนที่เปียกโชกไปด้วยเลือด \nเป่าแตรครั้งที่ 3 อุกกาบาตที่ลุกโชติช่วงตกลงมาเหมือนคบเพลิงจากฟากฟ้า ทำให้แม่น้ำและน้ำพุทั้งหมดในโลกแห้งเหือด \nเป่าแตรครั้งที่ 4 ดวงอาทิตย์ ดวงจันทร์ และดวงดาวตกลงมาจากท้องฟ้า ปกคลุมโลกด้วยความมืดมิดตลอดกาล \nเป่าแตรครั้งที่ 5 หลุมลึกก็ปรากฏขึ้นบนพื้น ควันและไฟปะทุออกมา ตั๊กแตนที่หุ้มเหล็กจำนวนนับไม่ถ้วนโผล่ออกมาจากหลุม โจมตีผู้ที่ไม่มีเครื่องหมายของเทพเจ้าแห่งแสง \nเป่าแตรครั้งที่ 6 มีเสียงหนึ่งดังขึ้นว่า \"ปลดปล่อยวิญญาณที่ถูกจองจำในอดีต\" กองทัพพลม้า 300 ล้านนายปรากฏตัวขึ้น ร่างกายของพวกมันเผาไหม้ด้วยเปลวไฟสีม่วงและมีกลิ่นเหม็นของกำมะถัน หัวของม้าคล้ายกับสิงโต มีไฟ ควัน และกำมะถันไหลออกจากปากม้า \"จงออกไปสังหารผู้ที่ทำการฆาตกรรม ใช้เวทมนตร์ ทรยศ และขโมยโดยไม่สำนึกผิดแม้แต่น้อย\" \nเป่าแตรครั้งที่ 7 ออโรเรียนก็ปรากฏตัว หัวของเขาเหมือนดวงอาทิตย์ เท้าเหมือนเสาไฟที่ลุกโชติช่วง เขายืนด้วยเท้าขวาบนทะเล เท้าซ้ายอยู่บนบก แผดเสียงด้วยความดุร้ายยิ่งกว่าสิงโต เมื่อเสียงคำรามของเขาหยุดลง ผู้ส่งสารก็ประกาศว่าทุกอย่างเสร็จสมบูรณ์แล้ว และเขาได้รับข่าวที่น่ายินดีสำหรับผู้รับใช้ทุกคนของเทพเจ้าแห่งแสง \n\"ผู้ใดก็ตามที่ได้รับตราประทับของพระเจ้าของเราจะมีชีวิตอยู่ชั่วนิรันดร์โดยไม่คำนึงถึงฐานะของพวกเขาในชีวิตนี้ หากผู้มีตราประทับปกปิดความเท็จต่อผู้อื่น ก็จะจมอยู่ในหายนะแห่งสงครามเช่นกัน เหล่าผู้ครองตราประทับนั้นจะต้องข้ามธรณีประตูนี้ และถูกทดสอบด้วยไฟและดาบ\" \nการพิพากษาจะมาถึงทุกคน",
  str_dispatch_book_chaptercont_1000_3 = "สงครามและความขัดแย้งยังคงกัดกินโลกนี้ แต่ผู้ที่มีตราประทับของเทพเจ้าแห่งแสงจะสามารถมองเห็นผู้ส่งสาร ผู้กล่าวว่า \"เวลาแห่งการพิพากษามาถึงแล้ว ใครที่มีตราประทับต้องบูชาผู้ที่สร้างสวรรค์ โลก ทะเล และทุกชีวิต\" \nมีเสียงดังมาจากระยะไกล ขณะที่เมืองของคนบาปกำลังล่มสลาย \nมีเสียงตะโกนอีกด้านดังขึ้น กลุ่มคนที่มาสักการะสัตว์ป่าและมีเครื่องหมายที่มือและหน้าผาก พยายามจะข้ามธรณีประตู แต่ถูกผู้ส่งสารของเทพเจ้าแห่งแสงพูดดูหมิ่น “ผู้บูชาเทวรูปจะไม่รู้อะไรเลยนอกจากทุกข์ระทมในไฟและกำมะถัน!” แล้วพวกเขาก็ถูกสาปแช่งไปชั่วนิรันดร์ในนรก \nอีกเสียงหนึ่งบนท้องฟ้าเอ่ยขึ้นว่า \"ตั้งแต่วันนี้เป็นต้นไป จะปรากฏบันทึกไว้ว่าทุกคนที่มีตราประทับของพระเจ้าจะได้รับพร แม้จะตายไปแล้ว ผู้ติดตามเราจะได้ผลตอบแทนจากความยากลำบากมายาวนานของพวกเขา\" \nชาวออโรเรียนปรากฏตัวบนเมฆบนท้องฟ้า สวมมงกุฎทองคำและถือเคียวแหลมคมอยู่ในมือ เขาตะโกนว่า \"ใกล้ถึงฤดูเกี่ยวแล้ว เพราะพืชผลในดินและผลบนต้นไม้สุกงอมแล้ว\" \nภายในวันเดียว ภัยพิบัติทุกรูปแบบมาเยือนแผ่นดินโลก ความตาย ความเศร้าโศก ความอดยาก โรคระบาด และสงคราม ได้โอบล้อมสิ่งมีชีวิตทั้งปวงไว้หมด เพราะบาปของพวกเขาก็สุกงอมแล้วเช่นกัน \nราชาแห่งแผ่นดินโลกที่ยังหลงเหลืออยู่ร่ำไห้และคร่ำครวญเมื่อเห็นควันและไฟที่จะเผาผลาญเขา บรรดาผู้ปรนนิบัติราชาและสนองความปรารถนาของตนเองก็ได้ร้องเศร้าโศกออกมา เพราะพวกเขามีส่วนในชะตากรรมเดียวกัน \nพ่อค้าต่างก็ร้องไห้และสิ้นหวัง เพราะไม่มีใครซื้อสินค้าของตนได้ ทอง เงิน อัญมณี และไหม เครื่องหอม เครื่องเทศ และขี้ผึ้งทุกชนิด ไม้ ผลิตภัณฑ์จากนม ไวน์ และแป้ง วัว แกะ เกวียน และม้า ผู้รับใช้และเจ้านาย ล้วนได้รับผลกระทบ พ่อค้าร้องไห้คร่ำครวญ รู้ว่าความรวยของตนนั้นช่างไร้ความหมาย และความมั่งคั่งของตนนั้นก็ไม่มีค่าอะไรเลย \nชาวบ้านทั่วไปเล่นเครื่องดนตรีและเต้นรำ แต่พวกเขาไม่อาจได้ยินหรือมองเห็นอีกต่อไป ความสนุกสนานของพวกเขาจึงเป็นความโง่เขลา แสงสูญเสียความสว่าง ความปีติสูญเสียเสียงหัวเราะ ความรู้สูญเสียความน่าดึงดูดใจ และสิ่งที่เหลืออยู่ก็คือความว่างเปล่า \nและบรรดาผู้มีตราประทับจะกล่าวจากสวรรค์ว่า \"ความอยู่รอด ความรุ่งโรจน์ และฤทธิ์เดชล้วนมีแก่เทพเจ้าแห่งแสง การพิพากษาของพระองค์คือความชอบธรรม การลงโทษของพระองค์ก็เช่นกัน จงสรรเสริญพระองค์ และข้ามธรณีประตูตั้งแต่บัดนี้จนถึงที่สุด\" \nความเป็นนิรันดร์จะมาถึงทุกคน",
  str_dispatch_book_chaptercont_1000_4 = "ควัน บาป และความชั่วร้ายของโลกไม่สามารถข้ามธรณีประตูได้ เสียงที่ประตูกล่าวว่า \"เวลานี้อาณาจักรแห่งแผ่นดินโลกเป็นอาณาจักรของเทพเจ้าแห่งแสงแล้ว และจะเป็นเช่นนี้ตลอดไป\" \n ผู้มีตราประทับได้ยินเสียงของผู้ส่งสารพูดว่า \"จงบูชาเทพเจ้าแห่งแสง เพราะพระองค์คือผู้ปกครองของเรา\" \n ดังนั้นบรรดาผู้มีตราประทับของพระองค์ก็จะเปรมปรีดิ์ เพราะพระสิริของพระองค์ได้ประทานแก่พวกเขาทั้งหมด พวกเขาสวมเสื้อผ้าสีขาวบริสุทธิ์ซึ่งเป็นสัญลักษณ์ของความชอบธรรมของพวกเขา \n ผู้ส่งสารกล่าวว่า \"เขียนเถิด ผู้ที่มีตราประทับจงมีแต่ความสุข นี่คือพระวจนะที่แท้จริงของพระเจ้าของเรา\" \n บรรดาผู้เชื่อต่างกราบแทบเท้าของผู้ส่งสาร สรรเสริญ แต่สำหรับเรื่องนี้ เขาตอบว่า \"จงหยุดเสีย เพราะเราทุกคนต่างก็เป็นผู้รับใช้ของพระองค์ อย่านมัสการพระเจ้าอื่นใดนอกจากเทพเจ้าแห่งแสง เพราะความหมายของคำพยากรณ์ของพระองค์ คือการเป็นพยานถึงความสง่าผ่าเผยของพระองค์ \" \n “ชาวออโรเรียนผู้หนึ่งลงมาจากฟากฟ้า ถือโซ่ขนาดใหญ่และกุญแจสู่หลุมลึก เขาจะรวบรวมปีศาจทั้งหมด มัดมันด้วยโซ่และโยนมันลงไปในหลุมลึก เขาจะปิดผนึกพวกมันด้วยกุญแจเพื่อไม่ให้เกิดอันตรายอีกต่อไป เมื่อผู้มีตราประทับเริ่มหลงทาง ปีศาจจะได้รับอนุญาตให้กลับคืนสู่โลกอีกครั้งในชั่วคราว” \n ผู้ส่งสารใช้อำนาจของเขาในฐานะตัวแทนของเทพเจ้าแห่งแสงอีกครั้ง เพื่อเรียกวิญญาณของผู้ที่ถูกประหารอย่างผิด ๆ วิญญาณของผู้ที่ไม่ได้บูชารูปปั้นสัตว์ร้ายหรือไม่ประทับเครื่องหมาย แล้วนำพวกเขากลับมามีชีวิตอีกครั้ง เพื่อร่วมยินดีกับคนอื่น ๆ นี่เป็นการฟื้นคืนชีพครั้งแรก และผู้ที่ไม่ได้เป็นส่วนหนึ่งของการฟื้นคืนชีพครานี้จะต้องรอถึงหนึ่งล้านปี \n ผู้ที่เป็นส่วนหนึ่งของการฟื้นคืนชีพครั้งแรก จะได้รับพร มีความบริสุทธิ์ และปีติ พวกเขาจะไม่มีวันตายเป็นครั้งที่สอง และจะทำหน้าที่เป็นนักบวชและผู้ส่งสารของเทพเจ้าแห่งแสงเป็นเวลาหนึ่งล้านปี \n หลังจากหนึ่งล้านปี ปีศาจจะโผล่ออกมาจากหลุมเพื่อทำให้ผู้คนบนโลกหลงผิดและเรียกร้องให้ผู้คนสู้รบ สาวกของเหล่าปีศาจจะมีจำนวนเท่ากับเม็ดทรายในทะเลทราย และจะปกคลุมแผ่นดินโลกเมื่อล้อมรอบที่ตั้งของผู้มีตราประทับ เทพเจ้าแห่งแสงจะโปรยไฟจากฟากฟ้ามาแผดเผาพวกมัน ปีศาจจะถูกโยนลงไปในบึงไฟและกำมะถันอันเป็นที่เดียวกับสัตว์ร้าย จะต้องทนทุกข์ทรมานและถูกเผาไหม้ไปชั่วนิรันดร์ \n หน้าบัลลังก์สีขาว มีคนตายยืนอยู่เกลื่อน ไม่ว่าเด็กหรือผู้ใหญ่ ชายหรือหญิง บันทึกบนบัลลังก์จะถูกกางออก และพวกเขาทั้งหมดจะถูกตัดสินโดยสิ่งที่เขียนไว้ในบันทึกเหล่านี้ แผ่นดิน ทะเล และขุมนรกทั้งมวลได้ถวายวิญญาณผู้ตายของตนเพื่อรับการพิพากษา และถูกโยนลงในบึงไฟ นี่คือความตายครั้งที่สอง \n สวรรค์และโลกใหม่สามารถมองเห็นได้ ในช่วงก่อนหน้านี้ เมืองใหม่ที่รุ่งโรจน์ได้ถูกจัดเตรียมและส่งลงมาจากสวรรค์ มีเสียงหนึ่งดังขึ้นว่า \"ดูเถิด บัดนี้พระเจ้าของเราทรงพระชนม์และปกครองแผ่นดินโลก เพราะพระองค์ประสงค์จะอยู่ท่ามกลางเราในฐานะเพื่อนบ้านและผู้ช่วยให้รอดของเรา\" \n \"เทพเจ้าแห่งแสงต้องการปาดน้ำตาไปจากดวงตาของเรา และอยู่ห่างจากความตาย ความโศก ความเจ็บปวด ความทุกข์ เพราะมันผ่านไปแล้ว\" \n \"ดูเถิด ทุกสิ่งได้ถูกสร้างขึ้นใหม่ ขอให้เขียนว่าสิ่งเหล่านี้เป็นความจริงและคำพูดของเราเป็นความจริง\" \n \"ทั้งหมดเสร็จสมบูรณ์ พวกเราคือจุดเริ่มต้นและจุดสิ้นสุด และผู้ชนะจะได้รับทั้งหมดนี้ ความสง่าราศีของพระเจ้าของเราส่องสว่างทั่วเมือง สว่างกว่าอัญมณีล้ำค่าที่สุด และกระจ่างชัดเจนกว่ากระจก ประตูเมืองจะไม่มีวันปิด เพราะกลางคืนจะไม่มีอีกต่อไป บรรดาผู้ที่เป็นมลทิน ผู้มุสา และกระทำการทารุณกรรม จะไม่มีวันเข้าไปในสถานที่นี้ได้\" \n \"แม่น้ำแห่งชีวิตไหลผ่านเมืองส่องประกายราวกับคริสตัล หล่อเลี้ยงต้นไม้ที่ริมฝั่ง และในทางกลับกัน ผลของมันก็หล่อเลี้ยงผู้คน และรักษาพวกเขาจากความทุกข์ยากและความทรมานทั้งปวง\" \n แล้วผู้ส่งสารจึงกล่าวว่า \"อย่าปิดบังคำพยากรณ์ในหนังสือเล่มนี้ เพราะวันเหล่านี้ใกล้เข้ามาแล้ว\" \n การรู้แจ้งจะมาถึงทุกคน",
  str_dispatch_book_chaptercont_2000_1 = "กว่าพันปีที่ผ่านมา พวกครึ่งมนุษย์เร่ร่อนได้ค้นพบถ้ำที่โดดเด่นแห่งนี้ระหว่างการเดินทางผ่านแอสตรา ในตอนนั้นพวกเขาใช้ถ้ำแห่งนี้เป็นเพียงสถานที่พักชั่วคราว โดยไม่รู้เลยว่ามันจะกลายเป็นแหล่งกำเนิดของยุคเฟื่องฟูของเผ่าพันธุ์ครึ่งมนุษย์\nหลังจากสำรวจมานานหลายทศวรรษ ชาวครึ่งมนุษย์ได้ค้นพบเศษซากทางเทคโนโลยีของอารยธรรมโบราณ พวกเขาคาดเดาว่าผู้คนในอารยธรรมโบราณแห่งนี้ใช้ถ้ำขนาดมหึมาเพื่อทำการทดลอง ในเวลาเดียวกัน พวกครึ่งมนุษย์ที่อาศัยอยู่ในถ้ำก็ตระหนักว่าร่างกายของพวกเขาแข็งแกร่งขึ้นอย่างมากเมื่อเทียบกับตอนเร่ร่อน ความไวต่อลูมินาก็เพิ่มขึ้นเช่นกัน ปรากฏการณ์นี้ น่าแปลกที่ดูเหมือนจะเป็นประสบการณ์พิเศษของพวกครึ่งมนุษย์เท่านั้น แต่ไม่เห็นการเปลี่ยนแปลงใด ๆ ในออโรเรียนและเคเลสไทต์ที่มาเยือน สิ่งเดียวที่เผ่าพันธุ์อื่นสัมผัสได้ก็คือระบบนิเวศภายในถ้ำนั้นมีเอกลักษณ์เฉพาะตัว กล่าวคือ ดูเหมือนว่าจะไม่ได้รับผลกระทบจากฤดูกาลที่เปลี่ยนแปลงไป อากาศภายในถ้ำอบอุ่นและสบายอยู่เสมอ ด้วยเหตุนี้ พวกครึ่งมนุษย์จึงประกาศให้ถ้ำแห่งนี้เป็นดินแดนแห่งคำสัญญาจากสวรรค์ และเมืองขนาดใหญ่ของพวกเขาที่สร้างขึ้นที่นี่จึงได้ชื่อว่าเป็นดินแดนลับ\nหลังจากทำงานหนักมายาวนานกว่าสิบชั่วอายุคน ชาวครึ่งมนุษย์ได้สร้างอารยธรรมอันรุ่งโรจน์และเป็นอิสระให้กับตนเอง ไม่เพียงใช้เทคโนโลยีโบราณของถ้ำเท่านั้น แต่ยังสร้างและปรับปรุงให้ดีขึ้นอีกด้วย บ้านเกิดของครึ่งมนุษย์อันรุ่งโรจน์เป็นศูนย์กลางของความก้าวหน้าทางเทคโนโลยีและอุตสาหกรรมมานานหลายร้อยปี และความเจริญรุ่งเรืองทางการเกษตร... จนกระทั่งถูกรุกรานและบุกรุกโดยภัยคุกคามจากอิคลิพไซท์",
  str_dispatch_book_chaptercont_2000_2 = "\"ระบบระบายอากาศและแสงสว่างได้รับความเสียหายอย่างรุนแรงในช่วงแรกของการโจมตี กลิ่นของดินปืนไม่สามารถกำจัดออกไปได้ แต่ก็ช่วยกลบกลิ่นเหม็นของเลือดในอากาศได้ดี อิคลิพไซท์ที่ดุร้าย ร่างกายของพวกมันบิดเบี้ยวไปมาในควัน ฆ่าอย่างไม่เลือกหน้าโดยไม่ลังเลและไม่รู้สึกผิดชอบชั่วดี พวกมันไม่จับเป็น และสังหารพลเมืองทั้งหมดที่ถูกจับกุมโดยไม่มีข้อยกเว้น เหมือนสัตว์อสูร\nพวกของเราบางคนพยายามที่จะต่อสู้และแย่งชิงเด็กจากเงื้อมมือของกลุ่มอิคลิพไซท์... แต่กลับไม่อาจหลบหนีพวกมันได้พ้น ต้องตกเป็นเหยื่อของกรงเล็บสัตว์ประหลาด เราขาดการติดต่อกับแนวหน้าเมื่อสองสามชั่วโมงก่อน... เกรงว่าคงมีสิ่งที่เลวร้ายที่สุดเกิดขึ้นกับพวกเขา ความหวังเดียวของเรา... คือผู้คนที่หลบหนีไปยังทางเดินใต้ดิน เราสวดภาวนาต่อชะตากรรมขอให้ลูกหลานไปถึงที่นั่นอย่างปลอดภัย... ฉันจะไม่มีวันลืมสิ่งที่เห็นในวันนั้น คนของเรานอนตายอยู่บนถนน ถูกบดขยี้ในซากโบราณ แววสุกสกาวในดวงตาของพวกเขาหายไป... ศพกองสูงตระหง่านในทิวทัศน์ที่มีเปลวเพลิงและเสียงกรีดร้องแห่งความทรมาน...\nบ้านเกิดอันแสนงดงามของเราถูกเปลี่ยนไปเป็นนรกบนดิน สำหรับบาปที่พวกมันก่อ...พวกอิคลิพไซท์ชั่วร้ายจะต้องชดใช้!\"\nตัดตอนมาจากสมุดบันทึกที่ทีมสำรวจอิลลูมินาพบในดินแดนลับ",
  str_dispatch_book_chaptercont_2000_3 = "จากคำบอกเล่าของผู้อาวุโส เราน่าจะเป็นนักสู้กลุ่มสุดท้ายที่จะเข้าไปในถ้ำ ฉันเรียกพวกเขาว่า \"ผู้อาวุโส\" แต่ความจริงแล้วพวกเขาก็เป็นเพียงกลุ่มพวกครึ่งมนุษย์รุ่นเยาว์ ผู้อาวุโสที่แท้จริงซึ่งมีอายุยืนยาวกว่าพินาศไปนานแล้วในการต่อสู้กับภัยคุกคามจากอิคลิพไซท์ \nแม้ว่าเราจะเตรียมใจไว้หลังจากได้รับสัญญาณขอความช่วยเหลือ ว่าอาจต้องเจอสถานการณ์ที่เลวร้ายที่สุด แต่เมื่อเห็นถ้ำอันยิ่งใหญ่ของเราถล่มกลายเป็นซาก... เมื่อเราเห็นกองซากศพของเพื่อนครึ่งมนุษย์ของเรา... ใน ทิวทัศน์ดุจดังนรกนี้ เราทุกคนล้วนสูญเสียความมุ่งมั่นที่จะต่อสู้ โชคดีที่คำพูดอันเมตตาและปลอบโยนของผู้อาวุโสทำให้เรามีสติ แม้พวกเขาจะดูอ่อนกว่าเราแค่ไม่กี่ปี แต่ฉัน...\nพวกชั่วอิคลิพไซท์ พวกมันจะต้องชดใช้ในสิ่งที่พวกมันก่อ! หัวของพวกมันร้อยหัวต่อครึ่งมนุษย์หนึ่งคนที่ตายไป! พวกเราไม่มีใครลืมใบหน้าของเหล่าสหายขณะชีวิตพวกเขาถูกพรากไปได้... แต่เราสูญเสียบ้านของเรา ชีวิตของเรา... พวกมันจะเอาอะไรไปจากเราอีก ไม่มีที่พึ่งอื่นใดสำหรับครึ่งมนุษย์อย่างพวกเราในดินแดนแห่งนี้แล้วหรือ งั้นเราก็จงยืนหยัดต่อสู้กับผู้รุกรานเป็นครั้งสุดท้ายและตายเหมือนเพื่อนร่วมชาติของเราไปดีกว่า กองทับถมกันโดยไม่คำนึงถึงอายุหรือสถานะ พวกเขาได้สละชีวิตเพื่อปกป้องบ้านของเรา ดังนั้นตอนนี้ก็ถึงตาเราแล้วที่จะทำเช่นเดียวกัน ให้เลือดอิคลิพไซท์เป็นชุดงานศพของเรา และให้ศพของพวกมันเป็นสุสานของเรา! เราจะต่อสู้เพื่อบ้านของเรา จนถึงวินาทีสุดท้าย... \nตัดตอนมาจากสมุดบันทึกของครึ่งออโรเรียน ครึ่งมนุษย์นิรนาม",
  str_dispatch_book_chaptercont_2000_4 = "เมื่อฉันนึกถึงกระดูกเหี่ยวเฉาที่ทิ้งเกลื่อนกลาดตามซากปรักหักพัง... หรือทหารผู้กล้าหาญของ Illumina ที่ไม่เคยละทิ้งอาวุธของพวกเขา แม้ชีวิตจะเลือนหายไปจากสายตา... การเดินทาง. \nการสูญพันธุ์ของพวกเดมิมนุษย์เกิดขึ้นเมื่อหลายร้อยปีก่อน และตอนนี้พวก Eclipsites เป็นจ้าวแห่งถ้ำ สิ่งที่เราในฐานะคนนอกเลือกที่จะเรียกมันไม่ได้เปลี่ยนแปลงข้อเท็จจริงนั้น ยิ่งไปกว่านั้น การโจมตีของ Eclipsite ต่อการตั้งถิ่นฐานอื่น ๆ ได้หยุดลงหลังจากที่พวกเขาบุกรุกบ้านเกิดของ Demi-Human ดูเหมือนว่าพวกเขาจะพอใจที่จะมีชีวิตอยู่และถูกทิ้งให้อยู่ตามลำพังในส่วนลึกของดินแดนลับ พวกเราไม่มีใครรู้ว่าพวกเขาทำอะไรในนั้นอย่างแท้จริง... \nนั่นเป็นเหตุผลที่เราตกลงที่จะค้นหา \nในตอนแรก ทีมงาน Illumina Expedition เต็มไปด้วยความกล้าหาญและการมองโลกในแง่ดี โดยหวังว่าพวกเขาจะเป็นคนที่จัดการกับ Eclipsites อย่างเด็ดขาด ความคิดของพวกเขาคือการปกป้องคนที่ตนรัก และสหพันธ์อิลลูมินา... แต่ในไม่ช้าความเป็นจริงก็แสดงให้ทุกคนเห็นถึงความโง่เขลาของการมองโลกในแง่ดีของพวกเขา เมื่อเวลาผ่านไป สมาชิกทีม Expedition จำนวนนับไม่ถ้วนถูกสังหารโดย Eclipsites ที่อาศัยอยู่ในถ้ำ หรือไม่ก็สูญหายไปในส่วนลึกอันกว้างใหญ่ของ Secret Territory ในบางกรณี ทีมงานทั้งทีมจะหายไปและจะไม่ปรากฏให้เห็นอีก การต่อต้านคณะสำรวจเพิ่มขึ้นเมื่อเวลาผ่านไป อย่างไรก็ตาม ผู้นำของอิลลูมินายืนยันที่จะเดินทางเพื่อ \"ค้นพบความจริง\" แรงจูงใจที่เรียบง่ายนี้เกิดจากความเชื่อของอิลลูมินา ส่งผลให้เกิดการสูญเสียทหารผู้กล้าจำนวนนับไม่ถ้วน ตลอดจนความโศกเศร้าตลอดชีวิตของครอบครัวและบุคคลอันเป็นที่รักของพวกเขา \nในที่สุด ผู้แปรพักตร์ก็กลายเป็นเรื่องธรรมดาในแนวหน้า และเราก็อยู่ในหมู่พวกเขา เราละทิ้งสหายที่ล่วงลับของเรา เพิกเฉยต่อคำสั่งของเรา และหนีออกจากดินแดนลับโดยที่ชีวิตไม่เสียหาย สันนิษฐานได้ว่า เราถูกจัดประเภทเป็น \"ผู้สูญหายขณะปฏิบัติการ\" ในบันทึกสาธารณะของอิลลูมินา แต่บันทึกทางทหารของเรามักจะระบุว่าเราเป็นผู้ละทิ้งหน้าที่ เกิดอะไรขึ้นกับญาติของเรา? พวกเขาถูกลงโทษเพราะความขี้ขลาดของเราหรือไม่? ฉันเกรงว่าเราจะไม่มีทางรู้ เพราะไม่มีการกลับมาที่สหพันธ์สำหรับเรา เราไม่มีทางเลือกอื่นนอกจากใช้ชีวิตที่เหลืออยู่ในทะเลทรายแห่งนี้ \nแม้ว่าฉันจะคิดถึงครอบครัวและบ้านเกิดของฉันเป็นครั้งคราว แต่ความตั้งใจที่จะมีชีวิตอยู่นั้นมีค่ามากกว่าความคิดถึงบ้าน ในตอนท้ายของวัน เรายังมีชีวิตอยู่ และตอนนี้เรามีทะเลทรายทั้งหมดที่จะเรียกว่าบ้าน ในบางแง่ ฉันคิดว่าการรู้ว่าเมื่อใดควรยอมแพ้เป็นภูมิปัญญาในแบบของมันเอง หากเราอุทิศตนเพื่อบ้านเกิดเมืองนอนของเราเหมือนกับที่พวกเดมิมนุษย์ในตอนนั้น เรามีเพียงสองทางเลือก: สำรวจดินแดนลับและถูกสังหารโดย Eclipsites หรือฝ่าฝืนคำสั่งและกลับบ้านเพื่อถูกทดลองและประหารชีวิต ไม่ว่าจะด้วยวิธีใด ความตายเป็นเพียงผลลัพธ์เดียว \nเมื่อเร็ว ๆ นี้เราไม่ได้รับข่าวใด ๆ เกี่ยวกับการสำรวจดินแดนลับของสหพันธ์อิลลูมินา พวกเขาน่าจะยอมแพ้ไปแล้ว เนื่องจากนครรัฐอื่นๆ ก็ไม่ได้แสดงท่าทีว่าจะพยายามต่อไปเช่นกัน ดูเหมือนว่าโลกทั้งใบจะยอมรับในที่สุดว่าดินแดนแห่งความลับเป็นสถานที่สาบสูญ สถานที่ซึ่งอยู่ภายใต้การควบคุมของ Eclipsites และไม่มีใครอื่น และนั่นเป็นสิ่งที่ดีฉันคิดว่า ดินแดนลับและอิลลูมินา กึ่งมนุษย์และสุริยุปราคา เราเบื่อมันทั้งหมด \nบัญชีโดยตรงของสมาชิก Rediesel Wrench รุ่นแรกที่ไม่ประสงค์จะออกนาม",
  str_dispatch_book_chaptercont_3000_1 = "งานต่อไปของฉันคือไปที่ _____ และกวาดล้างคนทรยศที่ซุกซ่อนอยู่ในนั้น การจ่ายเงินนั้นยอดเยี่ยมมาก ฉันพยายามประหยัดค่าใช้จ่ายส่วนใหญ่ แต่การคำนวณค่าอาหารและค่าใช้จ่ายอื่นๆ เป็นเรื่องที่น่าปวดหัวมาก... แต่ถ้าฉันไม่ทำงานพิเศษ ฉันคงไม่มีทีมทหารรับจ้างที่เหมาะสมเป็นของตัวเอง ใช่ไหม ? เราจะต่อสู้เพื่อเศษผ้าจากชุดที่ใหญ่กว่านี้ไปตลอดชีวิต เหมือนที่ฉันกำลังทำอยู่ตอนนั้น... ฉันจึงบอกตัวเองให้เก็บออมต่อไป! ฉันยังไม่ได้คิดชื่อทีมของฉันในตอนนั้น แต่ก็ไม่ต้องรีบร้อนที่จะทำเช่นนั้น \nภูมิประเทศของ _____ ซับซ้อนกว่าที่ฉันคิดไว้มาก ตามภารกิจ เราต้องตามทีมทหารรับจ้างอีกทีมเข้าไปในทางเดินใต้ดินและแอบเข้าไป... แต่เราไม่รู้ว่าทางเดินนั้นเป็นอย่างไร และเนื่องจากเป็นปฏิบัติการลับ เราจึงใช้ของเราไม่ได้ อาวุธ ฉันกังวลเล็กน้อยเกี่ยวกับภารกิจ หากมีกับดักหรือซุ่มโจมตีรอเราอยู่ในทางเดินนั้น โชคดีที่เราผ่านมันไปได้โดยไม่มีปัญหา ฉันเห็นจิ้งจกวิ่งผ่านเท้าฉันไประหว่างทางด้วยซ้ำ \nเมื่อเราเดินทางผ่านทางนี้ เราก็อยู่ใน _____ ผืนแผ่นดินหลังฝังทะเล ทางเดินที่ไม่มีใครอยู่นั้นพาเราตรงไปยังที่ซ่อนของศัตรู สถานที่นั้นเละเทะไปหมด แต่ไม่ใช่จากการต่อสู้ใดๆ เท่าที่เราบอกได้ ศัตรูไม่มีเวลาทำความสะอาดหรือไม่ต้องการทำความสะอาด พื้นดินเกลื่อนไปด้วยขยะ เสื้อผ้าสกปรก และอาหารที่กินไม่หมด ดูเหมือนว่าพวกเขาจะไม่พร้อมสำหรับการโจมตี \nเรานำพวกมันออกไป ง่ายและรวดเร็ว ทุกอย่างเป็นไปตามแผน... แต่ฉันรู้สึกว่าเราเสียกระสุนไปมากเกินความจำเป็น เราใช้ระเบิดห้าหรือหกแพ็ค ทั้งหมดมาจากสต็อกของเราเอง แต่พวกของฉันยืนยันกับฉันว่าเราสามารถซื้อวัตถุระเบิดเกรดทางการทหารจริง ๆ ด้วยค่าจ้างของเรา ถ้าเราทำงานถูกต้อง แน่นอนว่าพวกเขามองโลกในแง่ดี แต่ฉันอยากทำเงินเพิ่มจริงๆ \nโอ้ และในที่สุดฉันก็ตัดสินใจเลือกชื่อสำหรับทีมของฉัน ฉันเรียกเราว่า Bomb Squad เพราะเราโจมตีเหมือน TNT และเรามักจะให้ผลตอบแทนที่คุ้มค่าแก่ลูกค้าเสมอ!",
  str_dispatch_book_chaptercont_3000_2 = "ค่าตอบแทนสำหรับงานล่าสุดของเราคือพีนัท เมื่อเทียบกับสิ่งที่เราคาดไว้... แต่เราก็ทำอะไรไม่ได้ เมื่อเราเดินทางไปหานายจ้างเพื่อรับเงิน เราถูกฝูงอิคลิพไซท์ซุ่มโจมตี และนายจ้างถูกกิน ที่เราทำได้คือซ่อนตัวจนกว่าพวกอิคลิพไซท์จะจากไป จากนั้นค้นหาว่าเขาเหลืออะไรบ้างสำหรับค่าจ้างของเรา และค้นซากปรักหักพังไปด้วย เราพบกระเป๋าเหรียญอยู่บ้าง แต่ก็เท่านั้น ไม่สามารถต่อรองกับนายจ้างได้จริง ๆ ในสถานการณ์แบบนี้ คุณก็รู้นี่ \nเราก็เลยนั่งล้อมวงและคุยกันว่าจะรับงานไหนต่อ คุณพอจะนึกออกมั้ย? เราไม่มีทางเลือกแล้วจริง ๆ! มีอยู่ 2 งานในตอนนี้: งานแรกจาก _____ ให้ไปฆ่าสมาชิก_____ ส่วนอีกงานมาจาก _____ ให้ไปฆ่าสมาชิก _____ เราคิดว่ามันสนุกมากที่_____ และ_____ บังเอิญมาจ้างเราในเวลาเดียวกันแบบนี้ เราเลยต้องเลือกว่าจะจัดการใคร: _____ หรือ _____? \nฉันคิดว่าจะจัดการ_____ ให้กับ _____ เพราะฉันไม่ชอบ_____เลย พวกเขาเอาแต่พล่ามเรื่องความเสมอภาคและความชอบธรรมซ้ำแล้วซ้ำเล่า แต่นั่นเป็นเพียงวิธีที่พวกเขาหลอกล่อให้ผู้คนที่อยู่ภายใต้พวกเขายอมขายชีวิตให้ก็เท่านั้น ถ้ามันยุติธรรมจริง ๆ ทำไมเราไม่ได้รับอนุญาตให้ลงไปใต้ดินเพื่อลี้ภัยล่ะ พวกเขาไปเอาทรัพยากรมาจากไหน ทรัพยากรที่พวกเขาไม่คิดจะแบ่งให้เรา แล้วยังมีเจ้านายของพวกเขาอีก... ถ้าทุกคนเท่าเทียมกันภายใต้กฎหมายจริง ๆ ทำไมเขาไม่ใส่เสื้อผ้าแบบเดียวกับทหารทั่วไป หรือใช้อาวุธแบบเดียวกัน หรือนอนในที่เดียวกันล่ะ\nแต่หนึ่งในพวกเราคิดว่าสังหาร _____ ให้ _____ ดูจะยากเกินไป เพราะการป้องกันของ_____ดูจะไร้ช่องโหว่ ยังไงก็ตามในแง่ของความยาก ไม่ง่ายกว่าเหรอที่จะสังหาร _____ ให้_____? ฉันหมายถึง _____ อยู่ใน_____ เนี่ย! \n\"ยังไงก็ได้\" ฉันพูด \"เลือกมาสักอย่าง ไม่สำคัญหรอกตราบเท่าที่พวกเขาจ่ายเงิน ถูกมั้ย?\" ฉันต้องทำงานให้หนักขึ้น ถ้าฉันต้องการสร้างทีมทหารรับจ้างของตัวเอง... แม้ว่าฉันจะไม่ใช่พวกที่ชอบเสี่ยงแทนพวกขี้โมโหจอมอวดอย่าง_____ก็ตาม",
  str_dispatch_book_chaptercont_3000_3 = "ไม่ว่าจะเป็นสังหาร_____ ให้กับ_____ หรือสังหาร_____ ให้_____ เราก็ไม่ได้เลือกสักอย่าง หลังจากคุยกับทุก ๆ คนแล้ว เรารู้สึกว่าการป้องกันของทั้ง_____ และ_____ต่างก็แข็งแกร่งเกินไปที่จะทำลาย เราต้องการค้อนใหญ่เท่าเมืองหรือสว่านขนาดใหญ่เลยทีเดียวหากเราต้องการทำงานนี้ แต่เราไม่เหลือเงินจนเริ่มอดอยากเต็มทีแล้ว เราจะไปเอากระสุนมาโจมตีแบบนี้ได้จากที่ไหน ส่วนใหญ่เราทำได้แค่ใช้ดาบ มันเป็นงานที่ไม่คุ้มเอาซะเลยสำหรับทีมเรา และกานเห็นเงินของเราต้องเสียไปเปล่า ๆ คือเรื่องที่แย่ที่สุด... \nการไม่รับสองงานนั้น ทำให้เงินของเราเริ่มร่อยหรอ ลืมเรื่องตั้งทีมของตัวเองไปได้เลย เงินจะไปซื้ออาหารยังแทบจะไม่มี โชคดีที่เราเจองานปลายแถวที่พอจะช่วยพลิกสถานการณ์ของเราได้บ้าง ใครจะปฏิเสธอาหารสามมื้อต่อวัน และหลังคาคุมหัวตอนนอนกันล่ะ ปัญหาคือพวกเพื่อนในทีมไม่ชอบเก็บกวาดบ้านและทำงานสวนให้คนอื่น ความอับอายมีผลต่อกำลังใจของพวกเขา ในทางกลับกันสำหรับฉัน กลับคิดว่านี่มันดีกว่าการเป็นทหารรับจ้างที่ต้องฆ่าฟันผู้อื่นเสียอีก! นี่หมายความว่าฉันไม่มีความเหมาะสมที่จะเป็นทหารรับจ้างเลยใช่มั้ย? \nฉันกำลังทำความสะอาดห้องตอนที่ผู้เช่าไม่อยู่ ฉันบอกได้เลยว่าห้องนั้นน่าจะเป็นของสาวน้อยน่ารัก เตียงนอนนุ่มราวกับก้อนเมฆ และมีผ้าห่มสีชมพูขนาดใหญ่ที่มีตุ๊กตาหมีนั่งอยู่ด้านบน หูของหมีข้างหนึ่งมีรอยฉีกขาด ดังนั้นเมื่อทำความสะอาดเสร็จแล้ว ฉันคิดว่าฉันจะซ่อมมันให้เธอเพราะฉันก็ไม่มีอะไรทำแล้ว ตอนเห็นว่าฉันใช้เข็มและด้ายได้เร็วและว่องไวเพียงใด ฉันก็รู้สึกว่าตัวเองไม่เหมือนทหารรับจ้างเลยสักนิด \nแต่จะว่าไปแล้ว ทุกคนในทีมของฉันเก่งเรื่องงานเย็บผ้ากันหมด เสื้อของเรามักฉีกขาดตอนไปทำภารกิจ แล้วเราก็ไม่มีเงินซื้อใหม่ เราเลยมีฝีมือเรื่องเย็บผ้าเพื่อคอยซ่อมแซมเสื้อผ้าของตัวเอง นี่หากเราไม่ได้เป็นทหารรับจ้าง เราน่าจะลองเปิดธุรกิจเย็บปักถักร้อยดูนะ เราคงจะทำเงินได้มากเลย และมันก็ปลอดภัยกว่าด้วย \nธันวาคม",
  str_dispatch_book_chaptercont_3000_4 = "ฉันไม่ได้เขียนบันทึกตั้งแต่เลิกเป็นทหารรับจ้าง เปิดขึ้นมาอีกครั้งรู้สึกคิดถึงจริงๆ \nถึงอย่างนั้นฉันก็ดีใจที่ได้จบชีวิตนั้นเสียที กลายเป็นว่าฉันไม่เคยถูกไล่ออกจากการต่อสู้หรือหาอาวุธและกระสุน ดังนั้นโดยธรรมชาติแล้วฉันจึงไม่สามารถทำภารกิจอันตรายเหล่านั้นให้สำเร็จได้เหมือนแต่ก่อน ฉันต้องการสร้างชุดทหารรับจ้างของตัวเอง แต่ฉันไม่เคยทำเงินได้มากพอที่จะทำ และสุดท้าย... พวกเราทั้งหมดก็ไป _____ เพื่อทำความสะอาดบ้านและหาเงินแทน มันเป็นสิ่งที่น่าละอายที่สุดในโลกสำหรับเรา \nน่าอายที่เราค้นพบได้อย่างรวดเร็วว่าการทำงานที่ให้อาหารและที่อยู่อาศัยแก่เรานั้นไม่ได้เลวร้ายนัก ฉันเคยเย็บตุ๊กตาหมีของเด็กผู้หญิงตัวเล็กๆ ครั้งหนึ่ง และพบว่าฉันมีความสามารถพิเศษด้านการเย็บผ้า ฉันบอก _____ ว่าทีมของฉันและฉันค่อนข้างมีพรสวรรค์ในการใช้เข็มและด้าย ในเวลานั้น ฉันรู้สึกภาคภูมิใจในทีมและตัวฉันเองมากกว่าครั้งไหนๆ ในฐานะทหารรับจ้าง \nและแล้ว สิ่งเหลือเชื่อก็เกิดขึ้น! _____ ประทับใจในฝีมือการตัดเย็บของเรามากจนได้รับอนุญาตให้เปิดร้านตัดเสื้อของเราเอง! ในขณะนั้น เราเลิกเป็นกองทหารรับจ้างเร่ร่อน และกลายเป็นสมาชิกที่น่าภาคภูมิใจของร้านตัดเสื้อคุณภาพสูงของ _____! ชื่อร้านของเราก็ยอดเยี่ยม: the Bomb Outfitters เรากำลังจะใช้ชื่อที่คล้ายกันสำหรับทีมทหารรับจ้างของเรา แต่ดูดีกว่าในร้านค้าของเรา \nธุรกิจของ Bomb Outfitters นั้น... เฟื่องฟูจนพูดไม่ออก ผู้คนจาก _____ และ _____ มาหาเราเพื่อความต้องการด้านเสื้อผ้าทั้งหมดของพวกเขา ฉันยังคงไม่สนใจ _____ มากนัก ฉันจึงเย็บกระดุมให้แน่นเกินไปเสมอ เพื่อทำให้อึดอัด ปรากฎว่าพวกเขาชอบมันจริง ๆ โดยบอกว่ามันช่วยให้ทหารของพวกเขาอยู่ในแนวเดียวกัน ทั้งหมดที่ฉันต้องพูดคือ ถ้าพวกคุณสนใจเรื่องความยุติธรรมและความเท่าเทียม ทหารของคุณอ้วนลงพุงได้อย่างไร \nไม่ว่าในกรณีใด ชีวิตการเป็นช่างตัดเสื้อนั้นดีกว่าชีวิตการเป็นทหารรับจ้างมาก และสหายของผมก็คิดเช่นนั้นเช่นกัน หนึ่งในนั้นกำลังเก็บเงินเพื่อแต่งงานกับคนรักในชีวิตของเขา และฉันก็กำลังคิดที่จะเริ่มต้นครอบครัวของฉันเองเช่นกัน เรากำลังคิดที่จะเริ่มต้นแบรนด์เสื้อผ้าทหารของเราเอง: Bomb Fatigues สักวันหนึ่ง ทั้ง _____ และ _____ จะขอทานชุดทหารของพวกเขาในแบรนด์ของเรา! \nเอาล่ะพอแล้วสำหรับวันนี้ ฉันจะเขียนเพิ่มเติมเมื่อฉันมีเวลา ร้านค้าทำตามคำสั่งหู แต่งานมากขึ้นหมายถึงเงินมากขึ้น! ฮ่าๆ!",
  str_dispatch_book_chaptercont_4000_1 = "พระคัมภีร์: \nและเธอพูดว่า: \"ความจริงไม่อาจมองเห็นได้ด้วยตาเปล่า แต่ความจริงสามารถมองเห็นฉันได้ด้วยตาของมันเอง เมื่อความจริงมองมาที่ฉัน ฉันจะได้ยินเสียงของมันและรู้ว่ามันอยู่ที่ใด\" \n\"ไม่ ฉันปฏิเสธความจริงของเธอ เธอเป็นแค่ร่างปีศาจ รอยยิ้มของเธอชั่วร้ายกว่าสายตาของอิคลิพไซท์ ความงามของเธอเลวร้ายกว่าโศกนาฏกรรมของโลก\" \nเธอพูด: \"ฉันจะไม่ปฏิเสธเธอ เช่นเดียวกับที่ไม่ปฏิเสธความจริง\" เธอหันมา และชุดสีแดงของเธอก็เต้นระบำไปกับเธอ ชุดนั้นพิเศษ มันเคลื่อนไหวเหมือนสายน้ำ เธอหันมาอีกครั้ง และชุดหันมาพร้อมกับเธอ ห่อหุ้มเธอ ห่อหุ้มฉัน \n\"ไม่ ฉันปฏิเสธความจริงอีกครั้ง\" ชุดแดงเคลื่อนไหวเหมือนมีชีวิต ลากไปตามพื้น แนบกับผิวฉัน เธอหมุนตัวเป็นวงกลม ชุดของเธอพลิ้วไสวเหมือนหิมะในสายลม หล่นมาที่พื้น หล่นมาที่ฉัน หล่นไปที่ริมฝีปากฉัน กลิ่นประหลาดของดอกไม้ที่จมูกของฉัน เหมือนเลือดที่ไหลเวียนในร่างกาย \nเธอพูดว่า: \"ฉันยินดีต้อนรับคุณ ฉันหวังว่าคุณจะสนุกกับมัน\" ขนตาของเธอปกลงมาราวกับผ้าม่าน เสียงของเธอน่าฟังเหมือนเสียงของธรรมชาติ เธอมองมาที่ฉัน \n“ไม่ ฉันปฏิเสธความจริงของเธออีกครั้ง” เลือดไหลออกจากร่างกายของเธอ มันก่อตัวเป็นชุดชั้นใน จากนั้นก็เป็นชุดของเธอ แล้วก็พรมแดงอยู่ใต้เท้าของเธอ มันก่อตัวเป็นมงกุฎสีแดงเลือดบนศีรษะของเธอ \nสายตาของเธอยังอยู่ที่ฉัน สายตาของเธอเพ่งมาที่ฉัน ดวงตาบนร่างกายของเธอจ้องมาที่ฉัน ดวงตาในมือของเธอจ้องมาที่ฉัน ดวงตาบนอกของเธอจ้องมาที่ฉัน ดวงตาบนเข่าของเธอจ้องมาที่ฉัน ดวงตาบนหลังของเธอจ้องมาที่ฉัน ดวงตาบนหัวของเธอจ้องมาที่ฉัน \nเธอเห็นฉัน ฉันถูกเธอเห็น ถูกเธอเพ่งพินิศ ฉันถูกความจริงเพ่งพินิศ \n“ไม่ ฉันปฏิเสธความจริงของเธอเป็นครั้งที่สี่” แต่การปฏิเสธของฉันไม่มีความหมาย เธอใช้ตาบนร่างกายของเธอมองดูฉัน และดวงตาที่ปรากฏบนร่างกายของฉันก็มองดูฉันเช่นกัน ตาบนมือของฉันจ้องมาที่ฉัน ตาบนหลังของฉันจ้องมาที่ฉัน ตาบนหัวของฉันจ้องมาที่ฉัน ความจริงได้ทำให้ดวงตาปรากฏบนร่างกายของฉัน และตั้งแต่นั้นเป็นต้นมา ไม่ว่าฉันจะอยู่ที่ไหนหรือทำอะไรก็ตาม... ความจริงกำลังเฝ้ามองอยู่เสมอ \n“ความจริงปรากฏบนร่างกายของคุณ และมันจะคอยเฝ้ามองคุณอยู่เสมอ” \nนี่คือสิ่งที่เธอบอกฉัน",
  str_dispatch_book_chaptercont_4000_2 = "ความจริงอยู่รอบตัวเรา ในแม่น้ำทุกสายที่ไหลเชี่ยว บนทุ่งหญ้าทุกแห่ง ในท้องฟ้าที่มืดมิด และในคืนที่ไม่มีที่สิ้นสุด \nอยู่บนตาและกิ่งของต้นไม้ทุกต้น และในทุกเมล็ด ดอกและผล บนเส้นทางที่เป็นโคลนทุกแห่ง และข้าง ๆ น้ำตกที่แห้งแล้งทุกแห่ง \nมันอยู่ในอากาศและด้านหน้าเรา รอบ ๆ ผิวหนังและใต้เท้าของเรา มันอยู่ในทุกลมหายใจที่เข้าสู่ปอดของเรา และแสงตะวันทุกที่เข้าสู่จอประสาทตาของเรา มันเดินตามหลังเราตลอดเวลา ผ่านร่างกายเราไปเบา ๆ \nมันอยู่ที่ริมฝีปากของเรา ฟันของเรา ปากของเรา คอของเรา และท้องของเรา มันถูกย่อย ดูดซึมเข้าสู่ร่างกายของเรา และผ่านเข้าสู่กระแสเลือดของเรา \nมันถูกส่งไปตามเส้นประสาทไปยังทุกซอกทุกมุมของร่างกายเรา: ไปยังตับ ถุงน้ำดี ลำไส้เล็กและลำไส้ใหญ่ ตับอ่อน ม้าม และไต มันทะลุผ่านกระดูกของเรา: กระดูกโคนขา กระดูกหน้าแข้งและน่อง ข้อเท้า และนิ้วเท้า \nเจ็บปวดเหมือนนิ้วชนเข้าที่ขาโต๊ะ \nมันถูกส่งไปตามเส้นประสาทไปยังศูนย์กลางของร่างกาย ไปยังหัวใจ หลอดลม ฐานลิ้น โพรงจมูก เส้นประสาทตา ก้านสมองและสมอง จากกะโหลกศีรษะ มันผ่านกระดูกสันหลัง ไปยังสะบัก ข้อศอก ข้อมือ และนิ้ว \nเจ็บปวดเหมือนโดนถอดเล็บ \nมันถูกส่งผ่านเส้นประสาทไปยังส่วนลึกที่สุดของร่างกายของเรา ไปยังไขกระดูก สายสะดือ ช่องท้องและเข้าไปในกะโหลกศีรษะของเด็กที่ยังไม่เกิด ต้นกล้าเติบโตในจิตใจของทารก หล่อเลี้ยงด้วยความคิดของมัน และผลิบานเป็นดอกไม้ที่สวยงาม กลีบดอกของมันหยดด้วยสีอันศักดิ์สิทธิ์ \nความคิดของพระเจ้าแตกเป็นชิ้น ๆ นับไม่ถ้วนและแทรกซึมสู่ทารก นำพาทารกนั้นเข้าสู่โลกที่เปียกโชกในความเป็นพระเจ้า แผ่นดินที่ทารกมาเยือนนั้นเป็นดินแดนรกร้างว่างเปล่าอันกว้างใหญ่ ทุก ๆ เสียงร้องของทารกผลิออกเป็นดอกไม้ตูม และน้ำตาทุกหยดที่ทารกหลั่งออกมาจะทำให้โลกรอบตัวเต็มไปด้วยความศักดิ์สิทธิ์ ขณะที่ทารกน้อยยังคงร้องไห้ ท้องฟ้าก็หลั่งน้ำตาแห่งความศักดิ์สิทธิ์เช่นกัน ดอกไม้บานรอบตัวของทารก และพื้นที่รกร้างกลายเป็นทะเลแห่งดอกไม้ศักดิ์สิทธิ์ \nความจริงอยู่รอบตัวเรา",
  str_dispatch_book_chaptercont_4000_3 = "ฉันจะอธิบายความรู้สึกนี้ยังไงดี \nมันมีลักษณะเหนียว เป็นโคลน และผสมปนเปกันไปหมด ฉันเอื้อมมือเข้าไป รู้สึกลื่น และเรียบเนียน โดยมีสสารที่เป็นของแข็งลอยอยู่ภายใน ฉันสามารถบีบ ฉันสามารถนวด และฉันสามารถกวนมันได้ ฉันไม่สามารถหลอมรวมเข้ากับมันได้ แต่มันก็ยังคงจับฉันไว้แน่น ความอบอุ่นแผ่ไปทั่วไหล่ของฉัน \nมันคือสิ่งมีชีวิต \nเนื้อของมันสดแล้วก็นุ่ม เต็มไปด้วยสารอาหาร และสามารถปรุงได้หลายวิธี ไม่ว่าจะเป็นการทอด ย่าง ปิ้ง นึ่ง หรือตุ๋น ตอนที่ฉันซื้อมา บรรจุภัณฑ์เขียนไว้ว่ารสชาติจะดีที่สุดเมื่อปรุงทั้งเป็น \nว่าแต่จะตัดเนื้อได้ยังไง? ทุกครั้งที่ตัด มวลที่เหนียวเหนอะหนะจะหนีใบมีดของฉัน ทำให้มันไหลเลื่อนลงมาด้านข้าง ฉันกดมันไว้ เล็งส่วนที่หนาที่สุด แล้วเลื่อนคมมีดเข้าไป สารคล้ายเมือกบนพื้นผิวจับใบมีดของฉันเหมือนปากยักษ์ ไม่ยอมให้ฉันตัดมันสักที \nน้ำเดือดแล้ว ฉันเสียเวลามามากพอแล้ว เลยใส่ลงไปในหม้อทั้งตัว ค่อย ๆ ใส่ลงข้างหม้อให้มันไหลลงไปในน้ำที่เดือดปุด ๆ นี่ฉันคิดไปเองรึเปล่านะ? ดูเหมือนว่าเนื้อจะหัวเราะเยาะฉันอยู่ มันบิดตัวและยิงฟันหยัก ๆ ของมันเสี้ยววินาทีที่เยื่อเมือกของมันละลายในน้ำ \nมันส่งเสียงด้วย มันกำลังหัวเราะจริง ๆ หัวเราะเยาะฉันจากในหม้อน้ำเดือด จ้องมองฉันจากหม้อน้ำเดือด มันถูกเคี่ยวและไอน้ำพวยพุ่งขึ้นมาจนทำให้ห้องมีแต่กลิ่นเหม็น กลิ่นเหม็นเน่า เหม็นคาวลอยแตะจมูกของฉัน และระเบิดในสมองของฉัน เสียงดิ้นเสียดหูและกลิ่นเหม็นที่บีบคั้นของมันครูดในกะโหลกศีรษะของฉัน เหมือนกับเล็บที่ขูดบนแผ่นกระดาน \nมันขูดแล้วก็ขำ จู่ ๆ มันก็พูดว่า \"กินฉันสิ กินฉันทีละชิ้น ชิมฉันสิ ชิมรสที่เหนียวเหนอะหนะของฉัน ชิมฉันสิ ฉันจะระเบิดปากของคุณ ไหลผ่านลงคอ และเข้าไปในท้องของคุณ ขอให้รสชาติของฉันแผ่ซ่านไปทั่วร่างของคุณ พวกเราจะเป็นรสชาติเดียวกัน สิ่งเดียวกัน หนึ่งเดียวกัน \nลิ้มรสความจริงแล้วกลายเป็นความจริง \nให้ผู้คนจำนวนมากขึ้นลิ้มรสเรา เพื่อให้พวกเขาได้รู้ถึงความจริงเช่นกัน",
  str_dispatch_book_chaptercont_4000_4 = "วันแห่งการลงมาบังเกิดจะไม่มีวันมาถึง ดังนั้นจงทำใจให้สบาย อยู่เคียงข้างเธอ และเพลิดเพลินกับความงามของชีวิตตามที่คุณปรารถนา \nหัวเราะอย่างสนุกสนาน มองดูความรักและรอยยิ้มของเธอที่ไม่เคยจางหาย อุ้มเธอ เต้นรำ และหมุนไปกับเธอทุกวินาทีในทุก ๆ วัน กินขนมแล้ววิ่งเล่นท่ามกลางแสงแดด แล้วดูพระอาทิตย์ตกดินไป ลองนึกภาพอนาคตของคุณ จินตนาการถึงลูกที่เธอจะให้กำเนิดแก่คุณ \nร้องไห้อย่างมีความสุข ร้องไห้ท่ามกลางสายฝน และปล่อยให้น้ำตาเป็นหนึ่งเดียวกับน้ำจากหยาดฟ้า วันที่คุณกลัวจะไม่มีวันมาถึง สักวันหนึ่งน้ำตาของคุณจะแห้งเหือด และเมื่อเป็นเช่นนั้น รอยยิ้มของเธอจะเปล่งประกายบนใบหน้าอีกครั้ง ฝนจะตกคืนสู่ท้องทะเลและกลับสู่ฟากฟ้า และทุกอย่างจะกลับคืนดังเดิม \nวันแห่งการลงมาบังเกิดจะไม่มีวันมาถึง \nวิ่งไล่ตามเธอจนพอใจ ดื่มด่ำกับความสุข และร้องเพลง กอดเธอไว้ในอ้อมแขนแล้วขี่ม้าชมพระอาทิตย์ตกดิน และดูว่าความรักจะนำพาอะไรมา โดยไม่มีใครต้องรอคอย และไม่มีเป้าหมายให้ต้องติดตาม คุณขี่ม้าตามจังหวะของคุณเอง ควบเต็มความเร็วและเพลิดเพลินไปกับความรู้สึกของลมที่พัดผ่านใบหน้าของคุณ วิ่งไปสุดขอบฟ้าโดยไม่หยุดยั้ง ไม่มีอะไรมาหยุดฝีเท้าของคุณได้ พระอาทิตย์จะขึ้นอีกครั้งเสมอ และวันรุ่งขึ้นก็จะมาถึงเสมอ \nวันแห่งการลงมาบังเกิดจะไม่มีวันมาถึง \nและในความมืดมิด ในแสงจันทร์นวล นัยน์ตาของเธอเปล่งประกายยิ่งกว่าแสงดาว นับดาวบนท้องฟ้า ดูดวงจันทร์ขึ้นและดับ เพลิดเพลินกับความเงียบสงบของยามค่ำคืน ความสง่างามของเธอใต้แสงจันทร์ทำให้นางฟ้าบนสวรรค์เบื้องบนอับอาย รอยยิ้มดั่งจันทร์เสี้ยวของเธอ ดวงตาอันเจิดจ้าของเธอ เปล่งประกายด้วยความรักอันอบอุ่น ผมสีดำราวม่านฟ้ายามค่ำคืน เสียงของเธอไพเราะเหมือนนกไนติงเกล เธอกระซิบข้างหูของคุณ: \"ฉันจะอยู่กับคุณเสมอ ดังนั้นอยู่เคียงข้างฉันตลอดไป ที่รัก\" \nวันแห่งการลงมาบังเกิดจะไม่มีวันมาถึง มันไม่มีวันที่จะมาถึง\nเธอยิ้มด้วยความงามที่ไม่เคยเห็นในโลกนี้ สายตาของเธอทั้งสดใสและเป็นประกาย \n\"วันนั้นจะไม่มีวันมาถึง\" เธอพูด \"เพราะตัวฉันอยู่เคียงข้างคุณเสมอ\"",
  str_dispatch_book_chaptercont_5000_1 = "เอาละเด็ก ๆ วันนี้เรากำลังเรียนรู้วิธีเตรียมหนอนทรายสำหรับทำอาหาร เนื่องจากคุณสามารถหาแมลงตัวเล็ก ๆ ได้ทั่วทะเลทรายเรดีเซล อย่าคิดว่ามันจะทำง่าย เพียงเพราะพวกมันหาง่าย! ก่อนอื่น คุณต้องมีหนอนขนาดที่เหมาะสมก่อน—20 ซม. คือตัวเลขมหัศจรรย์! ถ้าเล็กกว่านี้ คุณต้องโยนมันกลับไป แล้วปล่อยให้พวกมันกินทรายเพิ่มให้อ้วนขึ้น ตอนนี้ เพื่อเป็นการตกแต่งหนอนทราย ให้คุณจับมันแน่น ๆ ตรงกลาง จับหัว แล้วดึงมันไปตามถุงตะกอนของมัน ไม่ต้องใช้มีด หรือกรรไกร หลังจากนั้น จับไม้ (หรือใช้นิ้วของคุณก็ได้) แล้วเสียบเข้าไปในรูที่หัวมันเคยอยู่ ตะกอนที่ซ่อนอยู่ภายในจะถูกบีบออกมา (ข้ามขั้นตอนนี้หากคุณต้องการลิ้มรสชาติของหนอนทรายจริง ๆ!) \nการเตรียมหนอนทรายมีขั้นตอนแค่นี้แหละ (หรือถ้าใช้หนอนทรายตากแห้ง) ง่าย ๆ แค่นี้เอง หากคุณหิวจริง ๆ คุณสามารถย่างมันได้ แต่ให้ใช้ไม้แทนนิ้ว โอ้จดหมายมากมายที่ฉันได้รับเขียนว่า \"ลุงจอห์นนี่ ฉันทำตามคำแนะนำของคุณแล้วแต่เผลอไปย่างนิ้วตัวเองเข้า ฉันควรทำอย่างไรดี?!\" ก็นะ เนื้อก็คือเนื้อ ใช่มั้ย? นิ้วของเธอถูกจนสุกไปแล้ว เจ้างั่ง ยังไงก็ใช้ประโยชน์จากมันซะเลยสิ!\nตอนนี้ หากคุณมีหม้อ คุณจะถือเป็นบุคคลที่โชคดีกว่าผู้ที่อาศัยในทะเลทรายเรดีเซลมากกว่า 90% ที่เหลือเลย แล้วคุณยังมีโอกาสเป็นนักชิมที่ดีอีกด้วย! ตั้งน้ำมันให้ร้อน โยนหนอนทรายที่ทำความสะอาดแล้วลงไปผัดกับเกลือจนเหลืองและมีกลิ่นหอมเฉพาะตัว ใส่พริกรมควัน จิ้งหรีดทอด 1 กำมือ ซอสพริก 1 ช้อนโต๊ะ ผงกระเทียมและออริกาโน 1/4 ช้อน และครีมเปรี้ยว 5 ช้อน ตามลำดับ! หลังจากนั้นให้เติมน้ำและปล่อยให้เดือดประมาณ 20 นาที เสิร์ฟร้อน โรยหน้าด้วยต้นหอมและผักชีฝรั่ง และบูม! ซุปหนอนทราย ง่ายและเร็วของลุงจอห์นนี่! หากคุณไม่มีส่วนผสมอะไรเลย ไม่ต้องกังวลไป แค่ใส่สิ่งที่คุณมีในมือและทำให้มันออกมากินได้ก็พอ!\nครั้งต่อไป ลุงจอห์นนี่จะสอนวิธีนึ่งอูฐทั้งตัว จำไว้ว่าต้องมีเครื่องอบไอน้ำขนาดใหญ่พอที่จะใส่อูฐได้ ไม่รู้จะหาได้จากที่ไหนเหรอ ในทะเลทรายมีคนบ้ากลุ่มหนึ่งที่ชอบอบคนกินเป็นอาหารเย็น ลองถามพวกเขาดูสิ!",
  str_dispatch_book_chaptercont_5000_2 = "ตอนนี้ ไม่ว่าอายุต่ำกว่าเกณฑ์หรือไม่ก็ตาม หากคุณก้าวเท้าเข้าไปในทะเลทรายแห่งนี้ ก็จะไม่มีทางหลีกเลี่ยงบาร์แห่งนี้ได้แน่นอน มีข่าวลือว่าเจ้าของบาร์สนิทกับซินซา ดังนั้นฉันขอแนะนำให้ก้มหน้าเมื่อคุณอยู่ที่นี่ อย่าไปทำตัวกร่างและแข็งกระด้างกับคนพวกนี้ แม้จะไม่มีเรดีเซล เวรนช์อยู่รอบ ๆ แต่ป้อมยามรักษาความปลอดภัยก็สามารถยิงคุณจนฉี่ราดออกมาก่อนที่คุณจะทันได้ขอโทษ เพียงหนึ่งหรือสองสัปดาห์ก่อนที่ฉันจะเริ่มเขียนหนังสือเล่มนี้ ฉันเห็นพวกพังก์หัวร้อนจำนวนมากพยายามก่อเรื่องในบาร์ แล้วเกิดอะไรขึ้นต่อจากนั้นรู้มั้ย พวกเขาทุกคนถูกกระสุนยิงในเวลาไม่ถึง 2 นาที! ดื่มอย่างรับผิดชอบและสุภาพ หากคุณไม่แน่พอที่จะสู้จริง ๆ \nตอนนี้ เตกีลาที่พวกเขาทำที่นี่มีเอกลักษณ์เฉพาะตัวมาก ที่อื่นพวกเขาจะผสมหางจระเข้กับแคคตัส โยนใบอะกาเวสองสามใบลงไปแล้วปล่อยให้มันหมักในถัง ผลิตภัณฑ์ขั้นสุดท้ายมีกากตะกอน 70% มีสารสกัดจากน้ำมันเรดีเซล 20% (ซึ่งว่ากันว่าเป็นสูตรเฉพาะที่เราจะหาดื่มได้จากที่นี่เท่านั้น!) และทราย 10% นี่มันฉี่เตกีลาชัด ๆ ไม่ว่าคุณจะเรียกมันว่าอะไรก็ตาม! แต่พวกนี้น่าทึ่งมาก พวกเขาใช้อะกาเวสีน้ำเงินจริง (ใครจะรู้ว่าพวกเขาเอามันมาจากไหน?) และไม่มีอะไรอื่นปนอีก ส่วนวิธีการทำของมันก็ถูกต้อง พวกเขาอบใบอะกาเวในเตาอบ 700 องศาฟาเรนไฮต์นานกว่า 5 วัน เพื่อให้มันปล่อยน้ำตามธรรมชาติออกมา จากนั้นใช้ประแจหรือค้อนทุบแล้วบดใบอะกาเวในเครื่องบดหิน หลังจากนั้นก็บ่มในถังไม้โอ๊ค (ฉันสงสัยว่าต้นโอ๊คหน้าตาเป็นยังไง) เมื่อคุณเทลงในแก้ว มันจะเปลี่ยนเป็นสีแดงทองหรือน้ำตาลอมแดง ซึ่งสวยมาก! เลียเกลือทะเลจากนอร์ธแลนด์เล็กน้อย กระดกสักช็อต แล้วคุณจะรู้สึกเหมือนกับว่าได้กลืนดวงอาทิตย์เข้าไปทั้งดวง! ฉันพูดได้ไม่หมดจริง ๆ ขอให้ลอง แล้วจะรู้ว่าเตกิล่า อันเยโฮคือสิ่งที่คุณตามหา!\nนอกจากนี้ ดูเหมือนว่าช่วงนี้พวกเขาได้เพิ่มค็อกเทลใหม่ลงในเมนู มันทำจากวอดก้า น้ำมะนาว เบียร์ขิง มีส่วนผสมของความรักเล็กน้อย และน้ำแข็งเยอะ! ฉันคิดว่ามันน่าจะเรียกว่า \"ล่อ\" หรืออะไรสักอย่าง แต่ไม่ว่าจะยังไง ถ้าคุณอยู่แถวนั้นก็ไปลองดูได้นะ!",
  str_dispatch_book_chaptercont_5000_3 = "ย้อนกลับไปเมื่อลุงจอห์นนี่ยังเป็นเด็ก เคยมีความคิดเจ๋ง ๆ ที่จะเดินเท้าข้ามทะเลทรายทั้งหมด (ก็ไอเดียของคนโง่อะนะ ฉันรู้ แต่ช่วยไม่ได้ฉันอาจหัวกระแทกพื้นสักครั้งสองครั้งเมื่อตอนเป็นเด็กก็ได้ เข้าใจมั้ย) ต้องขอบคุณความคิดที่ผิดพลาดนี้ที่ทำเอาฉันเกือบเอาชีวิตไปทิ้งไว้ที่นั่น ถ้าไม่ใช่เพราะคาราวานอูฐท่องเที่ยวผ่านมาเจอแล้วขุดฉันขึ้นมาจากทราย ฉันคงสุกไปแล้ว! ไม่เพียงเท่านั้น แต่ฉันยังได้ลิ้มรสเนื้ออูฐที่ดีที่สุดในโลกอีกด้วย แล้วทุกอย่างก็จบลงด้วยดี! หัวหน้ากองคาราวานเป็นคนจัดเตรียมเนื้ออูฐเอง ฉันหิวมากจนพร้อมจะกินให้เกลี้ยง แล้วฉันจะปฏิเสธได้อย่างไร \nเขาเสิร์ฟเนื้อที่ปรุงสดใหม่บนจานให้ฉัน ข้างนอกไหม้เกรียมอย่างสมบูรณ์ และยังคงได้ยินเสียงแตกของไขมันอูฐด้วย มันดูหนาและเหนียวกว่าเนื้อวัว แต่คุณไม่รู้หรอก: ทุกอย่างละลายในปากของฉันเหมือนเนยเลย! ทันทีที่คุณกัดชิ้นเนื้อด้วยฟันของคุณ เนื้อจะไหลลงมาตามลำคอ และกลิ่นหอมนั่นอีก บอกเลยว่าเหมือนโดนอูฐถีบหน้า! ส่วนที่ดีที่สุดน่ะเหรอ เนื้อคุณภาพสูงและบริสุทธิ์ชนิดนี้ไม่ต้องใช้เครื่องปรุงใด ๆ พวกเขาเสิร์ฟให้ฉันแบบธรรมดา! สิ่งนี้ดีพอที่จะทำให้คุณอยากเปลื้องผ้าวิ่งกลางทะเลทรายไปเลย (แต่ฉันไม่คิดว่าชาวทะเลทรายคนอื่น ๆ จะทนเรื่องแบบนี้ได้…) \nอูฐที่เรากินนั้นผู้นำกองคาราวานเป็นคนเลือกให้ อูฐทั้งหมดที่มีทั้งอ้วนและแข็งแรง ดังนั้นเราจึงใช้เวลาเลือกอูฐอยู่นานพอสมควร “อ้อ ไอ้ตัวที่ขนสวยมันกินเยอะไป เอาตัวนี้กันเถอะ!” “โอ้ ไอ้นั่นเดินตลกเพราะขามันยาวเกินไป ไปกินตัวนั้นกันเถอะ!” “เฮ้ ตัวนี้ผอมมีแต่กระดูกล้วน น่าจะอยู่ได้ไม่นาน พนันได้เลย!” \nในที่สุด เราก็เลือกอูฐที่อ้วนที่สุดและมีไขมันมากที่สุดในฝูงมา หัวหน้ากองคาราวานบอกเราว่าแดดจัดเกินไปกลัวว่าอูฐตัวนี้จะทนได้ไม่นาน เขาจึงคิดว่าเราควรจะกินมันก่อน แต่ฉันไม่เห็นว่าอูฐจะมีปัญหาสุขภาพอะไร กองคาราวานเองก็รับรองกับฉันว่ามันไม่เป็นไร และอูฐก็กินได้อย่างปลอดภัย \nเราใช้เวลาตลอดทั้งเย็นกินอูฐทั้งตัว เรากินกับชีสที่ทำจากนมและทรายเพื่อประสบการณ์ที่สมบูรณ์ มันเป็นอาหารที่ดีที่สุดเท่าที่ฉันเคยกินมาในช่วงหลาย ๆ ปีที่ผ่านมาเลย! หลังจากดื่มไปสองสามแก้ว ฉันก็ถามหัวหน้ากองคาราวานว่า \"ไม่รู้สึกแย่บ้างเหรอ ที่ฆ่าอูฐแบบนี้\" แล้วเขาก็ตอบฉันว่า \"มีอะไรให้รู้สึกแย่ ถ้าเราไม่กำจัดอูฐตัวเก่าเราก็จะไม่ได้อูฐใหม่ อีกอย่างนะ...\" เขาดื่มนมอูฐอึกใหญ่ \"กองคาราวานนี้เป็นของพวกพ้องฉัน และอูฐเหล่านี้ก็เช่นกัน! กินให้อิ่ม เลิกกังวลเสียที!\" \nต่อให้เป็นมังสวิรัติ คุณก็ไม่ควรพลาด \"ผลไม้\" แห่งทะเลทรายนี้! เอาจริง ๆ นะ แค่คิดว่ามันเป็นผลซะถ้ามันจำเป็น แล้วลองชิมดู! คุณจะไม่เสียใจเลย!",
  str_dispatch_book_chaptercont_5000_4 = "ทุกคนรู้วิธีทำ Hell Ramen ใช่ไหม? \nต้มบะหมี่ของคุณแล้วพักไว้ เทน้ำ 4 ชามลงในหม้อ เติมน้ำสต็อกกระดูกหมูเข้มข้นและซอสร้อนพิเศษ จากนั้นใส่ไข่หรือเครื่องเคียงที่คุณต้องการลงไป เสร็จแล้ว! (ไม่ต้องอ้างอิงถึงสูตรของลุงจอห์นนี่อีกต่อไป!) \nแต่วันนี้ฉันอยากจะพูดถึงอาหารที่นอกเหนือไปจากสูตรง่ายๆนี้ ราเม็งที่ร้อนแรงที่สุด เผ็ดที่สุด แสบร้อน ละลายสมองที่สุดที่ฉันเคยกินมาในชีวิต: Hell Ramen เวอร์ชันของร้าน Eye-Pop Ramen Shop! \nHell Ramen ของพวกเขาประกอบด้วยน้ำหนึ่งแก้วและนมขวดเล็ก ๆ หากนั่นเป็นสิ่งบ่งชี้ว่าคุณต้องการอะไร! เมื่อคุณสั่ง ให้ใส่บะหมี่และเนื้อในช้อนของคุณพร้อมกับน้ำซุปและกัด บางคนอ้างว่ามีอาการประสาทหลอนเป็นไข้หลังจากกินของเข้าไปเพียงคำเดียว! \nสิ่งแรกที่ฉันสังเกตเห็นหลังจากกัดครั้งแรกคือปากของฉันแห้งมากพร้อมกับความเจ็บปวดที่รุนแรงยิ่งขึ้น จู่ๆ ทะเลทรายก็ปรากฏขึ้นต่อหน้าต่อตาฉัน! มันรู้สึกเหมือนฉันติดอยู่ในที่ที่ร้อนที่สุดและแห้งแล้งที่สุดในโลก แผ่นดินแตกระแหงและแห้งแล้ง ดวงอาทิตย์ก็ใหญ่ขึ้นเรื่อยๆ ความชื้นทุกหยดออกจากร่างกายของฉัน และผิวหนังของฉันก็เริ่มแตกและหลุดออกจากกระดูก คอของฉันแห้งผากไปหมด และความปรารถนาที่จะฉีกคอของฉันเกือบจะเอาชนะฉัน ฉันจึงคว้าแก้วน้ำที่พวกเขาให้ฉันอย่างสิ้นหวัง \nจู่ๆ น้ำในระบบของฉันก็ช็อตทำให้ฉันเวียนหัวจนแทบหมดสติ แต่แล้วภาพตรงหน้าก็เปลี่ยนไปอีกครั้ง! คราวนี้ฉันเห็นโอเอซิสสีเขียวที่รายล้อมไปด้วยม่านควัน มีชายหญิงสวยๆ เล่นสาดน้ำใส่กัน (ถ้าปากและคอฉันไม่ตาย ฉันคงผิวปากใส่พวกเขาแล้ว!) ถึงกระนั้น พวกเขาก็เห็นฉันและดึงฉันเข้าไปในโอเอซิสที่เย็นสบาย และในขณะที่ฉันเริ่มสบายตัว... หัวหน้ากลุ่มสาวก็จับฉันแล้วผลักฉันกลับลงไปในทราย! น่าเสียดายที่แก้วน้ำไม่ได้ทำตามเคล็ดลับ และเครื่องเทศก่อนหน้านี้ก็กลับมาพวยพุ่ง ทรายข้างใต้ฉันกลายเป็นลาวา และฉันก็จมลึกลงไปอีก จนเหลือแต่ซากที่ไหม้เกรียม แล้วก็... ไม่มีอะไร \nนี่คือขอบเขตของพลังของราเมง หลังจากนั้นฉันดื่มนมแก้วหนึ่งและเหมือนเวทมนตร์ ร่างกายที่ไหม้เกรียมของฉันกลายเป็นเนื้อและเลือดอีกครั้ง และความว่างเปล่าก็หายไปต่อหน้าต่อตาฉัน ความอบอุ่นที่ผ่อนคลายที่ฉันรู้สึก ณ จุดนั้นไม่ต่างจากการแช่น้ำพุร้อนเป็นเวลานาน (ซึ่งจะเป็นธีมของรายการต่อไปของเรา) \nและนั่นคือประสบการณ์ของฉันกับ Hell Ramen อันเป็นเอกลักษณ์ของ Eye-Pop Ramen Shop! \nฉันถามพ่อครัวเกี่ยวกับวิธีการเตรียมอาหารด้วยความอยากรู้อยากเห็น และคำตอบนั้นง่ายมากจนน่าตกใจ มันทำตามที่ฉันอธิบายไว้ในตอนแรกทุกประการ! ว่าทำไมมันถึงเผ็ดมาก เชฟบอกว่าผลลัพธ์นั้นสำเร็จได้ด้วยเครื่องปรุงรสที่พิเศษมาก \nคุณถามเครื่องปรุงอะไร เป็นความลับของพวกเขา แล้วฉันจะรู้ได้ยังไง!",
  str_dispatch_book_chaptercont_5000_5 = "ตั้งอยู่บนฝั่งของทะเลสาบ Emerald ในทะเลทราย Rediesel เป็นสถานที่เล็ก ๆ ที่เรียกว่า Harvest Hamlet ที่นี่รวบรวมอาหารและสูตรอาหารแสนอร่อยจากทั่วทุกมุมโลก และทุก ๆ สามปีจะจัดเทศกาลอาหารที่เรียกว่า \"มหกรรมการกินไม่รู้จบ\" อาหารและส่วนผสมที่มีคุณภาพสูงสุดจาก Lumopolis, Illumina, Northland และแม้แต่ Far East สามารถพบได้ที่นี่ในช่วงเทศกาล ข้าวหินทราย สตูว์เนื้อแกะ และไข่ม้วน เป็นเพียงส่วนหนึ่งของความอร่อยที่คุณจะพบได้ที่นี่ในสวรรค์สำหรับนักชิม! ฉันคิดว่าทุกคนควรมาที่นี่อย่างน้อยหนึ่งครั้งในชีวิตในช่วงงานนี้ ให้ตายเถอะ ฉันอายุแค่สามขวบเมื่อฉันไปครั้งแรก และฉันต้องโกงและขโมยเพียงเพื่อลองชิมอาหารอร่อยทั้งหมดที่นั่น! คุณคิดว่าฉันควรจะรับผิดชอบและหาอาหารของฉันเหมือนคนจริงเหรอ? ส่วนไหนของ 'อายุแค่สามขวบ' ไม่ชัดเจน?!\n\nฉันจำปีนั้นได้อย่างแจ่มใส มือข้างหนึ่งถือหนอนย่าง มือหนึ่งเคี้ยวกรุบกรอบ และเคี้ยวป๊อปร็อก ทันใดนั้นฉันก็ได้กลิ่นลึกลับจางๆ . ฉันเดินตามมันไปที่คอกม้าเก่าๆ ทรุดโทรม เจ้าของเป็นชายหนุ่มมือเดียว ฉันจำไม่ได้ว่าเขาหน้าตาเป็นอย่างไร แต่ฉันจำได้ว่าเขาดูเด็กมาก อย่างไรก็ตาม สิ่งที่ฉันจะไม่มีวันลืมคืออาหารที่เขาขาย นั่นคือ แมงดาทะเล \n\nเนื้อปูใสเหมือนน้ำแข็ง มีแถบสีแดงด้านหนึ่ง มันเกือบจะดูดิบวิธีการเสิร์ฟ! แต่เมื่อฉันกัด ความรู้สึกแปลก ๆ ปั่นป่วนเข้าครอบงำ มันเหมือนคลื่นทะเลที่หวานและเค็มกระทบกับฉัน มันเป็นความรู้สึกที่ฉันไม่เคยมีมาก่อนด้วยสติปัญญาของฉัน: ทะเล \n\nเจ้าของร้านหันมาหาฉันและพูดว่า \"นี่คือสูตรชีวิตของฉัน\" \n\nเอาล่ะเด็กๆ ถึงเวลาที่ลุงจอห์นนี่จะแบ่งปันความรู้ในชีวิตจริงกับผู้อ่านรุ่นเยาว์ มีมืออาชีพในโลกที่ใช้ชื่อว่า \"นักล่าอาหาร\" คนเหล่านี้ไล่ตามจุดสุดยอดของอาหารมาทั้งชีวิต ออกล่าและเสาะหาวัตถุดิบที่หายากไปทั่วแผ่นดิน เพียงเพื่อเติมเต็มสิ่งที่พวกเขาเรียกว่า \"สูตรชีวิต\" ผู้ชายคนนี้ก็ไม่มีข้อยกเว้น เขาใช้เวลาตลอดทั้งปีเพียงลำพังในทะเลหลวงเพียงเพื่อจับแมงดาทะเลที่สมบูรณ์แบบ จากนั้นปรุงมันในน้ำทะเลที่ดึงขึ้นมาจากร่องลึกที่สุดและโรยด้วยเกลือทะเลที่บริสุทธิ์ที่สุด นี่คือสิ่งที่ทำให้แมงดาทะเลของเขามีรสชาติที่อร่อยมาก! \n\nฉันไม่เคยเห็นชายมือเดียวคนนั้นอีกเลย บางทีเขาอาจกำลังค้นหาในป่าลึกหรือบนภูเขาที่สูงที่สุด เพื่อพยายามจับสัตว์หายากอีกตัว? โดยส่วนตัวแล้วฉันไม่คิดว่านักล่าอาหารจะพอใจกับสูตรอาหารเพียงชีวิตเดียว โหลหรือสองโหลจะทำเคล็ดลับใช่ไหม? \n\nนั่นอะไร? ลุงจอห์นนี่มีสูตรชีวิตไหม? \n\n'แน่นอน ฉันทำ และมันก็ง่ายจะตายด้วย: ไข่หนอนทรายต้ม! แค่หยิบทรายขึ้นมาสักสองสามเม็ดแล้วโยนลงไปในน้ำเดือดสักสามนาที คุณจะมีไข่หนอนทรายที่เนียนที่สุด ขาวที่สุด และอร่อยที่สุดในชีวิตของคุณ! ง่าย ราคาไม่แพง และสะดวกสุดๆ เพราะคุณสามารถหาไข่คนบ้าได้ทั่วทุกแห่ง!",
  str_dispatch_book_chaptercont_6000_1 = "\"มิสบลังค์ คุณพอจะบอกเราเพิ่มเติมเกี่ยวกับทะเลสาบกระจกเงา 'หยดน้ำตาแห่งนอร์ธแลนด์' หน่อยได้มั้ย?\"\n\"ได้สิ! ทะเลสาบกระจกเงา หรือเรียกอีกชื่อว่า 'หยดน้ำตาแห่งนอร์ธแลนด์' คือแลนด์มาร์กสำคัญของนอร์ธแลนด์\"\nแม้ว่านอร์ธแลนด์จะรักษาอุณหภูมิที่เย็นยะเยือกหรือใกล้จุดเยือกแข็งได้ตลอดทั้งปี แต่องค์ประกอบพิเศษของทะเลสาบกระจกเงาก็ป้องกันไม่ให้มันกลายเป็นจุดเยือกแข็งได้ ด้วยเหตุนี้มันจึงคงรูปลักษณ์ที่สวยงามราวกับกระจกไว้ตลอดเวลา ไม่มีคลื่น สีเหมือนหยก พื้นผิวของทะเลสาบช่วยเพิ่มสีสันให้กับภูมิทัศน์ฤดูหนาวของนอร์ธแลนด์\"\n\"มีตำนานหนึ่งเล่าว่าเมื่อหลายปีก่อน ราชวงศ์แห่งนอร์ธแลนด์เคยเดินทางมายังสถานที่แห่งนี้ โดยได้รับแรงบันดาลใจจากความงามและความโรแมนติกของที่นี่ พวกเขาจึงใช้เวทมนตร์ที่มีเพียงพวกเขาเท่านั้นที่รู้ เพื่อร่ายภาพทิวทัศน์ที่สวยงามตามธรรมชาติอันน่าทึ่งนี้ ทำให้ทะเลสาบคริสตัลและภูเขาโดยรอบนี้กลายเป็นจริง... แต่ฉันคิดว่าคนส่วนใหญ่เห็นด้วยว่ามันเป็นเพียงแค่ทะเลสาบที่เกิดจากการกัดเซาะของธารน้ำแข็งที่เกิดขึ้นตามธรรมชาติเท่านั้น\"\n\"บนฝั่งทางตะวันตกมีทุ่งนาที่เต็มไปด้วยดอกนาร์ซิสซัสสีขาว ซึ่งเป็นอีกมุมหนึ่งของความงดงามตามธรรมชาติของทะเลสาบกระจกเงา อย่างไรก็ตาม ฉันต้องขอแนะนำว่าไม่ควรมาที่นี่ เพราะเลดี้นิคินิส หรือที่รู้จักในชื่อกระจกเงาคู่แฝดแห่งนอร์ธแลนด์ได้ปลูกดอกไม้ไว้ที่นั่นด้วยตนเอง และเธอหวงแหนดอกไม้เหล่านั้นราวกับเป็นลูก ๆ ของเธอ ครั้งหนึ่งเคยมีแขกสองสามคนไม่สนใจคำเตือนและเด็ดดอกไม้ไว้เป็นที่ระลึก แต่จู่ ๆ ก็ถูกเลดี้นิคินิสโยนลงไปในน้ำที่เย็นยะเยือกของทะเลสาบกระจกเงา\n*หัวเราะคิกคัก* การตกคนออกจากทะเลสาบนั้นไม่ง่ายเหมือนปลานะรู้มั้ย\"\n\"และอีกอย่าง เพื่อเป็นการหลีกเลี่ยงอันตรายที่ไม่จำเป็น เมื่อไปที่ทะเลสาบกระจกเงา โปรดจงอยู่ให้ห่างจากทุ่งดอกไม้!\"",
  str_dispatch_book_chaptercont_6000_2 = "ป่าลู่ลมมีสภาพค่อนข้างชื้นตลอดทั้งปี ในวันที่แสนอบอุ่นและค่ำคืนที่เย็นสบาย ป่าเต็มไปด้วยชีวิตชีวา และไม่เพียงแต่เป็นที่อยู่อาศัยของสัตว์ป่าหายากมากมายเท่านั้น แต่ยังมีต้นไม้ที่สวยงามและเก่าแก่อีกด้วย ว่ากันว่า วินวอร์ด โมนาร์ค ซึ่งเป็นต้นซีดาร์ที่มีชื่อเสียงที่สุดในป่า มีอายุกว่าพันปีเชียวนะ\n\nคุณจะได้รับการต้อนรับด้วยสายลมอุ่น อากาศบริสุทธิ์ และสัตว์ที่เป็นมิตรต่อมนุษย์ซึ่งอาศัยอยู่ที่วินซอง ฟอเรสต์ นี่เป็นสถานที่พักผ่อนที่สุดยอดสำหรับทุกเพศทุกวัย\n\nอ้อ ถ้าคุณเลือกที่จะเดินทางมาที่นี่ อย่าลืมไปหาซิลวาผู้พิทักษ์ป่าด้วยล่ะ เพราะว่าเขาใช้เวลาส่วนใหญ่ไปกับการลาดตระเวนป่าและช่วยเหลือสิ่งมีชีวิตในป่า คุณอาจลองติดต่อลีอาห์ผู้เป็นตัวแทนของเขาในเมืองฮอลเลตันที่อยู่ใกล้ ๆ ก็ได้ เมืองเดียวกันนี้เป็นที่ตั้งของร้านอาหารที่ขึ้นชื่อเรื่องสตูว์แสนอร่อย สำหรับข้อมูลเพิ่มเติม โปรดดูบทที่ชื่อ \"คำแนะนำสำหรับนักชิม\" ในหนังสือเล่มนี้",
  str_dispatch_book_chaptercont_6000_3 = "หลังจากสำรวจทุ่งที่ปกคลุมไปด้วยหิมะในนอร์ธแลนด์แล้ว คุณจะได้พบกับการพักผ่อนและความสะดวกสบายภายในเนินเขาของป่าสนนอร์ธแลนด์ นักเดินทางที่หนาวเหน็บและเหน็ดเหนื่อยมักได้รับการต้อนรับด้วยกระท่อมที่อบอุ่น เตียงนุ่ม ๆ และซุปร้อน ๆ แม้ว่าภูมิประเทศจะเป็นแนวเทือกเขาสลับที่ราบ แต่ลักษณะเฉพาะของมันก็ช่วยปิดกั้นลมหนาวจากทางเหนือได้ดีจนน่าตกใจ ภูมิอากาศโดยทั่วไปอบอุ่น ชื้น และก่อให้เกิดหมู่บ้านมากมายภายในเนินเขา \n\nในอดีตอันไกลโพ้น ผู้ตั้งถิ่นฐานกลุ่มแรกบนเนินเขาเหล่านี้พบผลึกสีเขียวจำนวนนับไม่ถ้วนใต้พื้นดิน เปล่งประกายราวกับมรกต หลังจากการตรวจสอบเพิ่มเติม พวกเขาพบว่าบริเวณนั้นอุดมไปด้วยคริสตัลเหล่านี้ และบางส่วนก็ใหญ่พอ ๆ กับผู้ใหญ่เลย! ในที่สุด พวกเขาก็พบกับการค้นพบที่ยิ่งใหญ่กว่านั้น จริง ๆ แล้วเนินเขาทั้งเนินเป็นคริสตัลขนาดยักษ์ทั้งหมด! ผู้อาวุโสในกลุ่มผู้ตั้งถิ่นฐานสรุปว่าเนินเขาคริสตัลเคยเป็นส่วนหนึ่งของคริสตัลขนาดมหึมา และพระเจ้าได้ทำลายมันเพื่อสร้างดินแดนมหัศจรรย์เหล่านี้ขึ้น \n\nปัจจุบันนักท่องเที่ยวยังคงสามารถเห็นผลึกธรรมชาติที่สวยงามเหล่านี้กระจัดกระจายอยู่ทั่วภูมิประเทศ อย่างไรก็ตาม ห้ามทำเหมืองคริสตัลโดยเด็ดขาด เพื่อเป็นการเคารพต่อความเชื่อและประเพณีในท้องถิ่น ปกติแล้วผู้เข้าชมจะถูกห้ามไม่ให้นำคริสตัลเม็ดเล็ก ๆ ออกไปจากสถานที่แห่งนี้ โปรดให้เกียรติกับกฎข้อนี้ในการเดินทางของคุณด้วย!",
  str_dispatch_book_chaptercont_6000_4 = "ทางเหนือสุดของทวีปแอสตรา เทือกเขาสุดขอบโลกที่สูงตระหง่านได้ทำลายความพยายามในการออกสำรวจภายนอกของผู้คนไปอย่างสิ้นเชิง ในทางกลับกัน บางคนกล่าวว่าภูเขาที่ปกคลุมด้วยหิมะเหล่านี้รักษาดินแดนของเราให้ปลอดภัยจากภัยคุกคามทางธรรมชาติ และภัยเหนือธรรมชาติจากทั้งดินแดนรัตติกาลนิรันดร์และดินแดนแห่งทิวานิรันดร์ \n\nเทือกเขาที่หนาวเหน็บนี้แทบไม่มีใครมาเยือน เป็นต้นกำเนิดของชาวออโรเรียนตามตำนานที่เล่าขานกันมา อันที่จริงชาวออโรเรียนบางคนไม่เชื่อว่าที่แห่งนี้เป็นต้นกำเนิด อย่างไรก็ตาม เมื่อได้เห็นพระราชวังที่สร้างจากน้ำแข็งทั้งหลังภายในภูเขาแล้ว ผู้คนก็เริ่มคลางแคลงใจ พวกเขาไม่มีทางเลือกอื่นนอกจากต้องยอมรับว่าเป็นผลงานชิ้นเอกของบรรพบุรุษดินแดนเหนือของพวกเขา \n\nหากคุณโชคดีได้รับหมายเชิญจากราชินีแห่งแดนเหนือ หลังจากเดินขึ้นบันไดที่ทอดยาวคดเคี้ยวและเยือกแข็งไปยังทางเข้าแล้ว คุณจะไม่พบกับความหนาวเย็นอีกต่อไป แต่จะได้พบกับความอบอุ่นราวกับฤดูใบไม้ผลิที่ยากเกินจะอธิบาย จากคุณลักษณะเพียงแค่นี้ ก็เข้าใจแล้วว่าทำไมพระราชวังเหมันต์จึงมีชื่อเสียงอย่างมากในแอสตรา: เพราะการผสมผสานระหว่างน้ำแข็ง หิมะ และความอบอุ่นนั้นพรรณนาเป็นอย่างอื่นไปไม่ได้เลยนอกจากคำว่าลึกลับ \n\nไม่ว่าจะกลางวันหรือกลางคืน พระราชวังเหมันต์จะเปล่งประกายด้วยเสน่ห์ราวกับภาพฝัน แสงจากดวงอาทิตย์ ดวงจันทร์ และดวงดาวส่องผ่านผนังที่เป็นผลึกของพระราชวัง สะท้อนและหักเหแสงอย่างไม่สิ้นสุด ทำให้เกิดสีสันสดใสทุกรูปแบบภายในห้องโถง โดยเฉพาะเมื่อแสงออโรราของนอร์ธแลนด์ส่องกระทบกับตัวพระราชวัง กำแพงของวังจะมีชีวิตชีวาขึ้นด้วยแสงสีและเงาเต้นรำนับไม่ถ้วน ประสบการณ์นี้เป็นประสบการณ์ที่สามารถเจอได้แค่ในพระราชวังเหมันต์ และฉันก็โชคดีที่ในชีวิตนี้เคยเห็นมันมาแล้วครั้งหนึ่ง ฉันได้เห็นสิ่งมหัศจรรย์ทางธรรมชาติและสิ่งมหัศจรรย์ที่มนุษย์สร้างขึ้นมากมายนับไม่ถ้วน แต่ไม่มีที่ไหนที่น่าตื่นตะลึงและต้องมองตาค้างได้เท่ากับตอนที่เห็นแสงเหนือส่องผ่านพระราชวังแห่งนี้อีกแล้ว...",
  str_dispatch_book_chaptercont_7000_1 = "ผู้สร้างโลก\nตัดสินใจที่จะเริ่มต้นใหม่\nดังนั้น จึงเริ่มใช้พายุอันรุนแรงมาชำระล้างโลก\nแสงของดวงจันทร์ถูกดับไป\nเขาประกาศการมาถึงของอุปราคาของโลก\nเขาเดินทางระหว่างแสงและความมืดเป็นเวลา 2 วัน เพื่อสร้างผู้ส่งสาร\nสุดท้าย เขามอบดวงอาทิตย์ให้ฉายแสงลงมายังโลกเบื้องล่าง\nพร้อมกับแม็กม่าร้อน\nเขากำจัดโลกของสิ่งมีชีวิตทั้งมวลที่ต่อต้านเขา\n __________ \n ____________________ \n _____________ \n ____________ \n _____ \n _________ \n \n ก่อนรัตติกาลมาเยือน\nมีคนเคยถามว่า\n\"อะไรคือจุดประสงค์ของความฝันตั้งแต่เริ่มต้น\"\nและสติได้ตอบว่า\n\"เพื่อให้ความเป็นนิรันดร์กลับสู่สวรรค์\nเพื่อไปถึงอีกฟากฝั่ง\nเพื่อบรรลุ\"\nอีกคนถามว่า\n\"เราจะพบคำตอบอะไรที่จุดสิ้นสุดของวงกตนี้\"\nและสติตอบว่า\n\"เพื่อรอบรู้ทุกสรรพสิ่ง\nเพื่อลบอุปสรรคทั้งปวง\nเพื่อหลอมรวม\"\nจากนั้น เขาจึงแสดงความประสงค์ให้เป็นที่รู้กันถ้วนหน้า\n \n\"ก้าวหน้า ก้าวหน้าโดยไม่หยุดยั้ง\nก้าวข้าม ก้าวข้ามโดยไม่ลังเล\"\nครั้งนี้\nผู้ติดตามพูดว่า\n\"เราน่าจะพบกับจุดจบของเราที่นี่\"\nดังนั้น สติจึงเริ่มเคลื่อนเทวโลกอันมหึมา\nและทำลายหลักการอันสูงสูด\nไม่มีผู้ใดที่มุ่งมั่นแน่วแน่\nตัดสินใจที่จะเดินทางก้าวข้ามสวรรค์อันไกลโพ้น\nเพื่อไปมองดวงตาขุมนรก\nและดังนั้น ผู้ศรัทธาจึงปรากฏตัว\nพวกเขาทำตามคำสั่ง\nเพื่อล้มล้าง\nเพื่อหวงห้าม\nเพื่อปรับปรุง\nเพื่อให้ทุกอย่างล่มสลาย\nเพื่อให้เป็นวันสิ้นโลก \n เพื่อให้รัตติกาลมาเยือน",
  str_dispatch_book_chaptercont_7000_2 = "ในตอนแรกเขาจะตอบคำถามที่ค้างคาใจคุณ \nเมื่อคุณหลงใหลในเสรีภาพ เขาจะบอกคุณว่า \n\"อารมณ์และความหมกมุ่นเป็นรากเหง้าของปัญหาของคุณ กำจัดมันซะ แล้วคุณจะเข้าใกล้อิสรภาพมากขึ้น\" \nเมื่อคุณไม่แน่ใจว่าจะดำเนินการอย่างไร เขาจะบอกคุณ: \n\"ความทุกข์ยากเป็นสิ่งจำเป็นสำหรับความก้าวหน้า โดยการยอมรับและอดทนต่อความทุกข์ยากเท่านั้น คุณจะแข็งแกร่งขึ้นในแต่ละวัน และเดินไปตามเส้นทางที่ถูกต้อง\" \n\nในไม่ช้าเขาก็เริ่มแสดงให้เราเห็นถึงวิธีการเป็นคนที่เหมาะสม: \n\"การจะเข้าใจใครซักคน เราเพียงแค่สังเกตว่าการกระทำและแรงจูงใจของบุคคลนั้นสอดคล้องกันหรือไม่ จากนั้นเราจะสามารถตัดสินความจริงใจของบุคคลนั้นได้\" \n\"ยิ่งคุณพยายามทำความเข้าใจความคิดของผู้อื่นมากเท่าไหร่ คุณก็ยิ่งต้องใช้ความพยายามในการพัฒนาตนเองน้อยลงเท่านั้น เข้าใจไหม\" \n\nเขาเริ่มทำหน้าที่เป็นครูของเราและแบ่งปันภูมิปัญญาของเขา: \n“ผู้ที่ไม่อาบน้ำ จะได้กลิ่นอะไรเมื่อไฟอ่อนลง ผู้ที่ไม่เสียสละและไม่เรียนรู้ทักษะ แม้ว่าพวกเขาอาจดูมีคุณธรรมสำหรับบางคน แต่ก็จะค่อยๆ สูญเสียกลิ่นของไฟไปตามกาลเวลา” \n\"ความอิจฉาริษยาจะไม่เพิ่มอะไรให้กับชีวิตคุณ และจะไม่ลดช่องว่างระหว่างคุณกับคนอื่นๆ\" \n\nเขาเริ่มทำให้เราเป็นฮีโร่: \n\"แทนที่จะจมอยู่กับความพ่ายแพ้ของคุณ จงก้าวย่างอย่างกล้าหาญ\" \n\nเขาเริ่มไตร่ตรอง: \n\"แสดงความยืนหยัดของคุณด้วยความอ่อนน้อมถ่อมตน เพิ่มโศกนาฏกรรมเล็กน้อยและคนอื่น ๆ จะยอมรับได้อย่างง่ายดาย\" \n\"ทุกกลุ่มมีชีวิตจำนวนหนึ่ง แต่ไม่ใช่ทุกกลุ่มที่เข้าใจ น้อยกว่ามาก ปกป้องสิ่งที่ประกอบขึ้นเป็นชีวิตของพวกเขา ชีวิตเหล่านั้นที่เข้าใจหลักการนี้จึงถูกทรมานด้วยเหตุนี้\" \n\nจากนั้นเขาก็เริ่มเทศนา: \n\"ผู้มีชีวิตครอบครองพระประสงค์ของพระผู้เป็นเจ้าและพระพรของพระองค์ ซึ่งทั้งสองอย่างนี้ควรได้รับการทะนุถนอมและปกป้องตามนั้น\" \n\"'อารมณ์ไม่ใช่ของสาธารณะหรือส่วนตัว ไม่มีกฎหรือบรรทัดฐานสำหรับพวกเขา' นี่คือประเภทของความคิดที่แต่ละคนแสวงหาและยึดมั่นไปจนตาย” \n\"แต่ด้วยการรวบรวมเจตจำนงของแต่ละบุคคลให้เป็นความคิดแบบกลุ่ม เราสามารถรองรับแรงบันดาลใจที่ยิ่งใหญ่กว่านี้ได้\" \n\nเขาเริ่มตำหนิเรา: \n\"คุณจะเอาทรายใส่ขวดน้ำดื่มของคุณให้เต็มขวดไหม แล้วทำไมคุณถึงเอาความคิดทางโลกมาใส่ในสมอง\" \nเขาเริ่มล่อลวงเรา: \n\"นี่คือสิ่งที่คุณควรปรารถนาที่จะบรรลุ\" \nเขาเริ่มเป็นตัวแทน: \n\"ข้อมูลเชิงลึกของคุณจะกลายเป็นความคิดของฉัน แรงบันดาลใจของคุณจะถูกนำไปที่นี่ และกลายเป็นทั้งรากฐานและแรงผลักดันในการทำให้อุดมคติของคุณเป็นจริง\" \n\nเขาเป็นตัวแทนของความจริง จุดสูงสุดของความจริงและปัญญา \nแต่ท้ายที่สุด เขาก็เลิกพูดคุยกับผู้คนและเลือกที่จะออกคำสั่งเป็นภาษาใหม่ \nเป็นภาษาที่มาจากประชาชน แต่ไม่ใช่สำหรับประชาชน \nมันเป็นภาษาวัตถุประสงค์ที่สร้างขึ้นเพื่อปลดปล่อยเราจากพันธนาการของอัตวิสัย...",
  str_dispatch_book_chaptercont_7000_3 = "_____________________ \n________ \nความจริงที่ซ่อนอยู่ภายในข้อความ\nเหมือนหินในสายน้ำ\nเงียบ จมอยู่ก้นบึ้ง\nมีเพียงก้อนหินและทรายที่จะถูกกระแสน้ำพัดไป\nด้วยเหตุผลนี้ เราจึงรู้\nที่ใดสักแห่งบนโลก ณ ช่วงเวลาหนึ่ง\nสงครามได้กลืนกินทุกอย่าง\nหากมีใครถามว่าอะไรคือสาเหตุเริ่มต้นของสงคราม\nคำตอบก็คงเป็นความโลภ\nความโลภของใครบางคนชักนำหายนะมาสู่ทุกคน\n\nมีคนผู้หนึ่งเคยบรรยายถึงสิ่งที่พวกเขาเห็น\nในทันใด \nโทเท็มมังกรก็บังเกิดขึ้น\nมันนำมาซึ่งพายุที่บดบังท้องฟ้า\nแล้วในดินแดนแห่งเหล็ก\nผู้ส่งสารก็ลงมา\nแบกรับภารกิจและลงมาจากภูเขาที่ห่างไกล\nเขาเหินลงมาราวกับสายฟ้า\nเขาไม่ต้องกางธนู\nลูกศรนับหมื่นก็ปรากฏขึ้นในพริบตา\nเจาะทะลวงที่ราบอันกว้างใหญ่เบื้องล่าง\nสังหารทุกสิ่งในสายตา\n\nในผลพวงอันน่าสลดใจของการต่อสู้\nเมฆครื้มแทบจะปกคลุมไปทั่วโลก\nผู้ส่งสารประกาศว่าจะไม่มีผู้รอดชีวิตในสงครามครั้งนี้\nทว่าอีกากลับพบผู้รอดชีวิต\nและพวกเขาก็หลบหนีไปก่อนที่หมอกจะจางลง \nพวกเขานั่งเรือไปร้อยลำ\nแต่ละคนต้องนำธัญพืช 10 ชนิดไปด้วย\nทุกครั้งที่ข้ามผ่านภูเขา กำแพงหินและโคลนขนาดมหึมา\nพวกเขาจะสูญเสียเรือไป 1 ลำ\n\nพวกเขาตั้งกลุ่มและเดินทางบก\nจนคทากลายเป็นแท่งไม้\nและจากนั้น คนเลี้ยงแกะก็มอบแท่งไม้ให้กะลาสี\nและบุตรชายของกะลาสีก็มอบสังข์ให้กับผู้เผยพระวจนะ\nและสุดท้าย ผู้เผยพระวจนะตัดสินใจ\nนำขนหางสุดท้ายของอินทรีไป\nนำเอาเลือดที่แห้งเหือดของผู้บุกเบิกไป\nนำกระดาษที่รุ่งอรุณเคยฉายส่องไป\nเขาเขียนคำขอ\nและโยนมันลงในบ่อน้ำ\nและหลังจากนั้นสามวันสามคืน\nหินที่ก้นบ่อก็ยอมเอ่ยปากพูด\nหินพูดว่า: \nพวกคุณทุกคนต้องรอจนกว่าหิมะจะตกลงมาอย่างหนัก\nและกลบฝังทุกสิ่ง\nรอแสงสว่างช่วยเธอให้พ้นจากความหนาวเหน็บ\nรอความอบอุ่นเจ็ดร้อยปีผ่านพ้นไป\nรอหิ่งห้อยสิบล้านตัว\nรอให้หอคอยสูงใหญ่ลับหายไป และรอทะเลสาบปรากฏออกมา\nรอให้นักรบเดินทางไปทั่วโลกราวกับคลื่น\nรอให้ดวงจันทร์ส่องสว่างเหมือนดวงอาทิตย์\nรอให้ดวงอาทิตย์ไม่แผดเผาโลกอีกต่อไปเมื่อยามขึ้นจากขอบฟ้า\nจากนั้นใช้หินน้ำแข็งที่แข็งที่สุดและเย็นที่สุดล้อมรอบอาณาจักร\nหลังจากนั้น จึงจะได้กลับสู่พื้นโลก\"",
  str_dispatch_book_chaptercont_8000_1 = "โปรเจกต์วาลคีรี่ - วันที่ 15 มกราคม XXXX เวลา 10:00 น. ร่างทดลอง#3 ทดสอบเข้ารหัสสติ ครั้งที่ #219: เริ่มการทดลอง\n\"สิ่งอำนวยความสะดวกและอุปกรณ์บันทึกพร้อม เริ่มทดลองได้\"\n\"การเชื่อมต่อส่วนสมองสำเร็จ เข้าสู่โครงข่ายประสาทเทียมของร่างทดลอง ภาพระบบสะท้อนเป็นปกติ รู้สึกยังไงบ้าง XX?\"\n\"ฉัน... ฉันโอเคดี ไม่ได้หนาวมากแล้ว แค่รู้สึกมึนงงเล็กน้อย...\"\n\"ตามความคิดเห็นของคุณจากความพยายามครั้งก่อน เราได้ปรับโครงสร้างของฮิปโปแคมปัสของคุณ นี่อาจเป็นผลจากการปรับตัวนั้น\"\n\"หากทุกอย่างเป็นไปได้ด้วยดี คุณจะสามารถปรับตัวได้ภายใน 24 ชั่วโมง\"\n\"ฉันเข้าใจ... เอ่อ... วันนี้เธอจะมาที่นี่มั้ย\"\n\"เธอ... เธอมาตลอด... มาพร้อมกับผมยาวสีเงินของเธอและ... อั้ก!\"\n\"รูปภาพสูญเสียเลือนราง ผู้พัน!\"\n\"คุณต้องใจเย็น ๆ ก่อน XX!\"\n\"ใจเย็นก่อน! คนที่คุณกำลังพูดถึง... ไม่มีอยู่จริง\"\n\"ไม่มีอยู่งั้นเหรอ\"\n\"ใช่... ที่นี่มีแค่พวกเรา คนที่คุณพูดถึง... อาจจะความทรงจำของร่างทดลองอื่น\"\n\"ฉันไม่เข้าใจ...\"\n\"มันเป็นแค่ความฝัน คุณเข้าใจใช่มั้ยว่ามันคือความฝัน\"\n\"แต่... แต่ฉันคือฮามังคิวลัส... ฮามังคิวลัสก็ฝันได้เหมือนกันเหรอ?\"\n\"ใช่ ฝันได้... เมื่ือคุณหลับคุณก็จะฝัน ฝันอาจสั้นหรือยาว สุขหรือเศร้า... แต่ส่วนมากแล้วจะลืมไปเองหลังจากตื่นไม่กี่นาที เหมือนกับสิ่งมีชีวิตธรรมชาติ\"\n\"สัญญาณคงที่ ผู้พัน\"\n\"ดี คุณไปพักได้แล้ว XX มาสิ ปิดตาของคุณ...\"\n\"เข้าใจแล้ว... ราตรีสวัสดิ์ ผู้พันฮาร์ตแมน ขอให้คุณฝันดี\"\n\"ฝันดี XX ฝันดีเช่นกัน\"\nโปรเจต์วาลคีรี่ - วันที่ 15 มกราคม XXXX เวลา 11:00 น. ร่างทดลอง #3 (ระบบควบคุมส่วนกลาง ชื่อเรียกขาน: NOIR) การทดสอบเข้ารหัสสติ ครั้งที่ #219: สิ้นสุดการทดลอง",
  str_dispatch_book_chaptercont_8000_2 = "วันที่ 14 กรกฎาคม ปฏิทินปี XXX\nอาการของลิลินกำลังทรุดหนัก ลูกสาวผู้น่าสงสารของผม... แต่ตอนนี้ผมมีความคิดหนึ่ง แม้จะถูกมองว่าเป็นการล่วงละเมิดต่อพระเจ้า ถ้าผมถูกจับได้ละก็ ผมมีหวังถูกเฆี่ยนตีจนตายแน่... แต่ผมไม่มีทางเลือกอื่น เซย์ล่า... ผมไม่สามารถยืนเคียงข้างคุณและช่วยคุณได้ แต่ครั้งนี้... ผมจะช่วยลิลินให้ได้อย่างแน่นอน!\n\nวันที่ 4 กันยายน ปฏิทินปี XXX\nการทดลองเป็นไปอย่างราบรื่น ซึ่งต้องบอกว่าเหลือเชื่อมาก มันเกินความคาดหมายของผมไปมากเลยทีเดียว ระยะหลังมานี้ ผมเริ่มรู้สึก... แปลกมากขึ้นเรื่อย ๆ มีบางอย่างไม่ถูกต้องนัก ปกติแล้ว ผมจะเป็นคนออกแบบและทำการทดลองตามความคิดของผมเอง แต่ตอนนี้... ผมรู้สึกราวกับว่ามีใครบางคนหรืออะไรบางอย่างกำลังอยู่ในสมองของผม กำลังชี้นำการกระทำของผมอยู่ แต่มันจะเป็นไปได้อย่างไร ผมเป็นนักประสาทวิทยาเชียวนะ ความคิดแบบนี้น่าหัวเราะสิ้นดีเลย! จะยังไงก็ตามแต่ หลายวันมานี้ก็ไม่สงบสุขนัก ผมทุ่มเทความสนใจทั้งหมดไปกับลิลิน เงินทุนสำหรับการทดลองของผมจึงหมดลง... โชคดีที่ผมสามารถขายของแทนใจความรักของเราเพื่อหาเงินมาทำการวิจัยต่อได้! อย่าอารมณ์เสียเลยนะเซย์ล่า ทั้งหมดนี้ก็เพื่อช่วยลูกสาวสุดที่รักของเรานะ ใช่มั้ย ใช่มั้ย?!\n\n13 ธันวาคม ปฏิทินปี XXX\nช่างเลวร้ายจริง ๆ! อันธพาลพวกนั้นมาหาเรื่องอยู่หน้าประตูแล้ว... ผมไม่คิดว่าบาสรอดไปถึงตอนเช้า ผมใกล้จะถึงจุดจบแล้ว! ใจเย็น ๆ ใจเย็น ๆ... ผมคำนวณแบบจำลองทั้ง 9 แบบ และเส้นทางของประสาทสัมผัสของพวกมันนับครั้งไม่ถ้วน... และโครงสร้างร่างกายของพวกมันก็เสถียรทุกครั้งที่ทดลอง ฉะนั้น... ทุกอย่างจะโอเค พ่อกำลังจะปลุกลูกขึ้นมาแล้วนะลิลิน! ครั้งนี้ลูกจะต้องทำได้ พ่อรู้ว่าลูกทำได้ ลูกกับพ่อกำลังจะหนีออกจากสถานที่อันเลวร้ายนี้กัน เราต้องหนีออกไปได้! ได้ยินไหมเซย์ล่า ปกป้องพวกเราด้วย ที่รัก... ผมจะเขียนถึงคุณอีกครั้งเมื่อทุกอย่างเป็นไปด้วยดี! ทุกอย่างจะโอเค!",
  str_dispatch_book_chaptercont_8000_3 = "____ รายงาน: \nตามรายงานการต่อสู้ \"การปะทะ ไซเธีย ไฮแลนด์ 154\" เมื่อ __ วันที่ผ่านมา ศัตรูได้ติดตั้งอาวุธขั้นสูงชนิดใหม่ที่สามารถเปลี่ยนรูปแบบการทำสงครามในปัจจุบันของเราได้ จากข้อมูลที่ได้รับจากทีมขนส่งของศัตรูที่เราซุ่มโจมตีเมื่อ __ วันที่แล้ว อาวุธใหม่นี้ยังไม่มีแผนจะผลิตเป็นจำนวนมาก ยังอยู่ระหว่างการทดสอบภาคสนามขนาดเล็ก ฉันเชื่อว่าผลการต่อสู้ใน \"การปะทะ ไฮแลนด์ 154\" คงเป็นที่น่าพอใจแก่ศัตรูอย่างมากแน่\nเมื่อพิจารณาจากความก้าวหน้าของเราในช่วง 3 เดือนที่ผ่านมา การผลิตล็อตใหญ่และการแบ่งสรรชุดเกราะต่อสู้ ____ ให้กับกองกำลังของเราประสบความสำเร็จอย่างมาก โดยส่วนตัวแล้ว ทหารของเราได้รับการปกป้องอย่างดี เป็นเหมือนกับรถถังขนาดเล็กที่ติดตั้งเกราะต่อสู้ ____ พวกเขาไม่เพียงแต่จะทนต่อกระสุนขนาดเล็กและขนาดกลางได้อย่างง่ายดายเท่านั้น พวกเขายังสามารถพกกระสุนและเสบียงอื่น ๆ ได้มากขึ้น โดยไม่ถ่วง นอกจากนี้ ระบบสารสนเทศและการสื่อสารที่ติดตั้งไปกับชุดเกราะยังช่วยให้ทหารทุกคนมีบทบาทสำคัญในสนามรบอีกด้วย กองกำลังของเรายึดครองน่านฟ้าได้แล้ว ฉะนั้นทหารของเราที่ติดตั้งชุดเกราะใหม่นี้ ก็จะสามารถควบคุมและรักษาดินแดนของศัตรูได้อย่างมีประสิทธิภาพเพิ่มขึ้น ในสถานการณ์แบบนี้ ฉันมั่นใจว่าแนวต้านของศัตรูจะต้องพังทลายลงอย่างรวดเร็วแน่นอน \nทว่า ไม่มีใครคาดคิดถึงศักยภาพในการทำลายล้างของปืนไรเฟิลใหม่ของศัตรู ภูมิประเทศที่ลุ่ม ๆ ดอน ๆ และไม่สม่ำเสมอของไฮแลนด์ 154 ก็จำกัดความสามารถในการลาดตระเวนทางอากาศของเรา ส่งผลให้ความได้เปรียบบนน่านฟ้าของเรานั้นไร้ผล นอกจากนี้ กองกำลังของศัตรูก็มีจำนวนมาก แต่กระจัดกระจายและซ่อนตัวอยู่ทั่วสมรภูมิรบ โดยใช้ความรู้ความเข้าใจในภูมิประเทศและปืนไรเฟิลใหม่ พวกเขายิงและสังหารทหารของเราในระยะไกลด้วยกระสุนเจาะทะลวงแรงสูง เมื่อนักวิทยาศาสตร์ของเราได้คำนวณแล้ว ก็ได้ข้อสรุปว่าแม้แต่เกราะชุบด้านหน้ารถถังรบหลักของเราก็ไม่สามารถต้านทานพลังเจาะทะลวงของมันได้ ที่น่ากลัวยิ่งกว่านั้นก็คือ ปืนไรเฟิลใหม่เหล่านี้ไม่ปล่อยแสงวาบตรงปากกระบอกปืนและไม่มีเสียงขณะยิงเลยสักนิด ทหารที่รอดชีวิตไม่กี่คนรายงานว่าไม่เห็นศัตรูสักคนในทิศทางของวิถีกระสุนที่ยิงมา จากข่าวกรองที่สายลับของเรารวบรวมมาได้ ระบุว่ามีแนวโน้มว่าศัตรูได้พัฒนารูปแบบการพรางตัวที่ว่องไวพร้อมกับปืนไรเฟิลใหม่ของพวกเขา โดยสรุปแล้ว การต่อสู้ที่ ไซเธีย ไฮแลนด์ 154 ถูก___________ กำหนดไว้ล่วงหน้าแล้ว โดยวางแผนให้เป็นการทดสอบยุทโธปกรณ์ใหม่ทางภาคสนาม และเป็นการสังหารหมู่ทหารของเรา",
  str_dispatch_book_chaptercont_8000_4 = "________ \"แดรกคูลา! ปีศาจโบราณพวกนี้เป็นเหมือนคำสาปสำหรับพวกเรา เขาโยนดาบลงบนพื้นและพูดกับศาสตราจารย์ว่า \"สิ่งมีชีวิตที่เกิดจากคำสาปที่มืดมนที่สุดเหล่านี้ เหมือนถูกจัดสรรและเกิดมาเพื่อรัตติกาลนิรันดร์ ดวงอาทิตย์เป็นศัตรูคู่อาฆาตของพวกเขา และกลางคืนเป็นสถานที่ศักดิ์สิทธิ์สำหรับพวกเขา… ตอนนี้พวกเขากำลังเป็นเหมือนปลาได้น้ำ\"\n\"ท่านนายกเทศมนตรี ฉันไม่คิดว่าแดรกคูลานี้จะน่ากลัวอะไรนัก จากผลการวิจัยของฉัน…\" \n\"แล้วคุณค้นพบอะไรใหม่มั้ย คุณหาทางกำจัดเจ้าสิ่งสกปรกนี่แบบถอนรากถอนโคนได้หรือยัง\" \n\"มะ ไม่ ฉันขอโทษ… จากการวิจัยของฉัน บอกได้เพียงว่า มีดวงอาทิตย์เท่านั้นที่สามารถฆ่าพวกมันได้…\" \n\"คุณ… คุณเรียกสิ่งนี้ว่า 'การวิจัย' งั้นเหรอ วิจัยเพื่อหาวิธีที่เรารู้ ๆ กันอยู่แล้วเนี่ยนะ! ตอนนี้สัตว์ประหลาดชั่วร้ายเหล่านั้นได้บุกเข้าไปในเมือง แล้วก็ขับไล่พวกเราไปอยู่ใต้ดิน! ถ้าคุณไม่พบวิธีอื่นที่จะฆ่าพวกมันได้ในเร็ว ๆ นี้ คุณจะไม่มีเวลาสำหรับสิ่งที่คุณเรียกว่า 'การวิจัย' อีกต่อไป!\" \n\"จะ จากการวิจัยของฉัน…\" \n\"'วิจัย' อีกแล้วเหรอ?\"\n\"เป็นการดีกว่าถ้าพวกเราจะ… เข้าร่วมกับพวกมัน\" \n\"เข้าร่วม?!\" รู้สึกตกใจกับความคิดนี้ นายกเทศมนตรีชักดาบและชี้มาที่ศาสตราจารย์ \"อธิบายมา เร็วเข้า\" \nศาสตราจารย์ค่อย ๆ ดันแว่นขึ้น “ว่ากันตามตรงแล้ว ฉันคิดว่าปีศาจเหล่านี้ไม่ใช่ว่าจะสื่อสารไม่ได้เลย พวกมันมีความรู้สึก เป็นสิ่งมีชีวิตที่มีอวัยวะเหมือนเราทุกอย่าง! แดรกคูลาฉลาด และสามารถสื่อสารได้ชัดเจน ปีศาจเหล่านี้มีเหตุมีผล สามารถรู้สึกถึงอารมณ์ มีโครงสร้างทางสังคมเป็นของตัวเอง เรียกได้ว่ามีอารยธรรมที่เป็นเอกลักษณ์เฉพาะของเผ่าพันธุ์เลย จริงอยู่ที่นิสัยการกินของพวกมันทำให้เราค่อนข้างจะยอมรับพวกมันได้ยากหน่อย…” \n\"'นิสัยการกิน' งั้นเหรอ!\" นายกเทศมนตรีแกว่งดาบฟันแจกันแก้วแตก \"'นิสัยการกิน' ของพวกมันคือการดูดเลือดหยดจนสุดท้ายออกจากร่างกายเรา!\" \n\"คำว่า 'นิสัยการกิน' อาจผิดไปสักหน่อย พูดให้ถูกคือ มันเป็นจุดอ่อนของพวกมัน พวกมันต้องดื่มเลือดเพื่อให้มีชีวิตรอด ซึ่งในทางกลับกัน ก็ทำให้พวกมันไม่สามารถโดนแสงอาทิตย์ได้ แต่กลับมีอายุยืนยาว มีพละกำลัง คล่องแคล่วว่องไว และงดงาม...\" \n\"งดงามจนซีดเหมือนคนตาย ใช่สิ...\" \n\"คุณก็เห็นถึงความงามของแดรกคูลาใช่มั้ย ท่านนายกเทศมนตรี!\" \n\"อย่ามาเล่นคำกับฉันตามใจชอบแบบนี้นะ ศาสตราจารย์!\" \n\"แต่คุณต้องยอมรับมัน ว่าภายใต้รัตติกาลนิรันดร์นี้ พวกมันคือสิ่งมีชีวิตที่แข็งแกร่งกว่าเรามาก บางทีนี่อาจเป็นทิศทางการวิวัฒนาการ เป็นอนาคตของมนุษย์เราก็ได้ แม้ว่าคุณจะกลัวและดูถูกพวกมัน แต่รุ่นลูกรุ่นหลานของคุณล่ะ โลกในอดีตก็เคยเต็มไปด้วยความเกลียดชังระหว่างเผ่าพันธุ์ต่าง ๆ แต่เมื่อเวลาผ่านไปพวกมันก็หลอมรวมกันและก่อเกิดเป็นเผ่าพันธุ์ใหม่ขึ้น\" \n\"หยุดพูดเดี๋ยวนี้นะ ศาสตราจารย์!\" \n\"ท่านนายกเทศมนตรี ได้โปรดใจเย็นและเก็บดาบของคุณก่อน ฆ่าฉันตอนนี้ก็ไม่ได้เปลี่ยนแปลงอะไรหรอก\" \n\"หือ?!\" \n\"เพราะมันสายเกินไปแล้ว…\" ________",
  str_dispatch_book_chaptercont_9000_1 = "ผู้ที่อยู่บนนกแก้วยักษ์ล้วนเป็นนักรบจากทั่วทั้งอาณาจักร พวกเขาจะทักทายกันตามลักษณะนิสัยและชื่อ พวกเขาอยากจะปลุกเร้าความบันเทิงบนเรือ จึงจ้องเขม็งหาเรื่องและเยาะเย้ยหนุ่มโคลิน ผู้ซึ่งจ้องมองไปที่ทะเลอันเงียบสงบราวกับตกอยู่ในภวังค์ \n\"ท่ามกลางฮีโร่ที่ยิ่งใหญ่ของแผ่นดิน มีคนอย่างเจ้าหมอนี่ได้ยังไงนะ เขาไม่เคยเห็นทะเลมาก่อนหรือไง\" บางคนในกลุ่มเริ่มหัวเราะดัง \n\"ฉันได้ยินมาว่าเขาคือลูกชายของชาวประมง\" ใครบางคนพูดตอบ\n\"ดูจากสารรูปแล้ว เขาไม่น่าจะเคยอ่านแผนภูมิเดินเรือ หรือออกทะเลสักครั้งด้วยซ้ำ ยิ่งไม่ต้องพูดถึงเรื่องสู้ตาย ทั้งหมดที่เขารู้คงจะมีแต่ปลา! ชาวประมงแถวนี้ไม่เคยออกไปเกินแนวปะการังหรอก พวกเขาเลยจับแต่ปลาใกล้ตายที่ลอยมาในแหของตัวเอง\" \n\"แล้วอย่างเขาจะไปรู้วิธีหาสมบัติได้ยังไง? เขาจะหว่านแหไปดักเงินงั้นเหรอ อ๋า แต่อย่างน้อยเขาก็จับกุ้งหรือสาหร่ายกลับไปทำอาหารเย็นกินที่บ้านได้แหละนะ\" \nตอนนี้ทั้งดาดฟ้าเรือก็ดังสนั่นไปด้วยเสียงหัวเราะ และเหล่าวีรบุรุษผู้ยิ่งใหญ่ที่สุดของอาณาจักรก็พากันเรียกเขาว่า \"กัปตันโคลิน\" \nโคลินไม่สนใจเสียงนกเสียงกาเหล่านั้น เขาเดินกลับไปที่ห้องเพื่อพักผ่อนสำหรับการผจญภัยที่กำลังจะมาถึง \nขณะที่เขากำลังสลึมสะลือจากการหลับอยู่นั้น ก็ต้องตกใจตื่นเพราะเสียงใครบางคนตะโกนขึ้นว่า \"พายุ!\" เขารับรู้ได้ในทันทีว่านกแก้วยักษ์กำลังโคลงเคลงอย่างรุนแรงไปมาเหมือนต้นอ่อนในสายลม \nเขาขึ้นไปที่ดาดฟ้าเรือเพื่อดูว่าเกิดอะไรขึ้น และเกือบจะตกจากเรือเพราะกระแสลมที่พัดแรง ขณะที่เขาถูกเหวี่ยงข้ามดาดฟ้าเรือไปนั้น ก็ยื่นมือออกไปจับอะไรก็ตามที่เขาคว้าไว้ได้ โชคดีที่มันเป็นเชือกที่ผูกกับเสากระโดงเรือ \nกัปตันเป็นชายร่างผอมสูงที่มากประสบการณ์ในการเดินทะเล ภาคภูมิใจกับความสามารถในการพยากรณ์การเกิดพายุด้วยข้อเข่าของตัวเอง ในวันนี้เขามีความสุขไปกับการดื่มไวน์ชั้นเลิศที่ลูกชายขุนนางนำมามอบให้ ดื่มไปเพียงแก้วสองแก้ว เข่าพยากรณ์ของเขาก็เริ่มสั่นและไม่ได้สังเกตถึงความหายนะที่กำลังจะเกิดขึ้นเลยแม้แต่น้อย จนเมื่อรู้สึกกลัวตาย เขาสั่งลูกเรือใหม่ของเขาให้ไปลดใบเรือ น่าแปลกที่วีรบุรุษผู้ยิ่งใหญ่จำนวนหนึ่งพยายามหาที่ยืนบนเรือที่กำลังโคลงเคลง แต่กลับถูกคลื่นยักษ์ซัดลงมาจากดาดฟ้าเรือด้วยพลังทำลายล้าง พัดพาพวกเขาลงสู่ห้วงทะเล\nท่ามกลางสายฝนที่ตกกระหน่ำ โคลินสำลักน้ำ แล้วเขาก็รู้ตัวว่าตัวเองถูกคลื่นกระแทกสลบไป แต่โชคดีที่ไม่ทำให้เขาตกลงไปในสุสานคลื่นทะเล เขาคุ้น ๆ ว่าเขาได้ยินเสียงกัปตันกรีดร้องให้พวกเขาลดใบเรือก่อนที่คลื่นจะซัดเข้ามา แต่หลังจากนั้น โคลินก็พบว่าไม่มีใครทำตามคำสั่งของกัปตันเรือเลยสักคน \nกัปตันได้รับบาดเจ็บจนหมดสติไป ลูกเรือที่เหลือไม่บาดเจ็บ ก็ถูกคลื่นซัดตกลงน้ำ หรือไม่ก็อยู่ยอมจำนนปล่อยไปตามเวรตามกรรม \nโคลินรวบรวมความกล้า แล้วผูกเชือกรอบเอวของตัวเอง และเริ่มไต่ขึ้นเสากระโดงเรือ เมื่อเขาพยายามจะลดเสากระโดงเรือลง ก็ได้ตะโกนลงไปบอกคนข้างล่าง \"ตราบเท่าที่เรือยังไม่จม เราก็จะรอดไปกับมัน!\" \nคนบางส่วนข้างล่างรู้สึกฮึกเหิมด้วยคำพูดและการกระทำของโคลิน พวกเขาไม่อยากตายโดยสูญเปล่า พวกเขาทำตามเด็กหนุ่ม พยายามผูกเชือกรอบตัว แล้วปีนขึ้นไปที่ดาดฟ้าเรือเพื่อช่วยโคลิน คำพูดของโคลินทำให้พวกเขานึกถึงความจริง เรือคือดาบของพวกเขา พวกเขาจะต้องฟันฝ่าทะลุพายุออกไปและเอาชีวิตรอดจากความตายที่ได้พบเป็นครั้งแรกในชีวิตการเดินเรือ \nหลังพายุสงบลง หนึ่งในกลุ่มคนพวกนั้นก็เข้ามาหาโคลินและถามชื่อของเขา วีรกรรมความกล้าหาญของเขาถูกแพร่กระจายไปทั่วเรือ เข้าถึงหูผู้รอดชีวิตทุกคนรวมถึงกัปตันเรือที่เพิ่งฟื้นขึ้นมาไม่นาน เขาถูกยอมรับว่าเป็นวีรบุรุษ คนที่เรียกเขาว่า \"กัปตันโคลิน\" เข้ามาขอโทษ จากนั้นก็เรียกเขาว่า \"โคลินผู้กล้า\" \nอย่างไรก็ตาม ความทุกข์ยากของพวกเขายังไม่จบเพียงเท่านี้ พายุทำให้ใบเรือขาด กัปตันแจ้งว่าหากไม่มีใบเรือที่กำหนดทิศทาง พวกเขาก็จะต้องลอยไปอย่างไร้จุดหมายหรืออาจต้องตายกลางทะเล ตอนนั้นเองที่โคลินผู้กล้าเกิดความคิดอย่างหนึ่งขึ้นมา เขาหันไปหาลูกเรือ และแนะนำให้พวกเขาเย็บผ้าห่มและผ้าอื่น ๆ เข้ากับใบเรือที่ฉีกขาด \n\"ปล่อยให้เป็นหน้าที่ฉันเอง\" โคลินทำให้พวกเขาสบายใจ \"ก็ฉันเป็นลูกชายของชาวประมงนี่นา\" \nเขาเริ่มคลายเชือกเพื่อทำเป็นเกลียว และหยิบเข็มที่ทำจากก้างปลาออกมา จากนั้นก็เริ่มลงมือเย็บใบเรือใหม่ทั้งหมดด้วยมือของเขาเอง\nหลังจากทำงานหนักมาหลายชั่วโมง นกแก้วยักษ์ก็ได้ชักใบเรือใหม่ชั่วคราวขึ้น และเดินทางเกยฝั่งอย่างปลอดภัย",
  str_dispatch_book_chaptercont_9000_2 = "เกาะที่สองถูกครอบครองโดยมังกรบิน มากกว่าที่มนุษย์ทุกคนเคยเห็นมาในชีวิต เฝ้าสมบัติลับที่อยู่ลึกเข้าไปในถ้ำ พวกมันโฉบลงมาโจมตีใครก็ตามที่โง่เขลาพอที่จะเข้าใกล้ แม้ว่านักรบจะมีความชำนาญในการต่อสู้ แต่เมื่อเผชิญกับจำนวนมังกรบินที่ผ่านไม่ได้ พวกเขาก็ตัดสินใจถอยทัพชั่วคราว \nอย่างไรก็ตามมังกรไม่รองรับ พวกเขาไล่ตามเหล่าฮีโร่อย่างดื้อรั้นจนถึงชายฝั่งเกาะ \nนักรบคนหนึ่งถูกปลุกเร้าด้วยความอุตสาหะหันไปหาฝูงมังกรและตะโกนว่า \"นี่เป็นวิธีที่คุณตอบแทนความเมตตาของเราหรือไม่ เราเลือกที่จะไม่ฆ่าคุณ แต่ตอนนี้คุณไม่มีทางเลือกให้เราจับอาวุธ!\"\nเขาชักดาบออกมา ความเกรี้ยวกราดของการต่อสู้ที่พลุ่งพล่านอยู่ในดวงตาของเขา \nแต่ Colin the Brave จับแขนของชายผู้นั้น ชี้ไปทางภูเขาที่ใจกลางเกาะ ก่อนที่นักรบจะมีโอกาสโต้กลับ เสียงคำรามที่ดังและแรงสั่นสะเทือนก็เริ่มแผ่กระจายออกมาจากส่วนลึกของภูเขา \nทันใดนั้น รูปร่างมหึมาก็โผล่ออกมาจากยอดเขา ไม่ใช่ภูเขา แต่เป็นภูเขาไฟ และเป็นที่อยู่ของมังกรไททานิค! \nเหล่านักรบเมื่อรู้ว่าพวกเขาไม่สามารถต้านทานศัตรูตัวฉกาจเช่นนี้ได้ จึงผลักเรือของตนกลับออกไปในทะเลและออกห่างจากเกาะที่เต็มไปด้วยมังกร \nนักรบหันไปหา Colin the Brave และถามเขาว่า \"คุณรู้ได้อย่างไรว่ามังกรจะคลานออกมาจากภูเขาไฟนั้น\" \n“ฉันไม่ได้” โคลินตอบ \"ฉันเพิ่งสัมผัสได้ถึงแรงสั่นสะเทือนของพื้นดินข้างใต้เรา\" \nอย่างไรก็ตาม นักรบไม่พอใจกับคำตอบของเขา \"การสั่นสะเทือนเริ่มต้นขึ้นเมื่อสัตว์ร้ายตัวนั้นเริ่มปรากฏตัว! คุณบอกเรื่องไร้สาระอะไรกับฉัน?\" \nคอลินถามนักรบอย่างสุภาพเพื่อหลีกเลี่ยงการด่วนสรุป จากนั้นฟังอย่างตั้งใจสักสองสามวินาทีก่อนที่จะพูดว่า \"พ่อครัวของเรือจะขึ้นมาบนดาดฟ้าเรือในอีกสักครู่\" \nแน่นอนว่าไม่กี่วินาทีต่อมา แม่ครัวก็เดินขึ้นไปบนดาดฟ้า \nColin เริ่มอธิบายตัวเองอีกครั้ง แต่ในที่สุดนักรบก็เข้าใจ: Colin the Brave สามารถรับรู้ถึงแรงสั่นสะเทือนที่คนทั่วไปไม่สามารถทำได้ และยังสามารถแยกแยะขนาดและรูปร่างโดยประมาณของวัตถุที่เข้ามาได้ ด้วยเหตุนี้ เขาจึงทำได้เพียงคาดการณ์ว่าร่างมังกรขนาดใหญ่กำลังใกล้เข้ามา แม่ครัวเมื่อได้ยินประสบการณ์ของพวกเขาและความสามารถอันน่าทึ่งของ Colin ก็ชวนผู้ชายลงไปดื่มอย่างร่าเริงและทำกระต่ายกระตุกแบบพิเศษของเขา \nนกแก้วแกรนด์แล่นต่อไปอีกครึ่งวัน แต่เมื่อถึงที่หมาย ผู้โดยสารต่างตกใจสุดขีด เกาะแรกที่พวกเขาไปถึงซึ่งพวกเขาตัดสินใจล่าถอยกลับหายไปในอากาศ! \nนักผจญภัยที่งงงวยมองดูลูกเรือและถามว่าพวกเขาอ่านแผนที่ผิดหรือไม่ \nลูกเรือตรวจสอบแผนที่และปรึกษาเครื่องมือนำทางของพวกเขา และหลังจากโต้เถียงกันอยู่นาน พวกเขาได้ข้อสรุปว่าไม่มีข้อผิดพลาดในการนำทางเกิดขึ้น \nทันใดนั้น โคลินรู้สึกถึงแรงสั่นสะเทือนลึกลับอีกครั้ง เขาวิ่งออกไปที่หัวเรือและมองออกไปที่ทะเล หลังจากนั้นครู่หนึ่ง คลื่นแปลกๆ ก็เริ่มกระเพื่อมเข้าหาพวกเขา ทำให้นกแก้วโยกตัวหนักขึ้นเรื่อยๆ \nขณะที่เหล่าฮีโร่กำลังคาดเดาธรรมชาติของปรากฏการณ์ พวกเขาก็มองออกไปที่ขอบฟ้า พวกเขาสังเกตเห็นว่าทะเลข้างนอกนั้นมืดลงเรื่อยๆ ราวกับว่ามีเงาขนาดใหญ่ทอดตัวอยู่เหนือผืนน้ำ \n\"สิ่งนี้เกิดขึ้นตลอดเวลา\" ชายคนหนึ่งพูดขณะหัวเราะกับตัวเอง \"เมฆบังดวงอาทิตย์เป็นครั้งคราว และทิ้งเงาแบบนี้ไว้บนผิวน้ำ\" \nทุกคนมองขึ้นไปบนท้องฟ้า แต่ก็ต้องตกตะลึง... ไม่มีเมฆก้อนใดอยู่เหนือพวกเขา พวกเขาตระหนักว่าสิ่งนี้อาจหมายถึงเงาที่อยู่ใต้ผิวน้ำและแฝงตัวอยู่ในส่วนลึกเท่านั้น \nหลังจากนั้นไม่นาน ผิวน้ำก็เริ่มเป็นฟองไปทั่ว และวัตถุเล็กๆ สีขาวก็เริ่มลอยขึ้นสู่ผิวน้ำ ชายคนหนึ่งหันกล้องโทรทรรศน์ของเขาไปยังวัตถุสีขาวกลุ่มหนึ่ง เขากระซิบด้วยความตกใจ \"นั่นคือกระต่ายที่เราพบบนเกาะแรก...\"",
  str_dispatch_book_chaptercont_9000_3 = "โคลินผู้กล้าตื่นขึ้นมาและพบว่าตัวเองนอนอยู่บนพื้นแข็ง เขาเอื้อมมือออกไปอย่างงุนงง มันเยือกเย็นและราบเรียบเหมือนเป็นหินก้อนใหญ่ เขาลุกขึ้นนั่งขยี้ตาและเริ่มมองไปรอบ ๆ สิ่งที่เขาเห็นทำให้หายใจไม่ออก น้ำไหลอยู่เหนือศีรษะของเขา พร่ามัวและเป็นสีฟ้า ราวกับกำลังอยู่ใต้ท้องทะเล จุดแสงสีซีดก็ส่องอยู่เหนือศีรษะเช่นกัน มันเป็นดวงอาทิตย์ใช่มั้ย เขาแน่ใจว่าตัวเองกำลังหายใจอยู่ แต่ไม่มีฟองอากาศออกจากปากของเขา เขาอยากส่งเสียง แต่สภาพแวดล้อมรอบข้างของเขากลับเงียบเกินไป\nเมื่อลุกขึ้น เขาก็พบว่าตัวเองยืนอยู่ตรงกลางของสิ่งที่ดูเหมือนเป็นถนน โดยมีรูปปั้นแปลก ๆ ขนาบอยู่สองข้าง ด้วยความอยากรู้ เขาจึงเดินเข้าไปสำรวจดูรูปปั้นต่าง ๆ อย่างใกล้ชิด พวกมันดูเหมือนสัตว์ประหลาดที่แกะสลักจากโคลน\nโคลินเอื้อมมือไปจับ พื้นผิวที่หยาบกร้านของมันทำให้เขารีบดึงมือกลับอย่างหวาดกลัว\nนอกเหนือจากรูปปั้นหินแล้ว เขายังเห็นถนนธรรมดาที่ทอดยาวออกไปไกลสุดลูกหูลูกตา ซึ่งดูเหมือนจะเป็นบันไดขนาดใหญ่ที่ไม่สมส่วน เขามองขึ้นไปด้านบน ตรงสุดปลายทางบันได เหมือนเป็นซากประตูหินขนาดใหญ่ ส่วนใหญ่ทรุดโทรมไปเกือบหมดแล้ว\nเขาหันไปมองข้างหลัง ก็พบกับบันไดที่มีปลายทางสิ้นสุดคือขุมลึกใต้ทะเลซึ่งอยู่ไม่ไกล ทำให้โคลินได้แต่เดินไปข้างหน้าเพียงทางเดียวเท่านั้น อย่างไรก็ตาม หลังจากผ่านเสาหิน เขาก็สังเกตเห็นความเปลี่ยนแปลงรอบ ๆ ตัว... เริ่มรู้สึกเหมือนถูกมองด้วยสายตานับไม่ถ้วน แต่รอบตัวกลับไม่มีอะไร เขาเริ่มวิ่งหนี อยากจะออกไปจากที่นี่เต็มทน แม้ว่าเขาจะต้องคลานขึ้นบันไดขนาดใหญ่ที่อยู่ข้างหน้าเขาก็ตาม เมื่อมองย้อนกลับไป เขาก็พบว่าสายตาสยดสยองที่เขารู้สึกเมื่อกี้มาจากขุมลึกนั้น ขนทุกเส้นบนตัวเขาลุกชัน สัญชาตญาณบอกเขาให้หนีเอาชีวิตรอด\nเขาตะกายขึ้นบันไดหินขนาดใหญ่หลายสิบขั้นโดยแทบไม่ต้องใช้ความพยายาม แต่แล้วเขาก็สังเกตเห็นความผิดปกติของขั้นบันไดเหล่านี้: ดูเหมือนบันไดจะสูงขึ้นและกว้างขึ้นทุกทีที่เขาขึ้นไป\nเมื่อมาถึงประตูที่พังลงมา ก็เห็นรูปสัตว์ประหลาดที่แกะสลักบนเศษชิ้นส่วน มันมีตาและหนวดขนาดมหึมา\nโคลินตัวสั่นด้วยความกลัวหรือไม่ก็อาจเป็นความตื่นเต้น เขารู้สึกว่ามีอะไรกระตุ้นหัวใจให้เขาก้าวไปข้างหน้า เมื่อคลานไปบนซากปรักหักพังของประตูหิน เขาก็ต้องตกตะลึงกับภาพตรงหน้า มันคือสถานที่ที่ตั้งอยู่ในที่ราบกว้างใหญ่ใต้ท้องทะเล เป็นซากปรักหักพังของอาณาจักรขนาดใหญ่\nในใจของโคลินเต็มไปด้วยคำถาม แต่มีความคิดหนึ่งที่ผุดขึ้นมาอย่างรุนแรง ด้านล่างของบันไดที่เขาเพิ่งเดินขึ้นมานั้น เป็นขนาดที่เหมาะสมกับขนาดของมนุษย์โดยเฉลี่ย แต่พอขึ้นมาเรื่อย ๆ พวกมันก็ใหญ่ขึ้นเรื่อย ๆ จนกระทั่งเขาไม่มีทางเลือกอื่นนอกจากต้องปีนด้วยมือและเท้า ช่างน่าแปลก แม้ว่าอาณาจักรนี้ที่ใคร ๆ ต่างก็เคยเชิดชูจะอยู่ในสภาพทรุดโทรมไม่เหลือชิ้นดีแล้วก็ตาม ผู้มาเยือนก็ยังคงต้องคลานเข้าหาราวกับกำลังกราบพวกเขา...\nโคลินสัมผัสได้ถึงดวงตาที่จ้องมองอันคุ้นเคย เขารีบหันกลับไปอย่างรวดเร็ว... แต่เมื่อเขาฟื้นขึ้นมาอีกครั้ง ก็พบว่าตัวเองนอนอยู่บนหาดทรายที่อบอุ่น มั่นใจได้จากคลื่นเย็นกระทบเท้าว่าเขาไม่ได้ฝันไปอีก เขาเริ่มสำรวจไปรอบ ๆ ตัว พบว่าไม่มีอะไรผิดปกตินอกจากรอยลากแปลก ๆ ที่หลงเหลืออยู่บนหาดทราย\nทันใดนั้น โคลินก็นึกถึงสิ่งสุดท้ายที่เขาเห็นใต้ทะเล นั่นคือ สัตว์ประหลาดตัวใหญ่ที่มีหนวดขาวอมเทา...",
  str_dispatch_book_chaptercont_9000_4 = "ทันใดนั้น หนวดขนาดใหญ่ก็โผล่ขึ้นมาจากน้ำ คืบคลานไปตามข้างลำตัวเรืออาร์โก้จนเริ่มเอียง ลูกเรือถูกตรึงด้วยความหวาดกลัว มีเพียงโคลินผู้กล้าเท่านั้นที่ยกขวานขึ้นเหนือศีรษะแล้วเหวี่ยงฟันหนวดที่รุกล้ำเข้ามา นักรบถูกความกล้าหาญของโคลินกระตุ้น จึงชักกริชของเขาแล้วพุ่งเข้าปะทะกับหนวด ทั้งสองคนร่วมกันโจมตีมันจนหนวดขาด\nลูกเรือเร่งยกใบเรือขึ้นอย่างตื่นตระหนก อยากจะกลับขึ้นบก แต่ทะเลกลับเริ่มปั่นป่วนอย่างรุนแรง ในตอนแรก ลูกเรือนึกว่ามันเป็นเพียงแนวปะการังขนาดใหญ่ที่ลอยขึ้นจากผิวน้ำ แต่ในขณะที่มันโผล่ขึ้นจากน้ำมาเรื่อย ๆ ลูกเรือก็ตระหนักแล้วว่ามันเป็นเนื้อตะปุ่มตะป่ำของสัตว์ประหลาดขนาดมหึมา ลูกเรือโล่งใจเมื่อมันหยุดขึ้นมาจากส่วนลึก แต่มันดูนิ่งผิดธรรมชาติ\nโคลินผู้กล้ารู้สึกวิงเวียน อยู่ ๆ ก็นึกถึงภาพสัตว์ประหลาดขนาดใหญ่ที่แกะสลักไว้บนซากประตูหินที่อยู่ในอาณาจักรใต้ทะเลโดยไม่รู้ตัว สิ่งที่เขาไม่รู้ก็คือ สัตว์ร้ายตัวนี้มีชื่อที่สามารถพบได้ในแผนที่ทะเลโบราณเท่านั้น: ฮาฟก้า\nหลังจากเอนเอียงไปมาบนน้ำอยู่นาน เรืออาร์โก้ก็เทียบฝั่งได้ในที่สุด ลูกเรือกระโดดลงไปและตัดสินใจที่จะไต่ขึ้นหน้าผาที่ทอดแนวยาวไปตามชายหาด\nเมื่อเดินทางเลยครึ่งทางหน้าผาไป หนึ่งในลูกเรือก็ได้ยินโคลินกำลังพึมพำอะไรบางอย่าง\n\"ใต้ทะเลลึกมีมอนสเตอร์ 2 ตัว...\" เขาได้ยินโคลินพูดเช่นนั้น\nนักรบที่มักเป็นห่วงเป็นใยโคลินอดไม่อยู่ เลยคว้าเขามาและถามว่า \"นายพูดว่าอะไรนะ\"\n\"มอนสเตอร์ที่สามารถทำลายเรือ 10 ลำในเวลาเดียวกันได้... เจ้าสัตว์ประหลาดตัวใหม่นี่ดูจะตรงกับคำอธิบายมากกว่า ว่ามั้ย\" โคลินไม่ได้มองไปที่นักรบ แต่จ้องมองไปทางอื่นราวกับละเมออยู่ในความฝัน\n\"นายบอกว่ามอนสเตอร์ 2 ตัวงั้นเหรอ?\" ลูกเรือยังคงกังขา แต่หลังจากครุ่นคิดอยู่ครู่หนึ่ง พวกเขาก็ตระหนักว่ามันเป็นไปได้ทั้งหมด สัตว์ประหลาดตัวแรกที่พวกเขาพบมีหนวดสีขาวอมเทา เหมือนกับหนวดที่เพิ่งพันเรืออาร์โก้เมื่อกี้ แต่สัตว์ประหลาดตัวใหม่ที่โผล่ขึ้นจากทะเลตัวนั้น เป็นสีดำสนิท...\n“หรือข่าวลือจะผิด นี่ไม่ใช่คราเคนงั้นเหรอ” นักรบล้อเลียนตัวเองอยู่นานก่อนจะให้ข้อสรุป\n\"พวกนายเคยเห็นสิ่งมีชีวิตในทะเลที่เรียกว่า 'ปลาหมึก' มั้ย\" โคลินถาม ดูเหมือนกลับมารู้สึกตัวแล้ว\n\"ไม่เคยได้ยิน มันคืออะไรเหรอ\" หนึ่งในลูกเรือถาม\n\"ฉันได้ยินมาว่ามันไม่ใช่ปลา แต่เป็นปีศาจที่มีดวงตาชั่วร้าย\" อีกคนตอบ\n\"ฉันเคยได้ยินข่าวลือเกี่ยวกับมัน ว่ากันว่ามันฉลาดและหลอกล่อเก่ง\" คนที่สามโพล่งออกมา\n\"ใช่แล้ว พ่อของฉันเคยจับได้ตัวนึง แต่มันหนีไปได้... และมอนสเตอร์ขาวเทาตัวนั้นคล้ายกับปลาหมึกมาก\" โคลินพูด \"แต่ไม่มีปลาหมึกตัวไหนใหญ่พอที่จะทำให้ทั้งกองเรือหายไปในเวลาเพียงชั่วข้ามคืนได้หรอกนะ\" เขาเพิ่มเติม\nอันที่จริงแล้ว สัตว์ประหลาดสีดำที่ค่อย ๆ โผล่ออกมาจากมหาสมุทรนั้นมีขนาดใหญ่กว่าปลาหมึกยักษ์ใด ๆ เมื่อฟองและคลื่นที่ล้อมรอบมันมีขนาดใหญ่ขึ้นและรุนแรงขึ้น ก็มีภูเขาเล็ก ๆ ปรากฏขึ้นจากน้ำ ดูเหมือนมันจะสูญเสียพืชพันธุ์ส่วนใหญ่ที่เคยเติบโตอยู่บนนั้น มีเพียงหินเปล่าเปลือยเท่านั้นที่สัมผัสกับอากาศ\nหลังจากที่ลูกเรือไปถึงยอดหน้าผาและมองลงไปที่น้ำ พวกเขาก็ได้ตระหนักถึงขนาดที่แท้จริงของสัตว์ประหลาดในห้วงน้ำลึก ภูเขาลูกเล็กที่พวกเขาเห็นก่อนหน้านี้ได้ผุดขึ้นมาอย่างสมบูรณ์พร้อมกับหนวดสีดำขนาดใหญ่ มันฟาดหนวดเพียงครั้งเดียว ก็เกิดคลื่นน้ำพุ่งเข้าใส่ป่าของเกาะด้านล่างไปพร้อมกับเรืออาร์โก้ \nเมื่อเรือของพวกเขาติดอยู่ในซากต้นไม้ที่จมอยู่ใต้น้ำ พวกเขาก็เริ่มหมดหวัง “เป็นไปไม่ได้… เราจะเอาชนะสัตว์ประหลาดแบบนี้ได้ยังไง” ความหวาดกลัวเริ่มเข้าครอบงำเหล่าวีรบุรุษผู้กล้าหาญของอาณาจักร\n\"เรือโบราณอาร์โก้และเนตรทองคำ... ดูจากแผนที่ขุมทรัพย์ของเราแล้ว เรายังขาดตรีศูลแห่งทะเลลึก ขอแค่เราหามันเจอ เราก็จะมีโอกาสเอาชนะมอนสเตอร์แห่งท้องทะเลเหล่านี้ได้!\" โคลินผู้กล้าประกาศก้อง",
  str_dispatch_book_chaptercont_10000_1 = "1. ยอมจำนนต่อความเป็นผู้นำอันเป็นแบบอย่างของจอมทัพ\nจากคำพูดของจอมทัพแห่งอิลลูมินา \"มีเพียงผู้กล้าเท่านั้นที่กล้าเอื้อมถึงความสูงที่เป็นไปไม่ได้\"\nในฐานะผู้นำของสหพันธรัฐอิลลูมินาและแกนหลักของกองทัพ จอมพลแห่งอิลลูมินาเป็นพลเมืองต้นแบบ และเป็นแบบอย่างที่ดี ที่ชาวอิลลูมินาทุกคนควรศึกษาและปฏิบัติตามอย่างไม่ต้องสงสัย จอมพลสอนให้เราปฏิบัติต่อกันเสมือนคนในครอบครัว และหลอมรวมพวกเราทั้งหมดเข้าด้วยกันโดยการเสริมสร้างอุดมคติของเรา และส่งเสริมการมีวินัยในตนเอง จอมทัพให้ความสำคัญกับอิลลูมินาทุกคนอย่างดีราวกับแสงสว่างและความอบอุ่นของวันฤดูใบไม้ผลิที่สนุกสนาน และปกป้องพวกเขาโดยการกำจัดศัตรูของพวกเขาด้วยพลังอันท่วมท้น\nหากคุณพบว่าชีวิตของคุณขาดศรัทธาหรือผู้นำ จอมทัพแห่งอิลลูมินาคือตัวเลือกที่ดีที่สุดสำหรับการอยู่รอดของคุณ\n\n2. ขออิลลูมินาจงเจิดจำรัส! จงภักดีต่อหน้าที่และรักษาจิตใจให้ดีงาม\nไม่ว่าคุณจะสู้กับอิคลิพไซท์ในแนวหน้า หรือขุดค้นพบอารยธรรมโบราณ ทหารทุกคนของอิลลูมินาจะต้องแยกแยะและยึดถือหน้าที่บนบ่าของตนเอง:\nก. เพื่อกำจัดอิคลิพไซท์ทั้งหมดที่คุกคามความอยู่รอดของออโรเรียน\nข. เพื่อขุดค้นและวิจัยซากอารยธรรมโบราณอย่างเต็มที่ เพื่อผลักดันเทคโนโลยีและนวัตกรรมของเรา\nค. เพื่อฟื้นฟูแสงสว่าง ศักดิ์ศรี และความเจริญรุ่งเรืองของชาวออโรเรียและดินแดนนี้ ในนามของอิลลูมินา\n\n3. โอบรับความรุ่งโรจน์และความยุติธรรม\nความแตกต่างที่ชัดเจนระหว่างสหพันธรัฐอิลลูมินา และกองกำลังอื่น ๆ คือภารกิจอันรุ่งโรจน์ของเราที่ต่อสู้เพื่อออโรเรียนทุกคน และความยุติธรรมที่ชัดเจนของเราในการแยกแยะระหว่างสิ่งที่ถูกต้องกับสิ่งที่ผิด เดอะ แกรนดาร์เมียร์นำโดยผู้ตรวจการสูงสุด เนเมซิส ทำงานอย่างไม่รู้จักเหน็ดเหนื่อยเพื่อให้แน่ใจว่ามีการนำหลักคำสอนของเราไปใช้อย่างไม่คลุมเครือ\nพวกเขาเป็นผู้คุมระเบียบวินัยทางทหารของสหพันธรัฐอิลลูมินา และเป็นผู้ปกป้องความศรัทธาของเรา หากผู้ตรวจการสูงสุดเนเมซิสเห็นสมควรที่จะซักถามคุณ จงตอบคำถามอย่างซื่อสัตย์และอย่าทำอะไรที่เป็นการยียวนชวนให้ผู้ผดุงความยุติธรรมต้องโมโห โดยธรรมชาติแล้ว หากคุณเป็นผู้พิทักษ์ความยุติธรรมที่แท้จริง และแสดงความขอบคุณต่อเธอ คุณก็อาจได้กลายเป็นพันธมิตรแห่งความยุติธรรมของเธอได้เช่นกัน",
  str_dispatch_book_chaptercont_10000_2 = "I. เชื่อฟัง แต่จำไว้ว่าทุกคนเท่าเทียมกัน\nในสหพันธรัฐอิลลูมินา ยศและตำแหน่งทางทหารกำหนดว่าใครเป็นผู้นำและใครคือผู้ตาม แต่ผู้ที่มียศและตำแหน่งก็ไม่ได้มีสิทธิพิเศษมากกว่าชาวอิลลูมินาทั่วไป ความเท่าเทียมกันระหว่างพลเมืองทุกคนเป็นปัจจัยสำคัญที่แยกความแตกต่างระหว่างอุดมการณ์ของเรากับอุดมการณ์ของลูโมโพลิส ในสหพันธรัฐอิลลูมินา เราไม่เพียงแต่เป็นสหายร่วมรบเท่านั้น แต่ยังเป็นครอบครัวด้วยเช่นกัน โดยไม่คำนึงถึงภูมิหลังของคุณ ตราบใดที่คุณเห็นด้วยและรักษาค่านิยมของอิลลูมินาไว้ คุณก็สามารถผ่านการประเมินของเราและกลายเป็นสมาชิกที่น่าภาคภูมิใจและทรงคุณค่าของสังคมของเราได้\n\nII. ตรวจสอบอุปกรณ์ของคุณให้พร้อมใช้งานตลอดเวลา\nทหารทุกคนในสหพันธรัฐอิลลูมินามีความรับผิดชอบต่อตนเองและสหายร่วมรบ ควรตรวจสอบและบำรุงรักษาอุปกรณ์ของตนเองสม่ำเสมอ ซึ่งรวมถึงแต่ไม่จำกัดเพียง: การบำรุงรักษาปืนไรเฟิลพลังงานจลน์ การดูแลรักษาชุดเกราะต่อสู้ และลับใบมีดให้คมอยู่เสมอ นี่ไม่ใช่เพียงเพราะเมืองแกนน่อนทำหน้าที่เป็นกองกำลังต่อสู้หลักเพื่อต่อต้านภัยคุกคามจากอิคลิพไซท์และต้องพร้อมสำหรับการสู้รบตลอดเวลาเท่านั้น แต่หากผู้ฝึกสอนคนใดเห็นว่าคุณเตรียมตัวไม่ดีสำหรับการต่อสู้ พวกเขาจะส่งคุณเข้าร่วมการฝึกซ้อมสุดโหดซึ่งเลวร้ายยิ่งกว่าการเผชิญหน้ากับกองทัพอิคลิพไซท์เสียอีก เราเตือนคุณแล้วนะ\n\nIII. เทคโนโลยีมาก่อน\nทหารแกนน่อนเดิมเป็นพลเรือนติดอาวุธที่ได้รับคำสั่งจากลูโมโพลิสให้อพยพมาที่นี่ รวมถึงลูกหลานของพวกครึ่งมนุษย์และออโรเรียนทุกรูปแบบ ในตอนแรก ผู้ปกครองของลูโมโพลิสตั้งใจจะใช้เมืองแกนน่อนเป็นเหยื่อล่อเพื่อดึงดูดความสนใจของอิคลิพไซท์ จึงจำกัดการสนับสนุน ในตอนนั้นเหล่าทหารผู้กล้าและสามัญชนต้องเผชิญกับบททดสอบทุกรูปแบบจากสภาพแวดล้อมที่รุนแรง ภัยคุกคามจากอิคลิพไซท์ และแม้แต่เมืองลูโมโพลิสเอง\nแม้จะมีอุปสรรคมากมาย แต่บรรพบุรุษของเราก็ไม่เคยยอมแพ้ ด้วยความพยายามอย่างไม่เหน็ดเหนื่อยและทุ่มเทของนักวิทยาศาสตร์และนักวิจัยหลายคนที่พยายามรวมความรู้เกี่ยวกับลูมินาติกส์เข้ากับเทคโนโลยีโบราณที่อยู่ลึกเข้าไปในเมืองใต้ดินแกนน่อน ทำให้อิลลูมินาสามารถออกแบบเทคโนโลยีลูมินาเพื่อป้องกันภัยคุกคามอิคลิพไซท์ได้ในเวลาต่อมา ความรู้ทางเทคโนโลยีของเรามีมากกว่าเมืองอื่น ๆ ในทุกวันนี้ เทคโนโลยีล้ำสมัยของเราเหนือกว่าลูโมโพลิสบ้านเกิดของเราเมื่อนานมาแล้ว\nด้วยเหตุผลเหล่านี้ นักวิทยาศาสตร์และนักวิจัยจึงเป็นสมาชิกที่ได้รับความนับถืออย่างสูงของสังคมเมืองแกนน่อน ภายใต้สถานการณ์ฉุกเฉิน บุคลากรทางวิทยาศาสตร์และพลเรือนต้องได้รับความสำคัญให้อพยพก่อนเป็นกลุ่มแรก ๆ ในกรณีร้ายแรง การคุ้มครองบุคลากรทางวิทยาศาสตร์และอุปกรณ์ที่สำคัญจะมีความสำคัญสูงสุด",
  str_dispatch_book_chaptercont_10000_3 = "I. ทหารมีความสำคัญเป็นอันดับแรก\nอย่ามองว่าเมืองแกนน่อนเป็นเหมือนที่หลบภัยใต้ดิน แต่ให้เห็นว่าเป็นเหมือนป้อมปราการที่ไม่สามารถบุกเข้าไปได้จะเหมาะกว่า ในฐานะที่เป็นฐานปฏิบัติการในการต่อสู้กับภัยคุกคามอิคลิพไซท์ ทุกแง่มุมของชีวิตที่นี่จึงถูกออกแบบมาเพื่อส่งเสริมกิจกรรมทางทหารให้ดำเนินไปอย่างปกติเป็นอันดับแรก เพราะมีเมืองแกนนอนเป็นแบบอย่าง เราจึงยืนหยัดว่าการตั้งถิ่นฐานทั้งหมดภายในสหพันธรัฐอิลลูมินาจะต้องยึดมั่นในปรัชญาของตน นั่นคือ กองทัพมีความสำคัญเหนือทุกสิ่ง หากมีความขัดแย้งทางผลประโยชน์ระหว่างกองทัพกับด้านอื่น ๆ ของชีวิต (กิจการภายในประเทศ/ต่างประเทศ ความเป็นอยู่ของพลเมือง การวิจัยทางวิทยาศาสตร์ และอื่น ๆ) ควรมีการจัดลำดับความสำคัญและการสนับสนุนอย่างไร้เงื่อนไขแก่กองทัพก่อน\n\nII. การส่งเสริมวิทยาศาสตร์ \nควรสังเกตเสมอว่า ในกรณีที่อิคลิพไซท์บุกตีเมืองแกนน่อน เราไม่สามารถพึ่งพาใครได้นอกจากตัวเอง มีเพียงการศึกษาวิทยาศาสตร์และเทคโนโลยีของอารยธรรมในอดีตเท่านั้นที่สามารถปรับปรุงประสิทธิภาพในการต่อสู้กับอิคลิพไซท์ได้ โดยเฉพาะอย่างยิ่ง นี่หมายถึงการเพิ่มความรู้เกี่ยวกับเทคโนโลยีลูมินาของเรา\nเป็นเพราะมีวิทยาศาสตร์ เราจึงสามารถขับไล่ภัยคุกคามอิคลิพไซท์ไปได้ ปรับปรุงสภาพของเมืองแกนน่อน ให้อาหารและติดอาวุธให้กับกองทัพของเราด้วยอาวุธขั้นสูง และเลี้ยงประชากรของเราผ่านการใช้เทคโนโลยีขั้นสูง กล่าวโดยย่อว่า วิทยาศาสตร์เป็นอาวุธของเรา ไม่เพียงแต่ในการต่อสู้กับความชั่วร้าย แต่ยังรวมไปถึงการต่อสู้กับร่องรอยของความเขลาก่อนยุคสมัยใหม่ของเรา จิตวิญญาณแห่งเหตุผลและลัทธิปฏิบัตินิยมจะนำเราไปสู่เป้าหมายสูงสุด\n\nIII. ส่วนรวมนิยม\n\"ลูกธนูดอกเดียวนั้นหักง่าย แต่ลูกธนูมัดหนึ่งจะไม่มีวันโค้งงอ\" เราเป็นสัตว์สังคมที่ไม่สามารถอยู่รอดได้ด้วยตัวเองอย่างสมบูรณ์ ไม่ต้องพูดถึงความเจริญรุ่งเรือง เมื่อเผชิญกับความเป็นจริงและสภาพแวดล้อมที่โหดร้ายของชีวิต ทั้งหมดที่เราต้องพึ่งพาคือหมู่คณะ เพราะมีเพียงหมู่คณะเท่านั้นที่สามารถให้การสนับสนุนที่เราต้องการอย่างแท้จริงได้ เมื่อคุณพบว่าตัวเองอยู่ตามลำพังในเมืองแปลก ๆ คุณจะได้รับการคุ้มครองจากหมู่คณะใหญ่ที่รู้จักกันในชื่อสหพันธรัฐอิลลูมินา ดังนั้นคุณควรหลีกเลี่ยงการถามว่าส่วนรวมสามารถทำอะไรให้คุณได้บ้าง แต่ให้ถามว่าคุณสามารถทำอะไรเพื่อส่วนรวมได้บ้าง\n\nIV. เหตุผลและการปฏิบัติจริง\nแม้ว่าเราจะเป็นสิ่งมีชีวิตที่มีอารมณ์ความรู้สึก แต่โลกของเราก็มีพื้นฐานมาจากความเป็นจริงทางวัตถุ ดังนั้นควรหลีกเลี่ยงการสนทนาที่ว่างเปล่าอย่างพวกอภิปรัชญา วิทยาศาสตร์เป็นพื้นฐานของสหพันธรัฐอิลลูมินา และพื้นฐานของวิทยาศาสตร์คือความสมเหตุสมผลและหลักปฏิบัติที่คำนวณได้ การคาดเดาแบบสุ่ม ไสยศาสตร์ที่โง่เขลา และความหลงผิดในความยิ่งใหญ่เป็นศัตรูตัวฉกาจของเหตุผล และได้รับการพิสูจน์แล้วในประวัติศาสตร์ว่าจะนำผู้คนไปสู่ความมืด มีเพียงแสงแห่งเหตุผลเท่านั้นที่สามารถขจัดความมืดและไม่เพียงช่วยให้เราเผชิญหน้ากับความเป็นจริงเท่านั้น แต่ยังปรับปรุงให้ดีขึ้นด้วย",
  str_dispatch_book_chaptercont_10000_4 = "I. ปกป้องผลประโยชน์ของสหพันธรัฐอิลลูมินา\nในช่วงประวัติศาสตร์ มีเพียงสหพันธรัฐอิลลูมินาเท่านั้นที่ยังคงอยู่แนวหน้าในการต่อสู้กับภัยคุกคามอิคลิพไซท์ และนำชาวออโรเรียนทั้งหมดไปกำจัดอิคลิพไซท์เพื่อสันติภาพของโลก การทำให้สหพันธ์ยิ่งใหญ่เป็นสิ่งจำเป็นในการบรรลุเป้าหมายสูงสุด ดังนั้นสมาชิกทุกคนจึงมีหน้าที่ปกป้องผลประโยชน์ของสหพันธ์และไม่ถอนตัวเมื่อเกิดปัญหาสำคัญขึ้น\n\nII. ปกป้องผลประโยชน์ทางการทหาร\n\"ความจริงจะแผ่ขยายออกไปไกลเท่าที่ทหารจะเอื้อมถึง\" อย่าหลงกลความสงบสุขที่อยู่ตรงหน้า บนดินแดนนี้ กำลังทหารเป็นตัวกำหนดตำแหน่งของรัฐ โดยสหพันธ์ก่อตั้งขึ้นจากกองกำลังทหาร เพื่อเสริมสร้างความแข็งแกร่งให้กับหลายเมืองภายใน ดังนั้นเราต้องเฝ้าระวังรัฐที่มีกองทัพที่ทรงพลัง ไม่ว่ารัฐเหล่านั้นจะมีท่าทีเช่นไร ก็อาจเป็นภัยคุกคามต่อสหพันธ์ได้เหมือนกัน เราควรรักษาผลประโยชน์ทางทหารทั้งหมด ไม่ว่าทางตรงหรือทางอ้อม โดยห้ามขัดแย้งกับมาตรา 1\n\nIII. ปกป้องผลประโยชน์ของเมืองแกนน่อน\nเมืองแกนน่อนเป็นหัวใจสำคัญของสหพันธรัฐอิลลูมินา และเป็นแนวป้องกันสุดท้ายที่จะรับมือกับอิคลิพไซท์ การปกป้อง คุ้มครอง และพัฒนาเมืองแกนน่อนเป็นสิ่งที่อิลลูมินาไม่ควรลืม อย่างไรก็ตาม ห้ามขัดแย้งกับมาตรา 1 และ 2\n\nIV. ปกป้องผลประโยชน์ของการวิจัย\nการพัฒนาเทคโนโลยีและสำรวจทฤษฎีทางวิทยาศาสตร์เป็นหน้าที่ของนักวิจัยชั้นยอด ดังนั้นนักวิจัยทุกคนจึงมีค่า และแม้ว่าจะปฏิบัติงานคนละฝ่ายกัน แต่พลเมืองของอิลลูมินาก็ควรปฏิบัติตามคำสั่งของนักวิจัยในการปฏิบัติงานพิเศษ โดยจะต้องไม่ขัดแย้งกับมาตรา I, II และ III\n\nV. ปกป้องผลประโยชน์ส่วนรวม\nเมื่อสถานการณ์เอื้ออำนวย ชาวอิลลูมินาทุกคนจะต้องรวมกลุ่มเพื่อปกป้องผลประโยชน์ส่วนรวม แม้จะเป็นกลุ่มชั่วคราวก็ตาม โดยไม่ละเมิด 4 ข้อแรก เราต้องยึดหลักผลประโยชน์ส่วนรวมต้องมาก่อนผลประโยชน์ส่วนตัวเสมอ",
  str_dispatch_book_chaptercont_10000_5 = "I. ตรงต่อเวลา\nอิลลูมินาต้องมีวินัยเรื่องเวลา ในชีวิตประจำวัน ทุกเรื่องต้องทำตามแผน ความล่าช้าจะขัดขวางงานของผู้อื่น ดังนั้นต้องปฏิบัติตามกำหนดการอย่างเคร่งครัด\n\nII. จงซื่อสัตย์\nการโกหกไม่สามารถดำรงอยู่ในสหพันธรัฐได้ ไม่ว่าจะเพื่อจุดประสงค์ใดก็ตาม การโกหกจะส่งผลกระทบและสร้างความเสียหายต่อผู้อื่นเมื่อความจริงถูกเปิดเผย จงซื่อสัตย์และพูดแต่ความจริงคือความรับผิดชอบของอิลลูมินาทุกคน\n\nIII. ปฏิบัติตามคำสั่ง\nอิลลูมินาทุกคนต้องปฏิบัติตามคำสั่ง เหมือนกับแขนที่เชื่อฟังคำสั่งของสมอง ต้องปฏิบัติตามการตัดสินใจของผู้บังคับบัญชาให้ถึงที่สุด โดยไม่เบี่ยงเบน ปฏิเสธ หรือแม้แต่ขัดคำสั่ง\n\nVI. หมั่นเรียนรู้\nวิทยาศาสตร์ไม่มีขอบเขต และความรู้ก็เช่นกัน สหพันธรัฐกำลังมองหานวัตกรรมทางเทคโนโลยีอยู่ตลอดเวลา อิลลูมินาทุกคนต้องเรียนรู้ความรู้ใหม่เพื่อปรับให้เข้ากับสภาพแวดล้อมใหม่ อย่ากังวลกับการขาดความสามารถหรือความถนัด อิลลูมินาทุกคนที่เรียนรู้คืออิลลูมินาที่แท้จริง\n\nVI. ออกกำลังกายเป็นประจำ\nร่างกายของอิลลูมินาไม่ได้เป็นของตนเองเพียงผู้เดียวเท่านั้น แต่ยังเป็นของสหพันธรัฐอีกด้วย ดังนั้นการอยู่อย่างพอดีคือการปกป้องผลประโยชน์ของสหพันธ์ การฝึกอบรมที่สมเหตุสมผลเพื่อปรับปรุงลักษณะทางกายภาพ และการตระหนักถึงการไม่เสียเวลาไปกับการปล่อยตัวที่ไม่มีความหมายควรอยู่ในใจของอิลลูมินาทุกคน",
  str_dispatch_book_chaptercont_11000_1 = "เอด้ามักฝันถึงผ้าคลุม ที่เมื่อฉีกออกเป็นชิ้น ๆ เผยให้เห็นคนร่างผอมเพรียว 2 คน\nพวกเขาวางเด็กในอ้อมแขนลงในเปล แล้วลมก็พัดเข้าหน้าต่าง จนร่างทั้งสองกระจายซ่าน ทิ้งเพียงคำพูดว่า “พ่อกับแม่จะออกไปดูโลกภายนอก”\nเมื่อเอด้าโตขึ้น ความฝันก็ชัดเจนขึ้น เธอเห็นผมสีน้ำตาลเป็นประกายของแม่และคางที่เริ่มมีหนวดขึ้นของพ่อ พวกเขาจากไปพร้อมกับความเด็ดเดี่ยวที่เพิ่มขึ้นในแต่ละครั้ง หลอมรวมร่างกายของพวกเขาให้เรืองแสงอัศจรรย์ในทุกครั้ง เอด้าคุ้นเคยกับแสงนั้น เธอมองเห็นมันทุกคืนบนท้องฟ้าและรู้ว่ามันคือแสงออโรร่า\n“โลกภายนอกเป็นยังไงนะ ถ้าฉันสามารถขับยักษ์โคลอสซัสอย่างพวกเขาได้ ฉันจะออกจากอีราเวลไปด้วยได้ไหม” เอด้าเฝ้าฝัน\nวันหนึ่ง คำขอของเธอก็เป็นจริง เธอได้ยินเสียงจากส่วนลึกของอีราเวล\n\"โคลอสซัสถูกสร้างมาเพื่อโบยบินบนท้องฟ้า อาจมีบ้างที่ถูกสร้างมาเพื่อดิน และทะเล แต่ท้องฟ้าคือบ้านที่แท้จริงของโคลอสซัส!\"\n“โคลอสซัสตัวใหญ่พวกนั้นน่ะโง่ เห็นได้ชัดว่าพวกมันสามารถบินได้สูงมาก แต่ยังกักขังตัวเองไว้ที่อีราเวลโดยไม่มีความทะเยอทะยาน ถ้าเป็นฉันนะ ฉันจะพามันไปสู่จุดสิ้นสุดของแสงออโรร่า! ฉันไม่ได้อิจฉานะ... \"\n“ฉันอยากรู้จังว่าการมีผู้นำทางมันรู้สึกเป็นยังไงนะ”\n\"คงรู้สึกเหมือนมีเพื่อน\" เอด้าตอบเบา ๆ\n\"นั่นใคร มาคุยกับฉันทำไม\" โคลอสซัสตัวน้อยที่จอดอยู่ในส่วนลึกของอีราเวลรู้สึกประหลาดใจ เธอเริ่มกลัว \"คุณเป็นผีเหรอ? ไม่มีชาวเคเลสไทต์คนไหนมาที่ลานขยะแบบนี้หรอก เรื่องนั้นไม่มีทางเป็นไปได้\"\n“แต่ฉันเป็นชาวเคเลสไทต์” เอด้ากระโดดขึ้นบนหัวของโคลอสซัสอย่างว่องไว ซึ่งดูเหมือนมังกรตัวเล็ก ๆ และลองกระทืบเท้าดู\n\"เฮ้ การเป็นเคเลสไทต์ไม่ได้หมายความว่าคุณสามารถแอบฟังและกระทืบหัวฉันได้นะ หัวสวย ๆ ของฉันเป็นที่สงวน!\"\n\"มันสวยมาก มีดอกไม้ขึ้นอยู่บนนี้ด้วย\"\n\"แน่นอนฉันสวย! แล้วเคเลสไทต์ ทำไมเธอถึงตอบกลับฉันล่ะ อย่าได้หลอกฉันเชียวนะ เพราะฉันจะเป่าเธอลอยขึ้นฟ้าไปด้วยพลังเฮือกสุดท้ายของฉันเลย!\"\n\"เธออยากบินไม่ใช่เหรอ\" เอด้าเชื้อเชิญ \"ฉันอยากเห็นว่าโลกภายนอกอีราเวลเป็นยังไง อยากไปด้วยกันมั้ย\"\nแต่โคลอสซัสไม่ตอบรับข้อเสนอของเธอ แล้วกลับไปที่มุม\n\"ฉันก็อยากนะ แต่ฉันตัวเล็กและไม่มีที่ว่างพอ ปีกของฉันก็เล็ก ฉันทำไม่ได้...\"\n\"แต่เธออยากไป\" เอด้าเอื้อมมือไปที่โคลอสซัส และในตอนนั้น ความรู้สึกที่ลึกซึ้งก็พัดผ่านทั้งคู่ขณะที่พวกเขา \"ลิงก์\" ถึงกันและกัน\nโคลอสซัสสัมผัสได้ว่าปีกของเธอกางออกและบินขึ้นไปบนท้องฟ้า มองเห็นโลกจากมุมเบื้องบนราวกับปลาวาฬที่กระโดดขึ้นจากน้ำ ทั้งคู่ได้สัมผัสดวงดาวและออโรร่าพร้อมกัน\nโลกทั้งใบค่อย ๆ แผ่ขยายออกต่อหน้าพวกเขา\n\"โอ้ ฉันชื่อเอด้า เธอชื่ออะไร\"\n\"โบยบินไปบนท้องฟ้าและเดินไปกับสายลม ฉันชื่อแคซ\"",
  str_dispatch_book_chaptercont_11000_2 = "แคซที่ตัวมอมแมมและเอด้าผู้เป็นผู้นำทางมือใหม่บินไปมาบนท้องฟ้าอย่างไร้จุดหมาย หลุมอากาศเล็กน้อยทำให้พวกเขาพลิกคว่ำ และเพราะพลังงานหมดลง ทำให้พวกเขาต้องลงจอด\n \"ฉันว่าแล้ว ไม่ควรไปเที่ยวแบบกะทันหันแบบนี้เลย ตอนนี้ฉันติดอยู่กับพื้น... สุดท้ายฉันก็ไม่เก่งเรื่องบินหรอก! อืม ฉันเดาว่าเธอคงขับไม่เก่งเหมือนกัน!\" แคซพูดกับเอด้าผ่านลิงก์กระแสจิต\n เอด้าลูบหัวตัวเองที่ชนเข้ากับแผงควบคุมระหว่างลงจอด ด้านขวายังเจ็บ แต่เธอก็เหมือนจะไม่สนใจ \"ฉันยอมรับว่าฉันไม่เก่ง ก็ฉันไม่เคยเข้าเรียนการใช้งานโคลอสซัสมาก่อนเพราะฉันไม่มีพ่อแม่\"\n \"อะไรนะ แล้วอะไรทำให้เธอกล้าเชื่อมลิงก์กับฉันล่ะ\"\n \"อืม สัญชาตญาณล่ะมั้ง\" เธอลุกขึ้นมายืน \"แต่เชื่อฉันสิ ฉันคิดว่าฉันเรียนรู้เรื่องนี้ได้เร็วนะ\"\n “เธอนี่เห็นแก่ตัวยิ่งกว่าฉันเสียอีกนะ แม้ว่าฉันจะรู้สึกว่ามันน่าสนใจ... แต่ยังไงฉันก็จะไม่บินอีกแล้ว ฉันยอมถูกฝังอยู่ในดินดีกว่าโดนกระแทกกลางอากาศ ฉันควรจะรออยู่ที่ลานขยะให้คนมาแยกชิ้นส่วน ไม่ใช่มาตกลงมาส่วนไหนของป่าก็ไม่รู้... ที่นี่ดูสยองมาก แล้วก็เปียกไปหมด มีเห็ดแปลก ๆ มากมายด้วย...\"\n \"นี่ยังไม่รวมแขกที่ไม่ได้รับเชิญนะ\"\n มี \"สัตว์ประหลาด\" พร้อมอาวุธพุ่งเข้าหาเอด้าจากทุกทิศทาง\n แคซหลับตาลง ชาวเคเลสไทต์ที่ไม่สู้รบอย่างเอด้าได้แต่นั่งก้มลงเฉย ๆ เพื่อรอวาระสุดท้ายของชีวิต ลูมินาในตัวแคซถูกกระตุ้นขึ้น เธอมีความสงสัยผุดขึ้นทีละส่วนในวงจรจักรกลของเธอ เธอเป็นคนขี้ขลาด บินไม่ได้ ช่วยผู้นำทางของตัวเองก็ไม่ได้ แม้แต่ลืมตาเมื่อเอด้าตกอยู่ในอันตรายก็ยังทำไม่ได้เลย เธออยากจะร้องไห้ แต่เครื่องจักรอย่างเธอสามารถร้องไห้ได้ด้วยเหรอ\nเธอได้ยินเสียงของเอด้า \"ไม่ต้องกลัวนะ แคซ ทุกอย่างเรียบร้อยแล้ว เราไม่เป็นอะไรแล้ว\"\n เมื่อแคซลืมตา เธอเห็นเอด้ากำลังอุ้มแมวอยู่ โดยมีสัตว์ต่าง ๆ นอนอยู่รอบตัวเธอ\n\"ชาวเคเลสไทต์ไม่ใช่นักสู้ที่ดี แต่ฉันกลับเก่งการต่อสู้ ฉันอัดพวกสัตว์เล็ก ๆ เหล่านี้ตอนที่พวกมันพุ่งเข้ามา แล้วลูบท้องของพวกมัน พวกมันก็แค่ อดใจไม่ไหวน่ะ\"\nแมวในอ้อมแขนพูดขึ้น\n\"ช่างหยาบคายจริง ๆ เราไม่ใช่สัตว์ แต่เป็นครึ่งมนุษย์! เธอเพิ่งบดเห็ดไข่มุกอันล้ำค่าที่สุดของเราไป ควรจ่ายค่าชดเชยให้เรา 10 ล้านไนท์เทียมด้วย! แต่เห็นแก่เทคนิคการนวดที่ดีของเธอ เราจะให้เธอชดเชยด้วยแรงงานก็แล้วกัน!\"\nเอด้าจ้องดูแมวที่อยู่ในอ้อมแขนของเธออย่างงุนงง\n\"เมี้ยว เธอไม่รู้อะไรเลยเหรอ คนที่มองเห็นเส้นแสงคือพวกเคเลสไทต์ คนที่มองไม่เห็นเส้นทางแต่ใช้ลูมินาได้คือพวกออโรเรียน\" แมวยืดตัว\n\"แล้วครึ่งมนุษย์คืออะไร?\"\n\"เราสื่อสารด้วยภาษา เราเข้มแข็ง แต่ไม่เกี่ยวอะไรกับลูมินา... เฮ้ เกาตรงนี้ด้วยสิ... ข้อได้เปรียบของเราคือ...\"\n \"พวกเราน่ารักมาก\"",
  str_dispatch_book_chaptercont_11000_3 = "การเดินทางโดยไม่มีจุดหมายก็เหมือนเมล็ดดอกแดนดิไลออน คุณจะล่องลอยไปทุกตามแรงลม\n จุดหยุดพักล่าสุดสำหรับเอด้าและแคซคือซากโบราณที่แห้งแล้งที่ซึ่งพวกเขาได้พบกับเพื่อนร่วมชาติจากอีราเวล: โคลอสซัสที่เต็มไปด้วยดอกไม้\n“ดูเหมือนว่ามันจะยืนอยู่ได้ด้วยขาข้างเดียวและพลังงานของมันกำลังจะหมด” เอด้าลูบไล้เบฮีมอธที่แก่ชรา ซึ่งตัวสั่นเทาและหายใจเหมือนเคเลสไทต์\n\"เป็นไปได้ไง ทำไมคุณไม่บินกลับไปที่อีราเวลล่ะ พวกเขาต้องช่วยคุณได้แน่!\" แคซแสดงความคิดเห็น\n\"เพราะฉันไม่สามารถหาทางกลับไปที่อีราเวลได้ แผนที่หรือระบบนำทางของฉันไม่สามารถหยุดฉันจากการหลงทางได้...\" โคลอสซัสที่อ่อนแรงค่อย ๆ ลืมตา \"จะบอกว่าที่นี่เป็นบ้านของฉันเลยก็ว่าได้\"\nเอด้านั่งลงตรงหน้าของโคลอสซัส \n\"คุณพอจะเล่าเรื่องราวของคุณให้ฉันฟังได้มั้ย\"\nยักษ์ตั้งหัวขึ้น \"ผู้นำทางและฉันมาที่ป่าแห่งนี้ และเราได้พบกับเผ่าอื่นอย่างออโรเรียน\"\n\"เฮ้ พวกเขาคือเผ่าที่สามารถควบคุมลูมินาได้นี่ และเพียงแค่คิด ก็สามารถยิงน้ำจากมือได้ด้วย!\"\n\"แล้วไง พวกเขาบินได้มั้ยล่ะ ถ้าเธออยากประทับใจ ก็ประทับใจกับเรื่องที่ว่าโคลอสซัสทรงพลังขนาดไหนจะดีกว่า\" แคซพึมพำ ไม่แยแสออโรเรียนเลยสักนิด\n\"ผู้นำทางของฉันใช้ชีวิตอยู่กับออโรเรียนและได้รับการยอมรับ แต่เขาก็ยังรู้สึกโดดเดี่ยวอยู่ดี เคเลสไทต์แตกต่างจากออโรเรียน และนี่ไม่ใช่บ้านของเขา ตอนที่เขาตัดสินใจออกจากที่นี่ อิคลิพไซท์ก็จู่โจมหมู่บ้าน\"\n\"อิคลิพไซท์!\" หัวใจของเอด้าเต้นเร็วขึ้น จิตใจของเธอเต็มไปด้วยภาพอันน่ากลัวของมอนสเตอร์เทาดำที่โผล่มาจากความมืด ขู่คำรามและอาบไปด้วยเลือด วิ่งเข้าหาเอด้า เมื่อคมดาบกำลังจะเฉือนคอของเธอ ภาพก็จางหายไป\n\"ผู้นำทางของฉันสละชีวิตเพื่อช่วยเหลือชาวออโรเรียน พวกเขาเอาชนะได้ในที่สุด แต่ดินแดนก็ถูกพลังความมืดทำลาย จนไม่สามารถอาศัยอยู่ได้อีก ออโรเรียนที่เขาปกป้องกลับมาที่นี่และวางดอกไม้ไว้ให้เขา อย่างที่พวกเธอเห็น ตอนนี้ดอกไม้เหล่านั้นมันขึ้นอยู่บนตัวฉัน\"\nเอด้าและแคซเงียบสนิท พวกเขาอยากปลอบโคลอสซัสแต่ไม่รู้ว่าจะควรจะพูดยังไง\n\"อย่าเศร้าไปเลย เจ้าเด็กน้อย ฉันไม่เคยคิดรังเกียจดอกไม้พวกนี้เลย หรือเสียใจที่รอคอยวันที่พลังงานเหือดแห้งไปจากตัว เพราะว่าฉันได้สัมผัสถึงสิ่งมีชีวิตที่กำเนิดขึ้นบนตัวฉัน ดอกไม้ที่งดงามคือสิ่งแทนคำขอบคุณของชาวออโรเรียนที่มีต่อผู้นำทางของฉัน และนี่ก็เพื่อเป็นการระลึกถึงเขาด้วยเช่นกัน\"\nโคลอสซัสปิดเปลือกตาลงและตัดลิงก์เชื่อมโยงจิตใจกับเอด้า\nดอกไม้คือสัญลักษณ์แห่งชีวิตเพียงอย่างเดียวในซากปรักหักพัง เอด้านึกถึงพ่อแม่ของตนในอีราเวล เธอพูดเบา ๆ \"การออกมาดูโลกภายนอกคือการตัดสินใจที่ถูกแล้วเหรอ หรือจริง ๆ แล้วมันคือเรื่องที่ผิดพลาดกันแน่\"",
  str_dispatch_book_chaptercont_11000_4 = "\"ที่นี่มีแต่ทราย ถ้าเราหยุดพักอยู่ที่นี่ เกราะนอกของฉันจะต้องสกปรกแน่ ๆ... อ้อ แล้วทรายจะร้อนอะไรปานนี้เนี่ย!\"\nเอด้าและแคซบินไปที่ทะเลทรายและหยุดพัก\n\"ทำได้ดีมากแคซ! เราคงไม่ได้มาเห็นอะไรแบบนี้ถ้าไม่มีเธอ!\"\nดวงอาทิตย์ร้อนจัดที่อยู่เหนือหัวกำลังเผาไหม้อากาศ ทะเลทรายกว้างใหญ่ทอดยาวสุดลูกหูลูกตา แม้แต่โคลอสซัสเองก็เป็นเพียงก้อนกรวดเล็ก ๆ เมื่อเทียบกับทะเลทรายอันกว้างใหญ่ เป็นภาพที่เห็นได้ในยามที่จากอีราเวลมาเท่านั้น\n\"มาไม่ได้ถ้าไม่มีฉันงั้นเหรอ ใช่ ใช่ นั่นคือเรื่องจริง! ฉันคือโคลอสซัสผู้ยิ่งใหญ่! สรุปแล้วที่นี่คือทะเลทรายสินะ! แต่ไม่เห็นมีใครเลย\"\n\"ตรงนั้นมีอะไรน่ะ\"\nเกิดความโกลาหลขึ้นในทะเลทรายอันเงียบสงบ\n\"นั่นเรือเหรอ มันกำลังมาทางนี้และกำลังจะชนเรา!\"\nแคซผู้น่าสงสารที่ระมัดระวังมาตั้งแต่ออกเดินทาง ตอนนี้เพิ่งถูกเรือแล่นในทะเลทรายชนเข้า\n\"โอ้ย!\" แคซส่งเสียงร้อง เรือชนเข้ากับปีกของเธออย่างจัง\nกัปตันลงมาจากเรือ ยื่นหัวออกมา\n\"เป็นไงบ้าง... นั่นชนไปแรงเหมือนกันนะ เอาเถอะ ฉันคือหัวหน้าของกลุ่มผู้ท่องดวงดาว เราคือออโรเรียนพเนจรที่สำรวจโลกบนยานของเรา\"\n\"ฉันเคยอ่านเกี่ยวกับเรือที่ล่องในทะเล แต่ในทะเลทรายมันจะเป็นไปได้ยังไง\" เอด้าที่กำลังงงมองไปที่กัปตัน\n\"ในทะเลทรายไม่มีเรือหรอก แต่ที่นี่มี ดูสิ\"\nเอด้าก้มมองไปทางที่กัปตันชี้ ทรายใต้เท้าของเธอถูกลมพัดปลิว เผยให้เห็น \"ท้องฟ้า\" เบื้องล่าง ที่อัศจรรย์กว่านั้นคือพวกเธอมองเห็นดาวเคราะห์ดวงหนึ่งอยู่ข้างในนั้น\n\"นั่นคืออีโอเรีย ดาวโลกของเรา\" กัปตันอธิบาย\n\"เหมือนคุกกี้ป่นที่แช่ในชามที่ใส่น้ำมากกว่า\" แคซกระซิบ\n“ใช่ ส่วนคุกกี้ที่ป่น ๆ นั่นก็คือแอสตรา แล้วด้านข้างของโลกนี้ก็คือแสงนิรันดร์ อีกด้านหนึ่งเป็นคืนนิรันดร์ เราอยู่ในเส้นบาง ๆ ระหว่างพวกมัน”\n“แล้วคุณคิดจะสำรวจความมหัศจรรย์ของโลกด้วยเรือแบบนั้นน่ะเหรอ\"\nกัปตันเกาหัว “มันอาจจะดูโทรมไปบ้าง แต่ข้างในค่อนข้างหรูหรานะ และเรามีลูกเรือที่เก่งที่สุด อย่างช่างเครื่องของเรา...” ชาวออโรเรียนคนหนึ่งบนเรือเหวี่ยงค้อนเหมือนอยากโชว์ฝีมือแต่พลาดโดนเรือเข้าจนเป็นรู ส่วนออโรเรียนอีกคนพยายามกระโดดอย่างสง่างามจากเรือแต่ก็ร่วงลงบนพื้นทรายอย่างไม่เป็นท่า\n\"ขายขี้หน้าจริง ๆ!\" กัปตันกรอกตาแต่ก็สงบลงอย่างรวดเร็ว \"ล่องเส้นทางใหม่ ๆ และค้นหาสิ่งที่ไม่รู้จักคือสิ่งที่เราทำ\n\"ออโรเรียนขี้สงสัยแบบนี้กันทุกคนมั้ย\"\n\"คนปกติมักไม่ล่องเรือบนทรายกันหรอก\"\n\"ทราย?\" เอด้ามองลงไปและเห็นกาแลกซี่เบื้องล่างเท้าของเธอที่ถูกทรายปกคลุมไปอีกครั้งหนึ่ง เมื่อเธอเงยหน้ามองขึ้นมา เรือก็หายไปแล้ว\nผู้ท่องดวงดาวเป็นแค่ความฝันหรือมีอยู่จริงกันแน่นะ",
  str_dispatch_book_chaptercont_11000_5 = "เอด้านั่งที่ขอบเกาะแอชูไรต์ขณะที่แคซซ่อนตัวอยู่ในเมฆ\nเวลาล่วงเลยไป เป็นเวลานานแล้วที่พวกเขาออกจากอีราเวล หนึ่งวัน หนึ่งเดือน หนึ่งปี หรืออาจจะหลายปีก็ได้ ความทรงจำเกี่ยวกับอีราเวลของเอด้าเริ่มเลือนลางลงเรื่อย ๆ\n\"เธอยังจำได้มั้ยว่าอีราเวลเป็นยังไง แคซ?\"\n\"แน่นอน ฉันจำได้ ฉันคือโคลอสซัส ขอดูไฟล์ก่อน...เอ๋ ไฟล์อีราเวลหายไปไหนนะ ข้อมูลใหม่ที่บันทึกไว้มันไปทับข้อมูลเก่าจนลบไปเหรอ? เป็นไปไม่ได้...ความจุของฉันไม่ได้น้อยขนาดนั้นนี่นา\"\n\"ฉันจำหอคอยสีขาวได้ มีสิ่งปลูกสร้างสีขาวสูงบนเกาะแอชูไรต์เหมือนกัน แต่ก็ไม่เหมือนกันเสียทีเดียว เพราะหอคอยในอีราเวลมักจะมีนกร่อนลงมาหยุดพัก ส่วนด้านล่างก็เป็นป่าที่มีดอกแดนดิไลอัน\"\n\"ทำไมเธอถึงลิงก์กับฉันและพาฉันออกมาจากอีราเวลล่ะ เอด้า\" แคซมองตามสายตาของเอด้าที่มองไปยังขอบฟ้า ทะเลทราย ที่ราบ หิมะ ภูเขาไฟ และแม้แต่ท้องทะเลก็อยู่ในครรลองสายตา ถ้าอยู่อีราเวลคงไม่ได้เห็นอะไรแบบนี้ แต่ก็ต้องแลกมาด้วยบางสิ่งบางอย่าง\n“ตอนนั้นฉันแค่อยากจะตามหาคนสองคน คือพ่อแม่ของฉันในความฝัน ฉันอาจจะดูชิลล์ แต่นั่นเป็นเพราะฉันเกลียดชีวิตในอีราเวล ฉันคิดว่าที่อื่นจะต้องดีกว่าที่นั่น พ่อกับแม่ทิ้งฉันไว้ที่อีราเวล ฉันไม่สามารถเข้ากับคนอื่นได้เลยต้องอยู่ตามลำพัง มันแย่มากเลยละ\"\n\"ฉันก็รู้สึกเหมือนกัน... ฉันตื่นมาพบว่าตัวเองเป็นโคลอสซัสที่ไม่สมบูรณ์ คนพวกนั้นพูดว่าฉันเป็นผลผลิตที่ล้มเหลว ไม่สามารถบินได้ ชะตากรรมที่กำลังรอฉันอยู่คือนอนนิ่งจนพลังงานหมดในลานขยะ อย่างน้อยการออกจากที่นั่นก็ดีขึ้น ฉันคิดว่าจะต้องตายที่นั่นแล้วซะอีก แต่น่าแปลก ตอนนี้ฉันกลับคิดถึงที่นั่น\"\n“ฉันก็ด้วย ไม่รู้เหมือนกันว่าตั้งแต่เมื่อไหร่ แต่ฉันเลิกสนใจที่จะตามหาพวกเขาแล้ว พวกเขาต้องใช้ชีวิตของตัวเอง และฉันก็ควรมีชีวิตของฉัน การบินไปกับเธอนั้นน่าสนใจกว่าการพยายามไขปริศนาที่ไม่มีความหมาย”\n\"เธอรู้สึกแบบนั้นจริง ๆ เหรอ ฉันไม่คิดแบบนั้นเลย! โคลอสซัสประมวลผลแบบนั้นได้ด้วยเหรอ ฉันไม่มีข้อมูลเก่าอะไรแบบนั้นเลย!\"\n\"ทำไมฉันจะรู้สึกแบบนั้นไม่ได้ล่ะ เราเป็นคู่หูกันนะ มันเป็นมากกว่าความสัมพันธ์แบบผิวเผิน” เอด้าหลับตาลงและจดจ่อไปที่ลิงก์\" เธอรู้สึกมั้ย\"\n\"ฉัน... ฉันรู้สึกได้ แล้วฉันก็รู้สึกได้ถึงความคิดของเธอ เอด้า เธอกำลังคิด...\"\n\"อีราเวล ฉันคิดว่าถึงเวลาที่เราจะกลับไปยังที่ที่เราพบกันแล้ว\"\nก่อนที่ความทรงจำจะหายไปจนหมด",
  str_dispatch_book_chaptercont_12000_1 = "หลายครั้งที่ฉันได้นั่งริมฝั่งแม่น้ำทองคำดูพระอาทิตย์เคลื่อนผ่านท้องฟ้าอย่างช้า ๆ\nน้ำเย็นเฉียบกระทบน่องของฉัน และฉันรู้สึกว่าท้องของฉันบิด พ่อของซิฟออกไปตกปลาในแม่น้ำพร้อมกับแหของเขา เขามักจะหันกลับมายิ้มให้ โดยเอามือไปข้างหลัง แต่ฉันรู้ว่าฝ่ามือของเขาเต็มไปด้วยสะเก็ดสีน้ำตาล\nซิฟกำลังเดินเท้าเปล่าวิ่งไปมาตามริมฝั่งแม่น้ำ เธอเก็บหอยแมลงภู่ที่เธอรวบรวมไว้เป็นกองใหญ่ข้าง ๆ ฉัน จากนั้นให้ฉันแงะมันออกด้วยมีดของฉันแล้วตักเนื้อออก ขณะที่เธอลุยน้ำไปล้างแผลที่เท้าที่โดนก้อนกรวดบาด\nพระอาทิตย์ส่องแสงให้เรา\n ไม่มีอะไรยากไปกว่าการไปกินข้าวบ้านซิฟ ฉันต้องพยายามอย่างมากที่จะกินให้เร็วเท่าเธอ เพราะฉันรู้สึกเหมือนเสียมารยาทอย่างมากไม่ว่าจะกินเสร็จก่อนหรือหลังเธอ \nแม่ของซิฟใจดีแบ่งเอาปลาแห้งและเบคอนกลับไปบ้านให้พ่อขี้เมาของฉัน\n“คงจะดีกว่านี้มากถ้าแม่ของเธอยังมีชีวิตอยู่” เธอกล่าว \nแม่ของซิฟชอบหวีผมยุ่ง ๆ ของฉันกลับด้วยนิ้วของเธอ เมื่อเธอทำเช่นนั้น ดวงตาของเธอก็ดูอ่อนล้าอยู่เสมอ และดูเหมือนเธอจะมองไปไกลๆ หาใครบางคน\nเธอและแม่ของฉันเป็นเพื่อนที่ดีต่อกัน เหมือนกับซิฟและฉัน\nเมื่อแม่ของฉันเสียไป พ่อของฉันและฉันใช้ชีวิตที่ดีกันต่อไป\nพ่อกลัวว่าฉันจะจับได้ว่าเขาดื่ม เขามักจะยืนห่างจากฉันเสมอเมื่อฉันกลับบ้าน แต่กลิ่นแอลกอฮอล์แรงเกินไปที่จะซ่อนไว้ เขาจะสั่งให้ฉันวางอาหารลงบนโต๊ะไม้โยกเยก แล้วให้ฉันไปซักเสื้อผ้า หลังจากที่เขาหลับไป ฉันจะไปหาขวดสุราที่ซ่อนอยู่ของเขา\nมันมีอยู่ทุกที่ ใต้เตียง ในกองเสื้อผ้า ในกองขี้เถ้าเตา...\nฉันมักจะล้างพวกมันในแม่น้ำและผูกเชือกอวนรอบคอขวด แล้วมัดยาวไป 10 ขวด มีตะปูตอกสองตัวที่หน้าต่างห้องนอนแต่ละด้าน และฉันก็แขวนขวดไว้ที่นั่น ดวงอาทิตย์ส่องแสงน้อยๆ สะท้อนจากขวดแต่ละขวด และพวกมันก็ส่งเสียงกระทบกันเมื่อชนกัน\nจนถึงวันนั้น นี่เป็นความบันเทิงเดียวของฉัน\n(โปรดติดตามตอนต่อไป)",
  str_dispatch_book_chaptercont_12000_2 = "ฉันจำได้ว่ามันเป็นวันที่มืดมน ลมพัดใบไม้และฝุ่นปลิวไปในอากาศ\nสามารถได้ยินเสียงกระดิ่งม้าในระยะไกล และเด็ก ๆ ก็เงี่ยหูลงกับพื้นเพื่อฟังเสียงกีบเท้า มันเป็นคาราวาน! พวกเขาหยุดอยู่ในทุ่งโล่งนอกเมือง กางเต็นท์สีขาวขนาดใหญ่ของพวกเขา และจัดวางสินค้าไว้ข้างใน\nได้ยินความโกลาหล ชาวบ้านจำนวนมากจึงรีบไปที่ทุ่งเพื่อดู ฉันกับซิฟเบียดฝูงชนเข้าไป เธอจับมือฉันแน่น ฉันรู้สึกประหม่าและตื่นเต้นแผ่ซ่านไปทั่วกระดูกและผิวหนังของฉัน และเข้าไปในหัวใจของฉัน\nอากาศเต็มไปด้วยกลิ่นเหม็นของมูลม้า แต่ถึงแม้จะเดินทางไกล เสื้อผ้าของกองคาราวานก็แวววาว และใบหน้าของพวกเขาก็สะอาดและเต็มไปด้วยพลัง ตอนนั้นฉันไม่รู้ว่านี่เป็นผลของลูมินาติกส์\nข่าวแพร่กระจายอย่างรวดเร็วว่ากองคาราวานรับเมล็ดพืช ขนสัตว์ และเขาสัตว์แลกกับเสื้อผ้าชั้นดีและเบียร์ พ่อค้าบางคนไปที่หมู่บ้านและพักอยู่ในโรงเตี๊ยมที่ไม่มีลูกค้ามาครึ่งปีแล้ว ไม่นานนัก กลิ่นของถั่วปรุงสุกก็ลอยออกมาจากหน้าต่าง\nพ่อค้าเสื้อผ้าก็นำสินค้าของพวกเขาออกมา ที่พันอยู่รอบแขน แล้วคลี่ออกมาเพื่อให้คนอื่นชม มีสีขาวเหมือนหิมะ สีเขียวนกยูง น้ำเงินแซฟไฟร์ สีแดงพระอาทิตย์ตก... นี่เป็นครั้งแรกที่ฉันได้เห็นสีสันที่สดใสเช่นนี้\nซิฟบอกฉันว่าเธอต้องการแลกหนังหมาป่าที่เธอจับได้เมื่อฤดูหนาวที่แล้วเป็นชุดสีขาว นั่นคือตอนที่ฉันนึกถึงขวดแก้วที่ห้อยอยู่นอกหน้าต่าง\n\"อย่างน้อยฉันก็ต้องลอง\" ฉันพูดกับตัวเอง",
  str_dispatch_book_chaptercont_12000_3 = "พอซิฟกับฉันกลับมาถึงบ้าน นางก็นำหนังหมาป่ามาม้วนเป็นมัดให้แน่นแล้วหนีบไว้ใต้แขนตัวเอง ขณะที่ฉันเดินตามมาด้วย ขวดที่ร้อยเรียงบนเชือกในมือของฉันก็ส่งเสียงอันเพลินหู สิ่งของธรรมดาแบบนี้เป็นดั่งสมบัติของเรา \nซิฟตื่นเต้นมากจนเกือบจะทำท่ากระโจนออกไปทางขบวนรถแต่ขวดพวกนั้นทั้งหนักและเปราะบาง ฉันเลยได้แต่ตามไปข้างหลังช้าๆ ฉันรู้สึกเหมือนทุกคนจ้องมองมาทางเรา คนอย่างฉันไม่เคยเป็นจุดสนใจมาก่อนเลยในชีวิตแล้วก็รู้สึกดีใจไปชั่วขณะหนึ่ง \n\"อยากเอาของพวกนี้มาแลกกับอะไรงั้นเหรอ\" พ่อค้าหน้าตางุนงงกล่าวขึ้นตอนที่เราเดินตรงไปหาเขา\nฉันไม่เข้าใจสิ่งที่เขาพูดเลยแค่แหงนคอไปมองเขาแพะกรวยแห่งความอุดมสมบูรณ์ที่มีของมากมายเรียงรายอยู่ข้างหลังเขา มองแล้วก็มองอีก\n\"เราไม่รับขวดไวน์หรอกนะ\" เขาพูดอย่างเฉยเมย สุดท้ายแล้วจึงถามว่า \"นั่นขวดไวน์ธรรมดาหรือเปล่า\"\nชั่วขณะนั้นเอง ฉันก็รู้สึกว่ามีเสียงดังกริ๊งในหูแล้วความอับอายก็ทำให้ตัวชาจนแข็งทื่อตรงนั้น พระอาทิตย์บนหัวส่งเสียงตึงตังราวกับเป็นกลอง ทนฟังกระทั่งเสียงขวดกระทบกันแทบไม่ไหว \nขวดนั้นหนักเกินไปและมือของฉันก็เริ่มสั่นไหวเพราะน้ำหนักจากเชือกที่เชื่อมขวดเข้าด้วยกัน เหงื่อพลันไหลรินลงมาจากด้านหลังลำคอและใบหูของฉันแต่ก็ยังบังคับขาตัวเองให้เดินไปไม่ได้\nทันใดนั้นก็ได้ยินเสียงต่ำจากด้านขวาของฉัน\n\"แม่หนู อยากแลกขวดกับอะไรล่ะ\"\n(โปรดติดตามตอนต่อไป)",
  str_dispatch_book_chaptercont_12000_4 = "นั่นเป็นครั้งแรกที่ฉันได้พบกับเชริโอซา แสงอาทิตย์สะท้อนเกราะสีเงินของเขาจนพร่ามัว\nตอนนั้นเชริโอซาอายุประมาณสามสิบและได้รับการจ้างวานให้ไปเป็นยามอารักขาขบวนรถ เขาถอดหมวกเกราะออก เผยให้เห็นหน้าม้าสีน้ำตาลเปียกเหงื่อซ่กและหนวดหนายุบยั่บ เขายิ้มยิงฟันขาวดุจไข่มุกให้ฉัน\nเขาอยากได้ขวดของฉันและเอาขนมปังสีขาวบางอย่างที่เรียกว่า \"บิสกิตปันส่วนของลูโมโพลิส\" เป็นการแลกเปลี่ยน เขาบอกว่าของพวกนี้มีไว้สำหรับทหารลูโมโพลิสโดยเฉพาะ แล้วฉันก็ห่อมันเอาไว้ที่มุมกระโปรงของฉัน\nฉันได้สิ่งที่มหัศจรรย์ของจริงมาแล้ว! ความขายหน้าของฉันพลันเลือนหายไป\nเชริโอซาคว้าขวดออกจากเชือกแล้วถือไว้ในมือของเขา คลื่นความร้อนจากมือที่ถือขวดไว้สะท้อนออกมาอย่างบิดเบี้ยว\n\"เธอชอบลูกหมาไหม ตอนเด็ก ๆ ฉันชอบลูกหมานะ\" เขาพูด\nเชริโอซาแบมือออกมาให้เห็นลูกหมาแก้วตัวจ้อยนั่งอยู่ข้างใน แต่ยิ่งไปกว่านั้น ฉันกลับสงสัยเกี่ยวกับคลื่นความร้อนในอากาศที่สูงขึ้น เชริโอซาสังเกตเห็นว่าฉันตื่นเต้นแล้วก็ยิ้มกริ่ม\n\"นั่นคือลูมินาติกส์น่ะ อยากหัดไหมล่ะ\"\nขบวนรถอยู่ที่นั่นสามวันแล้วเหมือนทั้งหมู่บ้านกลับมามีชีวิตชีวาอีกครั้ง กลิ่นเนื้อย่างคละคลุ้งในปล่องไฟ เด็ก ๆ วิ่งเล่นเท้าเปล่าไปตามถนน ชายชราต่างก็หยิบไม้เท้าโขยกเขยกออกมาจากบ้านอันมืดมิดของตน กระทั่งน้ำในแม่น้ำทองคำก็ดูอุ่นขึ้น เชริโอซานั่งบนเวทีของหมู่บ้านแล้วพยายามสอนลูมินาติกส์ให้ฉัน ซิฟนั่งอยู่ข้างฉัน บางครั้งก็ฟังตาม บางครั้งก็เหม่อลอยใส่ฉัน\nเชริโอซาชอบเดินทอดน่องไปตามหมู่บ้านหลังมื้อเย็นแล้วฉันกับซิฟก็จะติดตามไป เขาแทบจะไม่เคยถอดชุดเกราะหรือปลดดาบกับโล่ที่คาดไว้เลย มีครั้งหนึ่งฉันพุ่งไปด้านหน้าแล้วแตะที่โล่สลัก ถามว่ามันคืออะไร\n\"นั่นโล่หอคอยน่ะ\" เขาว่า \"สัญลักษณ์ของอัศวินลูโม\"\nสามวันจากนั้น ขบวนรถก็จากไปแล้วเชริโอซาก็ร่ำลาเรา\nหลังจากนั้นหนึ่งเดือน ฉันก็สร้างลูกบอลน้ำขนาดเท่ากำปั้นไว้ในมือได้สำเร็จ\nฉันเลยได้รับโชคชะตาใหม่",
  str_dispatch_book_chaptercont_12000_5 = "สามเดือนหลังเชริโอซาจากไปก็มีคนมาเคาะหน้าต่างบ้านฉัน\n\"ขอโทษทีนะ มินะอยู่ที่นี่ไหม\"\nแก้มแดงก่ำสองข้างและแกละสีบลอนด์สว่างคู่นั้นจุ่มอยู่ตรงหน้าต่าง เธอเห็นฉันแล้วก็กะพริบตาสีเขียวมะกอก หันไปค้นกระเป๋าเป้ แล้วเธอก็ดึงหนังสือปกหนังเล่มเล็กออกมา ปีกสีเขียวมรกตยื่นออกมาจากหลังของเธอ ขนนกมันวาวส่องประกายใต้ดวงอาทิตย์และนิ่วมือของเธอแตะลงบนตราสัญลักษณ์ที่ติดอยู่บนหนังสือนั้น\n\"สหภาพผู้ส่งสาร\" เธออ่านเสียงช้า ๆ ฟังชัด\nหลังยืนยันแล้วว่าเป็นฉันถูกคนแล้วจึงส่งพัสดุที่ห่อด้วยกระดาษกันน้ำมาให้ ก้าวถอยหลังสองเก้าแล้วสยายปีกออกมา ฝุ่นตลบเมื่อเธอหมุนเป็นวงกลมแล้วโบกมือให้ฉัน พอรู้ตัวอีกที เธอก็จากไปแล้ว\nฉันแกะพัสดุออก ข้างในเป็นจดหมายและของขวัญจากเชริโอซา จดหมายสั้นนิดเดียวแล้วจากนั้นที่ฉันได้หัดอ่านเขียนก็รู้ว่าจดหมายเขียนผิดเต็มไปหมด ของขวัญคือดอกแดนดิไลออน มีพลังบาง ๆ ในก้อนนุ่มฟูสีขาว ผ่านมาสักพักใหญ่แล้วฉันก็รู้ว่าดอกไม้นั้นมาจากอีราเวลอันห่างไกล\nเชริโอซาส่งพัสดุของขวัญหลากหลายแบบอย่างต่อเนื่อง: ไส้กรอกนอร์ธแลนด์ รูปแกะสลักของราชินีเบธเลเฮม กระสุนสลักเครื่องหมายดาวคู่ของอิลลูมินา ลูกอมที่เป่าเป็นนกหวีดได้ ขนมกรุบกรอบเคี้ยวเพลินรสชาติประหลาดและมีอยู่ครั้งหนึ่งที่ส่งดวงตาของอิคลิพไซท์มา ผู้ส่งสารมาส่งจดหมายแตกต่างกันแต่ก็มีลักษณะที่เหมือนอมนุษย์บางอย่าง เช่น ปีก เขา เขี้ยวหรือลายจุด หลังจากชินกับผู้ส่งสารแล้วฉันก็พยายามคุยกับพวกเขามากขึ้น สุดท้ายแล้วฉันยังขอให้พวกเขาช่วยอ่านจดหมายด้วย \nไม่ว่าจะหน้าตาเป็นยังไงก็ทำให้วันของฉันสำคัญได้เสมอ\nพัสดุสุดท้ายของเชริโอซาส่งมาจากลูโมโพลิส ตอนฉันเปิดออกก็มีรูปวาดหล่นออกมา รูปวาดของเขายืนอยู่บนระเบียงกว้างขวางพร้อมกับท้องฟ้าเปิดกว้างด้านหลัง ฉันเดาทันทีว่าเป็นลูโมโพลิส เขาเคยบอกฉันว่าเมืองนั้นสร้างขึ้นบนเกาะลอยแอชูไรต์ที่ออโรเรียนอาศัยอยู่ นั่นเป็นพัสดุชิ้นสุดท้ายที่ฉันได้จากเชริโอซา\n(โปรดติดตามตอนต่อไป)",
  str_dispatch_book_chaptercont_12000_6 = "จากนั้นหกเดือน ขณะที่พ่อของฉันเมาจนไม่รู้สึกตัว ฉันก็สะพายกระเป๋าออกจากบ้าน ในกระเป๋ามีเพียงอาหารเล็กน้อยเท่านั้น พื้นที่ส่วนอื่นมีแต่จดหมายและของขวัญของเชริโอซา ฉันไปตามทางที่ผู้ส่งสารบอกแล้วไม่นานก็มาถึงสถานีสหภาพผู้ส่งสาร\nผู้ส่งสารบางคนก็จำฉันได้ ฉันอธิบายว่าพ่อเลวร้ายอย่างไรแล้วใส่สีตีไข่เทียบกับมาตรฐานที่ดี พวกเขาเลยตกลงที่จะรับดูแลฉันแลกกับให้ฉันจัดเรียงจดหมายและทำงานบ้านอื่น ๆ ในระหว่างนี้ฉันก็หัดอ่านเขียนไป ฉันอ่านจดหมายของเชริโอซาครั้งแล้วครั้งเล่า แม้ว่าการเขียนของเขาจะเละเทะไปหมดแต่ฉันก็ยังเข้าใจสิ่งที่เขาจะสื่อ เขาแทบไม่ได้อธิบายถึงการเดินทางเลยแต่มักจะเขียนถึงช่วงวัยเด็กของตัวเอง แม้ว่าจะเกิดในลูโมโพลิสแต่เขาก็จนเหมือนกับฉัน ฉันสัมผัสได้ว่าเขาพยายามปลอบประโลมฉันอยู่ ยังไงเขาก็เป็นถึงอัศวินลูโม ทุกอุปสรรคที่เขาพานพบมีแต่จะทำให้แข็งแกร่งยิ่งขึ้น สุดท้ายแล้วฉันก็เริ่มเขียนจดหมายตอบเขาแต่ไม่มีการตอบรับใด ๆ\nซิฟและแม่ต่างก็วิ่งมาหาฉันเมื่อพวกเขาเข้าไปในเมือง\nเธอคว้าแขนของฉันไว้ไม่ยอมปล่อย ร้องไห้แล้วคร่ำครวญว่าเป็นห่วงฉัน เห็นใบหน้าเปื้อนน้ำตาของเธอแล้วก็อดรู้สึกผิดขึ้นมาเสียไม่ได้ ฉันพูดไม่ออกแม้แต่คำขอโทษแล้วทำได้แค่เช็ดน้ำตาบนใบหน้าของเธอ\nท้ายที่สุดซิฟก็ปาดน้ำตา เอาแขนเสื้อเช็ดน้ำมูกและสะอื้นคำหนึ่งออกมา:\n\"ดูนะ\"\nเธอหลับตาลงแล้วมีสายฟ้าสว่างวาบรอบตัวเธอ เจาะทะลวงผ่านเข้าไปในอากาศ",
  str_dispatch_book_chaptercont_12000_7 = "ฉันลองพยายามเข้าสหภาพผู้ส่งสารแล้วแต่กลับถูกปฏิเสธ\n\"มินะ เธอยังเด็กเกินไป\"\n\"เธอยังไวไม่พอ ไม่ใช่ความผิดเธอหรอก ก็แค่... เธอใช้เท้าวิ่งได้อย่างเดียว\"\n\"มันอันตรายเกินเหตุ ลื่นครั้งเดียวก็เจ็บตัวแล้ว\"\n\"เธอเคยเจออิคลิพไซท์หรือเปล่า ฉันเคยเจอนะ\"\n\"ยังไงค่าจ้างก็ไม่ดีหรอก\"\n\"ใช่ นั่นแหละประเด็นหลัก\"\nถึงแม้พวกเขาจะติงานว่ามีปัญหาทั้งหมดนี้แต่ก็ส่งยิ้มกว้างแล้วส่งจดหมายทุกวัน\nผู้ส่งสารไม่เคยใจอ่อน ฉันเลยต้องตัดเรื่องนั้นทิ้งแล้วกลับไปจัดจดหมาย หวังว่าจะไปเจอจดหมายจากเชริโอซาเข้า แต่ก็ไม่เจออีกเช่นกัน\nหลังซิฟเรียนลูมินาติกส์แล้ว พ่อแม่ของเธอก็ให้เธอเข้าไปในเมืองคนเดียว เราจะนั่งอยู่กับผู้ส่งสารใต้ต้นโอ๊กหน้าสถานีแล้วลูกโอ๊กก็จะตกใส่หัวเรา ฉันชอบถามผู้ส่งสารเรื่องลูโมโพลิส โดยเฉพาะเรื่องอัศวินแต่กลับไม่ได้คำตอบที่ยาวนัก\n\"อัศวินเก่งกล้ามาก โดยเฉพาะกับลูมินาติกส์\"\n\"ครั้งหนึ่งฉันเคยส่งของให้อัศวินลูโม เธอเป็นบุคคลตัวอย่างที่งดงามแม้ยามเปิดจดหมาย\"\n\"รู้อย่างอื่นบ้างไหม\" พวกเขาถามไถ่กัน\n\"บอกตามตรง ฉันก็ไม่ค่อยเจอพวกนั้นหรอก\"\nซิฟนั่งพิงหลังพลางใช้มือดันตัวเองขึ้น แสงอาทิตย์รำไรทะลุมาผ่านใบไม้และเต้นระบำบนใบหน้าของเธอที่เงยขึ้นมา \"ตัวฉันเองยังอยากเห็นพวกเขาเลย\"\nฉันไม่รู้ว่านี่เป็นช่วงเวลาที่ควรตัดสินใจไหมแต่ก็ตัดสินใจไปแล้ว ฉันจะไปดูทุกอย่างด้วยตาตัวเอง ไม่ว่าจะที่ลูโมโพลิส อีราเวล เมืองใต้ดินอิลลูมินา ทะเลทรายเรดีเซล อัมบราตัน รวมถึงดินแดนลับด้วย\n(โปรดติดตามตอนต่อไป)",
  str_dispatch_book_chaptercont_12000_8 = "บางครั้งมันก็มากกว่าการขจัดห่วงความสงสัยที่มีต่อดินแดนที่ฉันมีแล้ว การจากลามีความหมายลึกซึ้งกว่าสำหรับฉัน—เป็นโอกาสให้เอื้อมหาและสัมผัสกับวัตถุประสงค์ในชีวิตในตัวของมันเอง ก็เหมือนกับเชริโอซา ฉันไม่ได้เกิดมาเพื่ออดทนกับชีวิตอันน่าเบื่อและความฝันลม ๆ แล้ง ๆ\nตอนฉันอายุสิบเจ็ด ฉันกับซิฟก็ตัดสินใจออกเดินทางด้วยกัน ฉันเสนอว่าเป้าหมายแรกของเราควรเป็นลูโมโพลิสแล้วซิฟก็เห็นด้วย เราเดินทางขึ้นไปยังแม่น้ำทองคำด้วยเรือไม้ง่องแง่น กระแทกคลื่นไปมาเป็นเวลาครึ่งเดือนก่อนจะถึงด้านที่ใกล้ที่สุดของลูโมโพลิส\n\"แอชูไรต์!\"\nซิฟยกแขนขึ้นแล้วชี้ขึ้นไปบนท้องฟ้า ฉันเอามือป้องที่คิ้วแล้วมองไปทางที่เธอชี้ ตอนนั้นเองที่ฉันได้เห็น—เกาะลอยที่มีหมวกกลม ยอดเป็นโคน ลอยละล่องอยู่เหนือดินแดนรกร้างทางตะวันออก ส่องสว่างตระการตาอยู่ใต้แสงเจิดจ้าของดวงอาทิตย์\nยิ่งเราเข้าไปใกล้เท่าไหร่ เราก็ยิ่งรู้สึกถึงความใหญ่โตและน่าเกรงขาม ในขณะที่เราเข้าไปใต้เงาของเกาะก็มีคลื่นอากาศเย็นยะเยือกล้อมรอบเรา เงานั้นหนาวเกินไปสำหรับชาวออโรเรียน\nศูนย์กลางรถรับส่งเป็นสถานที่เดียวซึ่งสามารถเข้าและออกจากลูโมโพลิสได้ และถ้าอยากเข้าละก็ต้องไปด้วยเรือเหาะ แต่ซิฟและฉันไม่มีหนังสือสำคัญที่ไว้ใช้ขึ้นเรือเหาะ เราเลยถูกเชิญออกจากลูโมโพลิส\n\"นักเดินทางทุกคนต้องลงทะเบียนขออนุญาตจากกรมการท่าเพื่อเข้าลูโมโพลิส!\"\n ซิฟถามไปว่า \"นานเท่าไหร่ถึงได้รับอนุญาตเหรอ\" \n\"ครึ่งเดือนถึงหนึ่งเดือนน่ะ\"\nเราไม่มีทางมีเงินเก็บอยู่นานพอเท่านั้นอยู่แล้ว กระทั่งค่าเรือเหาะเองก็ยังมากกว่าที่เราคิดว่าจะจ่ายไหว เราหันหลังกลับออกมาโดยไม่มีทางเลือก\nในขณะที่เรากำลังช่วยกันแนะนำสถานที่ต่อไปของเราไม่กี่แห่ง ซิฟก็พูดออกมาอย่างโมโหว่า \"จะไปไหนก็อย่าลืมว่าต้องเป็นที่ซึ่งไม่ใช้ใบอนุญาตเข้าก่อนแล้วกัน!\"\nเลยเราตัดสินใจว่าที่ต่อไปจะเป็นนอร์ธแลนด์\nแต่ขณะที่เราไปนอร์ธแลนด์ ชะตาก็เสนอโอกาสให้เราไปเข้าลูโมโพลิสฟรีเสียอย่างนั้น",
  str_dispatch_book_chaptercont_12000_9 = "หลังจากที่ออกจากท่าเรือลูโมโพลิสแล้ว เราก็มุ่งหน้าสู่ทางเหนือ ถนนที่ทอดยาวสายนี้ดูจะหาจุดสิ้นสุดไม่ได้เลย แล้วเราก็พบกับผู้ส่งสารที่บาดเจ็บคนหนึ่งที่โดนพวกอิคลิพไซท์เล่นงานระหว่างที่กำลังเดินทางไปลูโมโพลิส หลังจากวิกฤติการณ์ดาร์กโอเวอร์มานั้น พวกอิคลิพไซท์ก็เริ่มพบเห็นได้ตามที่ต่าง ๆ เธอคนที่ว่านี้นั่งทรุดอยู่บนหลังกวางเรนเดียร์ ปีกและขาท่อนล่างของเธอเปรอะเปื้อนไปด้วยโลหิตสีแดงฉานที่หยดติ๋งลงบนขนกวางเรนเดียร์ที่เธอนั่งอยู่ด้วย\nฉันกับซีฟได้พาเธอไปยังที่ทำการที่อยู่ละแวกใกล้เคียงเพื่อที่เธอจะได้รับการรักษาด้วยลูมินาติกส์ และเพื่อเป็นการตอบแทนเรา เธอแนะนำว่าเราจะพักผ่อน ณ ที่ทำการไปรษณีย์สักวันสองวันก็ได้ จนกระทั่งเรื่องน่ากังวลเกี่ยวกับการเข้าเมืองลูโมโพลิสก็ย้อนกลับมาหาเราอีกครั้ง\n\"ลูโมโพลิสมีระเบียบที่รัดกุมในการคัดกรองสินค้าและผู้คนที่เดินทางเข้าเมืองน่ะ\" เธอกล่าวพลางยิ้มออกมา \"แต่สหภาพผู้ส่งสารไม่ใช่สหภาพนักเดินทาง และเราไม่ขนส่งสินค้าด้วย\"\n\"เรามีสิทธิพิเศษในการเข้าออกเมืองลูโมโพลิส สื่งที่เราต้องทำมีเพียงแค่ต้องแสดงบัตรประจำตัวให้ทหารรักษาการณ์ดูเท่านั้น\"\nเธอหยิบบางสิ่งออกมาจากกระเป๋าพกของเธอ มันคือสมุดบันทึกที่ฉันเห็นจนชินตามาตั้งแต่ที่ทำการไปรษณีย์ใกล้บ้านเกิดฉันแล้ว ผู้ส่งสารใช้สมุดนี้ในการบันทึกข้อมูลเดินทางของพวกเขา ตัวเล่มมีเข็มประดับสองชิ้น ซึ่งมีรูปขนนกโบกสะบัดเป็นสลักเอาไว้\nเธอดึงเข็มนั่นออกแล้วนำมันมากลัดไว้ที่อกของเรา \"แค่นี้เธอก็เดินทางเข้าออกลูโมโพลิสได้โดยไม่มีใครมาขวางแล้ว ถือว่าฉันให้เธอยืมสักพักละกันนะ แล้วห้ามบอกใครเด็ดขาดล่ะ\"\nซีฟและฉันได้ขึ้นเรือเหาะตามผู้ส่งสารเพื่อเดินทางไปสู่ลูโมโพลิส เรือเหาะลำนี้เป็นพาหนะที่สงวนไว้สำหรับเจ้าพนักงานของสหภาพฯ เท่านั้น\nเมื่อเราทะยานขึ้นสู่ท้องฟ้า มือของฉันพลันแตะไปโดนม้วนกระดาษม้วนหนึ่งในกระเป๋าพกพาเข้า มันก็คือสิ่งสุดท้ายที่เชริโอซาส่งมาให้ฉันนั่นเอง\n(โปรดติดตามตอนต่อไป)",
  str_dispatch_book_chaptercont_12000_10 = "ศูนย์กลางขนส่งมวลชนที่พาไปยังอัมบราตันนี้ถูกตราด้วยคำอธิบายที่ว่าโกลาหลวุ่นวาย เสียงดังโหวกเหวก และเป็นพื้นที่อันตรายประจำนครลูโมโพลิสที่ทรงเกียรติ แต่ทว่าฉันรู้ตั้งแต่แรกเห็นว่านี่คือคำอธิบายที่ผิดเพี้ยนไปจากความจริง เพราะความจริงมันคือสถานที่ที่อภิรมย์ที่สุด ตื่นตาตื่นใจที่สุด และเต็มไปด้วยชีวิตชีวาที่สุดในลูโมโพลิสแล้ว\nทันที่ที่เรามาถึงศูนย์กลางขนส่งฯ เราก็ได้พบกับผับและคาเฟ่มากมาย และแม้แต่ร้านเครื่องเพชรนานาชนิด ที่แห่งนี้อบอวลไปด้วยกลิ่นอายของเครื่องเทศ เบียร์ และโกโก้นานาชนิดอีกต่างหาก ความอบอวลที่ว่าทำให้ซีฟถึงกับเผลอจามออกมากลางถนนเลยทีเดียว ชัดเจนเลยว่าบรรดากลิ่นทั้งหลาย ณ ที่แห่งนี้ประดาประดังเข้ามาหาเธอแบบปัจจุบันทันด่วนจนเธอรับมือไม่ทัน ออโรเรียนทั้งคู่เดินเตรไปเรื่อย ๆ ตามทาง แต่ละย่างก้าวกระทบกับพื้นถนนเป็นจังหวะต่อเนื่องกัน ผู้ช่วยร้านค้าที่ยืนประจำอยู่หน้าร้านของตนต่างแต่งตัวอย่างภูมิฐานและเปี่ยมด้วยมารยาทอันดี พวกเขาต่างก็จับผ้าเช็ดหน้าไว้ตรงหว่างนิ้วของตนเพื่อแต้มกลิ่นอันหอมหวลทว่าแรงให้กับผู้ที่เดินผ่านไปมา\nที่แห่งนี้คือบ้านเกิดของเชริโอซา\nขณะที่ซีฟเอาจมูกแนบติดกับหน้าต่างร้านเพื่อส่องดูสร้อยคออันงดงามหรูหราที่ห้อยอยู่กับหุ่นลองเสื้อนั้น ฉันก็ถามออโรเรียนที่นั่งจิบเบียร์อยู่ว่าเขารู้จักที่อยู่ที่เชริโอซาทิ้งไว้ให้ฉันหรือเปล่า\n\"นั่นมันเขตสลัมน่ะ\" เขากล่าว ดูเหมือนว่าเขาจะเมานิด ๆ แล้วด้วย หนวดของเขาเปรอะเปื้อนไปด้วยฟองเบียร์ เขาเบิกตาให้กว้างอีกนิดแล้วมองมาที่ฉันพลางถามว่า \"สาวน้อย เธอจะไปที่นั่นทำไมกันล่ะ?\"\nฉันบอกเขาไปว่ากำลังตามหาอัศวินคนหนึ่ง\n\"อัศวินงั้นเหรอ?\" เขายิ้มพลางส่ายหน้า \"อัศวินแบบไหนกันที่ไปหมกตัวอยู่ในที่แบบนั้น?\"\nฉันรู้สึกว่าตัวเองเริ่มทำตัวไม่ถูกอยู่ครูหนึ่ง แต่ก็พยายามกลบมันออกไปได้ พลางตอบกลับไปว่า \"แต่เขามีโล่ทรงหอคอยที่มีแต่อัศวินจะได้รับเท่านั้นนะ!\"\n\"โล่ทรงหอคอยรึ?\" เขาเอ่ยทุกถ้อยคำอย่างชัดเจนจนอ่านริมฝีปากได้ ทีแรกฉันกลัวว่าเขาจะพ่นคำผรุสวาทบางอย่างที่ไม่น่าฟังออกมา แต่เขากลับเอ่ยกลับมาว่า \"สาวน้อย นั่นคือโล่ที่พวกอัศวินใช้จริง ๆ นั่นแหละ แล้วเธอเคยพบกับเขาที่ไหนบ้างรึเปล่าล่ะ?\"\nฉันรู้สึกว่าฉันควรจะรีบจบบทสนทนาตั้งแต่ตอนนี้เลย แต่ฉันก็ไม่อาจทนความหยิ่งผยองที่เขาแสดงออกมาได้ ฉันจึงตัดสินใจอธิบายออกไปว่าเชริโอซาแต่งกายยังไง รวมถึงภารกิจคุ้มกันกองคาราวาน ไหนจะเรื่องลูมินาติกส์อีก\n\"คุ้มกันกองคาราวานน่ะรึ?\" เขาเย้ยกลับทันควัน \"ไม่มีอัศวินหน้าไหนลดตัวลงมาทำงานคุ้มกันกองคาราวานหรอก!\"",
  str_dispatch_book_chaptercont_12000_11 = "ฉันก็ไม่รู้ชัด ๆ ว่าฉันออกมาจากชานชาลาขนส่งฯ ได้ยังไง แต่หลังจากที่ฉันฟื้นจากภาวะมึนตึงแล้ว ฉันพบว่าซีฟกำลังลูบมือฉันอยู่แล้วฉันก็ดันกำแขนเธอไว้หนึบเลย เธอกู่ตะโกนชื่อฉันอย่างขับเขี้ยวเคี้ยวฟันว่า \"มินะ! ฉันเจ็บนะ!\"\n\"ฉันขอโทษ\" ฉันรีบตอบขอโทษขอโพยแล้วปล่อยแขนเธอออก\nเธอลูบแขนของเธอแล้วเบิกตามองไปยังหมู่บ้านที่กั้นกำแพงขาวที่ตั้งอยู่บนภูเขาลูกหนึ่งเขม็ง เธอถามฉันว่า \"เธอแน่ใจนะว่าเรามาถูกทางแล้ว?\"\nฉันส่องดูป้ายบอกทางริมถนนที่อยู่ห่างไปไม่กี่ก้าว ฉันเลยมุ่งหน้าต่อไปเพื่อไปดูใกล้ ๆ จนแน่ใจว่านี่แหละคือที่ ๆ เชริโอซาเขียนบอกไว้บนซองจดหมาย\nหลังจากที่เดินทางเข้าสู่ท้องถนนที่มีบ้านหลังเล็กหลังน้อยตั้งอยู่กระจัดกระจายไปทั่ว เราก็เริ่มหลงทิศจนได้ เพราะกำแพงด้านนอกที่อยู่ติดถนนของบ้านนั้นถูกพ่นด้วยลายกราฟิตีแปลก ๆ และรอยเท้าด้วย ทางถนนเบื้องล่างเราก็ไม่มีการปูพื้นอย่างเป็นระเบียบ หากแต่เป็นทางดินเลนไปแล้ว นัยน์ตาคู่หนึ่งกำลังสอดส่องดูเราอยู่จากเงามืด ตอนนี้ซีฟเกาะแขนฉันแล้วถามว่า \"เธอไม่ลองถามหาที่อยู่ของเขาชัด ๆ จากใครสักคนแถวนี้สักหน่อยเหรอ?\"\nแต่ความไม่สบายใจที่คุ้นเคยกำลังรบกวนจิตใจฉันอยู่ ฉันกลัวว่าจะเผลอพูดอะไรที่เป็นความลับที่ฉันต้องเก็บงำไว้หากปริปากออกมาแม้เพียงนิดเดียวก็ตามที\nทว่าซีฟไม่สนใจ เธอเหลือบไปเห็นผู้หญิงนางหนึ่งเดินผ่านไป ซีฟเลยเดินไปถามเธอคนนั้นว่ารู้จักคนชื่อเชริโอซาไหม\n\"พวกเธอต้องการอะไรจากไอ้ตัวเกะกะขวางโลกนั่นล่ะ?\" เธอตอบด้วยสีหน้าบึ้งตึงจากทุกอนูผิวบนเครื่องหน้าที่สะสวยของเธอ ที่ตอนนี้ปกคลุมไปด้วยกลิ่นอายของความชิงชังที่ย้อมไปกับคำพูดนั้น \"บางทีพวกเธออาจจะช่วยจ่ายหนี้ที่มันติดค้างฉันได้นะ ฉันจะบอกให้ละกันว่ามันอยู่ไหน\"\nซีฟไม่เข้าใจว่าสตรีนางนั้นพูดเรื่องอะไร \"ยังมีคนอื่นที่ชื่อเชริโอซาอยู่ที่นี่อีกเหรอ?\" เธอถามออกไป จากนั้นก็รีบอธิบายรูปพรรณสัณฐานของเขาให้สตรีผู้นั้นฟัง\n\"แม่หนู เธอลืมไปอย่างนึงนะ\" คนจรคนหนึ่งที่นั่งอยู่ตรงริมทางกล่าวพลางชี้นิ้วที่มอมแมมนั่นไปทางซีฟ พลางฉีกยิ้มให้เราจนเห็นฟันเหลืองอ๋อยอยู่ครึ่งปาก \"เธอต้องบอกว่าขาเขาเดี้ยงข้างนึงด้วยสิ\"\nฉันลากซีฟกลับมาแล้วเดินจากไป\nหลังจากเดินทางต่อไปได้สักพัก ฉันก็ได้สอบถามหาเชริโอซากับออโรเรียนคนอื่น ๆ ที่อยู่ตามทาง ทว่าทุกคนกลับมีท่าทีที่แทบไม่ต่างกันเลย เชริโอซาที่ก่อหนี้สินให้ตัวเองเพราะติดพนัน จนต้องนำอุปกรณ์ประจำตัวที่เป็นของอัศวินลูโม แถมยังโดนกองทหารรักษาการณ์จับได้เสียอีก แต่ก็ไปมีเรื่องกับพวกเขาจนขาเดี้ยงไปข้างหนึ่ง...\n\"ครั้งหนึ่งตอนที่เขาเมาน่ะ เขาขิงกับฉันว่าเขาได้ของดีมาด้วยล่ะ แล้วมันคืออะไรรู้ไหม? มันคือโล่ทรงหอคอยและชุดเกราะอัศวินลูโมยังไงล่ะ!\"\n\"เมื่อยังเด็กเขาใฝ่ฝันที่จะเป็นอัศวิน แต่เขาจะรักษาสถานภาพอันทรงเกียรติได้ยังไงกันเล่า!?\"\n...\n\"ลงเขาลูกนี้ไปสิ ที่นั่นมีผับอยู่ตรงสุดทางถนนเลย เธอจะเจอเขาที่นั่นแหละ\"\nในที่สุด ก็มีคนยอมบอกที่กบดานของเชริโอซาเสียที\n(โปรดติดตามตอนต่อไป)",
  str_dispatch_book_chaptercont_12000_12 = "ซีฟถามฉันว่า \"ลองไปดูไหม?\"\nฉันพยักหน้าตอบด้วยสีหน้าอันไร้อารมณ์ พลางตอบซีฟไปว่า \"ไม่มั่นใจนะ พวกเขาต้องจำคนผิดแน่ ๆ\"\nเราเดินลงเขาไปจนกระทั่งเห็นผับซอมซ่อแห่งหนึ่ง ผู้ชายมากหน้าหลายตาและรูปลักษณ์ต่างยืนหลังพิงกำแพงด้านนอก และห้อยเครื่องมือหลากชนิดไว้ตรงข้างเอวของพวกเขา เสื้อที่พวกเขาพับแขนขึ้นจนถึงข้อศอก ในมือถือแก้วเบียร์ขนาดใหญ่พลางพูดคุยเสียงเซ็งแซ่\nชายผู้มีรูปลักษณ์พะรุงพะรังผู้หนึ่งกำลังนั่งขัดสมาธิพิงกำแพงอยู่ เขามีเรือนผมหยักโศกสีน้ำตาลและหนวดเคราที่ดกเฟิ้มจนเกือบบดบังหน้าค่าตาของเขาจนมิด ชายผู้นี้วางมือลงบนพื้น เอียงตัวไปด้านหน้า พลางเผยอยิ้มออกมาให้คนอื่น ๆ แล้วกล่าวว่า \"เฮ้ยวิลล์ ขออีกแก้วสิ?\"\nชายท่าทางแข็งแรงผมดกดำผู้หนึ่งเตะเขาพลางหัวร่อออกมา \"ไอ้เป๋มันจะดื่มอีกเหรอ?\"\nชายผมน้ำตาลผู้นั้นร้องครวญออกมาแปลก ๆ แล้วยื่นมือมาเก็บขาเสีย ๆ ของเขา จากนั้นก็นั่งพิงกำแพงต่อไป ทว่าสีหน้าของเขายังเปื้อนยิ้มอยู่ เขาแลบลิ้นออกมาแล้วเลียริมฝีปากแตก ๆ ของเขา พลางจ้องมองแก้วสุราของคนอื่น ๆ\nซีฟหันมาถามฉันว่า \"เห็นเชริโอซามั้ย? ฉันนึกเลยว่าเขาจะอยู่ในสภาพนี้\"\nฉันจำเขาได้\nแต่กลับไม่อาจเอื้อนเอ่ยวาจาใด ๆ ออกมาได้\nดวงตะวันสว่างจ้าอยู่เหนือหัวของฉัน จากนั้นเสียงกลองนั่นก็ดังกึกก้องขึ้นมาอีกครั้ง ฉันให้รู้สึกราวกับว่าร่างกายของฉันถูกห้อมล้อมไปด้วยสายน้ำขมุกขมัวของแม่น้ำทองคำที่ซัดสาดและไม่เคยหยุดไหลเชี่ยว มันไหลผ่านปากและจมูกของฉัน แม้แต่ตาของฉันก็จมไปกับมวลน้ำนี่ด้วย\n\"ไม่ล่ะ\" ฉันได้ยินตัวฉันเอ่ยวาจานั้นออกมา \"ไว้เราค่อยกลับมาใหม่คราวหน้าละกัน...\" สัญญาอันว่างเปล่านี้ทำฉันหายใจไม่ออก นี่มันเรื่องโกหก แต่ซีฟรู้ว่าฉันล้มเลิกภารกิจค้นหาไปแล้วและเธอก็สุขใจมาก เธอกุมมือฉันไว้แล้วหันหลังกลับมา พลางย้อนระลึกถึงเรื่องราวประหลาดทั้งหลายที่เธอพบพาน ณ ศูนย์กลางขนส่งฯ แห่งนั้น\nเราเดินทางออกจากลูโมโพลิสในวันเดียวกันนั้นเอง\nตั้งแต่วันนั้นเป็นต้นมา ฉันก็แทบไม่กลับไปยังนครลอยฟ้าแห่งนั้นอีก",
  str_dispatch_book_chaptercont_13000_1 = "ที่ทางเข้าหมู่บ้านมีซุ้มหินอยู่สองซุ้ม เป็นหินที่ตัดมาจากหินทั้งหลายบนภูเขาและนำมาเรียงรายซ้อนกันเป็นชั้น ๆ มีไม้สนล้อมกรอบทั้งสองข้างทำเป็นประตูรั้วที่ตั้งอย่างโดดเดี่ยว ไม้นั้นไม่ได้ตัดแต่งอย่างประณีต ริบบิ้นไหมที่ผูกไว้จะส่งเสียงหวีดหวิวในลมหนาว เมื่อนักเดินทางมองเห็นประตูจากระยะไกลจะรู้ว่ามีที่พักในหมู่บ้านข้างหน้า เด็ก ๆ มักจะปีนซุ้มประตูโค้ง พวกเขาจะตั้งหลักในรอยแยก จับกิ่งไม้ไว้แล้วเอนไปข้างหน้า มองไปยังขอบฟ้าเท่าที่จะทำได้ แต่ในวันที่อากาศหนาว มีเด็กสองสามคนพลัดลื่นบนซุ้มประตูโค้งที่มีน้ำแข็งเกาะและได้รับบาดเจ็บ ผู้อาวุโสจึงสั่งห้ามการเล่นแบบนั้นอีก\nคืนก่อนหน้ามีหิมะตกหนัก แม้ว่าจะไม่ถึงหัวเข่าก็ตาม ผู้อาวุโสเรียกโดโรธีและครูซ ส่งพลั่วให้คนละอัน และสั่งให้ไปตักหิมะกับชาวบ้านคนอื่น ๆ บางคนใช้ลูมินาติกส์โยนหิมะส่วนใหญ่เข้าไปในป่าใกล้ ๆ ในขณะที่โดโรธีสามารถใช้ลูมินาติกส์ได้เช่นกัน แต่มันไม่เหมาะกับสิ่งนี้ เธอกับครูซเดินตามชาวบ้านที่เหลือและแซะน้ำแข็งบนถนน ในเวลาตกเย็นพวกเขาคืนเครื่องมือให้ผู้อาวุโสซึ่งให้ปลาเฮอริ่งกระป๋องจำนวนมากตามปกติ ถามพวกเขาว่าเหลืออาหารอยู่เท่าไร และยื่นขนมกัมมมี่ให้ครูซหนึ่งกำมือ ครูซยัดขนมลงในกระเป๋าของเขา แต่ขนมหล่นลงมาหมดเพราะกระเป๋าขาด เขาเอื้อมมือไปเก็บขณะที่โดโรธีก็ช้อนขนมขึ้นจากพื้น ว่าแล้วผู้เฒ่าก็พูดถึงคู่สามีภรรยาที่ท้ายหมู่บ้านด้านตะวันออกเฉียงใต้ว่า \"พวกเขาอยากมีลูก และพวกเธอก็ยังเด็กไม่มีผู้ใหญ่คอยดูแล ฉันคิดว่าพวกเธอจะสร้างครอบครัวที่ดีได้นะ\"\nโดโรธีไม่ตอบอย่างอื่นนอกจากจับกระเป๋าน้องชายแล้วกระซิบว่า \"คราวหน้าก็บอกสิ ไม่ใช่ว่าจะไม่ซ่อมให้นะ\"\nผู้อาวุโสถอนหายใจและโบกมือลา พี่น้องขอบคุณผู้อาวุโสอีกครั้งและจูงมือกันเดินกลับบ้าน",
  str_dispatch_book_chaptercont_13000_2 = "ระหว่างทางกลับบ้านหิมะเริ่มตกอีกครั้ง ความมืดเริ่มปกคลุม มีโคมสลัวอยู่ไม่กี่ดวง ไม่ไกลจากบ้านนัก ครูซวิ่งเข้าไปและสะดุด เขาเงยหน้าขึ้นและเห็นเงาร่างมืด ๆ นอนอยู่บนหิมะ โดโรธีตามเสียงกรีดร้องของครูซไปและเห็นว่าคนผู้นั้นกำลังไอและพยายามลุกขึ้น หลังจากแน่ใจว่าเป็นออโรเรียน แม้ว่าจะเป็นคนไม่คุ้นเคย เธอเรียกน้องชายของเธอให้ช่วยคนแปลกหน้า พวกเขาพาออโรเรียนไปที่เพิงเก็บฟืนห่างออกไปสองสามฟุต ชาวออโรเรียนขอบคุณพวกเขาด้วยเสียงแหบห้าว ทรุดตัวพิงกำแพงและเงียบไป ภายใต้แสงสลัวใกล้ ๆ นั้น โดโรธีมองเห็นผมสีบลอนด์แห้ง ๆ เล็ดลอดออกมาจากหมวกของออโรเรียน พลิ้วไหวไปตามจังหวะการหายใจของเธอ\nเป็นเรื่องปกติที่จะช่วยเหลือออโรเรียนแปลกหน้า ดังนั้นโดโรธีและครูซจึงลืมไปอย่างรวดเร็ว... กระทั่งวันรุ่งขึ้นเมื่อมีข่าวแพร่ไปว่าในหมู่บ้านมีผู้อาศัยคนใหม่ ตอนที่กวาดหิมะ พี่น้องสังเกตเห็นว่าประตูและหน้าต่างของบ้านหลังเก่าทรุดโทรมที่ติดกับบ้านของพวกเขานั้นปิดลงแล้ว มีควันพวยพุ่งจากปล่องไฟสู่ท้องฟ้าสีครามที่เย็นยะเยือก\nครูซชี้ไปที่รูขนาดเท่าอ่างอาบน้ำบนหลังคาบ้านหลังนั้น และถามพี่สาวของเขาว่า \"ใครจะไปอยู่ในบ้านแบบนั้นได้นะ?\"\nโดโรธีคว้าปกเสื้อของเขาและดึงตัวออกไป\nคืนนั้นพายุหิมะพัดถล่ม สองพี่น้องม้วนตัวอยู่ในผ้าห่ม นอนฟังเสียงลมโหยหวนและกิ่งไม้ปลิวว่อน ทันใดนั้น ก็มีเสียงระเบิดดังตามมาด้วยเสียงที่กระทบกันราวกับมีอะไรถล่มทลาย ครูซตัวสั่นเทาในความฝัน ขณะที่โดโรธีตกใจตื่นขึ้นนั่งและสำรวจไปรอบ ๆ อย่างประหม่า\nไม่นานก็กลับสู่ความเงียบอีกครั้ง ไม่มีเสียงลมที่ผ่านรอยร้าวของหน้าต่าง โดโรธีขยี้ตาและเอาหัวซุกหมอนอีกครั้ง เธอตื่นขึ้นในเวลาต่อมาเพราะมีคนมาเคาะประตูบ้าน เธอค่อย ๆ ลุกจากเตียงเพื่อไม่ให้รบกวนการนอนของน้องชาย ย่องขึ้นไปที่หน้าต่างพร้อมตะเกียงในมือแล้วตรวจดู ร่างที่สั่นสะท้านยืนอยู่ข้างนอก คลุมด้วยผ้าห่มบาง ๆ ลมหนาวพัดผมสีบลอนด์ที่หยิกเป็นลอนของเธอ\nโดโรธีจำเธอได้ในทันที แต่ไม่เปิดประตู แค่ถือตะเกียงแล้วโผล่หัวออกมา \"เกิดอะไรขึ้นเหรอ?\"\nออโรเรียนผมบลอนด์ชี้ไปที่บ้านหลังเก่า \"หลังคาบ้านฉันถล่มลงมา... คุณช่วยกรุณาให้ฉันพักกับคุณสักคืนหนึ่งได้ไหม\"\nโดโรธีหยุดอยู่ครู่หนึ่ง มองเข้าไปในความมืดแล้วตอบว่า \"ฉันคิดว่าคุณควรไปหาผู้อาวุโสดีกว่า\"\nออโรเรียนพยักหน้า จับผ้าห่มของเธอแล้วหันหลังเดินจากไป โดโรธีจึงตระหนักว่าสาวผมบลอนด์กำลังเดินเท้าเปล่าอยู่ท่ามกลางหิมะ เธอกัดฟันและลังเล ก่อนจะเปิดประตูและเรียกหญิงสาวด้วยน้ำเสียงเรียบ ๆ ว่า \"คุณ... เข้ามาก็ได้\"",
  str_dispatch_book_chaptercont_13000_3 = "โดโรธีได้รู้ว่าออโรเรียนผู้นี้ชื่อมาร์ธา คืนนั้นเธอนอนขดตัวในผ้าห่มของเธออยู่ข้างเตาผิง เมื่อพี่น้องออกมาในตอนเช้า ก็เห็นสภาพของบ้านเก่าที่เหลืออยู่เพียงครึ่งหลัง หลังคาหายไปหมดแล้ว ก้อนอิฐกระจัดกระจายไปทุกหนทุกแห่ง\nมาร์ธาคุ้ยซากปรักหักพัง เธอขุดได้รองเท้าบูทคู่หนึ่ง ซึ่งเธอสวมใส่หลังจากปัดหิมะและขี้เลื่อยข้างในออก หลังจากสวมรองเท้าแล้ว เธอขยับคานที่หักไปด้านข้างเพื่อจะหยิบกระเป๋าผ้าใบสีดำ\n\"สักชิ้นไหม? มันคือช็อกโกแลต\" มาร์ธาหยิบสิ่งที่ห่อด้วยกระดาษฟอยล์ออกจากถุง แต่โดโรธีหยุดครูซไว้เมื่อเขาเอื้อมมือไปหยิบ มาร์ธายักไหล่ ใส่ช็อกโกแลตกลับเข้าไปในถุง หยิบขนมปังที่ปิดผนึกสุญญากาศแล้วเคี้ยวไปในขณะที่หิมะตกลงมาใส่\nมาร์ธานั่งเคี้ยวอยู่ในซากปรักหักพังขณะไตร่ตรองที่อยู่อาศัยที่พังทลายไม่เหลือชิ้นดี \"ฉันจะซ่อมบ้านหลังนี้โดยเร็วที่สุด\" เธอประกาศเป็นมั่นเหมาะ\nโดโรธีพยักหน้าและเดินจากไปพร้อมกับน้องชาย\nเมื่อได้ยินข่าว ผู้อาวุโสแนะนำว่าโดโรธีควรให้มาร์ธาอยู่กับเธอสักพักจนกว่าจะซ่อมบ้านเสร็จ โดโรธีไม่เห็นด้วยกับความคิดนี้ แต่ตะขิดตะขวงใจที่จะปฏิเสธเมื่อผู้อาวุโสมอบเนื้อฉลามหมักก้อนโตให้เธอ\nมาร์ธาขอยืมม้าตัวหนึ่งจากผู้อาวุโส ทุกวันจะเห็นเธอขนก้อนหินและไม้จากป่าไปสุมที่คลังหลังบ้านที่พังยับเยิน โดโรธีแทบไม่เคยเห็นมาร์ธาในตอนเช้าเลย มีแค่ตอนเที่ยงหรือตอนกลางคืนเท่านั้นที่มาร์ธาจะทำอาหารอยู่ในครัวหรือนอนข้างเตาผิง\nในตอนแรกมาร์ธาไม่ได้รับประทานอาหารร่วมกับพี่น้อง เธอจะนั่งไขว่ห้างหันหน้าไปทางเตาผิงและแทะขนมปัง มีเนื้อย่างและซุปปลาเป็นครั้งคราว โดโรธีจำไม่ได้ว่ามันเริ่มต้นอย่างไร อาจจะเป็นตอนที่มาร์ธาแบ่งกระต่ายสดให้โดโรธี หรือครูซกับมาร์ธานั่งไขว่ห้างอยู่ด้วยกันข้างเตาผิง แบ่งกันกินขนมกัมมี่กับช็อกโกแลต อย่างไรก็ตาม ในที่สุดพวกเขาก็มานั่งร่วมวงกินอาหารอย่างเอร็ดอร่อยด้วยกัน",
  str_dispatch_book_chaptercont_13000_4 = "มาร์ธาเลิกใช้เวลาทั้งวันอยู่แต่ในป่าข้างหมู่บ้านหันมาทำอาหารแทน เธอไม่ชอบกินปลาฉลามเย็น ๆ กับปลาเฮอริ่งกระป๋อง บนโต๊ะอาหารจึงมีสตูว์ผัก ซุปปลา เคบับ และมันฝรั่งบดมากขึ้น โดโรธีไม่ต้องการให้มาร์ธาทำอาหารในตอนแรก เนื่องจากถือว่ามาร์ธาเป็นแขก แต่เมื่อเทียบกับฝีมือการทำอาหารที่ไม่เอาไหนของโดโรธีแล้ว ครูซก็ชอบอาหารของมาร์ธามากกว่าอย่างเห็นได้ชัด นั่นทำให้โดโรธีต้องช่วยมาร์ธาจัดเตรียมส่วนผสมก่อนเท่าที่เธอจะทำได้ พร้อมกับจดจำสูตรอาหารต่าง ๆ ไปในตัว\nมาร์ธาไม่ปรารถนาเพียงแค่ให้อิ่มท้อง ครั้งหนึ่ง เธอชิมน้ำซุปและแสดงความคิดเห็นว่า \"นี่อาจจะต้องเติมเกลือหน่อย\"\n\"เกลือเหรอ?\" โดโรธีครุ่นคิดอยู่นานกว่าจะนึกออกว่ามันเป็นเครื่องปรุงเม็ดเล็ก ๆ ขนาดเท่าเกล็ดหิมะ \"หายากมากนะ\" เธอกล่าว\nมาร์ธาพยักหน้าอย่างครุ่นคิดเมื่อได้รับคำตอบ\nวันต่อมาเมื่อโดโรธีกลับจากทำงานบ้านให้ผู้อาวุโส ครูซก็ดึงแขนเสื้อของเธอแล้วพาเข้าไปในครัว ชี้ไปที่ถุงใบน้อย ตะโกนเสียงดังว่า \"เกลือ!\"\nโดโรธีก้มลง จิ้มนิ้วเข้าไปในเกล็ดละเอียดสีขาวแล้วชิมรส ความเค็มแผ่ซ่านไปทั่วลิ้น\n\"มันมาจากไหน?\"\n\"มาร์ธาเอามา!\" ครูซชี้ไปทางด้านหลังโดโรธีขณะที่มาร์ธาเดินเข้าไปในครัวพร้อมกับขาหมูป่า\n\"เกลือ... ราคาแพงมั้ย?\" โดโรธีถามมาร์ธาด้วยความสงสัย\nมาร์ธาเงียบสักพักก่อนจะตอบว่า \"ฉันไม่ได้ซื้อ\"\n\"แล้วเอามาจากที่ไหนล่ะ\"\nมาร์ธายิ้ม \"ทะเลสาบน้ำเค็มใกล้ ๆ นี่ไง\"\nภายใต้การสอบปากคำของพี่น้อง มาร์ธาเปิดเผยว่าเธอได้เกลือมาได้อย่างไร... เมื่อไม่นานมานี้เธอได้ติดตามเหยื่อที่ต้องการล่าไปถึงทะเลสาบน้ำเค็ม เธอจะใช้น้ำมาแช่แข็งเหยื่อบนฝั่ง นำน้ำเกลือที่ยังไม่แช่แข็งกลับบ้าน ต้มเพื่อให้ได้เกลือ จากนั้นกรองแล้วกรองอีกเพื่อให้กินได้ โดโรธีกับครูซรู้สึกทึ่งกับเรื่องนี้ ขนาดมาร์ธากำลังหมักขาหมูป่าก็ยังเซ้าซี้ถาม\n\"เธอรู้มากขนาดนี้ได้ยังไง มาร์ธา?\" โดโรธีถามพร้อมกับใช้เกลือทาถูให้ทั่วเนื้อตามอย่างมาร์ธา\n\"มันไม่ยากจริง ๆ\" มาร์ธาให้คำตอบที่ค่อนข้างคลุมเครือ\nโดโรธีพยักหน้ากับตัวเอง โดยคิดว่ามันไม่ยากเกินไปที่จะทำเช่นกัน",
  str_dispatch_book_chaptercont_13000_5 = "วันนั้นเป็นวันธรรมดาอีกวัน นอกจากการโกยหิมะแล้ว ผู้เฒ่าพบงานบ้านใหม่สำหรับโดโรธี นั่นคือการต้อนแกะให้ไปกินหญ้าในป่า ทันทีที่มาร์ธาลากท่อนไม้และก้อนหินกลับมา เธอก็ตรงเข้าไปในครัวเพื่อทำอาหารเย็น ขณะพิงหน้าต่าง ครูซชะโงกหน้าออกไปดูก้อนน้ำแข็งใหม่บนบ้านหลังเก่า แล้วก็หันกลับมาถามมาร์ธาว่า \"พี่มาร์ธาจะไปแล้วเหรอ?\"\n\"น่าจะอีกสักหนึ่งหรือสองสัปดาห์นะ\" เธอหั่นมันฝรั่งลงในหม้อที่แขวนอยู่\nครูซวิ่งเข้าไปในครัว นั่งข้างมาร์ธา จับใบหน้าในมือและจ้องก่อนจะพูดออกมาในที่สุด \"แต่ฉันไม่อยากให้พี่ไป\" เขาหยุดพูดสักพัก \"แต่อย่าบอกพี่สาวนะว่าฉันพูดแบบนี้\"\n\"ทำไมล่ะ\" มาร์ธากวนหม้อด้วยทัพพี\n\"เพราะเธอบอกว่าเราไม่ควรพึ่งพาผู้ใหญ่... เพราะสุดท้ายพวกเขาจะทิ้งเราไป\"\nทัพพีหมุนวนและกระแทกกับหม้อเป็นครั้งคราว\n\"ผู้ใหญ่มักจะมีงานที่ต้องทำมากมาย โดโรธีบอกว่าหนึ่งในงานเหล่านั้นจะสำคัญกว่าการดูแลเรา\" ครูซก้มศีรษะลงเพื่อให้กองไฟอุ่นแก้ม \"แต่มาร์ธาจะไม่ทิ้งพวกเราไป ใช่มั้ย?\"\n\"เกิดอะไรขึ้น...\" มาร์ธาพยายามอย่างหนักที่จะเปลี่ยนเรื่อง กลับมาถามในสิ่งที่เธอคิดอยู่ในใจ ก่อนจะมองไปรอบ ๆ และสงสัยว่า \"ทำไมโดโรธียังไม่กลับมาอีก\"\nครูซเงยหน้าและมองออกไปนอกหน้าต่าง ท้องฟ้ามืดครึ้ม ลูกเห็บตกกระหน่ำ และเสียงลมโหยหวน\nเด็กชายเริ่มตื่นตระหนก \"โดโรธี... ทำไมโดโรธียังไม่กลับบ้าน\"",
  str_dispatch_book_chaptercont_13000_6 = "โดโรธีตัวสั่นเทาเดินก้าวเท้าไปบนหิมะ ต้านแรงลมบาดผิวทุกย่างก้าว แทบจะมองไม่เห็นว่ามีอะไรอยู่ข้างหน้าหรือไม่ เธอเริ่มเสียใจกับการตัดสินใจทุกอย่างที่ทำไปในวันนี้ หลังจากต้อนฝูงแกะกลับเมืองแล้วเธอก็น่าจะกลับบ้าน ขดตัวอุ่นอยู่ข้างเตาผิง เธอน่าจะรู้ดีว่าทางลัดไปทะเลสาบนั้นเต็มไปด้วยอันตรายและควรจะหันหลังกลับ กระทั่งเมื่อถึงทะเลสาบแล้วก็ควรจะตรวจสอบสภาพอากาศสักหน่อย ไม่เห็นต้องรอให้น้ำกลายเป็นน้ำแข็งเลย... พายุหิมะกรรโชกแรงทั่วทุกหนแห่ง แย่กว่านั้นคือฟ้าเริ่มจะมืดแล้ว โดโรธีมองไปรอบ ๆ และเตรียมใจรับสิ่งที่เลวร้ายที่สุดคือต้องนอนกลางป่าหิมะแบบนี้หนึ่งคืน\nพอคิดอย่างนั้นแล้ว เธอก็คลำหาทางข้ามโขดหินไป ค้นหารอยแยกเพื่อเข้าไปพักในนั้น โชคดีที่เธอเจอร่องหินหนึ่งที่ใหญ่พอให้เธอเบียดตัวเข้าไปพอดี เธอถอนหายใจอย่างโล่งอกขณะที่พิงศีรษะกับแผ่นหินด้านหลัง\nเธออดเป็นห่วงครูซไม่ได้ เขาจะตกใจแล้วร้องไห้ไหมนะ? หรืออาจจะฝ่าพายุไปขอร้องผู้อาวุโสให้ส่งกลุ่มค้นหาออกมาตามหาเธอหรือเปล่า? ผู้อาวุโสจะส่งคนมาทั้ง ๆ ที่สภาพอากาศไม่เอื้ออำนวยอย่างนี้ไหม? มาร์ธาจะเป็นห่วงเพราะเธอไม่กลับบ้านหรือเปล่า? หรือแค่นั่งมองเตาผิงเฉย ๆ นะ?\nโดโรธีอ่านใจครูซได้ เขาอยากให้เธอยอมรับมาร์ธาและอยู่ด้วยกันเป็นครอบครัว ไม่ใช่แค่เพื่อนบ้านที่มาขออาศัยอยู่ชั่วคราว แต่พวกเขาไม่รู้ด้วยซ้ำว่ามาร์ธามาจากที่ไหน อดีตของเธอเป็นดั่งแผ่นกระดานที่ว่างเปล่าซึ่งเธอไม่เคยเปิดเผยมาก่อน\nโดโรธียังจำได้ในตอนที่มาร์ธานั่งอยู่หน้าเตาผิง ก้มหัวลงต่ำ ผมสีบลอนด์ห้อยลงมาข้างแก้ม เธอเงียบสงบ เหนื่อยล้าและทรุดโทรม โดโรธีเห็นมาร์ธายิ้มแค่ตอนนั่งอยู่ที่โต๊ะอาหาร ชั่วครู่เดียวที่โล่งอกเพราะทิ้งอดีตไว้เบื้องหลังในช่วงเวลาสั้น ๆ โดโรธีเชื่อว่าเธอไม่ควรเชื่อใจคนแบบนั้น มาร์ธาไม่ใช่ \"ครอบครัว\" ที่ดีแน่นอน เธอมาโดยกุมความลับเอาไว้แล้วก็จะจากไปทั้ง ๆ แบบนั้น โดโรธีไม่อยากสูญเสียอีกต่อไปแล้ว...\nโชคดีที่บ้านของมาร์ธาซ่อมใกล้เสร็จแล้ว\nในที่สุดโดโรธีก็รู้สึกว่าพายุหิมะเริ่มสงบลงแล้ว เธอนวดขาที่แข็งจนชา ออกจากร่องหินและพยายามควานหาเส้นทางในความมืด ทันใดนั้นก็ได้ยินเสียงเบา ๆ เธอตัวแข็งวาบขึ้นมาเมื่อเห็นแสงสีเขียวค่อย ๆ เยื้องกรายเข้ามาใกล้\nในสายลมมรณะ เธอได้ยินเสียงพวกมันหายใจ\nไม่มีทางเป็นอย่างอื่นไปได้นอกจากหมาป่า",
  str_dispatch_book_chaptercont_13000_7 = "\"ตุบ!\"\nหมาป่าอีกตัววิ่งฝ่าหิมะที่ปลิวไสวต่อหน้าโดโรธี เธอลืมพวกหมาป่าที่เคยจัดการด้วยลูมินาติกส์ไปหมดแล้ว\nหลังจากที่พ่อแม่เสียชีวิตลง เธอก็บังเอิญพบว่าตัวเองทำให้อากาศแข็งตัวได้ ตอนแรกมันเป็นเพียงแค่ลูกบาศก์ใสขนาดเท่าอุ้งมือที่จะเลือนหายไปในไม่กี่วินาที แต่แล้วขนาดก็ขยายใหญ่ขึ้น รวมถึงระยะเวลาด้วย อย่างเก่งเธอสามารถสร้างเกราะกำบังขนาดเท่าครึ่งประตูใหญ่ได้เป็นเวลาสองนาที\nแต่ในคืนที่มืดมิดแบบนี้ เธอแทบจะทำสุดฝีมือไม่ได้เลย หมาป่าพุ่งเข้ามาใกล้ขึ้นเรื่อย ๆ จนได้กลิ่นน้ำลายเหม็นหืนของพวกมัน ทันใดนั้นเองเธอก็ลื่นล้ม มองลงไปเห็นหมาป่างับขากางเกง พยายามลากเธอถอยหลัง เธอกู่ร้องแล้วใช้ก้อนอากาศทุบหัวหมาป่า หมาป่าโหยหวนด้วยความเจ็บปวดแต่ก็ยังกัดขากางเกงขาดออกไปพอสมควร พรรคพวกของมันย่องไปรอบ ๆ แล้วคำรามออกมาพร้อมกัน\n\"ตุบ!\" เธอกัดฟัน เหงื่อไหลด้วยความกลัวในขณะที่หลบการโจมตีอีกครั้งแทบไม่พ้น\nเธอรู้ว่าต้านไว้ได้ไม่นานหรอก ความกลัวแทบทำให้เธอตัวแข็งทื่อไปหมดแล้ว และเธอก็สร้างเกราะกำบังได้ช้าลงทุกที ราวกับว่ามีเสียงใสกระซิบข้างหูเธอว่า เธอต้านไว้ไม่ไหวหรอก ค่ำคืนนี้ยังอีกยาวไกล เป็นไปไม่ได้\nความหนาวเย็นเจาะทะลวงเข้ามาในเนื้อที่เผยออกราวกับมีด แต่กว่าโดโรธีจะรู้ตัวว่าหนาวสั่นมาตลอดเวลาก็ผ่านไปนานแล้ว เมื่อความกลัวกัดกินใจก็เปิดทางให้ความสิ้นหวังท่วมท้นเข้ามา\nกำแพงอากาศค่อย ๆ เลือนหายไปในพายุหิมะ เธอสร้างมันขึ้นมาใหม่ไม่ได้อีกแล้ว ไม่ไกลจากเธอนักมีแสงสีเขียวจากดวงตาหมาป่าเปล่งประกายอาฆาตร้าย\nหมาป่าพุ่งเข้ามา โดโรธียกแขนขึ้นปิดป้องใบหน้าตัวเองไว้\nแต่กลับไม่เจ็บปวดอย่างที่คิดไว้ โดโรธีได้ยินเสียงแตกร้าวของบางอย่างที่แข็งตัวอย่างรวดเร็ว เธอลดแขนลงแล้วเห็นหมาป่าที่พุ่งเข้ามาหยุดอยู่กลางอากาศในท่าน่าขัน วินาทีต่อมาร่างนั้นก็เข้ามาใกล้แล้วยกหมาป่าจ่าฝูงขึ้น โยนมันลงไปในหิมะอย่างไม่ใส่ใจ หมาป่าไม่ได้เลือดสาดกระจายก็เพราะถูกแช่แข็งจากภายใน โดโรธีอยากกรีดร้องแต่กลับไม่มีแรงมากพอ\nมีคนเตะหมาป่าไปข้าง ๆ แล้วหันมาขวางหน้าโดโรธี ฮู้ดของเสื้อหล่นลงเผยให้เห็นผมสีบลอนด์เกาะอยู่ที่ใบหน้า ผู้ช่วยชีวิตของเธอถือกริชสองคมที่ส่องประกายชวนให้สยองขวัญในคืนอันหนาวเหน็บ\nโดโรธีรู้สึกว่ามีบางอย่างอุ่น ๆ บนใบหน้าของเธอและรับรู้ได้ในทันทีว่ามันคือน้ำตา",
  str_dispatch_book_chaptercont_13000_8 = "ค่ำคืนอันน่าสยดสยองนั้นผ่านมานานแล้ว โดโรธีเลิกคิดว่า Martha อุ้มเธอกลับไปที่หมู่บ้านได้อย่างไร หรือสุนัขลากเลื่อนที่ดมกลิ่นที่เท้าของเธอ การถอนหายใจยาวอย่างโล่งอกของผู้อาวุโส และแม้แต่น้อยเกี่ยวกับครูซที่ร่ำไห้ ตอนนี้เธอแค่ต้องการแกะสลักโคมน้ำแข็งให้เสร็จเพื่อที่เธอจะได้วางไว้ที่ทางเดิน\nปีใหม่กำลังจะมาถึง\nบ้านของ Martha ได้รับการแก้ไขแล้ว แต่ผู้อาวุโสสั่งให้เป็นสถานที่สำหรับต้อนรับและให้ความบันเทิงแก่แขกของเมือง ด้วยเหตุนี้ ผู้อาวุโสจึงจ่ายปลาฉลามหมักเต็มถังเป็นค่าตอบแทน\nโดโรธีเคยถามมาร์ธาเกี่ยวกับกริชสองคมก่อนหน้านี้ มาร์ธากดสวิตช์ที่ด้ามจับโลหะเพื่อดึงใบมีดกลับมาใส่มือโดโรธี โดยบอกเธอว่าเธอจะไม่ใช้มันอีก—ตอนนี้มันเป็นของโดโรธีแล้ว โดโรธีรู้ว่ามาร์ธาพยายามจะพูดอะไร จึงรับกริชโดยไม่พูดอะไรสักคำ และทิ้งการ์ดทั้งหมดของเธอ\nมาร์ธาบอกเธอว่า \"ฉันทิ้งอดีตไปแล้วและจะไม่ทิ้งเธอสองคน\"\nโคมไฟน้ำแข็งสว่างขึ้นทีละดวง กองไฟเกิดขึ้นในจัตุรัสกลางเมือง ผู้เฒ่ากดกริ่ง ชาวบ้านออกจากบ้านพร้อมอาหารหลายอย่างในมือ: ชีส, ขนมปังน้ำผึ้ง, ไส้กรอกรมควัน, สตูว์, พายผลไม้, ชาร์ดอนเนย์หิมะหนึ่งขวด... ลูกอมและก้าวออกจากประตู\nมาร์ธาอยู่ข้างกองไฟแล้ว กำลังสนทนากับผู้อาวุโส เธอโบกมือให้พี่น้องเมื่อเห็นพวกเขาด้วยรอยยิ้มอบอุ่นเช่นเคย\nชาวบ้านรวมตัวกันรอบกองไฟและผู้อาวุโส แลกเปลี่ยนเรื่องราวจากปีที่ผ่านมาและแบ่งปันอาหารของพวกเขา ในไม่ช้าเด็กสาวก็เริ่มร้องเพลง ชาวบ้านรีบประสานเสียงประสานเพลงพื้นบ้านโบราณ เด็กหญิงอีกคนเริ่มเต้นรำ กระโปรงขนฟูของเธอหมุนวน ระบบ Luminatics ของเธอสร้างประกายไฟที่ประสานกับท่วงท่าของเธอ\nโดโรธีนั่งข้างมาร์ธา ปรบมือตามจังหวะและฮัมทำนองเพลงเบาๆ ดวงตาของเธอเป็นประกายราวกับดาวสองดวงที่มีความสุขจากแดนไกล\nขณะที่การร้องเพลงจบลง โดโรธีผู้ยิ้มแย้มก็หลับตาลงและวางคางของเธอไว้ในมือที่ป้องไว้ มาร์ธาชำเลืองมองไปรอบๆ เห็นชาวบ้านกำลังหลับตาราวกับกำลังอธิษฐาน เธอกระซิบบอกครูซและพบว่าชาวบ้านกำลังขอพรสำหรับปีที่จะมาถึง\nโดโรธีลืมตาขึ้นมองมาร์ธาที่ยิ้มแย้มราวกับว่าเธอกำลังจะถามว่าโดโรธีขอพรอะไร แต่วินาทีถัดมา มาร์ธาก็หยุดยิ้ม ดวงตาของเธอจับจ้องที่มุมหนึ่งซึ่งอยู่นอกแสงไฟจากกองไฟ\nโดโรธีที่งุนงงมองไปทางนั้นแต่เห็นเพียงความมืด",
  str_dispatch_book_chaptercont_13000_9 = "โดโรธีพบว่าหมู่บ้านมีผู้มาเยือนอีกคนเมื่อไปช่วยชาวบ้านลากฟืน ออโรเรียนหน้าตาไม่คุ้นเคยผมสีดำออกมาจากบ้านของผู้อาวุโสและเข้าไปยังบ้านเก่าที่ซ่อมเสร็จแล้ว เมื่อโดโรธีออกจากบ้าน เธอก็เห็นว่ามาร์ธากำลังซ่อมเสื้อผ้าของครูซอยู่ข้างเตาผิงทั้งที่ในเวลาปกติเธอน่าจะออกไปล่าสัตว์ตั้งนานแล้ว เมื่อโดโรธีกลับมามาร์ธาก็หายไป ครูซชี้ไปที่บ้านข้าง ๆ เมื่อพี่สาวถามว่าสาวผมบลอนด์ไปไหนแล้ว\nออโรเรียนผมดำมาหามาร์ธา โดโรธีมั่นใจ\nในตอนมื้อเที่ยง โดโรธีอยากรู้เกี่ยวกับออโรเรียนผมดำคนนั้นโดยนึกไม่ถึงว่ามาร์ธาจะปากแข็งถึงเพียงนี้\nมาร์ธาเงียบสนิทขณะที่โดโรธีถามคำถามไม่ยั้งก่อนจะยอมรับกลาย ๆ ว่าออโรเรียนคนนั้นเป็น \"เพื่อนคนหนึ่ง\"\nโดโรธีไม่พอใจกับคำตอบนั้น เธออยากรู้ให้ได้ถึงที่มาที่ไปและเจตนาของออโรเรียนคนนั้น รวมถึงภัยที่อาจจะเกิดขึ้นกับมาร์ธาด้วย\n\"แค่เพื่อนคนหนึ่งน่ะ\" มาร์ธาบอกปัดคำถามของเธอไปอย่างใจเย็น\nโดโรธีที่ผิดหวังเลิกถาม\nทั้งสามคนกินอาหารในความเงียบจนเสียงกระดิ่งเตือนภัยดังขึ้นนอกบ้าน\nมาร์ธาเป็นคนแรกที่ลุกขึ้นไปเปิดประตู\nชาวบ้านรวมตัวกันที่จตุรัสเมือง บางคนสบถออกมาเสียงดัง บางคนร่ำไห้ บางคนซุบซิบกัน โดโรธีได้ยินเสียงเกรียวกราวแล้วตามมาร์ธาออกไปนอกประตู\nสีหน้าของโดโรธีแปรเปลี่ยนเป็นตกใจเมื่อเธอรู้ว่าชาวบ้านคุยเรื่องอะไรกัน\nอิคลิพไซท์นั่นเอง ชาวบ้านบอกว่าพบเห็นร่องรอยของอิคลิพไซท์ในละแวกนี้",
  str_dispatch_book_chaptercont_13000_10 = "ผู้อาวุโสเรียกรวมตัวชายหนุ่มทุกคนในหมู่บ้าน แยกออกเป็นห้ากลุ่มและส่งพวกเขาออกไปเป็นกลุ่มค้นหาเพื่อจัดการเหตุอิคลิพไซท์\nในขณะที่กลุ่มชายหนุ่มออกไปจากเมือง เด็ก ๆ ไปรุมซุ้มประตูเพื่อโบกมือลาคนรู้จัก โดโรธีแทรกตัวเข้าไปในกลุ่มชายหนุ่มแล้วกำกริชสองคมซ่อนไว้ในตัว ผู้อาวุโสจะไม่มีทางให้เธอเข้าร่วมกลุ่มค้นหาแน่ แต่เธอรู้ดีว่าเธอต้องทำอะไรสักอย่าง\nกลุ่มชายหนุ่มออกเดินทางไปทีละกลุ่ม โดโรธีก้มหัวลงแล้วเดินออกไปอย่างรวดเร็วเพื่อไม่ให้ใครมองเห็นเธอได้ คิดแต่ว่าจะตามให้ทันกลุ่มสุดท้ายที่ออกไป\nจู่ ๆ ก็มีคนจับแขนของเธอไว้\n\"คิดว่าตัวเองกำลังทำอะไรอยู่ โดโรธี\" เป็นเสียงของมาร์ธานั่นเอง\nโดโรธีพยายามดิ้นให้หลุดจากมือเธอ \"ปล่อยฉันนะ!\"\nมาร์ธาเห็นกริชแล้วยึดเอาไว้ \"จะออกไปหาอิคลิพไซท์เหรอ\"\n\"ไม่ใช่เรื่องของเธอ!\" โดโรธีเอื้อมมือไปกระชากกริชกลับแต่ถูกหลบอย่างง่ายดาย \"เอาคืนมานะ!\"\n\"กลับบ้านกับฉันเถอะ\" มาร์ธาเสนอเสียงอ่อน \"แล้วฉันจะคืนให้เธอ\"\nโดโรธีกัดฟันแล้วฉีกแขนเสื้อออกจนขาดเสียงดัง ย่ำเท้าออกห่างจากมาร์ธา ก่อนจะวิ่งหนีไปก็ถูกห้ามโดยอ้อมแขนที่กอดจากเอวด้านหลัง\n\"คิดว่าไปยุ่มย่ามกับอิคลิพไซท์มันสนุกนักรึไง?!\"\nโดโรธีตัวแข็ง มาร์ธาไม่เคยดุเธอแบบนี้มาก่อน ไม่ว่าเธอจะหยาบคายแค่ไหนก็ตาม เธอค่อย ๆ หันไปหามาร์ธาอย่างระมัดระวัง ใบหน้าที่สั่นสะท้านด้วยความโกรธนั้นเป็นสิ่งที่เธอไม่เคยเห็นมาก่อน\n\"อย่ามาดุกันนะ!\" โดโรธีได้สติอย่างรวดเร็วแล้วทำท่าทีแข็งกระด้าง \"คิดว่าตัวเองเป็นใครถึงมาสั่งกันแบบนี้\"\nแขนที่ล้อมรอบเอวเธอคลายลง โดโรธีวิ่งจากไปโดยไม่หันหลังกลับไปมอง\n\"เธอจะทิ้งน้องชายไปแบบนั้นหรือไง?\"\nเสียงโกรธาของผู้อาวุโสดังขึ้นข้างหลังเธอ โดโรธีหลับตาลงด้วยความหงุดหงิดแล้วหยุดเดิน",
  str_dispatch_book_chaptercont_13000_11 = "มาร์ธาผลักประตูบ้านออกแล้วพบกับความเงียบงัน ห้องสองพี่น้องปิดสนิท เธอพุ่งเข้าไปแล้วพยายามเคาะประตูแต่ก็ต้องลังเล หยุดมือไว้กลางอากาศ\n\"ห้าปีก่อน หมู่บ้านถูกอิคลิพไซท์โจมตี พ่อของโดโรธีและครูซอยู่ในกลุ่มค้นหาที่ไม่รอดกลับมา... จากนั้นแม่ของพวกเขาก็ตามร่องรอยไป แต่กลับเจอกับอิคลิพไซท์ เธอกลับมาพร้อมบาดแผลฉกรรจ์และตายหลังจากนั้นไม่นาน...\" สิ่งที่ผู้อาวุโสเล่ายังดังก้องอยู่ในหูมาร์ธา \"อย่าใจร้ายกับพวกเขานักเลย ทุกคนมีอดีตที่ลืมไม่ลง\"\nเธอลังเลอีก สุดท้ายก็ตัดสินใจไม่เคาะประตู หันไปมองด้านนอก\n\"มาร์ธา\" ออโรเรียนผมดำพูดขณะที่รออยู่ตรงชานเรือน \"ตัดสินใจจะไปแล้วเหรอ?\"\n\"ไปกันเถอะ\" เธอยอมจำนนพร้อมกับถอนหายใจ\nแต่แล้วจู่ ๆ ห้องก็เปิดออกแล้วมาร์ธาก็รู้สึกว่าถูกกอด ครูซนั่นเอง \"เข้ามาข้างในได้ไหม พี่มาร์ธา\"\nภายในห้อง โดโรธีนั่งเงียบเชียบอยู่บนเตียง เธอหันมาขณะที่มาร์ธาเข้ามาแล้วถามว่า \"จะไปแล้วเหรอ?\"\nก่อนมาร์ธาจะได้ตอบอะไร เธอก็ถามว่า \"เพราะฉันหรือเปล่า?\"\n\"เรื่องวันนี้ก็ขอโทษด้วย...\" ปากของโดโรธีสั่นระริก \"ฉันพูดจาหยาบคายมาก...\"\n\"ไม่หรอก ไม่ใช่เรื่องนั้น\" มาร์ธาย่อตัวลงและจ้องมองดวงตาที่รื้นไปด้วยน้ำตา \"ฉันต้องไปแล้ว\"\n\"ทำไมล่ะ?\"\n\"ฉันเป็น... ทหารทิ้งหน้าที่\" มาร์ธาชะงัก \"ฉันมาจากสหพันธรัฐอิลลูมินา\"\nโดโรธีไม่รู้จักสหพันธรัฐอิลลูมินาแน่นอนแต่เธอเข้าใจคำว่า \"ทหารทิ้งหน้าที่\" ดีทีเดียว\n\"ฉันสู้กับอิคลิพไซท์ไม่ไหวอีกแล้ว ไม่มีสหายคนไหนรอดกลับมาได้เลย ฉันทนการต่อสู้ไม่ไหวก็เลยหนีจนมาถึงนอร์ธแลนด์\" มาร์ธาหลุบตาลงต่ำ \"ตอนนี้เพื่อนเก่าคนหนึ่งของฉันมาเจอ ถ้าฉันไม่กลับไป...\"\n\"ก็ไม่เห็นต้องไปนี่!\" โดโรธีตวาดออกมาอย่างไม่หายใจ \"บอกเพื่อนไปสิว่าอยู่ที่นี่แล้วมีความสุขมาก! พวกเขาต้องเข้าใจแน่... ไปขอร้องผู้อาวุโสก็ได้ ท่านจะพูดแทนเอง...\"\n\"เธอจะไม่ทิ้งเราไปไหนไม่ใช่เหรอ\"\n\"โดโรธี...\" มาร์ธาเช็ดน้ำตาบนใบหน้าของเด็กสาว \"ฉันเสียใจกับสิ่งที่เกิดขึ้นกับพ่อแม่เธอนะ...\"\nคำพูดนั้นทำให้โดโรธีชะงักอย่างตกใจเล็กน้อย แล้วจึงถามว่า \"เธอไปเพราะเรื่องนั้นเหรอ?\"\n\"ฉันแค่อยู่กับเธอไม่ได้... ยกโทษให้ฉันด้วยนะ...\"\nโดโรธีตัวสั่นไหว \"เธอเลือกที่จะหนีทุกครั้งเลยเหรอ?\"\nบรรยากาศรอบตัวหนักอึ้งด้วยความเงียบชวนอึดอัด มาร์ธาคิดหาคำแก้ตัวไม่ได้ เธอคุ้นชินกับบทบาทการเป็นทหารทิ้งหน้าที่และวางป้อมปราการที่เปราะบางจนคนอื่นมองทะลุได้... เป็นป้อมปราการที่ใช้ไม่ได้เลย\n\"ไปเถอะ\" โดโรธีโพล่งออกมา ถอยตัวไปด้านหลังราวกับว่าต้องการออกห่างจากมาร์ธา\nมาร์ธาลุกขึ้น มองไปที่ครูซที่ยืนอยู่ตรงมุมห้องแล้วพยายามลูบผมของเขา แต่แล้วครูซก็ถอยหลังไปอีกคน เธอฝืนยิ้มและพูดด้วยน้ำเสียงที่แผ่วเบา \"ตอนนี้อย่าเพิ่งออกไปที่หมู่บ้านล่ะ รักษาตัวด้วย\"\nมาร์ธาออกจากห้อง วางกริชไว้บนโต๊ะห้องนั่งเล่นแล้วเดินออกจากบ้านไป",
  str_dispatch_book_chaptercont_13000_12 = "เช้าวันถัดมา มาร์ธากับออโรเรียนผมดำก็เดินทางออกจากหมู่บ้าน หิมะที่ปกคลุมทั่วทั้งซุ้มประตูละลายกลายเป็นแอ่งน้ำเหนอะหนะบนพื้น\n\"จะไม่บอกลาเด็ก ๆ พวกนั้นหน่อยเหรอ?\"\n\"ไม่จำเป็นหรอก\" มาร์ธาสวมฮู้ดเพื่อกันไม่ให้ศีรษะถูกหิมะที่ละลาย \"ยังไงพวกเขาก็ไม่อยากเจอหน้าฉันอยู่แล้ว\"\n\"การหลบซ่อนมันง่าย\" ออโรเรียนแสดงสีหน้าที่อ่อนโยนแต่ก็ดูซับซ้อน \"เธอแค่ต้องวิ่งไปเรื่อย ๆ จนกว่าคนที่ตามมาจะหมดความอดทน อิลลูมินาไม่เสียเวลากับทหารที่ทิ้งหน้าที่นานขนาดนั้นหรอก\"\nมาร์ธาล้อเลียนด้วยท่าทีฝืน ๆ \"เธอก็ปล่อยฉันไปเลยสิ\"\nออโรเรียนไม่แสดงท่าทีตอบกลับ\n\"ทั้งเธอและฉันต่างก็รู้ดีว่าชีวิตแบบนั้นมันไร้ความหมาย\" มาร์ธาฟังเสียงหิมะร่วงโรยที่เลือนลางไปแล้วกระซิบบอก \"ฉันไม่ได้หนีอิลลูมินาเพราะอยากอยู่รอดหรอกนะ ฉันเหนื่อยหน่ายกับการถูกใช้เป็นแค่อาวุธชิ้นหนึ่ง เหนื่อยหน่ายกับการต่อสู้ไม่จบไม่สิ้น\"\n\"แล้วเลือกที่จะกลับมากับฉันทำไม?\"\n\"เพราะ...\" หลังจากเงียบไปพักใหญ่ สุดท้ายมาร์ธาก็พูดต่อ \"ฉันเป็นทหารทิ้งหน้าที่ และมีแค่ฉันคนเดียวที่จะให้อภัยตัวเองเรื่องนั้นได้\"\n\"ฟังดูย้อนแย้งชอบกล\"\n\"ถูกต้อง\" มาร์ธาหัวเราะเบา ๆ \"ในที่สุดฉันก็รู้ตัวหลังจากวิ่งหนีมานาน\"\nออโรเรียนหยุดกะทันหัน \"ผ่านโค้งนี้ไปก็จะมองไม่เห็นหมู่บ้านแล้วนะ\"\nริมฝีปากของมาร์ธากระตุกแล้วกระซิบบอกไปว่า \"ขอบคุณนะ\"\nเธอหันกลับไป จากจุดที่เธอมองนั้นยังเห็นซุ้มและริบบิ้นที่เปียกโชกไปด้วยหิมะละลายห้อยอยู่ระหว่างกิ่งไม้ ไกลออกไปก็เห็นหลังคาสูงสีดำ ถึงแม้จะยังเช้าเกินกว่าที่ปล่องควันจะปล่อยควันออกมาก็ตามที\nมาร์ธาเตรียมตัวไปต่อแล้วแต่เหลือบเห็นคนโผล่ออกมาจากซุ้ม ระยะทางออกจะไกลพอสมควรแต่มองดูก็รู้ว่าเป็นครูซ\nเธออ้าปากค้าง สายลมหนาวเหน็บพัดผมสีบลอนด์ปลิวไสว แม้จะรู้สึกเย็นเฉียบที่สองแก้ม แต่กลับรู้สึกอบอุ่นที่นัยน์ตา\nเธอเห็นเด็กสาวที่ห่มผ้าคลุมสีขาววิ่งเข้ามาหา แล้วหยุดยืนในระยะห่างจากเธอไปหนึ่งศอก\n\"โดโรธี?\"\n\"นี่ของเธอ...\" โดโรธีที่หายใจหอบแบมือออกให้เห็นกริชสองคม \"ฉันไม่อยากเก็บไว้\"\n\"เธอควรจะถือกลับไปด้วย หนีไปอย่างนี้ไม่มีค่าอะไรหรอก ถ้านี่เป็นคำขอโทษ ฉันไม่รับไว้ มันไม่มีอะไรพิเศษ แล้วฉันก็ไม่สนใจด้วย\" โดโรธีวางกริชใส่มือมาร์ธาแล้วถามออกไปอย่างแข็งกระด้างและหนักแน่นว่า\n\"ฉันสนแค่ว่าเมื่อไหร่เธอจะกลับมาเท่านั้นแหละ\"\nทันใดนั้นก็ยิ้มหวาน \"เธอจะกลับมาใช่ไหม?\"\nมือที่ถือกริชอยู่นั้นสั่นไหว มาร์ธาตื้นตันเกินกว่าจะพูดคำใดออกไป ทำได้เพียงแค่พยักหน้า\n\"สัญญาแล้วนะ!\" โดโรธีถอยออกไปแล้วโบกมือ \"ลาก่อนนะ พี่มาร์ธา!\"\nเธอวิ่งรี่ไปที่หมู่บ้าน ครูซกระโจนลงจากซุ้ม เด็กสองคนจูงมือกันเดินกลับเข้าเมืองจนกระทั่งกำแพงบังร่างของทั้งสองลับจากสายตา\nและแล้วปล่องควันบนดาดฟ้าก็ปล่อยควันพวยพุ่ง ริบบิ้นพากันพลิ้วไหวลู่ลมอีกครั้ง หิมะละลายหยดลงมาเป็นจังหวะ จากป่าไม้ไปสู่ท้องทุ่ง จากถนนไปสู่หมู่บ้าน...\nเมื่อน้ำแข็งแห่งฤดูหนาวละลายจนหมดสิ้น ทุกคนต่างรู้ดีว่าบนซุ้มประตูจะมีเด็กน้อยนั่งแหงนหน้ามองไปยังขอบฟ้าแสนไกล",
  str_dispatch_book_chaptercont_14000_1 = "เรียน คุณแม็กซ์และคุณนายมินนี่\nฉันชื่อโรซ่า จากทะเลทรายเรดีเซล พอดีฉันเห็นโฆษณาของคุณในลังตากีล่าเถื่อน พวกเขาม้วนใบปลิวของพวกคุณไว้รองขวด ราคาอะไหล่ของร้านคุณไม่ได้ค้ากำไรจนเกินควร ฉันน่าจะเจอพวกคุณมาตั้งนานแล้ว ฉันได้ติดต่อกับคาราวานให้ช่วยส่งจดหมายสั่งซื้อฉบับนี้ให้คุณในอัมบราตัน และขอให้พวกเขาเดินทางปลอดภัยเพื่อที่เราจะได้เริ่มเจรจาธุรกิจกัน\nฉันได้แนบรายการอะไหล่ที่ต้องการพร้อมกับแผนผังที่ด้านหลังของจดหมายฉบับนี้\nฉันคำนวณราคาคร่าว ๆ จากโฆษณาและได้ส่ง 1,500 ไนท์เทียมมาด้วยสำหรับคำสั่งซื้อนี้ โปรดตรวจสอบเงินทั้งหมดด้วย เผื่อว่ามีใครในคาราวานเกิดโลภขึ้นมาแล้วฉกทิปให้ตัวเองเพิ่มจากค่าบริการซึ่งฉันเองก็ได้จ่ายไปแล้ว หากสิ่งที่ฉันกล่าวไว้เกิดขึ้น โปรดใช้งานบริการขนส่งที่น่าเชื่อถือในการตอบกลับจดหมาย แล้วฉันจะจ่ายให้คุณเอง\n\nขอแสดงความนับถือ\nโรซ่า\nเขียนในตอนบ่ายสุดแห้งแล้ง\n\n\nเรียน คุณโรซ่า\nเป็นเกียรติอย่างยิ่งที่ได้ให้บริการแก่คุณ เราได้บรรจุอะไหล่ที่คุณต้องการตามหมวดหมู่และส่งออกจากอัมบราตันด้วยคณะคาราวานเดียวกันแล้ว (เราได้รับ 1,500 ไนท์เทียมตามที่คุณให้มา ฉันคิดว่าคุณไว้ใจพวกเขาและใช้บริการพวกเขาต่อไปได้) ทั้งนี้ คุณให้เงินเรามาเกิน เราจึงส่งกลับคืนไป 21 ไนท์เทียมในจดหมายฉบับนี้ หวังว่าอะไหล่จะไปถึงคุณในเร็ววัน ขอให้เป็นวันที่ดี\n\nขอแสดงความนับถือ\nร้านอะไหล่ M&M\nเขียนตอนปลายฤดูฝน\n\n\nปล:\nสวัสดีโรซ่า ฉันมินนี่นะคะ ฉันไม่ค่อยชอบให้เรียกว่าคุณนายสักเท่าไรเลย มันฟังดูสูงส่งและดูมีความสำคัญเกินไป แต่ว่าพ่อของฉันชอบที่คุณเรียกว่าคุณแม็กซ์นะ ผู้ใหญ่ดูจะชอบที่คนอื่นให้เกียรติ ถึงจะเสแสร้งก็ตาม นี่คงจะเป็นเหตุผลที่เขาเขียนคำขึ้นต้นจดหมายว่า \"\"เรียน\"\" ทั้ง ๆ ที่ปกติออกจะหยาบคาย\nฉันช่วยพ่อจัดอะไหล่ตามคำสั่งซื้อของคุณ แต่บอกตามตรงว่าฉันนึกไม่ออกเลยว่าคุณจะเอาไปทำอะไร อะไหล่หลายชิ้นที่คุณต้องการค่อนข้างจะพิเศษ มันวางทิ้งไว้ชั้นล่าง ๆ อยู่นานพอสมควร เพราะงานดัดแปลงทั่วไปจะไม่ใช้อะไหล่พวกนี้กัน ถ้าไม่ว่าอะไร ช่วยบอกหน่อยได้ไหมว่าเอาไปทำอะไร ฉันข้องใจจริง ๆ!\nอีกอย่าง โปรดอย่าบอกพ่อฉันนะว่าฉันเปิดจดหมายของเขา แต่ว่าก็ว่าเถอะ เขาให้ฉันไปส่งพัสดุเองนี่นา",
  str_dispatch_book_chaptercont_14000_2 = "เรียน คุณแม็กซ์และมินนี่\nฉันเพิ่งได้รับอะไหล่จากคาราวานเมื่อวานนี้ ฉันว่าเราคงคาดหวังบริการขนส่งดี ๆ จากคาราวานไม่ได้จริง ๆ เหมือนหากินจากคนไม่รู้อิโหน่อิเหน่เสียมากกว่า ฉันว่าจะเปลี่ยนไปใช้ขนส่งที่เป็นผู้เป็นคนกว่านี้ ฉันเพิ่งรู้ว่ามีสหภาพผู้ส่งสารอยู่ไม่ไกลจากแคมป์ของเรา เดี๋ยวจะยอมเสียเวลาเอาของไปส่งที่ทำการน่าจะดีกว่า ได้ยินว่าชื่อเสียงเรียงนามของสหภาพผู้ส่งสารค่อนข้างดีในอัมบราตัน คุณจะได้ไม่ต้องเจออะไรกับคาราวานหลังจากนี้อีก\nครั้งนี้ฉันต้องการเหล็กพิเศษชนิดหนึ่ง แต่ไม่จำเป็นต้องเป็นวัสดุดิบหรอกนะ แค่เป็นอะไหล่ที่มีเหล็กอยู่ด้วยก็ใช้ได้แล้ว โปรดแจ้งค่าใช้จ่ายให้ฉันทราบด้วย ฉันเขียนรายการเหล็กไว้ที่ด้านหลังของจดหมายฉบับนี้แล้ว\nฉันได้แนบไปอีก 1,500 ไนท์เทียม หากมีส่วนเกิน โปรดเก็บไว้ แล้วถือว่าเป็นเงินมัดจำสำหรับคำสั่งซื้อในอนาคต ฉันมีสิ่งที่ต้องซ่อมและประกอบใหม่มากโขในทะเลทรายเรดีเซล แม้แต่สิ่งที่ฉันซ่อมไปแล้วก็จะพังหรือคงพังอีกไม่ช้าก็เร็ว\nอีกอย่าง สิ่งที่ฉันกำลังดัดแปลงคือรถเป่าลม อาจมีผู้หญิงบางคนอยากรู้ข้อมูลนี้\n\nขอแสดงความนับถือ\nโรซ่า\nเขียนในยามเย็นอันหนาวเหน็บ\n\n\nเรียน คุณโรซ่า\nนี่มินนี่เองนะ คุณก็น่าจะดูออกจากการเขียนว่าฉันไม่ได้จ่าหน้าจดหมาย เพราะฉันคงไม่เขียนเหมือนเด็กประถมแน่นอน ดีใจจังที่ครั้งนี้คุณไม่ได้เรียกฉันว่าคุณนาย มันช่วยให้ฉันรู้สึกดีขึ้นหน่อย แต่ประโยคสุดท้ายของคุณมันมีพิรุธอยู่นะ คุณพ่อหันมามองฉันด้วยความสงสัยทันทีที่อ่านจดหมายและบอกให้ฉัน \"\"ตอบจดหมายคุณโรซ่าด้วย\"\" เห็นชอบเขียนดีนัก ฉันก็เลยมานั่งเขียนถึงคุณอยู่นี่\nเข้าเรื่องดีกว่า ถ้าเป็นพ่อฉันนะ ท่านคงเขียนแต่อะไรไม่เข้าประเด็น อย่าง \"\"ผมบรรจุเหล็กพิเศษที่คุณต้องการไว้ตามหมวดหมู่และส่งไปทะเลทรายเรดีเซลผ่านสหภาพผู้ส่งสารแล้วครับ\"\" หรือเขียนอะไรฟุ่มเฟือยเพิ่มมากมาย มันคงยากสำหรับเขาที่จดหมายฉบับนี้และอะไหล่ทั้งหมดจะถึงคุณในเวลาเดียวกัน\nเงิน 1,500 ไนท์เทียม ที่คุณส่งมารอบนี้ไม่พอนะ เพราะฉะนั้นคุณยังติดเราอยู่อีก 327 ไนท์เทียม เราทำบัญชีให้คุณโรซ่าจากทะเลทรายเรดีเซลไว้เพื่อบันทึกการชำระเงินและค่าใช้จ่ายโดยเฉพาะ พ่อฉันคิดว่าเป็นแผนทำธุรกิจที่ดีที่สุด\nฉันเองก็สังเกตว่าเหล็กพิเศษในคำสั่งซื้อของคุณเป็นวัสดุสำคัญในการทำขาเทียม โปรดบอกฉันทีว่าคุณไม่ได้ทำให้ตัวเองใช้\n\nขอแสดงความนับถือ\nมินนี่และแม็กซ์\nเขียนก่อนวันปีใหม่",
  str_dispatch_book_chaptercont_14000_3 = "เรียน มินนี่และคุณแม็กซ์\nวัสดุเหล็กที่คุณส่งให้ฉันช่วยฉันได้อย่างยิ่ง ฉันต้องบอกเด็กผู้หญิงบางคนอย่างน่าเสียดายว่าฉันทำขาเทียมมาใช้เองจริง ๆ แคมป์ของเราถูกอิคลิพไซท์โจมตีเมื่อไม่กี่เดือนก่อน ในระหว่างการต่อสู้ ฉันได้รับบาดเจ็บที่ขาเล็กน้อยซึ่งมันติดตัวฉันและไม่สามารถรักษาได้ ฉันต้องเดินกะโผลกกะเผลก และการที่จะกลับไปขับรถได้คงเป็นแค่ฝัน แต่ตอนนี้ฉันทำเหล็กพยุงขาจากพัสดุของคุณได้แล้ว\nสภาพความเป็นอยู่ของเราในทะเลทรายเรดีเซลไม่ได้ดีไปกว่าตอนอยู่ในดินแดนลับเท่าไรนัก เราถูกส่งไปเป็นหน่วยแนวหน้าเพื่อสำรวจดินแดนลับ ถึงภารกิจจะยากลำบากแต่ก็น่าภูมิใจสุด ๆ แต่ตอนนี้น่ะเหรอ ฉันไม่อยากพูดถึงเจ้าหน้าที่ระดับสูงเฮงซวยที่แสนใจดำพวกนั้นหรอก แม้เราจะมีอิสระในทะเลทรายเรดีเซล แต่ก็ต้องแลกมาด้วยอาหาร เวลานอน และความมั่นคง\nสิ่งที่แย่ที่สุดในทะเลทรายเรดีเซลก็คือสภาพอากาศของที่นี่ คุณต้องหลบแดดแผดเผาอยู่ใต้ดิน นอกเสียจากว่าจะอยู่ในโอเอซิสหรือบริเวณขอบทะเลทราย หลังตอนพลบค่ำ คุณต้องห่มผ้าที่หนาที่สุดเพื่อไม่ให้เลือดและไขกระดูกแข็งตัว เรามีประสบการณ์อยู่ในทะเลทรายเพียงเล็กน้อย รถเป่าลมของเราก็เสียหายอย่างหนักตอนมาถึงที่นี่ครั้งแรก ฉันต้องเปลี่ยนอะไหล่ทั้งหมด พวกอิคลิพไซท์ที่เพ่นพ่านไปมาก็ทำฉันแทบบ้า ฉันต้องการส่วนประกอบพลังงานอีกเพื่ออัปเกรดระบบป้องกัน ฉันทำรายการไว้ที่ด้านหลังของจดหมายฉบับนี้เหมือนคราวก่อน และแนบภาพร่างแบบดัดแปลงรถเป่าลมไว้ด้วย ฉันคิดว่ามันอาจช่วยให้มินนี่เกิดแรงบันดาลใจขึ้นมาได้\nฉันเสียใจมาก แต่เงินทุนของเราใกล้จะหมดแล้ว ฉันไม่สามารถชำระหนี้ครั้งนี้ได้ ขอเวลาเพิ่มอีกสักวันสองวันได้ไหม ขอให้คุณมีวันที่ดี\n\nขอแสดงความนับถือ\nโรซ่า\nเขียนตอนเช้าตรู่",
  str_dispatch_book_chaptercont_14000_4 = "เรียน เลดี้โรซ่า:\nเราเห็นใจกับสถานการณ์ของคุณ คุณสามารถชำระหนี้ครั้งก่อนตอนส่งคำสั่งซื้อถัดไปมาก็ได้ อีกอย่าง แผนผังดัดแปลงยานโฮเวอร์คราฟต์ที่ส่งมานั้นมีค่ามาก และฉันก็เชื่อว่ามันมีค่าพอที่จะชดเชยหนี้บางส่วนได้\nขอให้สุขภาพดีและร่ำรวยมั่งคั่ง\n\nขอแสดงความนับถือ \nร้านอะไหล่ M&M\nในฤดูใบไม้ผลิ\n\n\nปล.:\nโรซ่า นี่มินนี่นะ\nฉันอยากรู้ว่าขาคุณหายดีรึยังในตอนนี้... โอ๊ะ ช่างเป็นการทักทายที่กลวงโบ๋ ไม่สื่อถึงความจริงใจและเป็นเพียงแค่ลมปากเสียจริง แต่ฉันก็หวังให้คุณหายดีจริง ๆ นะ\nคุณเคยบอกในจดหมายฉบับก่อน ๆ ว่าคุณเคยทำงานให้กับอิลลูมินา ซึ่งก็น่าตกใจอยู่นะ เพราะพ่อกับฉันก็เคยเดาว่าคุณเป็นใครมาจากไหน ฉันได้พบกับคนที่มาจากทะเลทรายเรดีเซล แม้ว่าพวกเขาจะสนใจการปรับแต่งเครื่องยนต์ แต่ก็ดูเป็นมือสมัครเล่นไปเลยเมื่อเทียบกับฝีมือของคุณ ในตอนนี้ปริศนาก็ไขกระจ่างแล้วด้วยจดหมายของคุณ และก็เป็นเรื่องยากที่ฉันจะสื่อหรืออธิบายให้คุณเข้าใจว่าฉันตื่นเต้นเพียงใดนอกจากคำว่า \"\"แน่นอน!\"\" เป็นเกียรติอย่างยิ่งที่คุณไว้วางใจเราและเราจะไม่ทำให้คุณผิดหวังหรือเปิดเผยตัวตนของคุณให้ใครรู้\nแบบการดัดแปลงที่คุณส่งมาเป็นอะไรที่มหัศจรรย์ยิ่ง! ฉันขอเดาว่าคุณตั้งใจที่จะเพิ่มความเสถียรให้กับยานเวลาลอยตัวและเพื่อไม่ให้ยานดูดเศษอะไรเข้าไปในห้องเครื่อง ฉันยังสังเกตอีกด้วยว่าตัวกำเนิดพลังงานเป็นระบบวนเวียนแบบใหม่ ฉันเลยตัดสินใจที่จะทำตามพิมพ์เขียวกับพ่อดู และติดตั้งบนรถบรรทุกเล็ก ๆ ดูว่ามันจะเป็นยังไง ไม่แน่นะ รถบรรทุกของเราอาจจะกลายเป็นยานจรวดก็ได้!",
  str_dispatch_book_chaptercont_14000_5 = "เรียน มินนี่และคุณแม็กซ์ที่เคารพ:\nโปรดรับเงิน 3,000 ไนท์เทียมที่ฉันแนบมาให้ ส่วนอีก 327 ที่ฉันติดไว้นั้น ฉันอยากจะขอซื้อส่วนประกอบเพิ่มเติม ซึ่งฉันได้เขียนรายการไว้ที่ด้านหลังของกระดาษใบนี้\nฉันอยากจะให้มินนี่ทราบเป็นอย่างยิ่งว่าฉันรู้สึกทราบซึ้งกับความคิดของเขาและเชื่อว่าเขาจริงใจ ขาของฉันกำลังหายดีนับตั้งแต่จดหมายที่เราเขียนให้กันครั้งล่าสุด และคงได้ถอดเหล็กดามขาเร็ว ๆ นี้ ฉันว่ามันคงเป็นเพราะคำอวยพรของพวกคุณแหละ อย่างไรก็ตาม ฉันยินดีเป็นอย่างยิ่งที่ได้รู้จักคุณ\nเพราะการต่อสู้ครั้งนั้น เราจึงมีวันที่ดีกว่าที่เคย ในทะเลทรายเรดีเซล เราต้องคอยระวังพวกโจรกับอิคลิพไซท์ที่ป้วนเปี้ยนอยู่ตลอด พวกนอกกฎหมายที่เนินทรายแห่งนี้มีจำนวนมากจนน่าประหลาดใจ ยิ่งผู้คนหมดหวังมากเท่าไร พวกเขาก็พร้อมที่จะผันตัวเป็นพวกนอกกฎหมายยิ่งขึ้นในทุก ๆ วัน แม้ว่าจะหมดหวังเพียงเพราะบ้านเรือนของพวกเขาถูกอิคลิพไซท์ทำลาย นอกจากการที่ต้องมาสู้กับพวกอิคลิพไซท์แล้ว การสู้กับเหล่าโจรก็เป็นส่วนหนึ่งในชีวิตประจำวันที่นี่เช่นกัน หลังจากนั้น เหยื่อจากการถูกทำลายบ้านรายใหม่ ๆ ก็เลือกที่จะเข้าร่วมกับเรา\nและนั่นคือสิ่งที่เกิดขึ้นกับเด็กผู้หญิงเมื่อไม่กี่วันก่อน กลุ่มพวกนอกกฎหมายบุกปล้นสะดมหมู่บ้านของเธอ มีแค่เธอคนเดียวที่หนีออกมาได้ ฉันไม่อยากเล่ารายละเอียดลึกกว่านี้ เพราะมันไม่ใช่เรื่องของฉันที่จะต้องสาธยายความโชคร้ายของคนอื่น... เธอก็คงไม่อยากให้ฉันรื้อฟื้นโศกนาฏกรรมที่เกิดขึ้นอยู่แล้ว ตอนแรกเธอก็ไม่อยากอยู่ที่นี่หรอก แต่กลับพยายามจ้างพวกเราให้ไปเอาคืนคนของเธอให้ ซึ่งเธอเสนอเครื่องจักรจากเทคโนโลยีโบราณขนานแท้ที่สามารถผลิตน้ำขึ้นมาได้อย่างดื้อ ๆ เป็นรางวัล เธอไม่คิดระแวงว่าเราจะโกง เนื่องจากเธอรู้ว่าจะสามารถหาเจ้าเครื่องจักรนี้ได้จากที่ไหนอีก เราแค่ต้องเอาหัวโจรมาแลกกับตำแหน่งที่เธอเจอเครื่องจักรพวกนี้ เอ้อ เด็กคนนี้ชื่อซัมเมอร์ ซึ่งตอนนี้เธอเข้าร่วมกลุ่มกับพวกเราแล้ว\nหลังจากการต่อสู้ในแหล่งกบดานของพวกโจรนั่น เราได้พบกับที่ซ่อนของมากมายที่เก็บไนท์เทียม ห้องใต้ดินที่เต็มไปด้วยไวน์ คลังเก็บปืนและระเบิด รถบรรทุกดัดแปลงอีกห้าคัน แต่ทั้งหมดทั้งมวลนี้เทียบไม่ได้เลยกับสิ่งที่ซัมเมอร์พาเราไปพบ... สิ่งประดิษฐ์จากเทคโนโลยีโบราณมากมาย ซึ่งฉันคิดว่าต้องรีบแยกชิ้นส่วนมันด้วยเครื่องมือที่เหมาะสม ไม่แน่จดหมายฉบับหน้าฉันอาจจะประกอบอุปกรณ์ที่สามารถแยกชิ้นส่วนได้อย่างละเอียดยิบ\n\nขอแสดงความนับถือ\nโรซ่า\nในยามบ่ายที่ร้อนอบอ้าว",
  str_dispatch_book_chaptercont_14000_6 = "เรียน เลดี้โรซ่า:\nรู้สึกเป็นเกียรติที่ได้รับคำสั่งซื้อจากคุณอีกครั้ง นอกจากนี้ฉันยังยินดีมากที่ได้ยินว่าขาคุณดีขึ้นแล้ว อย่างไรก็ดี ต้องขอโทษด้วยที่ต้องแจ้งให้คุณทราบว่าเราหาอุปกรณ์ที่คุณต้องการได้แค่ส่วนเดียวเท่านั้น เนื่องจากส่วนมากแล้วไม่มีผู้ใดรู้จักเลยและหาได้ยากในตลาดทั่วไปหรือในลานขยะ โปรดให้เวลาเราเพิ่มเติม ถ้าโชคดีเราอาจเจอสิ่งของในรายการของคุณที่การประมูล\n\nขอแสดงความนับถือ\nร้านอะไหล่ M&M\nในช่วงบ่ายของวันที่วุ่นวาย\n\n\nป.ล.:\nสวัสดีโรซ่า! ฉันเชื่อว่าในเวลาที่ฉันเขียนจดหมายอยู่นี้ ขาที่บาดเจ็บของคุณคงหายดีแล้ว ชีวิตในทะเลทรายเรดีเซลช่างไม่มั่นคงเอาเสียเลย หวังว่าคุณจะไม่เจ็บตัวอีกนะ\nฉันอยากเล่าให้ฟังจะแย่แล้วว่าช่วงนี้เกิดอะไรขึ้นบ้าง คุณรู้เรื่องการฉลองวันก่อตั้งลูโมโพลิสใช่ไหม สองสามวันก่อนที่จะเขียนจดหมายฉบับนี้ พ่ออนุญาตให้ฉันไปที่ลูโมโพลิสคนเดียวแล้ว ในวันก่อตั้ง ศุลกากรที่ท่าเรือจะใจดีกว่าปกติและนักท่องเที่ยวไม่ต้องส่งเอกสารขออนุญาตจากกระทรวงการต่างประเทศด้วย ฉันพักโรงแรมที่ลูโมโพลิสชั้นล่างอยู่สามวัน แล้วก็ไม่ได้กลับบ้านจนกระทั่งความสนุกสนานจบสิ้นลงเมื่อวานนี้ ถ้าคุณไปที่ลูโมโพลิสเมื่อไร อย่าลืมให้ฉันเป็นไกด์นำทางให้นะ ช่วงที่ฉันไปพัก ฉันเที่ยวในเมืองจนทะลุปรุโปร่งแล้ว เค้กร้านไหนอร่อยที่สุด ผลไม้ร้านไหนสดที่สุด ถ้าอยากชมแท่นบูชาในสวนลูโมโพลิสต้องไปที่ไหน ฉันหาข้อมูลไว้หมดแล้ว ในงานฉลองมีทั้งขบวนแห่และดอกไม้ไฟ แต่ที่สำคัญที่สุดคือมีอาหารมากมายหลายประเภทให้ลิ้มลองได้ฟรีเลย ปกติฉันคิดว่าออโรเรียนในเมืองชอบทำตัวห่างเหินแล้วก็หยิ่งด้วย แต่ในวันก่อตั้งพวกเขายิ้มให้ทุกคน คอยอธิบายเรื่องการเฉลิมฉลองให้ใครฟังก็ได้ทั้งนั้น และถึงกับชวนไปชิมอาหารที่บ้านตัวเองด้วยนะ พวกเขาต้อนรับกับแบบสุดโต่งมาก ไม่เหลือท่าทีที่ไม่น่าคบหาเลยสักนิด ฉันอยากให้ทุกวันเป็นวันก่อตั้งจังเลย\nเอ้อ นอกจากอุปกรณ์ที่พ่อหามาให้คุณได้แล้ว ยังมีของพิเศษจากท้องถิ่นจากลูโมโพลิสอยู่ในกล่องด้วยนะ ฉันเลือกเฉพาะของที่อยู่ได้นาน ๆ ดังนั้นไม่ต้องห่วงว่ามันจะหมดอายุกลางทาง นอกจากนี้ยังมีเจ้าลิงหุ่นเชิดสวมหมวกแดงให้คุณด้วย ลูกชายเจ้าของโรงแรมให้มาเป็นของขวัญ ฉันได้เที่ยวงานฉลองกับเขาอยู่นานเลย ฉันได้หุ่นเชิดมาสองตัว ฉันเก็บไว้เองตัวนึง อีกตัวนึงฉันให้คุณนะ เก็บรักษาให้ดีล่ะ",
  str_dispatch_book_chaptercont_14000_7 = "เรียน มินนี่และคุณแม็กซ์ที่เคารพ:\nฉันได้รับอุปกรณ์ที่คุณส่งมาแล้ว และของเหล่านั้นช่วยให้งานวิจัยของฉันรวดเร็วขึ้นอย่างมาก ของบางอย่างในรายการ ฉันเคยเห็นแค่ที่อิลลูมินาเท่านั้น จึงไม่แปลกที่หาที่อื่นไม่ได้ แต่ฉันก็ไม่ได้มุ่งมั่นอะไรมาก ถ้าดูราคาประมูลแล้วไม่มีทางไปต่อ ก็ช่างมันเถอะ\nที่ฉันเขียนจดหมายมาคราวนี้ก็เพื่อจะถามว่าคุณพอจะหากีตาร์เก่า ๆ กับลำโพงให้ฉันได้บ้างไหม มีคนในทีมของเราเกิดคลั่งร็อกแอนด์โรลขึ้นมาในทะเลทรายเรดีเซล และอีกเดือนเดียวก็จะถึงวันเกิดเธอแล้ว ฉันอยากเอากีตาร์มาปรับปรุงให้เธอ จะได้เลิกเอาสายไฟของฉันไปทำสายกีตาร์ซะที\nทะเลทรายไม่เคยขาดแคลนนักดนตรี และทีมงานของเรายิ่งมีดีจะอวดเยอะเลย พวกเขาด้นสดได้เสมอ ทุกครั้งที่มา ฉันจะได้ยินเสียงมากมายหลายประเภท เสียงเคาะขวดหรือถังน้ำมันเป็นจังหวะกลอง เสียงนิ้วดีดฝาขวด เสียงผิวปาก ฯลฯ... แทบหาความเงียบสงบไม่ได้เลย พวกเขาชอบแต่งเพลงกันด้วยนะ เอาสีกระป๋องมาพ่นเนื้อเพลงกับโน้ตกันเต็มกำแพงเลย ถ้าคุณชอบเพลงร็อกด้วยเหมือนกัน ฉันอัดเพลงให้ฟังสองสามเพลงได้นะ\nฉันได้รับลิงหุ่นเชิดจากคุณแล้วนะมินนี่ ตอนนี้ฉันเอาไว้ที่กระจกหน้าของโฮเวอร์คราฟต์นี่เลย ฉันตกใจมากที่คุณไปเที่ยวงานฉลองกับคนแปลกหน้า ไม่เหมือนนิสัยคุณเลยสักนิด ว่าแล้วก็ถามหน่อย คุณนี่โตพอที่จะมีแฟนหรือยังนะ ล้อเล่น ๆ เกือบลืมบอกคุณไปเลย ซัมเมอร์ชอบสโคนกับแยมที่คุณส่งมามากเลย ส่วนฉันน่ะชอบลูกเกดกับชีส พยายามทำตัวให้ชินกับอาหารแถบทะเลทรายนี่มันยากนะ ฉันเนี่ยขย้อนหนอนทรายดองไปไม่รู้กี่ตัวแล้ว ขนมที่คุณส่งมาคืนชีวิตให้ปุ่มรับรสของฉันเลยแหละ\n\nขอแสดงความนับถือ\nโรซ่า\nกำลังพักเบรกช่วงบ่ายหลังจากกินอาหารจนอิ่มแปล้",
  str_dispatch_book_chaptercont_14000_8 = "เรียน มินนี่และคุณแม็กซ์ที่เคารพ:\nรอบนี้ฉันต้องการวัตถุดิบจำนวนมากเพื่อนำมาทำอวัยวะเทียม ขออภัยด้วย แต่ยาแก้ปวดเพิ่งหมดฤทธิ์ไปและฉันควบคุมมือไม้ที่สั่นไม่ได้ ถ้าคุณแกะลายมือที่ด้านหลังของกระดาษแผ่นนี้ไม่ออกก็ไปดูรายการของเมื่อสามปีก่อนนะ\nฉันไม่เคยคิดเลยว่าพวกเขาจะทำอย่างนี้ และไม่คิดด้วยว่าตัวเองจะเข้าร่วมกับพวกเขาด้วย ฉันอธิบายความรู้สึกที่มีต่ออิลลูมินาออกมาเป็นคำพูดไม่ได้ ฉันเคยอยู่ที่นั่นตั้ง 20 กว่าปี มีเพื่อนและคนรู้จักในทุกกรมกอง ฉันเคยเรียกแกนน่อนว่า \"\"มาตุภูมิ\"\" พวกเขาไล่ฉันออกมาแบบไม่ไว้หน้าด้วยปืนและความเฉยชาไม่แยแส แต่ฉันไม่เคยคิดเลยว่าจะหันปากกระบอกปืนใส่พวกเขา คุณอาจคิดว่าความภักดีเป็นเรื่องโง่เขลา แต่ยังไงซะ มีลูกที่ไหนหนีออกมาแล้วเล็งปืนใส่แม่ตัวเองได้ล่ะ\nฉันไม่รู้ว่าจะมีป้ายประกาศจับจากอิลลูมินาไปติดตามกำแพงที่อัมบราตันรึเปล่า แต่ถ้าคุณได้ยินข่าวลือ มันคือเรื่องจริง เราปล้นพาหนะขนส่งอิลลูมินา พลขับหกคน ผู้คุ้มกันยี่สิบคน ไม่มีผู้รอดชีวิต พวกเรากลัว และฉันละอายที่จะใช้คำนั้น ราวกับว่านั่นทำให้การกระทำดังกล่าวเป็นเรื่องชอบธรรมขึ้นมาได้ ฉันอธิบายอารมณ์ความรู้สึกของฉันไม่ถูก ความกลัวเข้าครอบงำเราเหมือนปีศาจ กระตุ้นให้เราลั่นไกเข้าใส่ผู้บริสุทธิ์ได้ไม่หยุด ปลอกกระสุนเปล่า ๆ ร่วงกราวลงสู่พื้นแล้วก็จมลงในผืนทราย เราหยุดไม่ได้... มันเป็นไปถึงขนาดนั้นได้ยังไง\nฉันยอมรับว่าเราไปแหย่พวกนั้นก่อน แต่ไม่มีใครคิดว่าจะเกิดการสังหารหมู่ตามมา ตอนแรกก็แค่แกล้งกันเฉย ๆ ฉันจำไม่ได้ว่าลงมือยิงกันนัดแรกเมื่อไร แต่รู้ตัวอีกทีก็มีเลือดเต็มไปหมด แล้วก็ไหลลงสู่ผืนทราย แขนขวาของฉันไหม้เกือบทั้งหมด น่องข้างซ้ายเกรียมเพราะลูมินาติกส์ และหัวเข่าขวาก็แหลกเพราะกระสุนปืนหลายนัด ฉันตื่นขึ้นมาหลังการผ่าตัด ขาขวาถูกตัดออกไปครึ่งท่อน ส่วนขาซ้ายถูกตัดขึ้นมาถึงใต้หัวเข่า มันคือการลงโทษสำหรับความทรยศของฉัน รวมทั้งเหตุสังหารโหดด้วย ฉันชดใช้ให้กับความผิดพลาดของตัวเองไปมหาศาลแล้ว แต่ไม่อยากต้องนอนติดเตียง อภัยให้ฉันด้วย และฉันเข้าใจถ้าคุณมองว่าขาเทียมเป็นการหลีกเลี่ยงการลงโทษที่เจ้าเล่ห์มาก\nฉันต้องจบจดหมายฉบับนี้ไว้แค่นี้ก่อน ความเจ็บปวดมันสาหัสเหลือเกิน คุณคงอ่านไม่รู้เรื่องถ้าฉันยังเขียนต่อไป\n\nโรซ่า",
  str_dispatch_book_chaptercont_14000_9 = "โรซ่าที่รัก:\nคุณหายดีแล้วหรือยัง หลังจากผ่านมาหลายปี ในที่สุดฉันก็บอกคุณได้แล้วว่าเวลาที่ฉันได้จดหมายจากคุณ ฉันร้องไห้ใต้ผ้าห่มอยู่เป็นนานเลย ถึงกับคิดจะชวนให้คุณย้ายออกจากทะเลทรายมาอยู่เป็นเพื่อนบ้านกันที่อัมบราตันนี่ด้วย แต่จดหมายฉบับต่อ ๆ มาของคุณไม่ได้เขียนด้วยความเจ็บปวดในแบบเดิม แต่เป็นเรื่องปรับปรุงซ่อมแซมสิ่งของ เรื่องดนตรี แล้วก็เรื่องขนมกลับมาเหมือนเมื่อก่อน ฉันเลยเชื่อว่าคุณดีขึ้นเรื่อย ๆ และถึงกับพยายามหลีกเลี่ยงคำถามประเภท \"\"สุขภาพเป็นยังไงบ้าง\"\" เสียด้วย ฉันยอมรับว่าวันนี้ฉันดื่มมากไปหน่อย เพราะงั้นถ้าฉันเขียนอะไรโง่ ๆ ก็กรุณาอย่าแซวฉันเลยนะ\nฉันดื่มเพราะว่าฉันหมั้นแล้ว อะไรก็ตามที่คุณคาดเดาเรื่องฉันกับลูกชายเจ้าของโรงแรมที่ลูโมโพลิส ฉันบอกได้เลยว่าไม่มีอะไรเกิดขึ้น แม้เราจะแลกที่อยู่กันไว้และระหว่างอัมบราตันกับลูโมโพลิสก็ส่งจดหมายได้ง่าย ๆ แต่เราก็ไม่เคยเขียนจดหมายถึงกัน ยังไงก็เลิกล้อฉันเรื่องตาคนนั้นได้แล้วนะ ฉันรู้จักกับคู่หมั้นมาตั้งแต่เด็กแล้ว เขาไปเรียนต่างประเทศมานานและกลับมาพร้อมกับทักษะแปลก ๆ แล้วตอนนี้ก็ทำงานฝ่ายขายให้กับกิลด์แห่งหนึ่ง พ่อฉันดูแล้วว่าเขาก็ค่อนข้างปกติดี\nฉันอ่านนิยายรักมามาก แล้วก็วาดภาพตัวเองได้แต่งงาน แต่ฉันก็อดกังวลไม่ได้กับชีวิตคู่ที่กำลังจะมาถึง เหมือนฉันติดอยู่ระหว่างกำแพงสองฝั่ง หายใจไม่ออก ชีวิตที่อัมบราตันผกผันไม่แน่นอน วันหนึ่งแต่งตัวมอซอไปหลบฝนในตรอกเล็ก ๆ อีกวันอาจได้สวมแหวนเพชรนั่งบัลลังก์ทองคำก็ได้ แต่สำหรับบางคนอย่างเช่นฉันกับพ่อ ชีวิตของเราว่างเปล่า ไม่ได้มีอะไรมากไปกว่ากิน นอน พูดคุย ทำงาน แต่งงาน มีลูก แล้วก็ตาย ดังนั้นนี่คือกิจกรรมอีกอย่างหนึ่งที่คาดการณ์ไว้แล้ว เป็นอีกก้าวหนึ่งบนเส้นทางแห่งชะตาชีวิตของฉัน\nทั้งหมดนี้อาจฟังดูหดหู่ แต่การหมั้นหมายควรเป็นกิจกรรมแห่งความสุข ดังนั้นฉันไม่ควรเศร้าเรื่องนั้น งานแต่งงานจะจัดขึ้นในอีกสองเดือน ฉันออกแบบบัตรเชิญเองเลยนะ และฉันจะเขียนชื่อคุณลงในใบแรกเลย คุณจะถือการ์ดนั่นมาร่วมงานแต่งงานของฉันใช่ไหม?\n\nขอแสดงความนับถือ\nมินนี่\nท่ามกลางดวงอาทิตย์ตกที่เงียบงัน",
  str_dispatch_book_chaptercont_14000_10 = "มินนี่ที่รัก:\nข่าวงานแต่งงานของคุณทำให้ฉันรู้สึกไปต่าง ๆ นานา โปรดอย่าคิดว่าฉันไม่เห็นชอบด้วยเลยนะ ฉันแค่หดหู่นิดหน่อย เพราะคุณเอาไปเปรียบเทียบเป็น \"อีกก้าวหนึ่งบนเส้นทางแห่งชะตาชีวิต\" ฉันเองก็รู้สึกอย่างนั้นเหมือนกัน เว้นแต่ว่าฉันมองดูคุณก้าวเดินจากที่ไกล ฉันไปร่วมงานแต่งงานของเพื่อน ๆ ตอนอยู่ที่แกนน่อน ดูพวกเขาออกมาจากโบสถ์ท่ามกลางดอกไม้และริบบิ้น ขณะที่ประตูสู่ชีวิตใหม่เปิดออกให้พวกเขา ส่วนฉันเองก็อยู่รั้งท้าย... อย่างน้อยนั่นก็ไม่ใช่ความรู้สึกที่ดีเลย\nถ้าเป็นเมื่อก่อนฉันคงตัดสินใจไปทันที แต่ว่าตอนนี้... ขอโทษทีที่ฉันไม่ได้บอกคุณก่อนหน้านี้ แต่ฉันต้องขับรถ ก็เลยเชื่อมขาเทียมเข้ากับที่นั่งคนขับ จึงยากมากสำหรับฉันที่จะเดินเหินบนพื้น แล้วก็ขอโทษด้วยนะที่ฉันเห็นแก่ตัว แต่ฉันไม่อยากให้คุณเห็นฉันแบบนี้\nฉันทำช่อกุหลาบโลหะให้คุณนะ คุณจะได้กลิ่นเรดีเซลแน่นอน เวลาบิดก้าน กลีบดอกจะบานและหุบได้ด้วย ฉันอาจจะแก่เกินไปที่จะทำตัวโรแมนติกแล้วก็ได้ แต่ฉันคิดว่าดอกกุหลาบไม่มีวันเชยหรอก หวังว่าคุณจะชอบดอกไม้ที่คงทนนะ แล้วชีวิตของคุณก็จะปราศจากความกังวลเช่นกัน อย่างน้อยก็ทนฝนทนพายุแล้วกันแหละ\nคุณออกแบบบัตรเชิญได้น่ารักมาก ฉันชอบลวดลายข้างหลังมากเลย บอกหน่อยซิ คุณได้เอาแผนผังที่ฉันส่งให้ไปใช้ประโยชน์หรือเปล่า\n\nขอแสดงความนับถือ\nโรซ่า\nในช่วงค่ำที่สงบเงียบ",
  str_dispatch_book_chaptercont_14000_11 = "เรียนคุณแม็กซ์และคุณมินนี่:\nฉันขออนุญาตกล่าวสวัสดีด้วยความจริงใจ ฉันชื่อซัมเมอร์ เป็นผู้ช่วยของคุณโรซ่า ฉันมีข่าวร้ายมาแจ้งให้ทราบค่ะ เมื่อสองสามวันก่อน ขบวนขนส่งของเราโดนอิคลิพไซท์โจมตี และเพื่อป้องกันทีมงาน คุณโรซ่าจึงระเบิดโฮเวอร์คราฟต์เพื่อหยุดยั้งผู้โจมตี ซึ่งนั่นหมายความว่าตอนนี้เธอไม่อยู่กับเราอีกต่อไปแล้วค่ะ\nหลังจากที่เธอต้องตัดขาสองข้าง ฉันเป็นคนคอยรับส่งจดหมายจากสหภาพผู้ส่งสารให้เธอ ฉันจึงคิดว่าฉันควรส่งข่าวมาบอกคุณด้วย ฉันไม่แน่ใจว่าคุณโรซ่าคุยเรื่องนี้กับคุณหรือเปล่า แต่เธอเคยบอกว่าถ้าเกิดอะไรขึ้นกับเธอ เธอจะยกไนท์เทียมที่เหลืออยู่กับร้านอะไหล่ M&M ให้คุณมินนี่ ฉันจะส่งเอกสารทางกฎหมายที่คุณต้องใช้ไปให้โดยเร็วที่สุดนะคะ\nคุณโรซ่าพูดถึงคุณให้ฉันฟังบ่อย ๆ อะไหล่ของคุณช่วยเราได้มากทีเดียว ทั้งปรับแต่งโฮเวอร์คราฟต์ เครื่องดนตรีของทีมงาน ขาเทียมของคุณโรซ่า... อุปกรณ์ของคุณมีประโยชน์หลากหลายมากที่นี่ ทุกคนในค่ายก็เลยรู้ว่ามีคนขายอะไหล่มือสองในอัมบราตันที่ซื่อสัตย์ ไว้ใจได้ แล้วก็เป็นเพื่อนกับคุณโรซ่าเสียด้วย\nการจากไปของคุณโรซ่าเป็นความสูญเสียอันยิ่งใหญ่ของเรา เธอคอยช่วยเหลือผู้ที่ลำบากเสมอและไม่เคยลืมคำมั่นสัญญาที่ให้ไว้กับใคร เธอเป็นเซียนเรื่องเทคโนโลยีที่สร้างอะไรขึ้นมาได้ตามต้องการ แค่มีแผ่นโลหะ สกรู แล้วก็ประแจเท่านั้น ฉันฝึกงานกับเธอมาตั้งแต่อายุสิบสาม หัดถอดประกอบแล้วก็ปรับแต่งโน่นนี่กับเธอ เธอไม่เคยแต่งงานแล้วก็ไม่มีลูก แต่เธอก็เป็นเสมือนแม่สำหรับฉัน เนื่องจากเธอพูดคุยกับคุณทางจดหมายมาหลายปี ฉันคิดว่าเธอคงไม่อยากให้เขียนอะไรสั้น ๆ ฉันจึงเขียนจดหมายฉบับนี้ส่งมาแทนเธอ หวังว่าคุณคงไม่ว่าอะไรที่ฉันถือวิสาสะ\n\nขอแสดงความนับถือ\nซัมเมอร์\nเช้าวันที่พายุกำลังพัดเข้ามาใกล้",
  str_dispatch_book_chaptercont_14000_12 = "เรียนคุณซัมเมอร์:\nขอบคุณมากค่ะที่แจ้งข่าวมา\nฉันกับพ่อเสียใจมากที่โรซ่าจากไป พ่อได้จดหมายจากคุณก่อนเพราะฉันไม่ได้ไปที่ร้านนานแล้ว ครั้งหนึ่งร้านอะไหล่ M&M เคยจะต้องปิดตัว แต่ก็อยู่มาได้เพราะมีคำสั่งซื้อจากคุณโรซ่า ตอนนี้เราไม่ได้ทำอาชีพขายอะไหล่มือสองกันแล้ว แต่ยังเปิดร้านได้อยู่เพราะมีลูกค้าเจ้าประจำเก่าแก่ส่งจดหมายมาสั่งของอยู่บ้างเป็นครั้งคราว\nมันผ่านมานานเหลือเกินจนฉันจำไม่ได้แล้วว่าเราเริ่มส่งจดหมายคุยกันได้ยังไง ฉันคิดว่าเป็นเพราะเราได้รับจดหมายที่ค่อนข้างน่าสนใจจนต้องรีบตอบกลับทันที ซึ่งก็ตามมาด้วยจดหมายตอบรับที่แสดงถึงไมตรีจิต เพราะเหตุนั้นฉันจึงได้เพื่อนที่ดียิ่ง เธอชอบส่งแผนผังมาให้ฉัน เล่าตำนานทะเลทรายเรดีเซลและความลับทุกอย่างที่เกิดขึ้นในชีวิตของเธอให้ฉันฟัง ก่อนฉันแต่งงาน ในจดหมายที่เธอส่งมาพร้อมกับดอกกุหลาบโลหะ เธอเขียนว่าเพื่อน ๆ ของเธอที่แต่งงานไปต่างก็เปิดประตูสู่ชีวิตใหม่และทิ้งเธอไว้เบื้องหลัง ฉันคิดว่าเธอกำลังบ่น จนในที่สุดฉันก็เข้าใจความรู้สึกของเธอในเวลาต่อมา เธอเสียใจที่ยืนนิ่งเฉย แต่ฉันเองเหมือนจะถูกขังอยู่ในประตูที่เดินเข้าไป\nจนถึงตอนนี้เธอก็ยังคงเป็น \"\"เพื่อนที่ยอดเยี่ยม\"\" เธอเคยเห็นความตาย ต้อนรับชีวิตใหม่ มีแรงผลักดันที่จะช่วยผู้อื่นเสมอ และสามารถเลือกเส้นทางที่กล้าหาญเกินคาดหวังได้ตลอดเวลาในการเสียสละตัวเองเพื่อผู้อื่น\nตลอดเวลาที่ผ่านมา ฉันตั้งคำถามมากกว่าหนึ่งครั้งว่าที่จริงแล้วโรซ่ามีตัวตนอยู่จริงหรือเป็นแค่จินตนาการของฉัน เพราะเราไม่เคยเจอกันและเธอก็ไม่ได้มาร่วมงานแต่งงานของฉัน ตอนนี้ฉันอยากให้ทุกอย่างเป็นแค่เรื่องเพ้อฝัน อย่างน้อยฉันจะได้ชุบชีวิตเธอขึ้นมาในใจของฉันได้ แต่ก็ไร้ประโยชน์ เพราะดอกกุหลาบโลหะที่เธอส่งมาให้ยังคอยเตือนความจำฉันอยู่ที่หัวเตียง และแผนผังทั้งหมดที่เธอส่งมาก็อยู่ในสมุดบันทึกของฉัน\nก่อนที่ฉันจะเขียนจดหมายฉบับนี้ ฉันขอให้คาราวานไปส่งตอนที่พวกเขาจะออกไปยังทะเลทราย อีกไม่นานฉันคงได้พบกับคุณ ขอให้คุณประสบพบเจอแต่สิ่งที่ดีงามนะคะ\n\nขอแสดงความนับถือ\nมินนี่\nในคืนที่เงียบงัน",
  str_dispatch_book_chaptercont_15000_1 = "ใครก็ตามที่ไปที่ Umbraton จะต้องก้าวเข้าสู่เวทีการต่อสู้ที่เรียกว่า \"The Pit\" อย่างหลีกเลี่ยงไม่ได้เพื่อชมการต่อสู้ที่รุนแรงที่เกิดขึ้นที่นั่นอย่างน้อยหนึ่งรอบ โซ่เหล็กที่มีน้ำหนักหลายพันปอนด์ถูกผูกไว้กับขอบเวทีและดึงให้แน่น เพื่อให้เวทีพร้อมผู้คนและสิ่งของทั้งหมดถูกแขวนไว้ใต้แสงไฟ ผู้ชมถูกจัดให้อยู่ในวงกลมสูงขึ้นเรื่อยๆ ก่อตัวเป็นชั้นโค้งขึ้นไปรอบๆ เวที เหล่าขุนนางชอบฝึกฝนนักสู้และนำพวกเขาเข้าสู่สนามประลองเพื่อต่อสู้กันเอง หากนักสู้โผล่ออกมาจากค่ำคืนนี้ทั้งเป็นและมีชัยชนะมากที่สุด พวกเขาจะได้รับสิทธิ์ในการสวมเข็มขัดทองคำของแชมป์เปี้ยนเที่ยงคืน อย่างไรก็ตาม เข็มขัดนี้สามารถสวมใส่ได้เพียงครั้งเดียวในตอนกลางวัน และต้องนำมาคืนเมื่อเปิด Pit ในคืนถัดไป เมื่อการต่อสู้ดุเดือดขึ้น ผู้ชมจะโห่ร้องด้วยความตื่นเต้น บางคนถึงขั้นโยนเหรียญทองขึ้นไปบนเวที จนกระทั่งเสียงเหรียญที่ตกลงมาจากด้านบนเต็มเวที ฉันอยู่ในอารีน่าจนถึงรุ่งสาง เมื่อบรรยากาศไม่ตึงเครียด ในเวลานั้นผู้ชมที่เหนื่อยล้าก็แยกย้ายกันไปและผู้คนก็ออกมาเพื่อล้างเลือดออกจากเวที น้ำถูกเทลงบนแท่นหิน ทำให้ม่านน้ำสีแดงซีดไหลออกจากขอบ คนรับใช้ที่อุทิศตนโกยเหรียญทองออกจากเวที ทำความสะอาดด้วยน้ำเพื่อขจัดเลือดและฝุ่นออก แล้วใส่ไว้ในหีบดีบุก ชายสองคนหามหีบแล้วนำไปมอบให้กับผู้ชนะ\nหนึ่งในการต่อสู้ที่ดีที่สุดที่ฉันเคยเห็นเกิดขึ้นเมื่อสามปีที่แล้ว หนึ่งในนักสู้คือแชมป์เมื่อไม่กี่วันที่ผ่านมา มีข้อยกเว้นสำหรับเขาที่จะสวมเข็มขัดของ Midnight Champion ไปที่เวที เขาสวมเขาสีบรอนซ์แวววาวสองเขาบนหน้าผากของเขา และกล้ามเนื้อที่ปูดโปนของเขาภายใต้ผิวหนังที่ดำคล้ำของเขาเป็นคลื่นเหมือนคลื่น คู่ต่อสู้ของเขาคือชายร่างเล็กที่ห่อด้วยเสื้อผ้าสกปรกและมีรอยฟกช้ำทั่วตัว ดูเหมือนเขาจะได้รับบาดเจ็บสาหัสก่อนที่จะเดินขึ้นไปบนเวที เมื่อทั้งสองยืนอยู่บนเวทีด้วยกัน ผู้ชมก็เริ่มโห่ ผู้ดูแลคนหนึ่งเดินไปท่ามกลางผู้ชมพร้อมถาดสำหรับแขกที่จะวางเดิมพัน เมื่อเขามาหาเพื่อนของฉันที่ชวนฉันมา เธอเอาเงินทั้งหมดของเธอไปให้ชายตัวเล็กกว่า ฉันประหลาดใจมากและถามเธอว่าทำไมเธอถึงทำอย่างนั้น เธอหยิบกล้องส่องทางไกลและชี้ไปที่ชายคนนั้นและพูดว่า \"ชายคนนั้นเป็นหนึ่งในคนของ Mrs. Red Mercury\"\nแม้ว่าฉันจะไม่ได้มาที่ Umbraton บ่อยนัก แต่ฉันเคยได้ยินเรื่องเล่าเกี่ยวกับ Mrs. Red Mercury Umbraton รุ่งเรืองจากการลักลอบขนของทุกชนิด ที่อันตรายที่สุดคือการลักลอบขนอาวุธ หากการค้าไปได้ดีอาจได้รับโชค แต่ถ้าไม่ อาจทำให้คุณต้องเสียชีวิต อย่างไรก็ตาม ไม่ว่าจะเป็นธุรกรรมส่วนตัว การประมูลลับ หรือการได้มาจำนวนมาก การค้าเกือบทั้งหมดอยู่ในมือของกิลด์เดียว และหัวหน้ากิลด์นั้นคือ Mrs. Red Mercury ฉันเห็นคนสองคนต่อสู้กัน แชมป์มิดไนท์ชกหนัก เขาใช้ Luminatics ทุบพื้น ส่งเศษขยะปลิวว่อนไปทั่ว คนตัวเล็กสะดุดหลบซ้ายขวา ครั้งหนึ่งเขาโดนเศษชิ้นส่วนล้มลงกับพื้น มีเพียงการกลิ้งไปด้านข้างอย่างรวดเร็วเท่านั้นที่ทำให้เขารอดจากการถูกโจมตีอีกครั้ง\n“คุณนาย Red Mercury ไม่สนใจหรือว่าผู้ใต้บังคับบัญชาของเธอกำลังต่อสู้กันอย่างเอาเป็นเอาตาย” ฉันอดไม่ได้ที่จะถามเพื่อน\nเพื่อนของฉันส่ายหัวและมองไปที่ความมืดในมุม “เธออยู่ที่นี่ ดูสิ” เธอกระซิบ",
  str_dispatch_book_chaptercont_15000_2 = "ลำแสงสีขาวที่ร้อนและแห้งส่องไปที่วงแหวน ผู้ชมซึ่งถูกทิ้งไว้ในเงามืดกำลังปล่อยคลื่นยักษ์ตะโกนเข้าหาศูนย์กลาง ผมเดินตามสายตาของเพื่อนเข้าไปในความมืด ทันใดนั้นก็พบว่าจุดที่เธอมองอยู่นั้นเงียบสงัด นักสู้ชุดดำกลุ่มหนึ่งยืนอย่างเคร่งขรึม และที่หัวใจที่สุดก็มีคนนั่งอยู่ อย่างไรก็ตาม เงาหนาเกินกว่าที่ฉันจะมองเห็นรูปร่างหน้าตาและเสื้อผ้าของพวกเขาได้ ทั้งหมดที่ฉันเห็นคือจุดสีแดงสนิมตรงกลางสีดำทั้งหมด ในวงแหวนชายร่างเล็กสามารถขโมยการระเบิดใต้ซี่โครงของคู่ต่อสู้ได้ เกิดไฟลุกไหม้ขึ้นอย่างกะทันหัน และเสียงกรีดร้องของแชมป์เปี้ยนก็ดังไปทั่วอารีน่า ความตื่นเต้นพุ่งทะลุฝูงชน คนที่อยู่ข้างหลังฉันที่เดิมพันแชมป์เปี้ยนสบถเสียงต่ำ แต่มุมมืดยังคงเงียบ\nฉันไม่เข้าใจจริงๆ ฉันจึงถามเพื่อนอีกครั้ง “ทำไมคุณนายเรดเมอร์คิวรี่ถึงส่งผู้ใต้บังคับบัญชาของเธอเข้าไปในวงแหวน?”\nผู้คนใน Umbraton ไม่ได้มีนิสัยชอบเป็นนักสู้ และไม่เคยได้ยินมาก่อนที่หัวหน้ากิลด์จะใช้คนของพวกเขาเป็นของเล่น \n\"ชายคนนั้นเป็นคนทรยศที่ร่วมแผนการปล้นกิลด์ของตัวเอง\" เพื่อนของฉันกระซิบกลับมาหาฉัน\nฉันพิจารณาเรื่องนี้แล้วพูดว่า \"คุณเดิมพันแย่มาก ดูสิว่าเกิดอะไรขึ้นในสังเวียน คุณนาย Red Mercury ต้องการให้คนทรยศคนนี้ตายอย่างแน่นอน\"\nเพื่อนของฉันยิ้มและหยิบกล้องส่องทางไกลเพื่อดูการต่อสู้\nแชมป์เปี้ยนกำลังเดือดดาลหลังจากถูกชายตัวเล็กตบและก้าวไปข้างหน้าเพื่อพยายามคว้าตัวเขา เปลวไฟดูเหมือนจะทำให้แรงของคนตัวเล็กหมดไป เขาหลบแต่ช้ากว่าเดิม และถอยตรงไปที่ขอบเวที แชมป์เปี้ยนเห็นดังนั้นก็เหวี่ยงแขนไปที่ชายร่างเล็ก หมัดชกเข้าที่หน้าอกของเขาและทำให้เขาสะดุดออกจากเวที ผู้ชมต่างอ้าปากค้าง แต่ในไม่ช้าก็สังเกตเห็นว่าชายร่างเล็กจับโซ่เหล็กเส้นหนึ่งไว้เพื่อป้องกันไม่ให้ตัวเองหล่นลงมาจากเวที แชมป์เปี้ยนเตรียมชกครั้งที่สองต่อ แต่กรรมการเป่านกหวีดหมดเวลาครึ่งแรก เขาต้องถอนตัว ขณะที่คนตัวเล็กกระแอมไอ แล้วค่อยๆ คลานกลับเข้าไปในสังเวียน\nแสงสีขาวเจิดจ้าค่อยๆ เคลื่อนตัวออกจากเวที แล้วค่อยๆ หมุนมาส่องผู้ชมที่อยู่ตรงกลาง ทันใดนั้นมีการเคลื่อนไหวไม่ไกลจากส่วนของความมืดที่เราเคยสังเกตมาก่อน เชลยที่เปื้อนเลือดถูกผลักออกไป ศีรษะของเขาห้อยและมือของเขาถูกมัดไว้ข้างหลังเขา เขาคุกเข่าอย่างคดเคี้ยวบนเส้นแบ่งระหว่างแสงสว่างและความมืด ฉันตกใจมาก ทันใดนั้นฉันได้ยินเสียงตะโกนจากบนเวที ฉันหันไปมองที่ต้นเสียง ชายร่างเล็กซึ่งเมื่อครู่ยังหายใจหอบอยู่บนพื้น กำลังรีบวิ่งไปบนสังเวียน แต่ถูกหยุดโดยผู้ตัดสินและผู้เข้าร่วมประชุม คำสาปบิดเบี้ยวชุดหนึ่งออกมาจากมุมปากที่เปื้อนเลือดของเขา",
  str_dispatch_book_chaptercont_15000_3 = "เสียงนกหวีดดังขึ้นเป็นสัญญาณสิ้นสุดการพักครึ่ง คานกลับไปที่วงแหวนและเริ่มรอบใหม่ ฉันอดไม่ได้ที่จะมองไปที่เชลยที่นั่งคุกเข่าท่ามกลางผู้ชม เขาไม่ได้ส่งเสียงอะไร ศีรษะของเขาตกลงไป เลือดและเหงื่อไหลหยดจากปลายผม เมื่อผมหันไปมองที่อารีน่าอีกครั้ง สถานการณ์แตกต่างจากครึ่งแรกอย่างมาก\nเปลวไฟพุ่งออกมาจากแขนของชายร่างเล็ก และนิ้วที่ยื่นออกมาของเขาก็แดงเหมือนเหล็ก เขาเดินเข้าหาคู่ต่อสู้อย่างช้าๆ หินตกลงมาเหมือนห่าฝนในสนามประลอง แม้ว่าเขาจะยังตั้งรับอยู่ แต่เขาก็ไม่ดิ้นรนอีกต่อไป แม้จะโดนหินหลายก้อน แต่เขาก็ยังขยับเข้าใกล้คู่ต่อสู้ แชมป์เปี้ยนถูกบีบให้ถอยห่างจากเขา แต่ในที่สุด เขาก็ไม่สามารถหยุดไม่ให้เข้าใกล้ได้อีกต่อไป ทันใดนั้นเปลวไฟก็สว่างวาบและชายร่างเล็กก็จับข้อมือของฝ่ายตรงข้าม ควันลอยขึ้นและแชมป์เปี้ยนก็ร้องออกมาด้วยความเจ็บปวดและความโกรธ จากนั้น กำปั้นของชายร่างเล็กยื่นออกมาเหมือนตะขอยาวและฟาดเข้าที่ท้องของคู่ต่อสู้อย่างแรง มีการอ้าปากค้างบนอัฒจันทร์ของผู้ชม และใครบางคนที่อยู่ข้างหลังฉันลุกขึ้นยืนและตะโกนด้วยความโกรธขณะที่ผู้เข้าร่วมกระโจนเข้าสู่สังเวียนและลากชายร่างเล็กออกจากแชมป์เปี้ยน\nเมื่อชายร่างเล็กปรากฏตัวขึ้น นักสู้คู่ใหม่ก็เข้ามาในสนามประลองแล้ว คนตัวเล็กสวมชุดทักซิโด้ผูกโบว์ เขาสวมเสื้อชั้นในใหม่เช่นกัน แต่มันโชกไปด้วยเลือดแล้ว ฉันเหลือบมองเขาจากหางตาและเห็นว่าเขาตัวสั่นเล็กน้อย เขาคงยังช็อกจากการต่อสู้ที่รุนแรง\nมีคนเตะเชลยที่นั่งคุกเข่าอยู่ในความมืด และได้ยินเสียงทุ้มนุ่มถามคนทรยศว่า \"คุณรู้จักชื่อเขาไหม\"\nคนทรยศใช้ผ้าเช็ดหน้าเช็ดเลือดจากปากของเขาและพูดชื่อเล่นด้วยเสียงแหบพร่า บุคคลเจ้าของเสียงหัวเราะพร้อมเอ่ยชื่ออื่น “คุณไม่รู้แม้กระทั่งชื่อจริงของเขา แล้วคุณยังเลือกที่จะเชื่อใจเขาอยู่หรือเปล่า” เธอพูด.\nคนทรยศพยายามที่จะพูด “มาดามน้องสาวของฉัน…”\nบุคคลที่มีเสียงถอนหายใจและพูดว่า \"ถ้าน้องสาวของคุณยังมีชีวิตอยู่ คำโกหกของเขาจะกินเวลาหลายวันไหม\" คนทรยศดูตกใจ หลังจากนั้นครู่หนึ่ง เสียงสะอื้นที่กลั้นไว้ก็เล็ดลอดออกมาจากเขาขณะที่เขาค่อยๆ คุกเข่าลงและฝังศีรษะลงในความมืด\nทันใดนั้น ชิ้นส่วนโลหะสีเงินที่แหลมคมและเย็นเฉียบก็พุ่งออกมาจากหน้าอกของเชลย มันหดกลับอย่างรวดเร็วเท่าที่ปรากฏ และเชลยก็คำรามเบา ๆ และล้มลง เลือดสีแดงเข้มไหลออกมาจากข้างใต้เขา เสียงร้องไห้หยุดลง คนทรยศยืดตัวขึ้นและจ้องเขม็งไปที่ศพที่อยู่แทบเท้าของเขา สีหน้าตกใจผสมกับความโกรธฉายบนใบหน้าของเขา มีเสียงเสื้อผ้าที่ขยับไปมา และในที่สุดคนที่นั่งอยู่ในความมืดก็เงยหน้าขึ้นภายใต้แสงสลัว\nเกิดความเงียบขึ้นเหนือกลุ่ม ผมสีแดงของผู้หญิงกลิ้งไปตามไหล่และแขนของเธอเหมือนแม่น้ำสีแดงที่เงียบสงบ เธอก้มลงมองคนทรยศที่คุกเข่าแทบเท้าเธอ แม้ว่าสายตาของเธอจะจับจ้องไปที่เขา แต่ฉันรู้สึกราวกับว่าเธอจ้องมองไปทุกที่ ราวกับแสงตะวันในวันที่อากาศหนาวเย็น ฉันเหลือบมองเธอแล้วก็ไม่กล้ามองอีก จากมุมหางตาของฉัน ฉันมองเห็นดอกลิลลี่ที่ปักอยู่ที่ปกเสื้อของเธอ ดอกไม้นั้นสดและบอบบางมากจนใคร ๆ ก็จินตนาการได้ว่ามีน้ำค้างโปรยปรายจากปลายกลีบของมัน\nเธอยื่นมือออกไปต่อหน้าคนทรยศ เห็นได้ชัดว่าตัดสินใจได้แล้ว คนทรยศจับนิ้วของเธอเบา ๆ และกดศีรษะของเขาไว้ที่หลังมือของเธอ\nมันเป็นคำมั่นสัญญาของความจงรักภักดี",
  str_dispatch_book_chaptercont_15000_4 = "เพื่อนของฉันทำเงินได้พอสมควรจากการเดิมพันนี้ เธอจึงชวนฉันไปที่โรงเตี๊ยมเพื่อดื่มกับเธอ ที่นั่น ฉันได้คุยกับเธอเกี่ยวกับนางเรด เมอร์คิวรี เพื่อนของฉันมีการติดต่อหลายครั้งกับกิลด์ของ Mrs. Red Mercury และรู้จักผู้คนมากมายที่นั่น แต่เธอได้พบเธอเพียงครั้งเดียว “เธอเกิดมาสวยสะดุดตา ดังนั้นย่อมมีข่าวลือหากเธอเห็นหน้าเธอบ่อยเกินไป” เพื่อนของฉันหัวเราะและพูดเมื่อเราพูดถึงเธอ\nแต่ก็ยังมีข่าวลือมากมายเกี่ยวกับนาง Red Mercury ใน Umbraton ฉันเคยได้ยินมาบ้าง และส่วนใหญ่ก็ไร้สาระจนน่าหัวเราะ อย่างไรก็ตาม แท้จริงแล้วน่าจะเป็นต้นกำเนิดของเธอ น่าแปลกที่เธอมาจาก Lumopolis และชื่อเดิมของเธอไม่ใช่ Red Mercury แต่เป็นสิ่งที่ดูเหมือนจะลงท้ายด้วยเสียง \"na\" ไม่ว่าในกรณีใด มันเป็นชื่อสามัญของขุนนางลูโมโปลิส คนจาก Lumopolis ไม่ได้ลงเอยที่ Umbraton เว้นแต่พวกเขาจะถูกเนรเทศ ฉันไม่รู้ว่าเธอผ่านมันมาได้อย่างไร\n“เธอเป็นสตรีสูงศักดิ์ที่แต่งงานกับชายผู้ต่ำต้อยในอัมบราตัน” เพื่อนของฉันโน้มตัวมากระซิบที่ข้างหูของฉัน ฟังดูเหมือนมั่นใจมาก \"ยังไงก็ตาม มันก็เหมือนหนึ่งในเรื่องราวความรักแปลกๆ เธอได้พบกับนักค้าอาวุธใน Umbraton เมื่อตอนที่เธอยังเด็ก และตั้งใจแน่วแน่ที่จะแต่งงานกับเขา ผู้ใหญ่ในครอบครัวของเธอไม่สามารถหยุดเธอได้ ดังนั้นพวกเขาจึงขอให้คริสตจักรมาและ บอกว่าพวกเขาจะถอดตำแหน่งขุนนางของเธอ แต่เธอก็ยังไม่ยอมก้มหัว”\n“ตอนนั้นเธอน่าจะยังเด็กมาก”\n“แน่นอนว่าเธอยังเด็ก ใครจะทำแบบนั้นถ้าพวกเขายังเด็กอยู่” \n“ถึงกระนั้น ค่าใช้จ่ายในการพลิกชีวิตของคุณกลับหัวกลับหางเพื่อเดิมพันกับอนาคตที่คลุมเครือ ไม่ใช่สิ่งที่คนธรรมดาจะทำได้” ฉันถอนหายใจ ส่ายหัว “ถ้าอย่างนั้น ตอนนี้สามีของเธออยู่ที่ไหน?” ฉันถาม.\n\"ตาย.\"\n\"ตาย?\" ฉันถามต่อไป \"ยังไง?\"\n\"พวกเขาบอกว่าเขามีปัญหากับขุนนางชาวลูโมโปลิส เฮอร์มีส มันอาจจะเป็นเรื่องของธุรกิจหรือบางอย่างที่ไม่สามารถบอกได้ ใครจะรู้ว่าคนเหล่านั้นในลูโมโปลิสกำลังทำอะไร\" เพื่อนของฉันหัวเราะ \"แล้วเขาก็ถูกจับได้และถูกสังหาร กิลด์ที่เขาทิ้งไว้ก็ถูก Mrs. Red Mercury จับไป\n“คุณนายเรดเมอร์คิวรี่ไม่ได้แก้แค้นเธอเหรอ?”\n“ตระกูล Hermes เหรอ ลองถามดูสิ แล้วจะรู้ว่ามันร่ำรวยขนาดไหน แม้แต่ตระกูลดั้งเดิมของ Mrs. Red Mercury ก็ไม่มีอะไรเทียบได้กับพวกเขา”\n ฉันเริ่มเมาและจำสิ่งที่เพื่อนพูดไม่ได้ชัดเจนในตอนนั้น สิ่งเดียวที่ฉันรู้ก็คือฉันคาดเดาได้ว่าคนอย่างนางเรด เมอร์คิวรีจะไม่มีวันละทิ้งความเกลียดชังเช่นนั้น",
  str_dispatch_book_chaptercont_15000_5 = "สองปีผ่านไปหลังจากเหตุการณ์นี้ วิสเคาน์เตสผู้ชื่นชอบนวนิยายของฉันขอให้ร้านหนังสือลูโมโปลิสพิมพ์หนังสือเพิ่มอีกสองสามเล่มเพื่อความสะดวกของผู้รักหนังสือในท้องถิ่น ดังนั้นร้านหนังสือจึงเชิญฉันไปที่ลูโมโปลิสเพื่อหารือเกี่ยวกับการเตรียมการ ฉันเห็นว่านี่เป็นโอกาสในการเดินทางไปยังลูโมโปลิส ดังนั้นฉันจึงส่งเอกสารการเที่ยวชมเพื่อขออนุมัติก่อนเวลาที่กำหนดและเข้าพักในโรงแรมเปลี่ยนเครื่อง\nโรงแรมสำหรับเปลี่ยนเครื่องมีหลายสไตล์ และอาคารแถวที่ออกแบบโดย Umbraton และ Lumopolis เรียงรายอยู่ตามท้องถนน โรงแรมที่ฉันพักเปิดขึ้นครั้งแรกโดยครอบครัวพลเรือนจากลูโมโพลิสตอนล่างเมื่อกว่าศตวรรษที่แล้ว ทำเลที่ตั้งดีเยี่ยม มีห้องพักเรียงเป็นแถวและระเบียงทั้งหมดหันหน้าเข้าหาแสงใยแมงมุมยามเช้าที่เย็นสบาย วันส่วนใหญ่ฉันอยู่ในห้องและเขียนเรื่องราว บางครั้งในตอนเย็น ฉันไปทานอาหารเย็นที่ห้องโถงใหญ่ ซึ่งฉันจะพลิกกระดาษหรือนิตยสารจนกระทั่งไฟในห้องโถงดับลง ฉันยังพบนวนิยายของฉันบนชั้นหนังสือในห้องโถง การเข้าสังคมส่วนใหญ่ที่ฉันทำในแต่ละวันคือกับพนักงานเสิร์ฟ ซึ่งจะนำอาหารเช้ามาที่ห้องของฉัน ขณะที่พวกเขารวบรวมเสื้อผ้าของแขกและโยนใส่กระสอบผ้าเพื่อนำไปที่ห้องซักรีด เสื้อผ้าที่สะอาดจะถูกส่งคืนในวันถัดไปพร้อมกับอาหารเช้า\nวันหนึ่งตอนพลบค่ำ ท้องฟ้าเต็มไปด้วยเมฆดำและลมหนาวพัดผ่านผนังและราวบันไดบ้านในเขตทางผ่านหลายหลัง ฉันไปทานอาหารเย็นที่ห้องโถงใหญ่ด้วยความหวังว่ามันจะทำให้จิตใจของฉันเบิกบาน มีแขกเข้าพักในโรงแรมไม่มากนัก ดังนั้นส่วนใหญ่จึงคุ้นหน้าคุ้นตากันดีตลอดช่วงที่ฉันพักระยะยาว แต่คราวนี้ฉันได้เห็นร่างที่ไม่คุ้นเคย\nแต่งตัวตามแบบฉบับของ Umbraton ด้วยรองเท้าบู๊ตหนัง เสื้อโค้ทหนา ผ้าพันคอสีดำที่เย็บอย่างประณีตรอบคอของเธอ และผมของเธอทั้งหมดถูกพันด้วยผ้าคลุมศีรษะสีบรอนซ์สวยงาม เธอยืนพิงเคาน์เตอร์ขณะที่เธอถามบางอย่างจากผู้ดูแลโรงแรม . เสียงของเธอเบา แต่เธอพูดเร็วมาก ฉันไม่สามารถลงรายละเอียดได้ แค่ส่วนเล็กๆ เช่น \"อัพทาวน์\" และ \"อนุมัติ\"—สันนิษฐานว่าเธอกำลังสอบถามเกี่ยวกับสิ่งที่ต้องทำกับลูโมโพลิส มีบางอย่างที่คุ้นเคยเกี่ยวกับเสียงของเธอทำให้ฉันมองตามเธอจนเธอหันกลับมา\nแม้แสงตะวันจะริบหรี่และความจริงที่ว่าจมูกและปากของเธอถูกคลุมด้วยผ้าพันคอสีดำเป็นส่วนใหญ่ ไม่ต้องสงสัยเลยว่ามันคือนางเรดเมอร์คิวรี",
  str_dispatch_book_chaptercont_15000_6 = "เธอวางตัวพิงกับโต๊ะ เฝ้าดูเจ้าหน้าที่นำกระเป๋าเดินทางเข้าไปในห้อง บางครั้งก็ยกมือขึ้นเพื่อรวบปอยผมสีแดงกลับเข้าไปในผ้าคลุมศีรษะ ฉันรู้สึกถูกตรึงอยู่กับที่นั่งชั่วขณะ ไม่สามารถขยับตัวได้ และทำได้เพียงแสร้งทำเป็นเมินเฉยมองไปรอบ ๆ ห้องโถงเพื่อพยายามเลือกผู้ติดตามของเธอจากฝูงชน แต่ฉันก็ไม่พบสัญญาณใด ๆ เลย เธอยกผ้าพันคอขึ้นอีกครั้งเพื่อปิดจมูก ก่อนจะก้มหัวลงและรีบไปที่ห้องของเธออย่างรวดเร็ว ในที่สุดฉันก็เข้าใจ—เธออาจกำลังเดินทางอย่างลับๆ\nฉันรอให้เสียงฝีเท้าของเธอจางหายไปก่อนที่จะหายใจออกในที่สุด คนอย่างเธอที่จู่ๆ ก็โผล่มาในโรงแรมโซนรอเปลี่ยนเครื่อง ทำให้ฉันรู้สึกแย่ ฉันเลยเตรียมกลับห้องแต่เช้า แต่หลังจากนั่งได้ครู่หนึ่ง ผมก็อดไม่ได้ที่จะเหลือบมองไปทางที่เธอจากไป หลังจากที่ฉันเผลอจ้องมองไปแบบนั้นสองสามครั้งโดยไม่รู้ตัว ฉันก็นึกขึ้นได้ว่าฉันหวังว่าเธอจะปรากฏตัวอีกครั้ง รวบรวมความกล้าที่ฉันไม่รู้ว่ามี ฉันตัดสินใจนั่งรอในห้องโถง\nพนักงานนำเบียร์มาให้ฉันอีกขวด และเมื่อฉันดื่มไปได้ครึ่งทาง ในที่สุดเธอก็ค่อยๆ โผล่ออกมาจากเงาของทางเดินของห้องพัก เธอเปลี่ยนผ้าคลุมศีรษะและสวมหมวกปีกกว้าง และตอนนี้ผมยาวของเธออยู่ในเปียที่ซ่อนอยู่ระหว่างผ้าพันคอและเสื้อโค้ทของเธอ เธอเพียงเดินผ่านบริเวณที่มีแสงสลัวๆ ก่อนจะเลือกโต๊ะในมุมที่ไม่มีคนสนใจ ใกล้กับชั้นวางหนังสือตอนสี่ทุ่มของฉัน ฉันรู้สึกกระวนกระวายใจ แต่แฝงไปด้วยความสุข\nระหว่างรอเจ้าหน้าที่มาเสิร์ฟ เธอหยิบหนังสือออกมาจากชั้นอย่างตั้งใจ—ฉันเห็นว่าเป็นนิยายเรื่องหนึ่งของฉันที่ตีพิมพ์เมื่อหลายปีก่อน ราวกับถูกแรงภายนอกดึงให้ลุกขึ้น ฉันจับเหยือกเบียร์ในมือที่เย็นเฉียบแล้วเดินไปหาเธอ\nฉันยืนอยู่ตรงหน้าเธอ ฉันคิดว่าสายเกินไปที่จะหันหลังกลับ ฉันกำเหยือกเบียร์และย่อตัวลง ชี้ไปที่หนังสือในมือเธอ และแสร้งทำเป็นไม่รู้ตัวตนของเธอ แล้วถามว่า \"คุณผู้หญิง คุณชอบหนังสือเล่มนี้ไหม\"\n\"ฉันชอบชื่อเรื่อง\" เธอพูด ยิ้มอย่างใจเย็นขณะที่เธอเงยศีรษะขึ้นมองมาที่ฉัน เธอใช้ปลายนิ้วแตะชื่อที่ปิดทอง \"มันทำให้ฉันนึกถึงสิ่งที่สวยงาม\"\nฉันพยายามหายใจราวกับถูกจำกัดโดยน้ำหนักของความงามของเธอ มันเหมือนกับใบหน้าของฉันจมดิ่งลงไปในน้ำเย็นหรือติดอยู่ในพายุน้ำแข็ง ฉันพยายามทุกวิถีทางที่จะหายใจโดยไม่ให้ฟันกระทบกัน: \"ฉันดีใจมากที่คุณชอบ อันที่จริง ฉันเขียนว่า... ดูนั่นสิ—นั่นคือชื่อของฉัน\"",
  str_dispatch_book_chaptercont_15000_7 = "ขณะที่ฉันนั่งตรงข้ามกับเธอ ฉันนึกขึ้นได้ว่าด้านหลังเสื้อชั้นในของฉันเปียกโชกไปด้วยเหงื่อแล้ว เราคงคุยกันเรื่องนิยายมาสักระยะหนึ่งแล้ว แต่เมื่อนึกย้อนไป ฉันกลับจำคำนี้ไม่ได้เลยแม้แต่คำเดียว สิ่งเดียวที่ยังคงอยู่ในความทรงจำของฉันคือความรู้สึกแปลก ๆ เหมือนฉันจมอยู่ในทะเลสาบในขณะที่คนอื่น ๆ กำลังเดินไปมาบนชายฝั่ง ราวกับว่าความเร่งรีบและวุ่นวายรอบตัวฉันถูกแยกออกไปในอีกโลกหนึ่ง เมื่อผมกลับมารู้สึกตัวอีกที ผมก็นั่งอยู่ที่ระเบียงนอกห้องของเธอแล้ว เราถูกคั่นด้วยชุดโต๊ะกลมขนาดเล็กพร้อมของว่างและแก้วไวน์ และแจกันคอบางตรงกลางถือดอกลิลลี่ดอกเดียวที่มีกลีบเลี้ยงสีเขียวชอุ่ม\nค่ำคืนยังไม่หลับสนิท แต่เมฆด้านบนบดบังแสง โอบล้อมพื้นที่รอบตัวเราด้วยความมืดสลัว ฉันตัวสั่นเพราะลมหนาว และนึกถึงวิธีที่พนักงานเสิร์ฟเพิ่งจัดอาหารในห้องโถงใหญ่ เมื่อจู่ๆ เธอแนะนำให้เราไปกินข้าวที่ระเบียง ตอนนี้เธอถอดหมวกและผ้าพันคอออกแล้วโยนผ่านหน้าต่างเข้าไปในห้องของเธอ เธอถูกห่อหุ้มด้วยเสื้อโค้ทของเธอและแขนของเก้าอี้ของเธอ แต่ตอนนี้ใบหน้าของเธอถูกเปิดออก กลัวเกินกว่าจะมองตรงไปที่เธอ ฉันจดจ่อกับผมสองสามปอยของเธอที่ปลิวไสวไปตามสายลม\n“ฉันจะไปลูโมโปลิสด้วย” เธอยิ้มขณะเช็ดนิ้วด้วยกระดาษเช็ดมือที่ชุบน้ำหมาดๆ ตอนนี้ฉันจำได้ว่าเราได้พูดคุยเกี่ยวกับแผนการเดินทางของเราก่อนหน้านี้ \"ฉันอาศัยอยู่ในลูโมโปลิสเมื่อตอนที่ฉันยังเด็ก เพื่อนสมัยเด็กของฉันอยู่ที่นั่นทั้งหมด\"\n\"จากนั้นฉันก็ไปที่ Umbraton ทุกอย่างดีมาก นอกจากการโต้เถียงกับเพื่อนของฉันก่อนที่ฉันจะจากไป\"\n“คุณเถียงเรื่องอะไร” ฉันนั่งตัวตรงเพื่อแสดงว่าฉันฟังเธออยู่\n“ฉันลืมไปแล้ว ทั้งหมดที่ฉันจำได้คือความโกรธนี้ เหมือนหัวใจของฉันพองโตและเต้นแรงกับหน้าอกของฉัน และตอนนี้ ฉันจำไม่ได้ตลอดชีวิตของฉันว่าทะเลาะอะไรกัน เพียงแต่ว่าค่อนข้างมาก หน่อมแน้ม” นิ้วที่สะอาดของเธอค่อยๆ สางผมของเธอในขณะที่เปียของเธอหมุนไปรอบๆ และค่อยๆ คลายออก \"เมื่อเร็วๆ นี้ ฉันคิดถึงเพื่อนคนนั้นอีกครั้ง มันเริ่มต้นจากความฝัน\"\n\"ฝัน?\"\n\"ใช่ค่ะ ในฝันฉันกลับมาอยู่ในห้องเก่าที่มีผนังสีขาวแป้งและประตูสีน้ำตาลทอง ฉันนั่งอยู่หน้าโต๊ะเครื่องแป้งที่ฉันใช้ประจำในตอนนั้น ฉันเห็นหน้าเพื่อนใน กระจก เธอถือหวีและกำลังแปรงผมให้ฉัน” เธอรวบผมที่ยาวสลวยของเธอขึ้นแล้วมองมาที่ฉัน ดูเหมือนกำลังปรับขนาดฉัน ก่อนจะเดินย้อนกลับไปในความคิดของเธอ \"เธอดูสวย สวยกว่าที่เคยเป็นมามาก พอฉันตื่นนอนก็คิดถึงเธออยู่หลายวัน\"\n“งั้นคุณจะไปลูโมโปลิสเพื่อไปหาเพื่อนใช่ไหม”\n“ในทางหนึ่ง” เธอพูดพร้อมกับถอนหายใจ “น่าเสียดาย มันคงยากที่จะไปเยี่ยมเธออย่างเหมาะสม แต่ฉันจะยอมเห็นเธอจากระยะไกล”\nโรงแรมในเขตเปลี่ยนผ่านทั้งหมดสว่างไสวด้วยรัศมีของแสงขนาดต่างๆ ระยิบระยับผ่านลมชื้นและหมอกหนาทึบ เธอมองมาที่ฉันพร้อมกับแก้วไวน์ในมือ ฉันตกอยู่ในภวังค์ จากนั้นรู้สึกได้ถึงกระแสแห่งความกลัวที่ค่อยๆ ก่อตัวขึ้นในตัวฉันอีกครั้ง สีหน้าของเธอค่อย ๆ จางลงจนเหลือร่องรอยเพียงเล็กน้อย—เปรียบเปรยถึงโชคชะตา ดั่งขอบจันทร์ที่เลือนลางในสภาพอากาศที่มีหมอก เมื่อความมืดมิดปกคลุมใบหน้าของเธอก็จมลงในเงาพร้อมกับผมที่ยาวเหมือนธงซึ่งส่องแสงสีแดงสนิมเย็นในส่วนลึกของความมืด",
  str_dispatch_book_chaptercont_15000_8 = "ฉันตื่นขึ้นมาด้วยอาการหายใจไม่ออก แล้วก็พบว่าฉันนอนอยู่บนเตียง โดยร่างกายทุกส่วนยังคงไม่บุบสลาย ฉันอดไม่ได้ที่จะรู้สึกโล่งใจ ศีรษะของฉันปวดแปลบ—อาการเมาค้างเล็กน้อย นอกม่าน ท้องฟ้ายังคงมืดอยู่—ฉันคงตื่นเช้ากว่าปกติ และคนรับใช้ก็ยังไม่ได้เคาะประตูฉัน ฉันออกจากห้องโดยประคองศีรษะด้วยมือข้างเดียวและมุ่งหน้าไปยังห้องของ Mrs. Red Mercury เพียงเพื่อจะพบว่ามันว่างเปล่า ผิดหวังและผิดหวัง ฉันเดินอย่างอ่อนล้าไปตามทางเดินที่เหลือจนกระทั่งถึงห้องโถงใหญ่ ไม่หยุดจนกว่าจะเห็นเจ้าของโรงแรม\n“ขอโทษนะ คุณรู้ไหมว่า... ผู้หญิงคนนั้น” ฉันพูดเสียงแหบพร่า ชี้ไปที่ห้องข้างหลังฉัน “เธอออกไปแล้วเหรอ”\n“เธอออกไปตั้งแต่เช้าแล้ว” เจ้าของโรงแรมพูดพร้อมกับหยุดงานและมองมาที่ฉันด้วยความสนใจ “คนจากลูโมโปลิสมารับเธอในเรือบิน ฉันว่าเธอต้องเป็นขุนนางใช่ไหม”\nฉันไม่รู้ว่าจะพยักหน้าหรือส่ายหัวดี ทั้งหมดที่ฉันรู้สึกคือความผิดหวังที่เอื่อยเฉื่อย เจ้าของโรงแรมถอนหายใจ \"เมื่อเธอเข้ามา ฉันบอกได้ทันทีเลยว่าเธอแตกต่างออกไป ความสวยงาม มันทำให้แทบไม่สงบเลย\" เขาหันมามองฉันอย่างเห็นอกเห็นใจในขณะที่เขาพูด \"ฉันประหลาดใจที่คุณกล้าที่จะขึ้นไปคุยกับเธอ\"\nฉันส่ายหน้า รู้สึกขมคอขณะค่อยๆ หันหลังกลับห้อง ฉันนั่งที่โต๊ะ และไม่กี่นาทีต่อมา พนักงานเสิร์ฟก็มาถึงพร้อมอาหารเช้าและเสื้อผ้าที่สะอาด ฉันยังคงนั่งที่โต๊ะเป็นเวลานาน แต่ลุกขึ้นเมื่อแสงแดดนอกหน้าต่างรุนแรงเกินกว่าจะทนได้\nตามกิจวัตรประจำวันของฉัน ฉันเดินไปที่โซฟาเพื่อจัดเสื้อผ้าให้เรียบร้อยก่อนจะเก็บเข้าตู้ ฉันกำลังพับเสื้อผ้าอย่างเหม่อลอย เมื่อมีบางสิ่งที่เล็กและเหี่ยวๆ ลอยออกมาระหว่างรอยพับ ฉันหยิบมันขึ้นมาและตะลึงกับสิ่งที่เห็น—\nมันเป็นดอกลิลลี่แห้งที่ถูกกดให้แบนเหมือนที่คั่นหนังสือ นี่คือบัตรโทรศัพท์ของเธอ",
  str_dispatch_book_chaptercont_15000_9 = "ฉันรออีกสามหรือสี่วันหลังจากนี้ และน่าประหลาดใจที่ใบสมัครเข้าเมืองของฉันยังไม่ได้รับการอนุมัติ ด้วยความงุนงงและกลุ้มใจ ที่นัดของฉันกับวิสเคานต์หญิงและคนขายหนังสืออยู่ห่างออกไปเพียงไม่กี่วัน สิ่งที่ฉันทำได้คือออกจากโรงแรมไปถามข่าวสารจากลูโมโปลิสรอบๆ โดยพยายามหาทางอื่นเพื่อไม่ให้การประชุมของฉันล่าช้า\nในระหว่างการสอบถามนี้เองที่ฉันได้ทราบเกี่ยวกับคดีฆาตกรรมล่าสุดในลูโมโปลิส เหยื่อเคราะห์ร้ายซึ่งเป็นลูกชายคนโตของตระกูลเฮอร์มีส ลูโมโปลิสถูกปิดล้อมเนื่องจากเหตุการณ์ดังกล่าว และการสมัครเข้าร่วมทั้งหมดถูกระงับไว้ หยุดคิดถึงสิ่งที่ได้ยินไม่ได้ ฉันรู้สึกกังวลระหว่างทางกลับโรงแรมอย่างช่วยไม่ได้ ขณะที่ฉันครุ่นคิดถึงสิ่งที่ Mrs. Red Mercury พูด ฉันรู้สึกว่าคำพูดของเธอเต็มไปด้วยความหมายที่ซ่อนอยู่ และเธออาจบอกเป็นนัยถึงการฆาตกรรมครั้งนี้ ฉันหลงทางจนลืมนัดกับวิสเคานต์หญิงเสียด้วยซ้ำ\nเรื่องราวลุกลามราวกับไฟป่า แม้แต่พนักงานซักรีดของโรงแรมก็เล่าเกร็ดเล็กเกร็ดน้อยในโถงทางเดิน แต่ฉันกลับพบว่าตัวเองขาดการเชื่อมต่อจากความตื่นเต้นทั้งหมด ฉันเป็นคนวงในที่มีความลับที่ต้องปกป้อง และฉันไม่สามารถเปิดเผยความรู้สึกที่แท้จริงได้จนกว่าพายุลูกนี้จะพัดผ่าน สองสามวันต่อมา การขอเข้าเมืองก็ค่อยๆ เริ่มขึ้นอีกครั้ง และเอกสารการอนุมัติเริ่มแพร่สะพัดไปพร้อมกับผลการสืบสวนคดีฆาตกรรม—ฆาตกรถูกจับได้และจะถูกแขวนคอในลูโมโปลิส\nฉันพบกับวิสเคาน์เตส แต่รู้สึกเสียสมาธิ พยายามหลายครั้งที่จะขัดจังหวะการอ่านหนังสือของเธอพร้อมกับถามคำถามเกี่ยวกับรายละเอียดของคดีฆาตกรรม แต่เธอยังคงดื้อรั้นกับหัวข้อของเธอ ราวกับว่าการสูญเสียชีวิตของคนสองคนนั้นไม่ก่อให้เกิดความตื่นตระหนก หรือบางทีอาจเป็นเรื่องที่เธอไม่ได้ตั้งใจจะพูดถึงคนนอกเช่นฉัน ไม่มีอะไรที่ฉันสามารถทำได้นอกจากระงับความสงสัยของฉัน หลังการประชุม วิสเคาน์เตสขอให้คนขายหนังสือพาฉันไปทัวร์ลูโมโปลิสก่อนจะอำลาเรา\nฉันรีบขอให้คนขายหนังสือพาฉันไปดูตะแลงแกง และเราก็มาถึงตอนพลบค่ำ\n“การประหารยังไม่เริ่มอีกเหรอ?” ฉันถามอย่างมีความหวัง\nคนขายหนังสือครุ่นคิดอยู่ครู่หนึ่งแล้วถามว่า \"คุณหมายถึงคดีฆาตกรรมเฮอร์มีสเมื่อวันก่อนเหรอ\"\n\"ใช่.\"\n\"มันจบแล้ว.\" เขาน่าจะสังเกตเห็นความสับสนบนใบหน้าของฉัน เขากล่าวเสริมว่า \"ประโยคดังกล่าวดำเนินไปเมื่อวานนี้\"\nโดยปกติแล้วผู้คนไม่ได้รับอนุญาตให้เข้าใกล้ตะแลงแกงและทำได้เพียงเฝ้ามองจากระยะไกลเท่านั้น มีเพียงไม่กี่คนเท่านั้นที่เดินผ่านบริเวณนั้น พร้อมกับนกพิราบตัวหนึ่งเดินเตาะแตะไปตามพื้นดิน\n“คุณเห็นมันไหม” ฉันถามเขา.\n\"แน่นอน.\"\n“คุณรู้ไหมว่าใครเป็นคนฆ่า”\n“คุณจะต้องสอบถามกับ Hall of Justice”\nความสงสัยของฉันเพิ่มขึ้น “ฆาตกรเป็นคนแบบไหน?”\n“ฉันไม่รู้” คนขายหนังสือพูดพร้อมกับส่ายหัว \"นักโทษต้องสวมเครื่องแบบเรือนจำ คุณไม่สามารถบอกอะไรเกี่ยวกับพวกเขาได้จากสิ่งที่ขาดรุ่งริ่ง ศีรษะของพวกเขายังถูกคลุมด้วยถุงผ้าหรือหมวกเหล็กที่มีรูตาเพียง 2 รู ในกรณีความผิดร้ายแรง ไม่มีใครได้รับอนุญาตให้ทำ ได้เห็นหน้านักโทษระหว่างถูกแขวนคอ”\n\"ทำไม?\"\n“มันคงน่ากลัวไม่ใช่เหรอ” เขาหัวเราะ.\nฉันรู้สึกหวั่นไหวเมื่อได้ยินสิ่งนี้และทำได้เพียงหัวเราะออกมา \"มันน่ารำคาญน้อยกว่าเมื่อพวกเขาสวมหน้ากาก ฉันเดาว่า\"\n\"สนุกมากขึ้นด้วย!\" เขาพูดทั้งที่ยังหัวเราะอยู่",
  str_dispatch_book_chaptercont_15000_10 = "ฉันออกจาก Lumopolis ราวกับกำลังวิ่งหนี เพื่อนคนหนึ่งชวนฉันไปพักกับพวกเขาที่ Umbraton แต่ฉันตื่นตระหนกและปฏิเสธ ตอนที่ฉันไปที่ Umbraton ก็หลายเดือนต่อมา\nเพื่อนชวนไปดื่มเหมือนเคย แถบนั้นเต็มไปด้วยผู้คนและมีเสียงผู้คนหนาแน่นและแยกส่วน เพื่อนของฉันที่สร่างเมาแล้วครึ่งแก้วก็พลิกแก้วแล้วชี้ไปยังสถานที่ที่มีผู้คนพลุกพล่าน แล้วพูดว่า \"ดูนั่นสิ คนทรยศที่มาจากหลุม\"\nฉันหันไปมองและสายตาก็จับจ้องไปที่ชายร่างเล็กในชุดดำและจำการต่อสู้เมื่อไม่กี่ปีก่อนได้ลางๆ จิตใจของฉันท่วมท้นไปด้วยความทรงจำเกี่ยวกับนางเรดเมอร์คิวรี ถ้าฉันบังเอิญเจอเขาเมื่อสองสามเดือนก่อน ฉันคงจะหลบหน้าเขาแน่ๆ แต่หลังจากสิ่งที่เกิดขึ้น ฉันแสดงท่าทีสงบนิ่ง ฉันถือแก้วในมือเดินไปหาเขา\n“ฉันจำคุณได้” ฉันพูดพร้อมยกแก้วขึ้นให้เขา ฤทธิ์แอลกอฮอล์โชยมา \"ฉันเห็นคุณในหลุม\"\nสีหน้าของเขาไม่แน่นอนในขณะที่เขาและพรรคพวกแลกเปลี่ยนสายตากัน ด้วยความกลัวและความทรงจำเกี่ยวกับความดุร้ายของคนเหล่านี้ที่ถูกลืมไปนาน ฉันพูดต่อ: \"ฉันเดินสวนทางกับครูใหญ่ของคุณ คุณนาย Red Mercury\"\nเมื่อได้ยินเช่นนี้ สีหน้าของพวกเขาก็อ่อนลงในที่สุด\n\"ขอแสดงความนับถือ ฉันเป็นนักเขียนจากโรงแรมในเขตเปลี่ยนเครื่อง เธอจะจำได้\" ฉันเฝ้าดูการแสดงออกของพวกเขาอย่างระมัดระวัง มองหาร่องรอยของความโศกเศร้าเพื่อยืนยันความสงสัยของฉัน แต่เด็กหนุ่มที่มีรอยแผลเป็นเก่าบนใบหน้ามีสีหน้าเรียบเฉยและคลุมเครือ\n“เธอสบายดีไหม ฉันหวังดี” ฉันถาม หยั่งเชิง\n“เธอสบายดี” พวกเขามองหน้ากัน ถอนหายใจเล็กน้อย “แต่เธอไม่ใช่หัวหน้ากิลด์อีกต่อไปแล้ว”\n\"หมายความว่าตอนนี้คุณไม่มีครูใหญ่แล้วใช่ไหม\"\nพวกเขาหัวเราะอย่างอึกทึกครึกโครม: \"เมื่อคนหนึ่งไป อีกคนก็เข้ามาแทนที่ คุณเคยได้ยินเรื่องกิลด์ที่ไม่มีหัวหน้าไหม\"\nด้วยเหตุนี้ การสนทนาจึงหยุดชะงักลงทันที ข้าพเจ้าไม่เห็นนางเรดเมอร์คิวรี่อีกเลยหลังจากนั้น และข้าพเจ้าก็ไม่ได้ยินข่าวเกี่ยวกับนางอีกเลย\nเสียงซุบซิบจาก Umbraton และ Lumopolis หลั่งไหลเข้ามาอย่างอิสระในกระแสผู้คนที่เดินผ่านบาร์ ฉันได้ยินข่าวลือที่แตกเป็นเสี่ยงๆ เหล่านี้เป็นส่วนใหญ่ แต่ไม่สามารถสรุปได้แม้แต่ข้อเดียวว่านางเรดเมอร์คิวรี่ที่ผูกมัดกับลูโมโปลิสตั้งใจที่จะมอบความตายให้กับศัตรู หรือเพื่อไปหาเพื่อนจากความฝันของเธอ",
  str_dispatch_book_chaptercont_15000_11 = "ผู้อ่านที่รัก เป็นเกียรติที่ได้พบคุณในคอลเลคชันนวนิยายของอีวอนน์ เราหวังว่าคุณจะไม่ไม่พอใจกับการเลือก \"Mrs. Red Mercury\" เป็นชื่อโดยรวมของคอลเลกชั่นนี้ \"Mrs. Red Mercury\" แม้ว่าอาจจะไม่ใช่ผลงานที่ดีที่สุดของอีวอนน์ แต่ก็เป็นเพียงเรื่องสั้นเท่านั้น ซึ่งเป็นผลงานที่โดดเด่นที่สุดในการสนทนาของคุณ ในฐานะผู้อ่านที่ซื่อสัตย์ของ Ms. Yvonne ความคิดแรกของฉันหลังจากจบนิยายเกี่ยวกับตัวละครนี้คือ: \"ฉันต้องการค้นหา 'Mrs. Red Mercury' ตัวจริง\" ฉันคิดว่าพวกคุณหลายคนต้องมีความคิดเช่นเดียวกัน\nเพื่อจุดประสงค์นี้ ฉันได้โทรหากิลด์เก่าของเธอใน Umbraton โดยเฉพาะ จ่ายค่าธรรมเนียมแรกเข้า 1,000 Nightium เพื่อเยี่ยมชม Pit และขอให้ใครสักคนตรวจสอบไฟล์บางไฟล์ที่ Lumo Hall of Justice ฉันยังถามคนรับใช้ตระกูลเฮอร์มีสแต่ละคนเกี่ยวกับคดีฆาตกรรมที่สะเทือนขวัญ ตอนนี้ฉันจะแบ่งปันการวิจัยและข้อสรุปของฉันกับทุกคน\nเรื่องราวของ Ms. Yvonne นั้นขึ้นชื่อว่าเป็น \"ความจริง\" เนื่องจากคุณสามารถค้นหา \"ความจริง\" บางอย่างในเรื่องราวเหล่านั้นได้เสมอ ยกตัวอย่างกิลด์ค้าอาวุธของ Umbraton—พูดตามตรง Umbraton มีกิลด์แบบนี้หลายกิลด์ แต่ก็มีบางดีลในรายการอื่นๆ ด้วย นิยายเรื่องนี้เขียนขึ้นเมื่อ 10 ปีก่อน และเป็นการยากที่จะระบุให้แน่ชัดว่าในตอนนั้นมีกิลด์เดียวที่ควบคุมการค้าทั้งหมดหรือไม่ ท้ายที่สุดแล้ว ความอุตสาหะไม่เพียงพอที่จะคลี่คลายความซับซ้อนของ Umbraton\nสำหรับคดีฆาตกรรมลูโมโปลิสนั้น มีการยืนยันในไฟล์และเป็นที่รู้จักกันเป็นอย่างดีในลูโมโพลิส ลูกชายคนโตของตระกูล Hermes นั่นคือลูกชายคนโตของ Lachon หัวหน้าครอบครัวถูกสังหาร เมื่อเกิดขึ้น บาดแผลฉกรรจ์ถูกจัดการด้วยอาวุธเหล็กเรียว ซึ่งทำให้นึกถึงอาวุธที่นาง Red Mercury ถือได้อย่างง่ายดาย—\"แสงสีเงินเย็น\" ที่คร่าชีวิตเชลยในหลุม สิ่งที่ไม่พบในไฟล์คือผู้กระทำความผิดที่แท้จริงของการสังหาร เห็นได้ชัดว่าพวกเขาถูกประหารชีวิต แต่ Lumopolis ยังคงลังเลที่จะเปิดเผยรายละเอียดต่อโลกภายนอก ไม่ต้องแสดงใบหน้าของฆาตกร แม้แต่คนรับใช้ของครอบครัวเฮอร์มีสที่เห็นการฆาตกรรมก็ไม่สามารถบอกได้ว่าฆาตกรมีหน้าตาเป็นอย่างไร ถึงกระนั้นก็ไม่จำเป็นต้องหงุดหงิด นี่เป็นเพียงแนวทางของ Lumopolis และความสูงส่งของมัน อย่างไรก็ตาม ความจริงจะปรากฎขึ้นในสักวันหนึ่ง ท้ายที่สุดแล้วไม่มีใครอยู่ค้ำฟ้า จริงไหม?",
  str_dispatch_book_chaptercont_15000_12 = "สิ่งที่เราผู้อ่านกังวลที่สุดคือตัวตนที่แท้จริงของ Mrs. Red Mercury ใช่ไหม? อย่างไรก็ตาม จากการวิจัยของฉัน Mrs. Red Mercury เป็นตัวละครในนิยายจริงๆ ความสวยเกินจริงของเธอคือเครื่องพิสูจน์ เมื่อ 10 ปีที่แล้ว นิยายรักได้รับความนิยมเป็นพิเศษ (และแน่นอนว่ายังคงขายดีมาจนถึงทุกวันนี้) และตัวละครเอกหญิงของพวกเขาก็สวยสะดุดตาอยู่เสมอ อีวอนน์มอบความงามที่ \"ไม่สงบ\" ให้กับ Mrs. Red Mercury เป็นเพียงรูปแบบหนึ่งของการเสียดสีแบบหน้าตายของกระแสนิยมในแต่ละวัน ท้ายที่สุดแล้ว นวนิยายโรแมนติกเต็มไปด้วยคู่รักที่มารวมตัวกันแม้จะมีสถานะผูกมัดก็ตาม\nในเรื่องนี้ Ms. Yvonne ทิ้ง Mrs. Red Mercury ไว้กับชะตากรรมอะไร มันเหมือนกับคำถามที่เธอถามในตอนท้าย—เธอไปที่ลูโมโปลิสเพื่อล้างแค้นหรือไปหาเพื่อน? เมื่อรวมกับข่าวลือจาก Lumopolis ในช่วงไม่กี่ปีที่ผ่านมา—ขุนนางจำนวนมากถูกประหารชีวิตหรือถูกเนรเทศ (เราไม่แน่ใจด้วยซ้ำว่าทำไม)—เราเดาได้อย่างแน่นอนว่าในฉากของ Ms. Yvonne ความรักเป็นเพียงการเสแสร้ง และเหตุผลที่แท้จริงของนาง Red Mercury แต่งงานใน Umbraton เป็นที่หลบภัย ท้ายที่สุด เราผู้อ่านผลงานของ Ms. Yvonne คุ้นเคยกับนิสัยการเขียนของเธอเป็นอย่างดี เธอเก่งในการใช้เรื่องโกหกเพื่อปกปิด \"สิ่งที่ไม่สามารถบรรยายได้\"\nในกรณีนี้ มีวิธีใดที่เราจะระบุได้ว่า Mrs. Red Mercury เพิ่งไป Lumopolis เพื่อไปหาเพื่อนหรือไม่? คำตอบคือไม่มี ไม่มี ในบทที่มีการเผชิญหน้ากันในโรงแรม อีวอนน์ตระหนี่กับข้อมูลที่แท้จริงและมีประสิทธิภาพที่เธอสื่อ ราวกับว่าแม่น้ำไหลผ่านเธอและเธอเพียงแค่เอนตัวไปตักน้ำจากมัน กำมือเดียวไม่สามารถกำหนด ทั้งแม่น้ำ ในเรื่อง บางทีเหยื่อผู้น่าสงสารคนนั้นอาจเป็นศัตรูที่ Mrs. Red Mercury ต้องการให้ตาย หรือบางทีเธออาจจะแค่คิดถึงเพื่อนสมัยเด็กของเธอ หรือบางทีอาจจะเป็นเรื่องจริงทั้งคู่ แต่เธอเล่าให้ตัวเอกฟังเพียงครึ่งเดียว\nผู้อ่านที่รัก คุณต้องพบว่าข้อสรุปของฉันน่าผิดหวัง อย่างไรก็ตาม \"Mrs. Red Mercury\" ไม่ใช่เรื่องนักสืบ และ Yvonne ไม่ได้ตั้งใจที่จะเขียนเรื่องราวเกี่ยวกับ \"ความจริง\" สิ่งที่เธออยากนำเสนอคือ \"ความจริง\" เรื่องราวจากชีวิตจริงที่แฝงด้วยตำนาน ในการมอบดอกลิลลี่สด ดาบคมกริบ และความงามอันน่าทึ่งให้กับ Mrs. Red Mercury นั้น เป้าหมายของเธอคือมุ่งความสนใจของเราเท่านั้น เพื่อไม่ให้พลาดช่วงเวลาที่ตัวละครพบกัน ช่วงเวลาแห่ง \"ความเป็นจริง\"—ในนั้น น้ำเพียงหยิบมือเดียวเป็นสิ่งที่มีค่ามากกว่าตำนานทั้งหมดรวมกัน",
